def _env_int(name: str, default: int, *, minimum: int = 1) -> int:
    raw = os.environ.get(name, "").strip()
    try:
        value = int(raw) if raw else default
    except ValueError:
        value = default
    return max(minimum, value)


def _task_flow_tick_since_hours() -> int:
    """Lookback for the scheduled stranding sweep."""

    return _env_int("MAC_TASK_FLOW_TICK_SINCE_HOURS", 24, minimum=1)


def _agent_quarantine_threshold() -> int:
    return _env_int("MAC_AGENT_QUARANTINE_THRESHOLD", 2, minimum=1)


def _agent_zombie_stream_age_seconds() -> int:
    return _env_int("MAC_AGENT_ZOMBIE_STREAM_AGE_SECONDS", 300, minimum=1)


def _evidence_artifact_max_bytes() -> int:
    raw = os.environ.get("MAC_EVIDENCE_ARTIFACT_MAX_BYTES", "").strip()
    try:
        value = int(raw) if raw else DEFAULT_EVIDENCE_ARTIFACT_BYTES
    except ValueError:
        value = DEFAULT_EVIDENCE_ARTIFACT_BYTES
    return min(MAX_EVIDENCE_ARTIFACT_BYTES, max(0, value))


def _evidence_artifact_total_max_bytes() -> int:
    raw = os.environ.get("MAC_EVIDENCE_ARTIFACT_TOTAL_MAX_BYTES", "").strip()
    try:
        value = int(raw) if raw else DEFAULT_EVIDENCE_ARTIFACT_TOTAL_BYTES
    except ValueError:
        value = DEFAULT_EVIDENCE_ARTIFACT_TOTAL_BYTES
    return min(MAX_EVIDENCE_ARTIFACT_TOTAL_BYTES, max(0, value))


def _evidence_artifact_bool(value: Any) -> bool:
    if isinstance(value, str):
        return value.strip().lower() in {"1", "true", "yes", "on"}
    return bool(value)


def _metadata_path_list(value: Any) -> List[str]:
    if isinstance(value, str):
        values = [value]
    elif isinstance(value, Iterable) and not isinstance(value, dict):
        values = list(value)
    else:
        return []
    paths: List[str] = []
    seen = set()
    for item in values:
        path = _normalize_repo_relative_path(item)
        if path and path not in seen:
            seen.add(path)
            paths.append(path)
    return paths


def _nested_json_object(root: JsonDict, *keys: str) -> JsonDict:
    node: Any = root
    for key in keys:
        if not isinstance(node, dict):
            return {}
        node = node.get(key)
    return ensure_json_object(node) if isinstance(node, dict) else {}


def _repository_contract_test_command_for_task(task: "Task") -> str:
    """The repository contract's test command for a task, or "" (the hub
    verifier then defaults to scripts/run-contract-tests.sh)."""
    metadata = ensure_json_object(task.metadata)
    for path in (
        ("execution_contract", "test"),
        ("execution_contract", "repository_contract", "test"),
        ("origin", "repository_contract", "test"),
        ("repository_contract", "test"),
    ):
        node = _nested_json_object(metadata, *path)
        command = str(node.get("command") or "").strip()
        if command:
            return command
    return ""


def _repository_contracts_from_metadata(metadata: JsonDict) -> List[JsonDict]:
    contracts: List[JsonDict] = []
    seen: set[str] = set()
    for path in (
        ("execution_contract", "repository_contract"),
        ("origin", "repository_contract"),
        ("repository_contract",),
    ):
        contract = _nested_json_object(metadata, *path)
        if not contract:
            continue
        key = json_dumps(contract)
        if key not in seen:
            seen.add(key)
            contracts.append(contract)
    return contracts


def _repository_required_commands_from_metadata(metadata: JsonDict) -> List[str]:
    required: List[str] = []
    seen: set[str] = set()
    for contract in _repository_contracts_from_metadata(metadata):
        toolchain = ensure_json_object(contract.get("toolchain"))
        for command in _metadata_string_list(toolchain.get("required_commands")):
            if command not in seen:
                seen.add(command)
                required.append(command)
    return required


_REPOSITORY_HOST_REQUIRED_COMMANDS = {"git"}


def _repository_host_required_commands_from_metadata(metadata: JsonDict) -> List[str]:
    """Commands a sandboxed host worker must have before it can start repo work.

    Repository contracts describe the project toolchain, which belongs inside the
    task sandbox when the agent is OpenShell-required. Dispatch should not
    require sandboxed worker hosts to advertise project-local commands like
    pnpm, java, or lein. Keep only the primitive the worker itself needs to
    prepare/push task-owned git worktrees.
    """
    return [
        command
        for command in _repository_required_commands_from_metadata(metadata)
        if command in _REPOSITORY_HOST_REQUIRED_COMMANDS
    ]


def _agent_requires_openshell(agent: Agent) -> bool:
    return openshell_required_for_identity(
        agent_id=agent.id,
        agent_name=agent.name,
        resources=ensure_json_object(agent.resources),
    )


def _required_changed_files_from_metadata(metadata: JsonDict) -> List[str]:
    containers = [
        ensure_json_object(metadata),
        _nested_json_object(metadata, "acceptance"),
        _nested_json_object(metadata, "execution_contract"),
        _nested_json_object(metadata, "execution_contract", "evidence"),
        _nested_json_object(metadata, "execution_contract", "repository_contract"),
        _nested_json_object(metadata, "execution_contract", "repository_contract", "evidence"),
        _nested_json_object(metadata, "origin", "repository_contract"),
        _nested_json_object(metadata, "origin", "repository_contract", "evidence"),
        _nested_json_object(metadata, "repository_contract"),
        _nested_json_object(metadata, "repository_contract", "evidence"),
    ]
    required: List[str] = []
    seen = set()
    for container in containers:
        if not container:
            continue
        for key in _REQUIRED_CHANGED_FILE_KEYS:
            for path in _metadata_path_list(container.get(key)):
                if path not in seen:
                    seen.add(path)
                    required.append(path)
    return required


def _truthy_env(name: str, default: str = "") -> bool:
    value = os.environ.get(name, default).strip().lower()
    return value in {"1", "true", "yes", "on"}


def _int_env(name: str, default: int, *, minimum: int = 1) -> int:
    """Read a positive integer config knob, falling back to *default*.

    Empty / unparseable / below-*minimum* values fall back to the default so a
    misconfigured env var can never DISABLE a safety cap (only widen/narrow it
    within sane bounds).
    """
    raw = os.environ.get(name, "").strip()
    if not raw:
        return default
    try:
        value = int(raw)
    except ValueError:
        return default
    return value if value >= minimum else default


# Decomposition guardrails (T1 — bound runaway auto-decompose). Enforced
# server-side in ControlPlane.add_child_tasks so NEITHER decomposition path
# (the executor prompt that tells the agent to POST /children, nor the
# declarative maybe_auto_decompose manifest path) can exceed them regardless of
# agent behavior. Both are overridable via env for operators who need wider
# trees, but never below the floor of 1.
DEFAULT_MAX_CHILD_TASKS_PER_PARENT = 10
DEFAULT_MAX_DECOMPOSE_DEPTH = 2

DEFAULT_BLOCKED_ATTEMPT_RETRY_BACKOFF_SECONDS = 60
BLOCKED_ATTEMPT_NON_RETRYABLE_DIAGNOSES = (
    "needs-operator",
    "wrong-host self-release",
    "dependency-on-external",
)


_TIMEOUT_BLOB_MARKERS = ("timed out", "timeout", "rc=124", "returncode 124", "code: 124")
_SHARED_TRANSIENT_FAILURE_MARKERS = (
    "transient transport error",
    "connection reset",
    "connection refused",
    "no route to host",
    "temporary failure",
    "service unavailable",
    "bad gateway",
    "gateway timeout",
    "rate limit",
)
_OPENSHELL_VERIFIER_INFRASTRUCTURE_MARKERS = (
    "openshell repository verifier did not start",
    # The same infrastructure fault, reported honestly: a verifier that dies on
    # launch never timed out. Both spellings must classify identically, or
    # making the message more accurate would silently turn a retryable
    # infrastructure failure into a permanent one.
    "openshell repository verifier exited immediately",
    "could not launch openshell repository verifier",
    "resource temporarily unavailable",
    "sandbox repository verification upload failed",
    "openshell repository verifier transport failed",
    "openshell_repository_verifier_start_failed",
    "openshell_repository_verifier_transport_failed",
)
_DETERMINISTIC_FAILURE_MARKERS = (
    "verification_contract_failed",
    "verification contract failed",
    "repo evidence requires",
    "required changed files",
    "test failures",
    "tests failed",
    "review rejected after max attempts",
)
_FAILURE_ID_RE = re.compile(
    r"\b(?:task|agent|lease|ev|review|pub|obs)_[A-Za-z0-9_-]{8,}\b",
    re.IGNORECASE,
)


def _is_timeout_blob(text: str) -> bool:
    """Return True when *text* contains a recognisable agent-run-timeout signal."""
    lowered = text.lower()
    return any(marker in lowered for marker in _TIMEOUT_BLOB_MARKERS)


def _nonnegative_int(value: Any, *, default: int = 0) -> int:
    try:
        return max(0, int(value))
    except (TypeError, ValueError):
        return default


def _is_openshell_verifier_infrastructure_failure(text: str) -> bool:
    """Identify verifier launch/transport faults without retrying test failures."""

    lowered = text.lower()
    if any(
        marker in lowered
        for marker in _OPENSHELL_VERIFIER_INFRASTRUCTURE_MARKERS
    ):
        return True
    verifier_context = (
        "openshell repository verifier" in lowered
        or "sandbox repository verification" in lowered
    )
    transport_failure = any(
        marker in lowered
        for marker in (
            "transport error",
            "connection reset",
            "connection refused",
            "no route to host",
            "service unavailable",
            "bad gateway",
            "gateway timeout",
        )
    )
    return verifier_context and transport_failure


def _blocked_attempt_retry_kind(value: Any) -> str:
    """Classify the latest block for retry policy, not root-cause analytics.

    Values are intentionally coarse: only failures likely to change when run
    again are retried. Contract/work failures stop; shared control-plane
    transport errors get one cross-worker retry and then one deduplicated
    incident; task-scope timeouts get one plan/decompose retry.
    """

    detail = ensure_json_object(value) if isinstance(value, Mapping) else {}
    blob = json_dumps(detail).lower() if detail else str(value or "").lower()
    if not blob.strip():
        return "legacy_transient"
    if any(marker in blob for marker in _DETERMINISTIC_FAILURE_MARKERS):
        return "non_retryable"
    if _is_openshell_verifier_infrastructure_failure(blob):
        return "infrastructure_transient"
    shared_transport = any(
        marker in blob for marker in _SHARED_TRANSIENT_FAILURE_MARKERS
    )
    if shared_transport or (
        ("mac api" in blob or "/evidence" in blob)
        and _is_timeout_blob(blob)
    ):
        return "shared_transient"
    if _is_timeout_blob(blob) or detail.get("returncode") == 124:
        return "timeout"
    reason = str(detail.get("reason") or "").strip().lower()
    if reason in {"heartbeat_offline", "lease_expired", "lease expired"}:
        return "transient"
    if detail.get("manual_repair_required") is True:
        return "non_retryable"
    # Unrecognised failures consume the retry budget they were granted rather
    # than bypassing it. Bad work is still stopped by the deterministic marker
    # list above, by an explicit manual_repair_required, by the repeated-
    # fingerprint gate, and by max_attempts. Returning "non_retryable" here
    # meant an infrastructure failure where the model never ran went terminal
    # at attempt 1 of 3 -- and, because attempt_count increments at claim time,
    # it burned an attempt for a sandbox that never started.
    return "transient"


def _blocked_attempt_failure_fingerprint(value: Any) -> str:
    detail = ensure_json_object(value) if isinstance(value, Mapping) else {}
    selected = {
        key: detail.get(key)
        for key in (
            "reason",
            "failure",
            "error",
            "problems",
            "returncode",
            "status_code",
        )
        if detail.get(key) not in (None, "", [], {})
    }
    normalized = json_dumps(selected or {"detail": str(value or "")}).lower()
    normalized = _FAILURE_ID_RE.sub("<id>", normalized)
    normalized = re.sub(r"\s+", " ", normalized).strip()
    return "sha256:%s" % hashlib.sha256(normalized.encode("utf-8")).hexdigest()


def _row_value(row: Any, column: str) -> Optional[str]:
    """Read a column that may not exist on an older row shape."""
    try:
        value = row[column]
    except (KeyError, IndexError, TypeError):
        return None
    return value if value in (None, "") or isinstance(value, str) else str(value)


def _non_retryable_blocked_attempt_marker(value: Any) -> Optional[str]:
    if value in (None, "", [], {}):
        return None
    if isinstance(value, (dict, list, tuple)):
        text = json_dumps(value)
    else:
        text = str(value)
    normalized = re.sub(r"\s+", " ", text.lower().replace("_", "-"))
    compact = re.sub(r"[^a-z0-9]+", "-", normalized).strip("-")
    for marker in BLOCKED_ATTEMPT_NON_RETRYABLE_DIAGNOSES:
        marker_text = marker.lower().replace("_", "-")
        marker_compact = re.sub(r"[^a-z0-9]+", "-", marker_text).strip("-")
        if marker_text in normalized or (marker_compact and marker_compact in compact):
            return marker
    return None


def _normalize_blocked_detail(detail: Optional[Dict[str, Any]]) -> JsonDict:
    """Require every new blocked-state ledger event to explain itself."""
    normalized = ensure_json_object(detail)
    if str(normalized.get("reason") or "").strip():
        return normalized
    dependencies = _metadata_string_list(
        normalized.get("blocked_by_task_ids") or normalized.get("dependencies")
    )
    if dependencies:
        normalized["reason"] = "waiting_on_dependencies"
        normalized.setdefault("blocked_by_task_ids", dependencies)
        return normalized
    if str(normalized.get("question") or normalized.get("prompt") or "").strip():
        normalized["reason"] = "operator_direction_required"
        return normalized
    if str(normalized.get("error") or "").strip():
        normalized["reason"] = "execution_error"
        return normalized
    if normalized.get("problems"):
        normalized["reason"] = "verification_problems"
        return normalized
    for key in ("failure_class", "diagnosis", "cause", "via"):
        value = str(normalized.get(key) or "").strip()
        if value:
            normalized["reason"] = value
            return normalized
    raise ValidationError(
        "blocked task transition requires a structured reason, dependency, "
        "question, error, problem, failure_class, diagnosis, cause, or via"
    )


def _failure_diagnosis(target_state: str, detail: Optional[Dict[str, Any]]) -> Optional[str]:
    """Map a block/fail transition to a glanceable 'Problem / Remediation' note.

    Failures should explain themselves ON the task (surfaced by `mac task show`/
    `summary`) instead of forcing an operator to SSH and dig through logs. Returns
    a short two-line string for the per-task activity log, or None when the
    transition is not a diagnosable failure. Signature-matched against the failure
    modes seen on the live fleets; falls back to a generic note.
    """
    if target_state not in (TaskState.BLOCKED.value, TaskState.FAILED.value):
        return None
    detail = detail or {}
    reason = str(detail.get("reason") or "").strip()
    error = str(detail.get("error") or "").strip()
    problems = detail.get("problems") or []
    problems_text = "; ".join(str(p) for p in problems) if isinstance(problems, list) else str(problems)
    blob = " ".join([reason, error, problems_text]).lower()

    def note(problem: str, remediation: str) -> str:
        return "Problem: %s\nRemediation: %s" % (problem.strip(), remediation.strip())

    if "could not clone" in blob or "authentication failed" in blob or "saml" in blob or (
        "clone" in blob and ("denied" in blob or "invalid username" in blob or "403" in blob or "sso" in blob)
    ):
        return note(
            "Repository clone/auth failed — the agent could not fetch the repo (%s)." % (error or reason or "git clone error"),
            "The fleet's git token isn't authorized for this repo/org (often SAML SSO). Provision an SSO-authorized token as GH_TOKEN (deploy with MAC_DEPLOY_GH_TOKEN) or SSO-authorize the deploy key; onboard with the https URL so the token is injected.",
        )
    if "heartbeat_offline" in blob or "lease_expired" in blob or "lease expired" in blob:
        return note(
            "Agent went offline mid-task (lease expired / heartbeat lost).",
            "Check agent<->hub connectivity (reverse tunnel), agent process health (crash/restart/OOM), or a long synchronous op (e.g. a large clone during repo-prep) blocking the heartbeat. Often transient during a deploy/restart — retry once agents are idle+healthy.",
        )
    if "timed out" in blob or "timeout" in blob or "rc=124" in blob or "returncode 124" in blob or "code: 124" in blob:
        return note(
            "Agent run timed out — the task is likely too large for one run.",
            "Raise MAC_EXECUTOR_AGENT_TIMEOUT for heavier work and/or split into child tasks (add_child_tasks / decompose-on-failure). Pre-bake slow toolchains into the sandbox image so setup doesn't consume the budget.",
        )
    if reason == "verification_contract_failed" or "refusing to push" in blob or "pushed=true" in blob or "contract" in blob:
        # ADR 0022: name the cause. This branch previously returned one
        # sentence for every contract failure -- true of all of them,
        # diagnostic of none -- and a remediation that told the agent to
        # commit and push harder, which is the wrong advice for most of the
        # causes below. 24 of 24 failures in the 24h to 2026-08-20 landed here
        # and were indistinguishable in the ledger.
        from mac.contract_failure import classify_contract_failure

        failure = classify_contract_failure(
            blob, problems_text=problems_text or "", error=error or ""
        )
        return note(
            "[%s] %s" % (failure.cause, failure.problem),
            failure.remediation,
        )
    if "review_retraction_cap_hit" in blob or "review_verdict_wait_cap_hit" in blob or "reviewer" in blob:
        return note(
            "Review never completed (reviewer unavailable or timed out).",
            "Ensure a free, fresh reviewer (don't run every agent executing at once); raise MAC_REVIEW_RETRACTION_CAP / MAC_REVIEW_VERDICT_WAIT_CAP / MAC_DEFAULT_REVIEWER_STALE_AFTER_SECONDS. Heavy reviews need the review heartbeat to stay alive.",
        )
    if "max attempt" in blob:
        return note(
            "Task failed after exhausting its retry budget (max_attempts).",
            "Inspect the per-attempt failures in history for the recurring cause; fix it, then `mac task reopen` (resets attempts) to retry, or decompose if the task is too large.",
        )
    if "dependencies_incomplete" in blob or "dependency" in blob:
        # The generic remediation below told the reader to run `mac task show`
        # -- which is the page they were already reading when they saw it. A
        # loop that hands back the same screen instead of the next step.
        #
        # A dependency block is never about THIS task. The work is in the
        # dependency, so say that, and say what to do about each way it can be
        # stuck. `task show` now names the blocking dependencies and their
        # states, so this advice has something to point at.
        return note(
            "Task %s waiting on a dependency that has not produced its output."
            % target_state,
            "This task is fine; its input is not. `mac task show` lists the "
            "blocking dependencies with their states and the join policy, and "
            "spells out the move for this task specifically. In general: fix "
            "the blocker and this task dispatches on its own; a FAILED blocker "
            "can only go to open (`mac task reopen`), not straight to "
            "cancelled; and under the default all_success join nothing but a "
            "COMPLETED dependency releases the parent, so if the blocker is "
            "hopeless cancel THIS task rather than the blocker.",
        )
    if reason or problems_text or error:
        return note(
            "Task %s: %s" % (target_state, reason or problems_text or error),
            "Inspect the task evidence + history (`mac task show`) and the agent workspace logs for the root cause.",
        )
    return note(
        "Task %s without a more specific failure description." % target_state,
        "Inspect the task evidence and history; repair the producer that omitted failure context before retrying.",
    )


_DIAG_SECRET_RE = re.compile(
    r"(?i)(\b(?:authorization|bearer|token|password|secret|api[_-]?key)\b\s*[:=]?\s*)([^\s,;]+)"
)
_DIAG_URL_AUTH_RE = re.compile(r"(https?://)([^/@\s]+)@", re.IGNORECASE)
_DIAG_KNOWN_TOKEN_RE = re.compile(r"\b(?:gh[pousr]_[A-Za-z0-9_]{12,}|sk-[A-Za-z0-9_-]{12,})\b")


def _diagnostic_output_tail(detail: Mapping[str, Any]) -> Tuple[str, str]:
    """Return a bounded, secret-redacted output tail or an explicit absence reason."""
    values: List[str] = []
    for key in (
        "output_tail",
        "stderr_tail",
        "stdout_tail",
        "stderr",
        "stdout",
        "output",
        "log_tail",
        "logs",
    ):
        value = detail.get(key)
        if value not in (None, "", [], {}):
            values.append(str(value))
    if not values:
        return "", str(
            detail.get("output_tail_unavailable_reason")
            or "transition supplied no stdout, stderr, output, log, or tail field"
        )
    text = "\n".join(values).replace("\x00", "")
    text = _DIAG_URL_AUTH_RE.sub(r"\1<redacted>@", text)
    text = _DIAG_SECRET_RE.sub(r"\1<redacted>", text)
    text = _DIAG_KNOWN_TOKEN_RE.sub("<redacted>", text)
    lines = [line.rstrip() for line in text.splitlines() if line.strip()]
    return "\n".join(lines[-20:])[-4000:], ""


def _structured_failure_diagnosis(
    target_state: str,
    detail: Mapping[str, Any],
    *,
    actor: str,
    attempt_count: int,
    resolve_output_tail: Optional[Callable[[], Tuple[str, str]]] = None,
) -> Optional[JsonDict]:
    summary = _failure_diagnosis(target_state, dict(detail))
    if not summary:
        return None
    problem = summary
    remediation = "Inspect the task evidence and history for the root cause."
    if "\nRemediation:" in summary:
        problem, remediation = summary.split("\nRemediation:", 1)
    problem = problem.removeprefix("Problem:").strip()
    output_tail, unavailable = _diagnostic_output_tail(detail)
    if not output_tail and resolve_output_tail is not None:
        # The transition detail carried no output. Before recording this
        # failure as undiagnosable, ask the caller to resolve the durable
        # stdout/stderr evidence the worker already uploaded.
        try:
            resolved, resolved_reason = resolve_output_tail()
        except Exception:  # noqa: BLE001 - diagnosis must never break a transition
            resolved, resolved_reason = "", ""
        if resolved:
            output_tail, unavailable = resolved, ""
        elif resolved_reason:
            # Report both facts: the transition carried nothing AND the durable
            # artifacts were checked. Replacing the first with the second loses
            # the primary cause.
            if not unavailable:
                unavailable = resolved_reason
            elif resolved_reason not in unavailable:
                unavailable = "%s; %s" % (unavailable, resolved_reason)
    record: JsonDict = {
        "actor": str(actor or "unknown"),
        "attempt": max(0, int(attempt_count)),
        "failure": str(detail.get("reason") or detail.get("failure_class") or target_state),
        "problem": problem,
        "remediation": remediation.strip(),
        "output_tail": output_tail,
        "output_tail_unavailable_reason": unavailable,
    }
    return record


_SCP_GIT_URL_RE = re.compile(r"^(?P<user>[^@]+@)?(?P<host>[^:/]+):(?P<path>.+)$")


def _canonicalize_git_url(url: str) -> Optional[Tuple[str, str]]:
    """Canonicalize a git remote URL to ``(host, path)`` for equivalence
    comparisons across ``git@host:path``, ``ssh://host/path``,
    ``https://host/path``, and ``git://host/path`` forms.

    Trailing ``.git`` and surrounding slashes are stripped from the path;
    the host is lowercased. Returns ``None`` if the URL is unparseable so
    callers can choose to fail-closed without crashing.
    """
    raw = (url or "").strip()
    if not raw:
        return None
    if "://" in raw:
        parsed = urllib.parse.urlsplit(raw)
        host = parsed.hostname or ""
        path = parsed.path or ""
    else:
        m = _SCP_GIT_URL_RE.match(raw)
        if not m:
            return None
        host = m.group("host") or ""
        path = m.group("path") or ""
    host = host.lower().strip()
    path = path.strip().strip("/")
    if path.endswith(".git"):
        path = path[: -len(".git")]
    if not host or not path:
        return None
    return (host, path)


REPOSITORY_CONTRACT_SCHEMA = "mac.repository_contract.v1"
REPOSITORY_CONTRACT_FILES = (
    Path(".mac") / "project.yaml",
    Path(".mac") / "project.yml",
)

#: Output signatures that mean the verification COULD NOT RUN, as opposed to
#: ran and found the change wanting.
#:
#: These are transport and environment faults of the harness itself. On
#: 2026-08-19 every review in a 90-minute window was rejected, and the signed
#: verdict for one of them ended:
#:
#:     coverage safety: statements 69300/76238 (90.90%, floor 90.00%);
#:                      branches   20216/24618 (82.12%, floor 80.00%)
#:       - Uploading files to /sandbox...
#:       + Files uploaded
#:     Error:   x ssh exited with status exit status: 1
#:
#: BOTH COVERAGE FLOORS PASSED. The gate the run exists to enforce was
#: satisfied, and the coding-agent's ssh stream then died. That exit status
#: became `rejected`, signed, and indistinguishable downstream from a reviewer
#: judging the work deficient. One task was rejected, redone more thoroughly
#: (58 tests -> 60, 2 files -> 11, ruff and a CodeGraph audit added), and
#: rejected identically, because the verdict never depended on the diff.
#: Output signatures proving the gate RAN AND JUDGED THE CHANGE WANTING.
#:
#: Checked BEFORE the unavailable signatures, and they win, because the two
#: overlap in exactly the case that matters.
#:
#: `ssh exited with status` is the generic wrapper exit printed whenever a
#: remote command returns non-zero -- it accompanies every failure through the
#: ssh transport, not only a transport fault. Listing it as "unavailable"
#: (2026-08-19, PR #478) therefore inverted the original bug instead of fixing
#: it. Before, a transport death was signed as a rejection. After, a genuine
#: rejection was swallowed as "could not verify", so NO verdict was signed and
#: the task sat in REVIEWING forever.
#:
#: Observed live on 2026-08-20: twelve `hub_verify_unavailable` events in
#: ninety minutes whose real failures were
#:     "documentation contract failed: published shell fences outside the
#:      executable book are forbidden"
#: and
#:     "documentation-inventory.md is stale: regenerate with
#:      scripts/generate-docs-reference.py --write"
#: -- both real, actionable, and both discarded. Twenty tasks accumulated in
#: REVIEWING, five of them for over a hundred hours.
#:
#: The discriminator is whether the gate reached a judgement. It is not
#: "did the gate produce output": in the #478 case the coverage gate ran and
#: PASSED before the stream died, so output alone would have called that a
#: rejection too. Only an explicit FAILING verdict counts.
#: Every entry must appear ONLY on failure. That is the whole discipline here,
#: and it is easy to get wrong in the direction that reintroduces #478:
#: `coverage safety:` was an obvious-looking candidate and is emitted whether
#: the floors pass or fail, so it would have marked the original
#: passed-then-the-stream-died run as a rejection -- exactly the bug #478
#: existed to fix. Likewise `repository contract` appears in
#: "running fail-fast repository contract preflight", which is a start
#: message, not a verdict.
#:
#: When in doubt leave a signature OUT. A missing signature means a real
#: rejection is retried as "unavailable", which wastes a run. A wrong one
#: means a transport fault is signed as a rejection, which discards correct
#: work and is what this pair of fixes is for.
_HUB_VERIFY_VERDICT_SIGNATURES: Tuple[str, ...] = (
    "documentation contract failed",
    "is stale:",
    "stale generated",
    "regenerate with",
    "contract test failed",
    " failed, ",         # pytest summary: "3 failed, 40 passed"
    "assertionerror",
    "error: process completed with exit code",
)


_HUB_VERIFY_UNAVAILABLE_SIGNATURES: Tuple[str, ...] = (
    # cursor-agent's stream transport, the observed cause
    "ssh exited with status",
    "connection reset by peer",
    "connection refused",
    "retriableerror",
    "resource_exhausted",
    # no route to run anything at all
    "no acceptable coding agent",
    "agent_binary_missing",
    "sandbox_policy_denied",
    # the harness never got far enough to test the change
    "failed to create sandbox",
    "error: could not create sandbox",
)


def hub_verification_unavailable_reason(output: str) -> Optional[str]:
    """The signature saying this run could not verify anything, if present.

    Returning a reason means "we do not know whether the change is good" --
    which must NOT be recorded as a rejection. A signature over "rejected" is
    a claim the evidence does not support, and downstream nothing can tell it
    apart from a real verdict.

    Deliberately narrow. An unrecognised failure stays a rejection, because
    treating unknown failures as infrastructure would let a genuinely broken
    change pass through as "could not verify" and retry forever -- failing
    open on the gate this exists to enforce.
    """
    text = (output or "").lower()
    # A gate that judged the change wanting is a REJECTION, whatever the
    # transport did afterwards. Checked first because the two sets overlap:
    # a real contract failure still exits through ssh and still prints
    # "ssh exited with status".
    for verdict in _HUB_VERIFY_VERDICT_SIGNATURES:
        if verdict in text:
            return None
    for signature in _HUB_VERIFY_UNAVAILABLE_SIGNATURES:
        if signature in text:
            return signature
    return None


def _hub_review_failure_excerpt(output: str, *, head: int = 2000, tail: int = 1500) -> str:
    """Keep the head AND the tail of a rejected verification's output.

    The tail alone was kept, and the tail of a pytest run is its summary line:
    "36 failed, 84 passed, 588 errors". That says the gate failed, which the
    verdict already said. WHY it failed is announced once, at the top -- an
    unprovisionable database, a bootstrap that never finished, a collection
    error -- and 500 characters of tail cannot reach it.

    Diagnosing one such rejection took a hub-side archaeology session that
    ended in the evidence being gone: the sandbox that produced it had been
    cleaned up, and nothing else recorded the run.
    """

    text = (output or "").strip()
    if len(text) <= head + tail:
        return text
    omitted = len(text) - head - tail
    return "%s\n... [%d chars omitted] ...\n%s" % (
        text[:head],
        omitted,
        text[-tail:],
    )


#: Where the reason for a failure is announced, in the order a run prints it.
#: "short test summary info" is pytest's own answer to "what failed"; the rest
#: are the verdict signatures, so anything the classifier can act on is kept.
_HUB_VERIFY_FAILURE_ANCHORS: Tuple[str, ...] = (
    "short test summary info",
) + _HUB_VERIFY_VERDICT_SIGNATURES


def _hub_verify_output_excerpt(
    output: str, *, head: int = 1500, window: int = 2000, tail: int = 1000
) -> str:
    """Keep the head, the TAIL, and the part that says why the run failed.

    Head-and-tail is not enough here, which is the trap this replaced a blind
    tail with. A failing contract run prints, in order: a session header,
    several hundred lines of pytest progress, the failure and its summary, a
    whole-repo coverage report (one row per source file, ~14KB), a coverage
    line whose floors both PASSED, and -- last -- OpenShell's generic
    "ssh exited with status 1". The verdict sits in the middle, out of reach
    of both ends, so a fixed head and tail preserve the two regions that say
    nothing and drop the only one that does.

    Position is the wrong selector. Anchor on the text that announces the
    failure and keep a window around its LAST occurrence, so the excerpt still
    carries a verdict signature after truncation and a rejection stays
    classifiable as a rejection.
    """

    text = (output or "").strip()
    if len(text) <= head + window + tail:
        return text

    spans = [(0, head), (len(text) - tail, len(text))]
    lowered = text.lower()
    found = [lowered.rfind(a) for a in _HUB_VERIFY_FAILURE_ANCHORS]
    anchor_at = max(found)
    if anchor_at >= 0:
        start = max(0, anchor_at - window // 4)
        spans.append((start, min(len(text), start + window)))

    merged: List[Tuple[int, int]] = []
    for start, end in sorted(spans):
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))

    parts: List[str] = []
    previous = 0
    for start, end in merged:
        if start > previous:
            parts.append("... [%d chars omitted] ..." % (start - previous))
        parts.append(text[start:end])
        previous = end
    return "\n".join(parts)


VERIFICATION_SCHEMA = "mac.worker_evidence.v1"
#: Marker recorded on a task that was approved but has no publication
#: destination, so the task itself says why it is sitting in REVIEWING instead
#: of leaving the reason in a code comment (task_ce6c8ea3).
PUBLICATION_BLOCK_SCHEMA = "mac.publication_block.v1"
_GIT_SHA_RE = re.compile(r"^[0-9a-fA-F]{7,64}$")
_FULL_GIT_OBJECT_ID_RE = re.compile(r"^(?:[0-9a-f]{40}|[0-9a-f]{64})$")


def _git_step_returncode(result: Mapping[str, Any]) -> int:
    """Read a git step's exit code without turning success into failure.

    ``int(result.get("returncode") or 1)`` reads as "1 when it is missing", but
    ``0 or 1`` is ``1`` -- so it reported EVERY successful git command as a
    failure. That silently disabled the merge queue's speculative base: the
    first `cat-file -e` on a commit we already had looked like a miss, the
    fetch that followed had no branch to fetch, and speculation fell back to
    deferring forever.
    """

    value = result.get("returncode", 1)
    return 1 if value is None else int(value)


class _PublicationAnchorMissingError(ValidationError):
    """The reviewed commit does not exist in the repository.

    PERMANENT, and that is the whole point of giving it a type. Publication
    treats every failure as transient and retries on the next sweep, which is
    right for a network blip, a lease conflict or a full queue window. It is
    wrong for a SHA that will never resolve -- a deleted branch, an unpushed
    commit, a collected object.

    Measured on the live hub 2026-08-19: one task in this state produced 498 of
    the 787 publish_failed events in three hours. With MAC_REVIEW_TICK_LIMIT=5
    and a 30-second sweep, it consumed the publication worker at roughly 600
    attempts an hour while nothing else published, and burned 1,962,501 tokens
    carrying the signal high_token_work_without_publication.

        git publication verify_commit failed:
        fatal: Not a valid object name 3a88fef069db...^{commit}

    A permanent failure retried at full rate is not just wasted work; it is a
    denial of service against every other task in the sweep.
    """

    publication_failure_kind = "reviewed_commit_missing"


class _PublicationBaseMovedError(ValidationError):
    """The canonical ref moved after a disposable publication was prepared."""

    def __init__(self, expected_sha: str, observed_sha: str) -> None:
        self.expected_sha = str(expected_sha)
        self.observed_sha = str(observed_sha)
        super().__init__(
            "git publication canonical branch moved while the tested candidate "
            "was being published: expected %s, observed %s"
            % (self.expected_sha, self.observed_sha)
        )


# Sandbox git preflight for hub verification. The repo is tar-uploaded into the
# sandbox, so its files can be owned by a different uid than the user running
# the tests (HOME=/tmp guarantees no .gitconfig safe.directory whitelist).
# Without this, git refuses the uploaded repo ("dubious ownership") and the
# contract tests that run `git` against the checkout itself fail — rejecting
# work whose tests pass everywhere else. GIT_CONFIG_* env (not --global) so the
# whitelist reaches every git subprocess the suite spawns without a writable
# HOME; the rev-parse probe distinguishes a lost-.git upload from a test
# failure with an unmistakable message and exit code.
_HUB_VERIFY_GIT_PREFLIGHT = (
    "export GIT_CONFIG_COUNT=1 GIT_CONFIG_KEY_0=safe.directory GIT_CONFIG_VALUE_0='*'; "
    "git -C /sandbox/repo rev-parse --is-inside-work-tree >/dev/null 2>&1 || "
    "{ echo 'hub verify: /sandbox/repo is not a usable git repo after upload"
    " (missing .git or git unavailable)'; exit 97; }; "
)
# mac-5xwh: bd issue ids look like ``<prefix>-<slug>`` where the slug
# may itself contain dashes (e.g. ``mac-defer-claim``). Reject anything
# that could be misread as a CLI flag (leading ``-``) or that contains
# whitespace, redirects, or quoting metacharacters.
_BEAD_ID_RE = re.compile(r"^[A-Za-z][A-Za-z0-9_]*-[A-Za-z0-9_][A-Za-z0-9_\-]*$")

# Bytes of cleartext attestation key per agent. 256 bits of HMAC key is
# overkill for the threat model but fits in one stretch of base64 and
# keeps the door closed if HMAC-SHA256 ever becomes the bottleneck.
ATTESTATION_KEY_BYTES = 32


def _serialize_runtime_source_publication(function: Callable[..., Optional[JsonDict]]):
    """Order mutation of the deployed checkout against fleet epoch creation."""

    @functools.wraps(function)
    def wrapped(
        self: "ControlPlane",
        task_id: str,
        target: str,
        evidence_id: str,
    ) -> Optional[JsonDict]:
        if target not in {"git://main", "git://origin/main"}:
            return function(self, task_id, target, evidence_id)
        if not self._publication_targets_runtime_source(task_id):
            return function(self, task_id, target, evidence_id)
        # Hold the barrier only long enough to READ it. It used to wrap the
        # publication itself, and a publication runs a contract gate in a
        # sandbox for 45-90 minutes.
        #
        # Thread dump taken on the hub mid-hang, 2026-08-14:
        #
        #   one thread:  publish_task -> validate_projected_merge_contract
        #                -> _hub_verify_run_contract_test -> subprocess wait
        #                (holding _PUBLICATION_BARRIER_THREAD_LOCK)
        #   seven more:  publish_task -> publication_serialization (blocked),
        #                one of them the hub TICK thread
        #
        # The waiters occupy the request threadpool, /health stops being
        # answered, the supervisor restarts the process after its probes fail,
        # and the in-flight gate dies without recording anything. 147
        # consecutive failed probes and 225 restarts were logged before this
        # was found; every publication attempt in this session died that way.
        #
        # The docstring of publication_serialization already says the epoch row
        # "remains the durable barrier after this short creation critical
        # section ends" -- so the long tail never needed the lock. The read is
        # what must be atomic against epoch creation.
        with self.fleet_release_epochs.publication_serialization():
            barrier = self.fleet_release_epochs.active_publication_barrier()
        if barrier is not None:
            raise PublicationDeferredError(
                "git publication is deferred while fleet release epoch %s is %s"
                % (barrier["epoch_id"], barrier["state"]),
                barrier=barrier,
            )
        return function(self, task_id, target, evidence_id)

    return wrapped


def _generate_attestation_key() -> str:
    """Mint a fresh per-agent HMAC key. Returned base64url so it fits
    in a single env var or JSON string without escaping."""
    import secrets as _secrets

    return base64.urlsafe_b64encode(_secrets.token_bytes(ATTESTATION_KEY_BYTES)).decode("ascii").rstrip("=")


# ---------------------------------------------------------------------------
# Legacy single-task publication: conflict-to-integration context payload.
#
# When the merge-gate (``mac.merge_queue.validate_projected_merge``) reports a
# textual conflict for an approved single-task publication, the task cannot
# fast-forward onto the moving canonical ``main`` tip. Rather than silently
# abort, the legacy publisher hands the conflict to an *integration executor*
# (rebase / resolve / re-verify). That executor needs context: which task was
# approved, the reviewed head it approved, the evidence receipt, the current
# canonical baseline, the attempt base it diverged from, exactly which paths
# conflict, and — the expensive part — which already-landed commits/tasks
# touched those same paths between the attempt base and current ``main``.
#
# ``build_conflict_integration_payload`` assembles that context as a pure,
# unit-testable function returning a ``JsonDict``. It is deliberately isolated
# from ControlPlane state: the only I/O it performs is through an injected
# ``git_runner`` shaped exactly like ``ControlPlane._git_output`` (returns a
# dict with ``returncode``/``stdout``/``stderr``), so it can be exercised
# against a real temporary repo without a database or a full control plane.
#
# It records *raw intent/evidence pointers* and leaves the semantic
# supersession decision to the integration executor as an explicit field
# (``supersession.decision`` defaults to ``"undecided"``); precedence is NEVER
# inferred from commit timestamps here. Current ``main`` is always preserved as
# the canonical baseline of the payload.
# ---------------------------------------------------------------------------

# Optional commit trailer an integration executor may read to correlate a
# landed commit back to the MAC task that produced it. Absent by default; when
# present it is surfaced as a raw pointer only (never used to infer precedence).
_MAC_TASK_TRAILER_RE = re.compile(
    r"^\s*Mac-Task-Id:\s*(?P<task_id>\S+)\s*$", re.MULTILINE
)


def _landed_commits_touching_paths(
    git_runner: "Callable[[List[str], int], JsonDict]",
    base_sha: str,
    main_sha: str,
    conflicted_paths: Sequence[str],
) -> List[JsonDict]:
    """Return raw commit pointers for commits in ``base_sha..main_sha`` that
    touched any of ``conflicted_paths``.

    Uses ``git log`` restricted to the conflicted paths (path-restricted
    ``rev-list`` semantics). Each entry carries only raw pointers — sha,
    subject, author, author-date, and any ``Mac-Task-Id`` trailer — so callers
    can present provenance without inferring precedence. Returns ``[]`` when
    the range or paths cannot be resolved; the builder records the failure
    separately rather than raising, so a conflict payload is always producible.
    """
    if not base_sha or not main_sha:
        return []
    paths = [str(path) for path in conflicted_paths if str(path).strip()]
    if not paths:
        return []
    # Record separator keeps commit records unambiguous even if a subject or
    # body contains newlines; %x1f (unit separator) delimits fields.
    record_sep = "\x1e"
    field_sep = "%x1f"
    fmt = field_sep.join(["%H", "%an", "%aI", "%s", "%b"])
    args = [
        "log",
        "%s..%s" % (base_sha, main_sha),
        "--no-merges",
        "--format=%s%s" % (record_sep, fmt),
        "--",
        *paths,
    ]
    result = git_runner(args, 60)
    if int(result.get("returncode", 1)) != 0:
        return []
    stdout = str(result.get("stdout") or "")
    commits: List[JsonDict] = []
    for raw in stdout.split(record_sep):
        raw = raw.strip("\n")
        if not raw:
            continue
        fields = raw.split("\x1f")
        if len(fields) < 4:
            continue
        sha, author, author_date, subject = fields[0], fields[1], fields[2], fields[3]
        body = fields[4] if len(fields) > 4 else ""
        trailer = _MAC_TASK_TRAILER_RE.search(body)
        commits.append(
            {
                "sha": sha.strip(),
                "author": author.strip(),
                "author_date": author_date.strip(),
                "subject": subject.strip(),
                "task_id": trailer.group("task_id").strip() if trailer else None,
            }
        )
    return commits


def build_conflict_integration_payload(
    *,
    approved_task_id: str,
    accepted_evidence_id: str,
    reviewed_head_sha: str,
    current_main_sha: str,
    attempt_base_sha: str,
    conflicted_paths: Sequence[str],
    depends_on: Optional[Sequence[str]] = None,
    git_runner: "Optional[Callable[[List[str], int], JsonDict]]" = None,
    supersession_decision: str = "undecided",
    superseded_task_id: Optional[str] = None,
    superseded_by_task_id: Optional[str] = None,
) -> JsonDict:
    """Assemble the context-rich integration payload for an approved-but-
    conflicting *legacy single-task* publication.

    This is a pure builder (aside from the optional injected ``git_runner``):
    it captures raw pointers and computed provenance and returns a ``JsonDict``.
    It does NOT mutate the repository, the database, or the REVIEWING flow, and
    it makes no semantic precedence decision.

    The payload records:

    * ``approved_task`` — the approved task id, its accepted evidence id, and
      the reviewed head SHA the reviewer approved.
    * ``canonical_baseline`` — the current canonical ``main`` tip, always
      preserved as the baseline the integration must land on.
    * ``attempt_base_sha`` — the base the attempt diverged from
      (``runtime.repository_base_sha``).
    * ``conflicted_paths`` — the conflicted paths from
      ``MergeGateVerdict.conflicted_files``.
    * ``landed_since_base`` — the set of commits (and any correlated task ids)
      between the attempt base and current ``main`` that touched the conflicted
      paths, computed via a path-restricted ``git log``.
    * ``dependencies`` — explicit *terminal* prerequisites supplied by the
      caller.  The approved task is an input authority, not a lifecycle
      dependency: it deliberately remains REVIEWING until this integration
      repair succeeds, so adding it here would deadlock the repair.
    * ``supersession`` — an explicit decision field the integration executor
      sets. Defaults to ``"undecided"``; timestamps are never used to infer
      precedence here.

    ``git_runner`` is shaped like ``ControlPlane._git_output`` — called as
    ``git_runner(args, timeout)`` and returning a dict with
    ``returncode``/``stdout``/``stderr``. When omitted, provenance is left
    empty and flagged as uncomputed, keeping the builder usable in contexts
    without repository access.
    """
    if not approved_task_id or not str(approved_task_id).strip():
        raise ValidationError("conflict integration payload requires approved_task_id")
    if not accepted_evidence_id or not str(accepted_evidence_id).strip():
        raise ValidationError(
            "conflict integration payload requires accepted_evidence_id"
        )
    if not _GIT_SHA_RE.match(str(reviewed_head_sha).strip()):
        raise ValidationError(
            "conflict integration payload requires a git reviewed_head_sha"
        )
    if not _GIT_SHA_RE.match(str(current_main_sha).strip()):
        raise ValidationError(
            "conflict integration payload requires a git current_main_sha"
        )
    if not _GIT_SHA_RE.match(str(attempt_base_sha).strip()):
        raise ValidationError(
            "conflict integration payload requires a git attempt_base_sha"
        )

    normalized_paths = coerce_list(
        str(path).strip() for path in (conflicted_paths or []) if str(path).strip()
    )
    if not normalized_paths:
        raise ValidationError(
            "conflict integration payload requires at least one conflicted path"
        )

    supersession = ensure_json_object(None)
    decision = str(supersession_decision or "undecided").strip() or "undecided"
    if decision not in {"undecided", "supersede", "coexist", "abandon"}:
        raise ValidationError(
            "conflict integration payload supersession decision must be one of "
            "undecided/supersede/coexist/abandon"
        )
    supersession = {
        # Explicit, integration-executor-owned decision. Never inferred from
        # commit timestamps in this builder.
        "decision": decision,
        "superseded_task_id": (
            str(superseded_task_id).strip() if superseded_task_id else None
        ),
        "superseded_by_task_id": (
            str(superseded_by_task_id).strip() if superseded_by_task_id else None
        ),
        "decided": decision != "undecided",
        "policy": "explicit_only_no_timestamp_inference",
    }

    provenance_computed = git_runner is not None
    landed = (
        _landed_commits_touching_paths(
            git_runner,
            str(attempt_base_sha).strip(),
            str(current_main_sha).strip(),
            normalized_paths,
        )
        if git_runner is not None
        else []
    )
    landed_task_ids = coerce_list(
        commit["task_id"] for commit in landed if commit.get("task_id")
    )

    payload: JsonDict = {
        "schema": "mac.conflict_integration_payload.v1",
        "kind": "legacy_single_task_publication_conflict",
        "approved_task": {
            "task_id": str(approved_task_id).strip(),
            "accepted_evidence_id": str(accepted_evidence_id).strip(),
            "reviewed_head_sha": str(reviewed_head_sha).strip(),
        },
        # Current main is ALWAYS the canonical baseline the integration lands on.
        "canonical_baseline": {
            "ref": "main",
            "main_sha": str(current_main_sha).strip(),
        },
        "attempt_base_sha": str(attempt_base_sha).strip(),
        "conflicted_paths": normalized_paths,
        "landed_since_base": {
            "computed": provenance_computed,
            "base_sha": str(attempt_base_sha).strip(),
            "main_sha": str(current_main_sha).strip(),
            "commits": landed,
            "task_ids": landed_task_ids,
        },
        "dependencies": {
            # Only terminal prerequisites belong in the scheduler dependency
            # set.  ``approved_task`` above records the non-terminal input
            # authority without making the repair wait for the very task it
            # must unblock.
            "depends_on": coerce_list(depends_on or []),
        },
        "supersession": supersession,
    }
    return payload


def _contract_mapping(value: Any, field: str) -> JsonDict:
    if not isinstance(value, dict):
        raise ValidationError("%s must be an object" % field)
    return value


def _contract_string(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ValidationError("%s must be a non-empty string" % field)
    return value.strip()


def _contract_string_list(value: Any, field: str, *, required: bool = True) -> List[str]:
    if value is None and not required:
        return []
    if not isinstance(value, list):
        raise ValidationError("%s must be a list of strings" % field)
    strings = []
    for item in value:
        if not isinstance(item, str) or not item.strip():
            raise ValidationError("%s must contain only non-empty strings" % field)
        strings.append(item.strip())
    if required and not strings:
        raise ValidationError("%s must not be empty" % field)
    return strings


def _contract_relative_paths(value: Any, field: str) -> List[str]:
    paths = _contract_string_list(value, field, required=False)
    for raw_path in paths:
        candidate = Path(raw_path)
        if candidate.is_absolute() or ".." in candidate.parts:
            raise ValidationError("%s entries must be relative paths inside the repository" % field)
    return paths


def _repository_contract_root(repo_path: Path) -> Path:
    expanded = repo_path.expanduser()
    if not expanded.exists():
        raise ValidationError("project repository path does not exist: %s" % repo_path)
    return expanded if expanded.is_dir() else expanded.parent


_ONBOARDING_REMOTE_URL_RE = re.compile(r"^(https://|git@|ssh://|git://)\S+$")
DEFAULT_PROJECT_BRANCH = "main"
# Work with no product repository still needs a scope. A NULL project is not a
# semantic -- it is an escape hatch: task_lifecycle's gate reads
# `project_registered = task.project is None or project_record is not None`, so
# an unscoped task bypasses BOTH the registered-project requirement and the
# operator dispatch_paused switch. It is also invisible to every per-project
# view and report. Giving fleet-maintenance work a real, registered project
# makes it countable, reportable and -- most importantly -- pausable, which is
# the only lever that can stop self-generated work crowding out product work.
FLEET_MAINTENANCE_PROJECT = "fleet-maintenance"


def _normalize_onboarding_remote_url(value: str) -> str:
    """Light validation of a git remote URL for onboarding (the worker
    re-validates strictly with its own regex before cloning)."""
    url = (value or "").strip()
    if not url or url.startswith("-"):
        raise ValidationError("repository_url is empty or looks like a flag: %r" % value)
    if len(url) > 2048:
        raise ValidationError("repository_url exceeds 2048 byte limit")
    if not _ONBOARDING_REMOTE_URL_RE.match(url):
        raise ValidationError(
            "repository_url must be an https://, git@, ssh:// or git:// git remote: %r" % value
        )
    return url


def _normalize_repository_registration(
    value: str,
    *,
    default_branch: Optional[str] = None,
) -> Tuple[str, str, str]:
    """Normalize ``GIT_URL[#BRANCH]`` into URL, branch, and canonical form.

    A fragment is a registration selector, not part of the Git transport URL.
    ``main`` is deliberately the boring default so project registration has one
    deterministic identity without probing a remote.
    """

    registration = str(value or "").strip()
    url_value = registration
    fragment_branch: Optional[str] = None
    if "#" in registration:
        url_value, fragment_branch = registration.rsplit("#", 1)
        url_value = url_value.strip()
        fragment_branch = fragment_branch.strip()
        if not fragment_branch:
            raise ValidationError("repository registration branch after # is required")

    explicit_branch = str(default_branch or "").strip() or None
    if (
        fragment_branch is not None
        and explicit_branch is not None
        and fragment_branch != explicit_branch
    ):
        raise ValidationError(
            "repository registration branch %r conflicts with default_branch %r"
            % (fragment_branch, explicit_branch)
        )
    branch = fragment_branch or explicit_branch or DEFAULT_PROJECT_BRANCH
    try:
        branch = validate_git_ref(branch)
    except ValueError as exc:
        raise ValidationError("repository registration branch is invalid: %s" % exc) from exc

    url = _normalize_onboarding_remote_url(url_value)
    return url, branch, "%s#%s" % (url, branch)


def _repository_name_from_url(url: str) -> str:
    """Derive a short project/repo name from a git remote URL.

    ``https://github.com/NVIDIA-dev/taskbrain.git`` -> ``taskbrain``;
    ``git@github.com:NVIDIA-dev/taskbrain.git``     -> ``taskbrain``.
    """
    tail = url.rstrip("/").split("/")[-1]
    if "/" not in tail and ":" in tail:  # scp-style git@host:org/repo with no extra slash
        tail = tail.split(":")[-1]
    if tail.endswith(".git"):
        tail = tail[:-4]
    name = "".join(ch if (ch.isalnum() or ch in "-_.") else "-" for ch in tail).strip("-._")
    return name or "project"


def _project_registration_from_metadata(
    metadata: Mapping[str, Any],
) -> Optional[Tuple[str, str, str]]:
    repository_url = str(metadata.get("repository_url") or "").strip()
    registration = str(metadata.get("repository_registration") or "").strip()
    if not registration and not repository_url:
        return None
    branch = str(metadata.get("default_branch") or "").strip() or None
    return _normalize_repository_registration(
        registration or repository_url,
        default_branch=branch,
    )


def _build_onboarding_description(url: str, repo_name: str) -> str:
    return "\n".join(
        [
            "Repository onboarding for %s (%s)." % (repo_name, url),
            "",
            "MAC has cloned a clean, writable checkout for you at $MAC_TASK_REPO_WORKTREE (a task branch). Work entirely there.",
            "This is READ-ONLY with respect to the remote: do NOT push or open a pull request. You MAY write local analysis files in the checkout (notably .mac/project.yaml).",
            "If CodeGraph is available, initialize it for local API/code behavior analysis with `codegraph init`; `.codegraph/` is generated local state and must not be committed or included as a deliverable.",
            "",
            "Start from the repo's own self-description. Read these files first if they exist and treat them as authoritative for intent, not just for code: README.md (what it is / how to build), AGENTS.md (instructions for AI agents working here), and PLAN.md (roadmap / planned work). Fold what they say into the deliverables below; do not contradict them without explaining why.",
            "",
            "ENVIRONMENT CONTRACT (derive before authoring the repository contract):",
            "  Run `from mac.environment_contract import derive_environment_contract, validate_environment_contract`",
            "  or call the CLI equivalent to statically analyse the checkout and emit the environment contract",
            "  (schema mac.environment_contract.v1).  The contract captures:",
            "    - runtime_versions: node_min / python_min / pnpm_min derived from engines, packageManager,",
            "      .nvmrc, .node-version, pyproject.toml, setup.cfg, lockfile headers.",
            "    - native_build.required: True when binding.gyp, Cargo.toml, go.mod, CMakeLists.txt,",
            "      or a known-native npm package (e.g. @vscode/sqlite3, better-sqlite3, sharp) is present.",
            "    - egress.hosts: registry URLs from .npmrc / lockfiles, plus nodejs.org when native_build.",
            "  After derivation, call validate_environment_contract() to run preflight checks against the",
            "  current sandbox.  If preflight.status == 'fail', report the precise error and STOP — do not",
            "  attempt install/build steps that will fail for the same root cause.",
            "  Include the full environment contract JSON in your evidence.",
            "",
            "Deliverables — report all of these in your evidence (evidence_type=investigation):",
            "  1. A concise summary of what the project does and its architecture (languages, frameworks, key modules, entry points), grounded in README.md/AGENTS.md/PLAN.md where present.",
            "  2. How to build it and run its tests, inferred from the repo's own manifests/CI and README — not guessed.",
            "  3. The environment contract (mac.environment_contract.v1) derived from static analysis of the checkout.",
            "  4. An authored repository contract written to .mac/project.yaml using schema mac.repository_contract.v1 (keys: schema, project, platforms, toolchain.required_commands, bootstrap.command, test.command, evidence.required). Include its full content in the evidence.",
            "  5. A prioritized backlog of 5-10 concrete next steps, improvements, or risks you observe. If PLAN.md exists, reconcile your backlog against it (what is already planned vs. newly surfaced).",
        ]
    )


def _load_repository_contract(repo_path: Path) -> JsonDict:
    root = _repository_contract_root(repo_path)
    checked = []
    for relative in REPOSITORY_CONTRACT_FILES:
        candidate = root / relative
        checked.append(str(relative))
        if not candidate.exists():
            continue
        try:
            raw = yaml.safe_load(candidate.read_text(encoding="utf-8"))
        except yaml.YAMLError as exc:
            raise ValidationError("repository runtime contract is invalid YAML: %s: %s" % (candidate, exc)) from exc
        try:
            contract_path = str(candidate.relative_to(root))
        except ValueError:
            contract_path = str(candidate)
        return _normalize_repository_contract(raw, contract_path)
    raise ValidationError(
        "repository runtime contract not found under %s; expected one of: %s"
        % (root, ", ".join(checked))
    )


def _tail_text(value: str, limit: int = 4000) -> str:
    if len(value) <= limit:
        return value
    return value[-limit:]


def _ensure_codegraph_git_exclude(repo_path: Path) -> Optional[str]:
    git = shutil.which("git")
    if git is None:
        return None
    try:
        result = subprocess.run(
            [git, "rev-parse", "--git-path", "info/exclude"],
            cwd=str(repo_path),
            check=False,
            capture_output=True,
            text=True,
            timeout=15,
        )
    except (OSError, subprocess.TimeoutExpired):
        return None
    if result.returncode != 0 or not result.stdout.strip():
        return None
    exclude_path = Path(result.stdout.strip())
    if not exclude_path.is_absolute():
        exclude_path = repo_path / exclude_path
    try:
        exclude_path.parent.mkdir(parents=True, exist_ok=True)
        existing = exclude_path.read_text(encoding="utf-8") if exclude_path.exists() else ""
        lines = {line.strip() for line in existing.splitlines()}
        if ".codegraph/" not in lines:
            suffix = "" if existing.endswith("\n") or not existing else "\n"
            exclude_path.write_text(existing + suffix + ".codegraph/\n", encoding="utf-8")
    except OSError:
        return None
    return str(exclude_path)


def _resolve_codegraph_binary() -> Optional[str]:
    found = shutil.which("codegraph")
    if found:
        return found
    home = Path.home()
    candidates: List[Path] = []
    mac_home = os.environ.get("MAC_HOME")
    if mac_home:
        candidates.append(Path(mac_home).expanduser() / "bin" / "codegraph")
    candidates.extend(
        [
            home / ".mac" / "bin" / "codegraph",
            home / ".codegraph" / "bin" / "codegraph",
            home / ".local" / "bin" / "codegraph",
            home / ".cargo" / "bin" / "codegraph",
            home / "bin" / "codegraph",
            Path("/opt/homebrew/bin/codegraph"),
            Path("/usr/local/bin/codegraph"),
        ]
    )
    for candidate in candidates:
        try:
            if candidate.is_file() and os.access(candidate, os.X_OK):
                return str(candidate)
        except OSError:
            continue
    return None


def _initialize_codegraph_repository(repo_path: Path) -> JsonDict:
    status: JsonDict = {
        "schema": "mac.codegraph_init.v1",
        "command": "codegraph init",
        "attempted": False,
        "initialized": False,
    }
    if not repo_path.exists() or not repo_path.is_dir():
        status["reason"] = "repository_path_not_directory"
        return status
    git = shutil.which("git")
    if git is None:
        status["reason"] = "git_unavailable"
        return status
    try:
        inside = subprocess.run(
            [git, "rev-parse", "--is-inside-work-tree"],
            cwd=str(repo_path),
            check=False,
            capture_output=True,
            text=True,
            timeout=15,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        status["reason"] = "git_probe_failed"
        status["error"] = str(exc)
        return status
    if inside.returncode != 0 or inside.stdout.strip() != "true":
        status["reason"] = "not_git_worktree"
        if inside.stderr.strip():
            status["stderr"] = _tail_text(inside.stderr)
        return status
    codegraph = _resolve_codegraph_binary()
    if codegraph is None:
        status["reason"] = "codegraph_unavailable"
        return status
    status["binary"] = codegraph
    status["git_exclude"] = _ensure_codegraph_git_exclude(repo_path)
    status["attempted"] = True
    try:
        result = subprocess.run(
            [codegraph, "init"],
            cwd=str(repo_path),
            check=False,
            capture_output=True,
            text=True,
            timeout=300,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        status["reason"] = "codegraph_init_failed"
        status["error"] = str(exc)
        return status
    status["returncode"] = result.returncode
    if result.stdout:
        status["stdout"] = _tail_text(result.stdout)
    if result.stderr:
        status["stderr"] = _tail_text(result.stderr)
    if result.returncode == 0:
        status["initialized"] = True
    else:
        status["reason"] = "codegraph_init_nonzero"
    return status


def _raise_for_codegraph_init_failure(status: JsonDict) -> None:
    if not status.get("attempted") or status.get("initialized"):
        return
    reason = str(status.get("reason") or "codegraph_init_failed")
    detail = str(status.get("stderr") or status.get("stdout") or status.get("error") or "").strip()
    if detail:
        detail = ": " + _tail_text(detail, limit=500)
    raise ValidationError("codegraph init failed (%s)%s" % (reason, detail))


def _normalize_repository_contract(raw: Any, contract_path: str) -> JsonDict:
    data = _contract_mapping(raw, "repository runtime contract")
    schema = _contract_string(data.get("schema"), "repository runtime contract.schema")
    if schema != REPOSITORY_CONTRACT_SCHEMA:
        raise ValidationError(
            "repository runtime contract.schema must be %s" % REPOSITORY_CONTRACT_SCHEMA
        )
    project = _contract_string(data.get("project"), "repository runtime contract.project")
    platforms = _contract_string_list(data.get("platforms"), "repository runtime contract.platforms")
    toolchain = _contract_mapping(data.get("toolchain"), "repository runtime contract.toolchain")
    bootstrap = _contract_mapping(data.get("bootstrap"), "repository runtime contract.bootstrap")
    test = _contract_mapping(data.get("test"), "repository runtime contract.test")
    evidence = _contract_mapping(data.get("evidence"), "repository runtime contract.evidence")
    canonical_remote_url_raw = data.get("canonical_remote_url")
    canonical_remote_url: Optional[str] = None
    if canonical_remote_url_raw is not None:
        canonical_remote_url = _contract_string(
            canonical_remote_url_raw,
            "repository runtime contract.canonical_remote_url",
        )
        try:
            canonical_remote_url = validate_secret_free_git_remote(
                canonical_remote_url
            )
        except ValueError as exc:
            raise ValidationError(
                "repository runtime contract.canonical_remote_url must not embed "
                "credentials and must be a secret-free git URL: %r"
                % canonical_remote_url
            ) from exc
    default_branch_raw = data.get("default_branch")
    canonical_branch_raw = data.get("canonical_branch")
    default_branch: Optional[str] = DEFAULT_PROJECT_BRANCH
    if default_branch_raw is not None or canonical_branch_raw is not None:
        default_branch = _contract_string(
            default_branch_raw
            if default_branch_raw is not None
            else canonical_branch_raw,
            "repository runtime contract.default_branch",
        )
        if canonical_branch_raw is not None:
            canonical_branch = _contract_string(
                canonical_branch_raw,
                "repository runtime contract.canonical_branch",
            )
            if canonical_branch != default_branch:
                raise ValidationError(
                    "repository runtime contract default_branch and "
                    "canonical_branch must match"
                )
        try:
            default_branch = validate_git_ref(default_branch)
        except ValueError as exc:
            raise ValidationError(
                "repository runtime contract.default_branch is invalid: %s" % exc
            ) from exc
    normalized = {
        "schema": schema,
        "project": project,
        "contract_path": contract_path,
        "canonical_remote_url": canonical_remote_url,
        "platforms": platforms,
        "toolchain": {
            "required_commands": _contract_string_list(
                toolchain.get("required_commands"),
                "repository runtime contract.toolchain.required_commands",
            ),
        },
        "bootstrap": {
            "command": _contract_string(
                bootstrap.get("command"),
                "repository runtime contract.bootstrap.command",
            ),
            "creates": _contract_relative_paths(
                bootstrap.get("creates"),
                "repository runtime contract.bootstrap.creates",
            ),
        },
        "test": {
            "command": _contract_string(test.get("command"), "repository runtime contract.test.command"),
        },
        "evidence": {
            "required": _contract_string_list(
                evidence.get("required"),
                "repository runtime contract.evidence.required",
            ),
        },
    }
    normalized["default_branch"] = default_branch
    return normalized


def _canonicalize_for_signature(manifest: Dict[str, Any]) -> bytes:
    """Deterministic JSON encoding of the verification manifest for
    HMAC signing.

    mac-wu3f: include ``signed_by`` in the canonical form so the
    signer identity is cryptographically bound into the MAC. Previously
    ``signed_by`` was excluded — a captured signature could be replayed
    in a manifest with a different ``signed_by``, and verification
    (which keys off the new ``signed_by``) might still pass if both
    agents shared a key. The ``signature`` field is still excluded
    because it's the output, not the input.
    """
    excluded = {"signature"}
    filtered = {k: v for k, v in manifest.items() if k not in excluded}
    return json_dumps(filtered).encode("utf-8")


def _hub_review_verify_enabled(environ: Optional[Mapping[str, str]] = None) -> bool:
    """Option C: hub runs the review contract test itself (one controlled
    sandbox) instead of dispatching to a reviewer agent. Off by default; the
    hub deploy sets MAC_REVIEW_HUB_VERIFY=1."""
    env = os.environ if environ is None else environ
    return str(env.get("MAC_REVIEW_HUB_VERIFY") or "").strip().lower() in {"1", "true", "yes", "on"}


HUB_REVIEW_VERIFIER_RESOURCE_SCHEMA = "mac.hub_review_verifier.v1"
DEFAULT_HUB_REVIEWER_AGENT_NAME = "hub-reviewer"
DEFAULT_HUB_REVIEWER_AGENT_ID = "agent_hub-reviewer"
DEFAULT_HUB_REVIEWER_MACHINE_ID = "machine_operator_review"
REVIEWER_INDEPENDENCE_REASONS = frozenset(
    {
        "reviewer_cooperative_family_participant",
        "reviewer_previously_owned_task",
        "reviewer_created_executor_evidence",
        "reviewer_same_persona",
    }
)


def sign_verification_manifest(key: str, manifest: Dict[str, Any]) -> str:
    """Sign ``manifest`` with the agent's attestation key. Returns the
    base64url HMAC tag. Exposed for the worker (writes signatures) and
    for tests (constructs signed evidence fixtures)."""
    import hmac as _hmac
    import hashlib as _hashlib

    digest = _hmac.new(
        key.encode("ascii"), _canonicalize_for_signature(manifest), _hashlib.sha256
    ).digest()
    return "v1:" + base64.urlsafe_b64encode(digest).decode("ascii").rstrip("=")


def verify_verification_manifest_signature(
    key: str, manifest: Dict[str, Any], signature: str
) -> bool:
    """Constant-time HMAC verification. Returns True iff ``signature``
    matches the expected tag for ``manifest`` under ``key``."""
    import hmac as _hmac

    if not signature or not signature.startswith("v1:"):
        return False
    expected = sign_verification_manifest(key, manifest)
    return _hmac.compare_digest(expected, signature)


