    def workflow_runs_summary(self) -> JsonDict:
        """Counts grouped by state plus the 20 most recent runs for the
        dashboard. Designed to be inlined into /dashboard/state without
        adding a separate read query path."""
        rows = self.store.query_all(
            "SELECT state, COUNT(*) AS count FROM workflow_runs GROUP BY state"
        )
        by_state = {row["state"]: int(row["count"]) for row in rows}
        latest = [
            run.to_dict()
            for run in self.workflow_runtime.list_runs(limit=20)
        ]
        return {
            "counts": by_state,
            "total": sum(by_state.values()),
            "latest": latest,
        }

    def _materialize_openclaw_execution_task(
        self,
        *,
        title: str,
        description: str,
        metadata: Dict[str, Any],
        idempotency_key: Optional[str] = None,
    ) -> Task:
        """Auto-materialize the minimal MAC task an OpenClaw direct execution needs.

        Current review/pre-push gates are keyed by ``task_id``. When a direct
        Slack/OpenClaw code request begins, this transparently creates the
        backing bookkeeping task so those gates can run. It is system
        bookkeeping created automatically at execution start, not a manual
        task-filing prerequisite or an extra conversational step.
        """

        return self.create_task(
            title,
            description=description,
            metadata=metadata,
            actor="openclaw",
            idempotency_key=idempotency_key,
            _idempotency_scope="openclaw-direct-execution",
        )

    def create_interaction_task(
        self,
        hermes_instance_id: str,
        title: str,
        user_id: Optional[str] = None,
        platform_binding_id: Optional[str] = None,
        conversation_ref: Optional[str] = None,
        description: str = "",
        project: Optional[str] = None,
        priority: int = 0,
        required_capabilities: Optional[Iterable[str]] = None,
        dependencies: Optional[Iterable[str]] = None,
        metadata: Optional[Dict[str, Any]] = None,
        max_attempts: int = 3,
        actor: str = "hermes",
        idempotency_key: Optional[str] = None,
        _idempotency_scope: Optional[str] = None,
    ) -> Task:
        instance = self.get_hermes_instance(hermes_instance_id)
        if user_id:
            user = self.get_user(user_id)
            if user.tenant_id != instance.tenant_id:
                raise ValidationError("interaction user must belong to hermes instance tenant")
        if platform_binding_id:
            binding = self.get_platform_binding(platform_binding_id)
            if binding.tenant_id != instance.tenant_id or binding.hermes_instance_id != instance.id:
                raise ValidationError("platform binding must belong to hermes instance")
        task_metadata = ensure_json_object(metadata)
        task_metadata.setdefault(
            "origin",
            {
                "type": "hermes_interaction",
                "tenant_id": instance.tenant_id,
                "user_id": user_id,
                "hermes_instance_id": instance.id,
                "persona_id": instance.persona_id,
                "platform_binding_id": platform_binding_id,
                "conversation_ref": conversation_ref,
            },
        )
        task_metadata.setdefault(
            "memory_boundary",
            {
                "hermes_is_authoritative_for_personality": True,
                "hermes_is_authoritative_for_user_memory": True,
                "mac_records_operational_provenance_only": True,
            },
        )
        return self.create_task(
            title,
            description=description,
            project=project,
            priority=priority,
            required_capabilities=required_capabilities,
            dependencies=dependencies,
            metadata=task_metadata,
            max_attempts=max_attempts,
            actor=actor,
            idempotency_key=idempotency_key,
            _idempotency_scope=_idempotency_scope,
        )

    # Task ledger

    def _ensure_fleet_maintenance_project(self) -> None:
        """Idempotently register the reserved scope for unscoped work.

        The projects table needs only a name, so this does not go through
        register_project (which is Git-backed and mints a contract-authoring
        task). Failure is swallowed: a task must still be creatable if the
        registry write races or the column set predates this.
        """

        try:
            existing = self.store.query_one(
                "SELECT id FROM projects WHERE name = ?", (FLEET_MAINTENANCE_PROJECT,)
            )
            if existing is not None:
                return
            now = utcnow()
            self.store.execute(
                "INSERT INTO projects (id, name, description, metadata, status, "
                "created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?) "
                "ON CONFLICT(name) DO NOTHING",
                (
                    new_id("proj"),
                    FLEET_MAINTENANCE_PROJECT,
                    "Fleet self-maintenance: work with no product repository. "
                    "Pause this project to stop the fleet generating and running "
                    "work about itself.",
                    json_dumps({"fleet_maintenance": True}),
                    "active",
                    now,
                    now,
                ),
            )
        except Exception:  # noqa: BLE001 - never block task creation on this
            return

    def _resolve_task_project(self, project: Optional[str]) -> Optional[str]:
        """Every task gets a scope; unscoped work lands in fleet-maintenance."""

        resolved = str(project or "").strip()
        if resolved:
            return resolved
        if not _truthy_env("MAC_SCOPE_UNPROJECTED_TASKS", "1"):
            return None
        self._ensure_fleet_maintenance_project()
        return FLEET_MAINTENANCE_PROJECT

    def _apply_project_task_defaults(
        self,
        project: Optional[str],
        required_capabilities: List[str],
        metadata: Dict[str, Any],
    ) -> Tuple[List[str], JsonDict]:
        normalized = ensure_json_object(metadata)
        caps = list(required_capabilities)
        if not project:
            return caps, normalized
        try:
            record = self.get_project_record(project)
        except NotFoundError:
            return caps, normalized
        project_meta = ensure_json_object(record.metadata)
        defaults = project_meta.get("task_defaults")
        if not isinstance(defaults, dict):
            return caps, normalized

        role = str(defaults.get("role") or "").strip()
        if role and not str(normalized.get("required_role") or "").strip():
            try:
                self.roles.get_role(role)
            except NotFoundError as exc:
                raise ValidationError(
                    "unknown project default role for %s: %s" % (project, role)
                ) from exc
            normalized["required_role"] = role

        default_caps = defaults.get("required_capabilities")
        if not caps and isinstance(default_caps, list):
            caps = [str(item).strip() for item in default_caps if str(item).strip()]

        # Capability policy (untrusted LLM input guard): when a project pins
        # an allow-list of hard runtime capabilities, any requested capability
        # outside it (e.g. domain/language labels like "typescript",
        # "frontend", "design" hallucinated by Hermes) is stripped from the
        # scheduler's hard requirements and preserved as domain context so the
        # task stays claimable while keeping the LLM's classification intent.
        allowed_caps = defaults.get("allowed_capabilities")
        if caps and isinstance(allowed_caps, list):
            allowed = [str(item).strip() for item in allowed_caps if str(item).strip()]
            allowed_set = set(allowed)
            accepted: List[str] = []
            filtered: List[str] = []
            for cap in caps:
                (accepted if cap in allowed_set else filtered).append(cap)
            if filtered:
                existing_domain = normalized.get("domain_capabilities")
                domain = list(existing_domain) if isinstance(existing_domain, list) else []
                for cap in filtered:
                    if cap not in domain:
                        domain.append(cap)
                normalized["domain_capabilities"] = domain
                normalized["capability_policy"] = {
                    "source": "project.task_defaults.allowed_capabilities",
                    "allowed": allowed,
                    "accepted": accepted,
                    "filtered": filtered,
                }
            caps = accepted
        return caps, normalized

    def _decouple_repository_commands_from_capabilities(
        self,
        required_capabilities: List[str],
        metadata: Dict[str, Any],
    ) -> Tuple[List[str], JsonDict]:
        normalized = ensure_json_object(metadata)
        required_commands = _repository_required_commands_from_metadata(normalized)
        if not required_commands:
            return list(required_capabilities), normalized

        command_set = set(required_commands)
        kept: List[str] = []
        filtered: List[str] = []
        for capability in required_capabilities:
            cap = str(capability).strip()
            if not cap:
                continue
            if cap in command_set:
                filtered.append(cap)
            else:
                kept.append(cap)

        toolchain = ensure_json_object(normalized.get("toolchain_requirements"))
        toolchain.update(
            {
                "schema": "mac.task_toolchain_requirements.v1",
                "source": "repository_contract.toolchain.required_commands",
                "required_commands": required_commands,
            }
        )
        if filtered:
            toolchain["filtered_from_required_capabilities"] = filtered
        normalized["toolchain_requirements"] = toolchain
        return kept, normalized

    @staticmethod
    def _reject_reserved_break_glass_metadata(metadata: Dict[str, Any]) -> None:
        runtime = ensure_json_object(metadata.get("runtime"))
        if (
            "break_glass_authorization" in runtime
            or "break_glass_authorization" in metadata
            or "execution_boundary" in metadata
        ):
            raise ValidationError(
                "break-glass execution metadata is control-plane-owned; "
                "use the admin break-glass authorization API"
            )
        if any(
            key in metadata
            for key in (
                "managed_fast_lane",
            )
        ):
            raise ValidationError(
                "publication route metadata is control-plane-owned"
            )

    def _single_task_fast_lane_shape(
        self,
        *,
        metadata: Mapping[str, Any],
        dependencies: Sequence[str],
        workflow_run_id: Optional[str],
    ) -> JsonDict:
        """Classify only an explicitly atomic, strong repository mutation.

        ``no_decompose`` is the operator's assertion that one worker mutation
        node is sufficient.  The controller still declares conservative
        repository-wide exclusivity; it never infers fine-grained writes from
        prose.  Tasks outside this shape retain the grandfathered legacy path.
        """

        contract = ensure_json_object(metadata.get("execution_contract"))
        origin = ensure_json_object(metadata.get("origin"))
        relationships = ensure_json_object(metadata.get("relationships"))
        checks = (
            (bool(metadata.get("no_decompose")), "task_not_declared_atomic"),
            (not dependencies, "task_dependencies_require_planning"),
            (not workflow_run_id, "workflow_task_uses_workflow_runtime"),
            (
                str(contract.get("type") or "") == "repository"
                and str(contract.get("quality") or "") == "strong",
                "strong_repository_contract_required",
            ),
            (
                bool(str(contract.get("repository_id") or "").strip()),
                "registered_repository_required",
            ),
            (not metadata_declares_report_deliverable(metadata), "report_task_is_not_a_repository_mutation"),
            (not bool(origin.get("onboarding")), "repository_onboarding_uses_legacy_bootstrap"),
            (
                not bool(
                    relationships.get("parent_task_id")
                    or relationships.get("child_task_ids")
                ),
                "cooperative_task_requires_managed_plan_admission",
            ),
        )
        blockers = [reason for passed, reason in checks if not passed]
        return {
            "eligible": not blockers,
            "blockers": blockers,
            "repository_id": str(contract.get("repository_id") or "").strip(),
        }



    def _reserve_task_create_idempotency(
        self,
        *,
        key: str,
        scope: str,
        request: Mapping[str, Any],
        actor: str,
    ) -> str:
        """Bind a caller retry key to one canonical task identity and intent."""

        exact_key = str(key or "").strip()
        if not exact_key:
            raise ValidationError("task create idempotency key must not be empty")
        if len(exact_key) > 200:
            raise ValidationError(
                "task create idempotency key may contain at most 200 characters"
            )
        exact_scope = str(scope or "").strip()
        if not exact_scope:
            raise ValidationError("task create idempotency scope must not be empty")
        if len(exact_scope) > 1000:
            raise ValidationError(
                "task create idempotency scope may contain at most 1000 characters"
            )
        scope_digest = hashlib.sha256(exact_scope.encode("utf-8")).hexdigest()
        key_digest = hashlib.sha256(exact_key.encode("utf-8")).hexdigest()
        try:
            request_digest = hashlib.sha256(
                json_dumps(dict(request)).encode("utf-8")
            ).hexdigest()
        except (TypeError, ValueError) as exc:
            raise ValidationError(
                "task create idempotency request must be JSON serializable"
            ) from exc
        task_id = "task_%s" % hashlib.sha256(
            (scope_digest + ":" + key_digest).encode("ascii")
        ).hexdigest()[:32]
        with self.store.transaction() as conn:
            conn.execute(
                "INSERT INTO task_create_idempotency ("
                "scope_digest, key_digest, request_digest, task_id, created_by, created_at"
                ") VALUES (?, ?, ?, ?, ?, ?) "
                "ON CONFLICT(scope_digest, key_digest) DO NOTHING",
                (
                    scope_digest,
                    key_digest,
                    request_digest,
                    task_id,
                    str(actor or "human"),
                    utcnow(),
                ),
            )
            row = conn.execute(
                "SELECT request_digest, task_id FROM task_create_idempotency "
                "WHERE scope_digest = ? AND key_digest = ?",
                (scope_digest, key_digest),
            ).fetchone()
            if row is None:
                raise ValidationError("task create idempotency reservation failed")
            if str(row["request_digest"]) != request_digest:
                raise ValidationError(
                    "task create idempotency key is already bound to a different request"
                )
            return str(row["task_id"])



    @property
    def generator_yield_gate(self) -> "GeneratorYieldGate":
        """The measured yield gate, constructed once per control plane."""

        gate = getattr(self, "_generator_yield_gate", None)
        if gate is None:
            gate = GeneratorYieldGate(self.store)
            self._generator_yield_gate = gate
        return gate

    def _enforce_generator_yield(self, metadata: Any) -> None:
        """Refuse a filing from a generator whose measured yield is too low.

        Records the suppression before raising: a generator that silently
        stopped filing would be indistinguishable from one that had nothing
        to file, which is how the low-yield generators went unnoticed for six
        weeks in the first place.
        """

        try:
            self.generator_yield_gate.enforce(metadata)
        except GeneratorSuppressed as exc:
            origin_type = generator_origin_type_of(metadata)
            try:
                self.record_log(
                    "task.generator_suppressed",
                    level="warning",
                    detail={
                        "origin_type": origin_type,
                        "verdict": self.generator_yield_gate.evaluate(origin_type),
                        "message": str(exc),
                    },
                )
            except Exception:  # noqa: BLE001 - reporting must not mask the refusal
                pass
            raise

    def generator_yield_report(self) -> JsonDict:
        """Every task origin's filed/completed record and gate standing."""

        gate = self.generator_yield_gate
        return {
            "schema": GENERATOR_YIELD_SCHEMA,
            "floor": gate.policy.floor,
            "min_sample": gate.policy.min_sample,
            "enabled": gate.policy.enabled,
            "origins": gate.report(),
        }

    def create_task(
        self,
        title: str,
        description: str = "",
        project: Optional[str] = None,
        priority: int = 0,
        required_capabilities: Optional[Iterable[str]] = None,
        dependencies: Optional[Iterable[str]] = None,
        metadata: Optional[Dict[str, Any]] = None,
        max_attempts: int = 3,
        actor: str = "human",
        idempotency_key: Optional[str] = None,
        # WHO filed this, as opposed to which agent runs it. The column and the
        # Human principal both already existed; nothing ever wrote to it, so
        # the ledger could say "who is running this" and not "whose task is
        # this".
        created_by_human: Optional[str] = None,
        _task_id: Optional[str] = None,
        _workflow_run_id: Optional[str] = None,
        _workflow_node_key: Optional[str] = None,
        _idempotency_scope: Optional[str] = None,
    ) -> Task:
        title = title.strip()
        if not title:
            raise ValidationError("task title is required")
        supplied_metadata = metadata if isinstance(metadata, Mapping) else {}
        if (
            normalize_execution_mode(supplied_metadata.get("execution_mode"))
            == EXECUTION_MODE_SYNC
            and not str(supplied_metadata.get("target_agent_id") or "").strip()
            and not str(supplied_metadata.get("target_agent_name") or "").strip()
        ):
            # Refused at the door as well as in the allocator. A sync task is a
            # barrier on ONE agent, and untargeted there is no answer to "all
            # tasks on what?" that is not either a guess or a fleet-wide
            # stop-the-world.
            raise ValidationError(
                "a synchronous task must name its agent: set "
                "metadata.target_agent_id (or target_agent_name). Without one, "
                "'wait for all tasks to complete' is ambiguous between a single "
                "worker and the whole fleet."
            )
        resolved_human: Optional[str] = None
        if created_by_human:
            requested_human = str(created_by_human).strip()
            if requested_human:
                # Store the stable human id, never the typed username. A
                # username is an external anchor that can change; a task's
                # record of who filed it must not silently re-point at
                # somebody else when it does.
                try:
                    resolved_human = self.get_human_by_username(requested_human).id
                except NotFoundError:
                    try:
                        resolved_human = self.get_human(requested_human).id
                    except NotFoundError:
                        raise ValidationError(
                            "no such human %r: register them first "
                            "(`mac admin user ...`) so task ownership points at "
                            "a real principal rather than a free-text string"
                            % requested_human
                        ) from None
        dependency_refs = coerce_list(dependencies)
        supplied_task_id = str(_task_id or "").strip()
        if supplied_task_id and any(
            supplied_task_id == dependency_ref
            or supplied_task_id.startswith(dependency_ref)
            for dependency_ref in dependency_refs
        ):
            raise ValidationError("task cannot depend on itself")
        dep_ids = self._canonical_dependency_ids(dependency_refs)
        requested_capabilities = coerce_list(required_capabilities)
        requested_metadata = ensure_json_object(metadata)
        for dep_id in dep_ids:
            self.get_task(dep_id)
        if bool(_workflow_run_id) != bool(_workflow_node_key):
            raise ValidationError(
                "workflow-linked task creation requires both run id and node key"
            )
        self._reject_reserved_break_glass_metadata(requested_metadata)
        # An automated generator whose filed work does not complete stops
        # filing. This is the single choke point every generator passes
        # through, so a generator added later is gated by default rather than
        # having to remember to opt in. Human-filed origins are exempt --
        # see mac.generator_yield.HUMAN_ORIGIN_TYPES.
        self._enforce_generator_yield(requested_metadata)
        if idempotency_key is not None:
            if _task_id is not None:
                raise ValidationError(
                    "task create idempotency key cannot be combined with a supplied task id"
                )
            task_id = self._reserve_task_create_idempotency(
                key=idempotency_key,
                scope=(
                    _idempotency_scope
                    or "control-plane-actor:%s" % str(actor or "human")
                ),
                request={
                    "schema": "mac.task_create_request.v1",
                    "title": title,
                    "description": str(description or ""),
                    "project": project,
                    "priority": int(priority),
                    "required_capabilities": requested_capabilities,
                    "dependencies": dep_ids,
                    "metadata": requested_metadata,
                    "max_attempts": int(max_attempts),
                    "actor": str(actor or "human"),
                    "workflow_run_id": _workflow_run_id,
                    "workflow_node_key": _workflow_node_key,
                },
                actor=actor,
            )
            existing_retry = self.store.query_one(
                "SELECT id FROM tasks WHERE id = ?", (task_id,)
            )
            if existing_retry is not None:
                return self.get_task(task_id)
        else:
            task_id = str(_task_id or new_id("task")).strip()
        if not task_id:
            raise ValidationError("task id is required")
        if task_id in dep_ids:
            raise ValidationError("task cannot depend on itself")

        now = utcnow()
        state = TaskState.WAITING.value if dep_ids else TaskState.OPEN.value
        project = self._resolve_task_project(project)
        task_capabilities, task_metadata = self._apply_project_task_defaults(
            project,
            requested_capabilities,
            requested_metadata,
        )
        normalized_metadata = self._normalize_task_execution_contract(
            task_metadata,
            project,
            task_capabilities,
        )
        task_capabilities, normalized_metadata = self._decouple_repository_commands_from_capabilities(
            task_capabilities,
            normalized_metadata,
        )
        if self.directives.enabled:
            execution_contract = ensure_json_object(
                normalized_metadata.get("execution_contract")
            )
            origin = ensure_json_object(normalized_metadata.get("origin"))
            repository_id = str(
                execution_contract.get("repository_id")
                or origin.get("repository_id")
                or normalized_metadata.get("repository_id")
                or ""
            ).strip() or None
            normalized_metadata["directive_snapshot"] = self.directives.effective_snapshot(
                repository_id=repository_id,
                project=project,
            )
        fast_lane_shape = self._single_task_fast_lane_shape(
            metadata=normalized_metadata,
            dependencies=dep_ids,
            workflow_run_id=_workflow_run_id,
        )
        if fast_lane_shape["eligible"]:
            normalized_metadata["managed_fast_lane"] = {
                "schema": "mac.managed_single_task.route.v1",
                "activation": "legacy_compatibility",
            }
        normalized_metadata, optimizer_assignment = self.optimizer.prepare_task_assignment(
            task_id,
            project,
            normalized_metadata,
        )
        created = False
        with self.store.transaction() as conn:
            existing = conn.execute(
                "SELECT workflow_run_id, workflow_node_key FROM tasks WHERE id = ?",
                (task_id,),
            ).fetchone()
            if existing is not None:
                if _task_id is None and idempotency_key is None:
                    raise ValidationError("task already exists: %s" % task_id)
                if (
                    str(existing["workflow_run_id"] or "")
                    != str(_workflow_run_id or "")
                    or str(existing["workflow_node_key"] or "")
                    != str(_workflow_node_key or "")
                ):
                    raise ValidationError(
                        "idempotent workflow task id %s belongs to a different run or node"
                        % task_id
                    )
            else:
                inserted = conn.execute(
                    """
                    INSERT INTO tasks (
                        id, title, description, project, priority, state,
                        required_capabilities, dependencies, metadata,
                        owner_agent_id, lease_id, leased_until, attempt_count,
                        max_attempts, started_at, completed_at, created_at, updated_at,
                        workflow_run_id, workflow_node_key, created_by_human
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, NULL, NULL, 0, ?, NULL, NULL, ?, ?, ?, ?, ?)
                    ON CONFLICT(id) DO NOTHING
                    """,
                    (
                        task_id,
                        title,
                        description,
                        project,
                        int(priority),
                        state,
                        json_dumps(task_capabilities),
                        json_dumps(dep_ids),
                        json_dumps(normalized_metadata),
                        int(max_attempts),
                        now,
                        now,
                        _workflow_run_id,
                        _workflow_node_key,
                        resolved_human,
                    ),
                )
                if inserted.rowcount == 0:
                    existing = conn.execute(
                        "SELECT workflow_run_id, workflow_node_key FROM tasks WHERE id = ?",
                        (task_id,),
                    ).fetchone()
                    if (
                        _task_id is None
                        and idempotency_key is None
                    ) or existing is None:
                        raise ValidationError("task already exists: %s" % task_id)
                    if (
                        str(existing["workflow_run_id"] or "")
                        != str(_workflow_run_id or "")
                        or str(existing["workflow_node_key"] or "")
                        != str(_workflow_node_key or "")
                    ):
                        raise ValidationError(
                            "idempotent workflow task id %s belongs to a different run or node"
                            % task_id
                        )
                else:
                    replace_task_edges(
                        conn,
                        task_id=task_id,
                        dependency_ids=dep_ids,
                        updated_at=now,
                    )
                    creation_detail = {
                        "title": title,
                        "required_capabilities": task_capabilities,
                        "dependencies": dep_ids,
                        "execution_contract_type": (
                            normalized_metadata.get("execution_contract", {}).get("type")
                            if isinstance(normalized_metadata.get("execution_contract"), dict)
                            else None
                        ),
                    }
                    self._record_history(
                        task_id,
                        "task.created",
                        actor,
                        None,
                        state,
                        creation_detail,
                        conn=conn,
                    )
                    if optimizer_assignment is not None:
                        self.optimizer.insert_assignment(conn, optimizer_assignment)
                    created = True
        if (
            created
            and isinstance(normalized_metadata.get("execution_contract"), dict)
            and normalized_metadata["execution_contract"].get("quality") == "weak"
        ):
            self.record_log(
                "task.execution_contract.weak",
                layer="control_plane",
                source=actor,
                level="warning",
                subject_type="task",
                subject_id=task_id,
                detail={
                    "project": project,
                    "required_capabilities": task_capabilities,
                    "reason": normalized_metadata["execution_contract"].get("reason"),
                },
            )
        return self.get_task(task_id)

    def register_project(
        self,
        repository_url: str,
        *,
        project: Optional[str] = None,
        default_branch: Optional[str] = None,
        title: Optional[str] = None,
        priority: int = 0,
        required_capabilities: Optional[Iterable[str]] = None,
        actor: str = "human",
    ) -> Task:
        """Register a Git-backed project and create its contract-authoring task.

        Creates one read-only *onboarding* task whose ``metadata.origin`` carries
        the remote URL + ``type=direct_task`` — enough for a worker to clone a
        task-owned worktree (see ``worker._repository_task_origin``) *without* a
        pre-existing ``repository_contract``. The agent then analyses the
        checkout and authors ``.mac/project.yaml`` (the contract), after which
        every later task on the project is fully contract-backed
        (``_normalize_task_execution_contract`` attaches it automatically).

        This is the "take a Git URL and register a project" entry point: the
        contract is the onboarding task's *output*, not a precondition.
        """
        url, branch, registration = _normalize_repository_registration(
            repository_url,
            default_branch=default_branch,
        )
        repo_name = _repository_name_from_url(url)
        default_project = (
            repo_name
            if branch == DEFAULT_PROJECT_BRANCH
            else "%s@%s" % (repo_name, branch)
        )
        project = (project or default_project).strip() or default_project
        origin: JsonDict = {
            "type": "direct_task",
            "repository_url": url,
            "repository_registration": registration,
            "repository_name": repo_name,
            "default_branch": branch,
            "onboarding": True,
        }
        metadata: JsonDict = {
            "origin": origin,
            # Drives the weak execution-contract's evidence_type so the
            # verification gate expects an investigation write-up, not a push.
            "evidence_type": "investigation",
        }
        # Register a first-class project record so onboard and create converge:
        # the repo URL becomes durable project state (surfaced by `project
        # list`/`show`), not just task metadata. Idempotent by project name.
        self._ensure_registered_project_record(
            project,
            registration,
            actor=actor,
        )
        resolved_title = (
            title
            or "Register %s: analyze, summarize, and author the repository contract"
            % repo_name
        ).strip()
        return self.create_task(
            resolved_title,
            description=_build_onboarding_description(url, repo_name),
            project=project,
            priority=priority,
            required_capabilities=required_capabilities,
            metadata=metadata,
            actor=actor,
        )

    def _assert_project_registration_available(
        self,
        repository_url: str,
        branch: str,
        *,
        exclude_project_id: Optional[str] = None,
    ) -> None:
        try:
            requested_remote = canonical_git_remote_identity(repository_url)
        except ValueError as exc:
            raise ValidationError(
                "repository registration URL is invalid: %s" % exc
            ) from exc
        for record in self.list_project_records():
            if exclude_project_id and record.id == exclude_project_id:
                continue
            identity = _project_registration_from_metadata(
                ensure_json_object(record.metadata)
            )
            if identity is None:
                continue
            existing_url, existing_branch, existing_registration = identity
            try:
                same_remote = canonical_git_remote_identity(existing_url) == (
                    requested_remote
                )
            except ValueError:
                continue
            if same_remote and existing_branch == branch:
                raise ValidationError(
                    "repository registration %s is already owned by project %s"
                    % (existing_registration, record.name)
                )

    def _ensure_registered_project_record(
        self,
        project: str,
        repository_registration: str,
        *,
        actor: str = "human",
    ) -> ProjectRecord:
        """Create or augment the ``projects`` record for a Git registration.

        New records carry ``repository_url`` (+ optional ``default_branch``) in
        metadata and are left ACTIVE on purpose: onboarding creates a single
        read-only analysis task that must dispatch so the repo gets analyzed.
        (``create``'s default-paused staging is the different case of seeding a
        backlog of work tickets.) For a pre-existing record we only *fill in* a
        missing repository_url/default_branch and never touch its dispatch
        state, so re-onboarding is idempotent and operator intent is preserved.
        """
        repository_url, branch, registration = _normalize_repository_registration(
            repository_registration
        )
        try:
            existing = self.get_project_record(project)
        except NotFoundError:
            existing = None
        self._assert_project_registration_available(
            repository_url,
            branch,
            exclude_project_id=existing.id if existing is not None else None,
        )
        if existing is None:
            metadata: JsonDict = {
                "repository_url": repository_url,
                "default_branch": branch,
                "repository_registration": registration,
                "onboarding": True,
            }
            return self.create_project(
                project,
                metadata=metadata,
                actor=actor,
                dispatch_paused=False,
            )
        md = ensure_json_object(existing.metadata)
        current_url = str(md.get("repository_url") or "").strip()
        current_branch = str(
            md.get("default_branch") or DEFAULT_PROJECT_BRANCH
        ).strip()
        if current_url:
            current_url, current_branch, _ = _normalize_repository_registration(
                str(md.get("repository_registration") or current_url),
                default_branch=current_branch,
            )
            try:
                same_remote = canonical_git_remote_identity(current_url) == (
                    canonical_git_remote_identity(repository_url)
                )
            except ValueError as exc:
                raise ValidationError(
                    "existing project repository URL is invalid: %s" % exc
                ) from exc
            if not same_remote or current_branch != branch:
                raise ValidationError(
                    "project %s is already registered as %s#%s; use a distinct "
                    "project name for the internal fork %s"
                    % (project, current_url, current_branch, registration)
                )
        changed = any(
            md.get(key) != value
            for key, value in (
                ("repository_url", repository_url),
                ("default_branch", branch),
                ("repository_registration", registration),
            )
        )
        md["repository_url"] = repository_url
        md["default_branch"] = branch
        md["repository_registration"] = registration
        if not changed:
            return existing
        return self.update_project(existing.id, metadata=md, actor=actor)

    @staticmethod
    def _read_only_report_evidence_override_paths(metadata: Mapping[str, Any]) -> List[str]:
        paths: List[str] = []

        def collect(value: Any, path: str) -> None:
            if isinstance(value, Mapping):
                for key, item in value.items():
                    child_path = "%s.%s" % (path, key)
                    if key in {"evidence_type", "expected_evidence_type"}:
                        paths.append(child_path)
                    collect(item, child_path)
            elif isinstance(value, list):
                for index, item in enumerate(value):
                    collect(item, "%s[%d]" % (path, index))

        collect(metadata, "metadata")
        return sorted(paths)

    @staticmethod
    def _validated_read_only_report_repository_contract(
        value: Any,
        *,
        field: str,
    ) -> JsonDict:
        """Validate the immutable repository identity needed by report workers.

        The normal repository-contract loader intentionally supports older
        contracts that predate an explicit canonical branch. A read-only report
        cannot use those compatibility fallbacks: both executor and independent
        reviewer must clone the same remote, branch, and test policy from the one
        current execution contract.
        """

        if not isinstance(value, Mapping):
            raise ValidationError("%s must be an object" % field)
        contract = json_loads(json_dumps(dict(value)), {})
        if contract.get("schema") != REPOSITORY_CONTRACT_SCHEMA:
            raise ValidationError(
                "%s.schema must be %s" % (field, REPOSITORY_CONTRACT_SCHEMA)
            )
        remote = str(contract.get("canonical_remote_url") or "").strip()
        if not remote:
            raise ValidationError("%s.canonical_remote_url is required" % field)
        try:
            remote = validate_secret_free_git_remote(remote)
            canonical_git_remote_identity(remote)
        except ValueError as exc:
            raise ValidationError(
                "%s.canonical_remote_url is invalid: %s" % (field, exc)
            ) from exc
        default_branch = str(contract.get("default_branch") or "").strip()
        canonical_branch = str(contract.get("canonical_branch") or "").strip()
        if default_branch and canonical_branch and default_branch != canonical_branch:
            raise ValidationError(
                "%s default_branch and canonical_branch contradict each other" % field
            )
        branch = default_branch or canonical_branch
        if not branch:
            raise ValidationError(
                "%s.default_branch (or canonical_branch) is required" % field
            )
        try:
            branch = validate_git_ref(branch)
        except ValueError as exc:
            raise ValidationError("%s branch is invalid: %s" % (field, exc)) from exc
        test = contract.get("test")
        if not isinstance(test, Mapping) or not str(test.get("command") or "").strip():
            raise ValidationError("%s.test.command is required" % field)
        contract["canonical_remote_url"] = remote
        contract["default_branch"] = branch
        contract.pop("canonical_branch", None)
        return contract

    def _normalize_read_only_report_execution_contract(
        self,
        metadata: Mapping[str, Any],
        project: Optional[str],
    ) -> JsonDict:
        """Persist exactly one current repository contract for a report task."""

        normalized = ensure_json_object(metadata)
        override_paths = self._read_only_report_evidence_override_paths(normalized)
        if override_paths:
            raise ValidationError(
                "read-only repository reports forbid evidence-type overrides: %s"
                % ", ".join(override_paths)
            )

        origin = ensure_json_object(normalized.get("origin"))
        raw_execution = normalized.get("execution_contract")
        if raw_execution is not None and not isinstance(raw_execution, Mapping):
            raise ValidationError(
                "read-only repository reports require execution_contract to be an object"
            )
        execution = ensure_json_object(raw_execution)
        if execution and str(execution.get("type") or "").strip().lower() != "repository":
            raise ValidationError(
                "read-only repository reports require a repository execution contract"
            )

        explicit_contracts: List[Tuple[str, JsonDict]] = []
        for field, container, key in (
            (
                "metadata.execution_contract.repository_contract",
                execution,
                "repository_contract",
            ),
            ("metadata.origin.repository_contract", origin, "repository_contract"),
            ("metadata.repository_contract", normalized, "repository_contract"),
        ):
            if key not in container:
                continue
            value = container.get(key)
            if not isinstance(value, Mapping):
                raise ValidationError("%s must be an object" % field)
            explicit_contracts.append((field, ensure_json_object(value)))

        repo = self._repository_for_project(project)
        if repo is not None:
            current = self._validated_read_only_report_repository_contract(
                ensure_json_object(repo.metadata).get("repository_contract"),
                field="registered repository contract",
            )
            for field, explicit in explicit_contracts:
                if json_dumps(explicit) != json_dumps(current):
                    raise ValidationError(
                        "%s contradicts the current registered repository contract"
                        % field
                    )
            if execution.get("repository_id") not in {None, "", repo.id}:
                raise ValidationError(
                    "metadata.execution_contract.repository_id contradicts the "
                    "current registered repository"
                )
            if execution.get("repository_path") not in {None, "", repo.path}:
                raise ValidationError(
                    "metadata.execution_contract.repository_path contradicts the "
                    "current registered repository"
                )
            contract = current
            canonical_execution: JsonDict = {
                "schema": "mac.task_execution_contract.v1",
                "type": "repository",
                "quality": "strong",
                "source": "registered_project",
                "repository_id": repo.id,
                "repository_path": repo.path,
                "repository_contract": contract,
            }
            for key, expected in (
                ("repository_id", repo.id),
                ("repository_path", repo.path),
            ):
                if key in origin and str(origin.get(key) or "") != expected:
                    raise ValidationError(
                        "metadata.origin.%s contradicts the current registered repository"
                        % key
                    )
            origin.update(
                {
                    "type": "direct_task",
                    "repository_id": repo.id,
                    "repository_name": repo.name,
                    "repository_path": repo.path,
                    "source": repo.source,
                }
            )
            acc_metadata = ensure_json_object(normalized.get("acc_metadata"))
            acc_metadata.setdefault("workflow_role", "work")
            acc_metadata["repository_contract_schema"] = contract["schema"]
            acc_metadata["repository_contract_project"] = contract.get("project")
            normalized["acc_metadata"] = acc_metadata
        else:
            if not execution:
                raise ValidationError(
                    "read-only repository reports require the current "
                    "execution_contract.repository_contract"
                )
            raw_contract = execution.get("repository_contract")
            contract = self._validated_read_only_report_repository_contract(
                raw_contract,
                field="metadata.execution_contract.repository_contract",
            )
            for field, explicit in explicit_contracts:
                comparable = self._validated_read_only_report_repository_contract(
                    explicit,
                    field=field,
                )
                if json_dumps(comparable) != json_dumps(contract):
                    raise ValidationError(
                        "%s contradicts the current execution repository contract"
                        % field
                    )
            canonical_execution = dict(execution)
            schema = str(canonical_execution.get("schema") or "").strip()
            if schema and schema != "mac.task_execution_contract.v1":
                raise ValidationError(
                    "read-only repository report execution_contract.schema is unsupported"
                )
            canonical_execution["schema"] = "mac.task_execution_contract.v1"
            canonical_execution["type"] = "repository"
            canonical_execution["repository_contract"] = contract
            origin_remote = str(origin.get("repository_url") or "").strip()
            if origin_remote:
                try:
                    same_remote = canonical_git_remote_identity(origin_remote) == (
                        canonical_git_remote_identity(contract["canonical_remote_url"])
                    )
                except ValueError as exc:
                    raise ValidationError(
                        "metadata.origin.repository_url is invalid: %s" % exc
                    ) from exc
                if not same_remote:
                    raise ValidationError(
                        "metadata.origin.repository_url contradicts the current "
                        "execution repository contract"
                    )
            origin_branch = str(
                origin.get("default_branch") or origin.get("canonical_branch") or ""
            ).strip()
            if origin_branch and origin_branch != contract["default_branch"]:
                raise ValidationError(
                    "metadata.origin.default_branch contradicts the current "
                    "execution repository contract"
                )
            origin.setdefault("type", "direct_task")
            origin["repository_url"] = contract["canonical_remote_url"]
            origin["default_branch"] = contract["default_branch"]

        # Historical fallbacks may be read for ordinary repository tasks, but a
        # report persists its contract in the current execution slot only.
        origin.pop("repository_contract", None)
        normalized.pop("repository_contract", None)
        normalized["origin"] = origin
        normalized["execution_contract"] = canonical_execution
        return normalized

    def _assert_current_read_only_report_task_contract(
        self,
        task: Task,
        *,
        conn: Optional[Any] = None,
    ) -> None:
        """Fail closed for pre-cutover rows without rewriting ledger history."""

        metadata = ensure_json_object(task.metadata)
        if not metadata_declares_read_only_report_repository(metadata):
            return
        override_paths = self._read_only_report_evidence_override_paths(metadata)
        if override_paths:
            raise ValidationError(
                "read-only repository report has legacy evidence-type overrides: %s"
                % ", ".join(override_paths)
            )
        execution = ensure_json_object(metadata.get("execution_contract"))
        if (
            execution.get("schema") != "mac.task_execution_contract.v1"
            or str(execution.get("type") or "").strip().lower() != "repository"
        ):
            raise ValidationError(
                "read-only repository report lacks its normalized current execution contract"
            )
        contract = self._validated_read_only_report_repository_contract(
            execution.get("repository_contract"),
            field="metadata.execution_contract.repository_contract",
        )
        row = None
        if task.project:
            sql = (
                "SELECT * FROM project_repositories WHERE project = ? AND enabled = ? "
                "ORDER BY name, id LIMIT 1"
            )
            row = (
                conn.execute(sql, (task.project, 1)).fetchone()
                if conn is not None
                else self.store.query_one(sql, (task.project, 1))
            )
        if row is None:
            return
        repo = self.project_repositories.from_row(row)
        current = self._validated_read_only_report_repository_contract(
            ensure_json_object(repo.metadata).get("repository_contract"),
            field="registered repository contract",
        )
        if json_dumps(contract) != json_dumps(current):
            raise ValidationError(
                "read-only repository report execution contract is stale relative "
                "to the current registered repository contract"
            )
        if execution.get("repository_id") != repo.id:
            raise ValidationError(
                "read-only repository report execution contract has the wrong repository_id"
            )
        if execution.get("repository_path") != repo.path:
            raise ValidationError(
                "read-only repository report execution contract has the wrong repository_path"
            )

    def _normalize_task_execution_contract(
        self,
        metadata: Dict[str, Any],
        project: Optional[str],
        required_capabilities: List[str],
    ) -> JsonDict:
        normalized = ensure_json_object(metadata)
        read_only_report = metadata_declares_read_only_report_repository(normalized)
        if read_only_report:
            return self._normalize_read_only_report_execution_contract(
                normalized,
                project,
            )
        # A plain report deliverable (report/answer/analysis/... without the
        # read-only-repo opt-in) stays a non-repository operator_result task even
        # when the project has a registered repository contract.  We must not let
        # it fall through to the repo-coupled branches below, which would force a
        # fabricated diff + pushed branch + canonical integration for a read-only
        # report.
        report_deliverable = metadata_declares_report_deliverable(normalized)
        origin = normalized.get("origin")
        origin_dict = dict(origin) if isinstance(origin, dict) else {}
        existing_contract = normalized.get("execution_contract")
        non_repository_outcome = declared_non_repository_outcome_evidence_type(
            normalized
        )
        if non_repository_outcome and not report_deliverable:
            normalized["execution_contract"] = (
                self._report_context_execution_contract(
                    normalized,
                    project,
                    required_capabilities,
                    existing_contract=(
                        existing_contract
                        if isinstance(existing_contract, dict)
                        else None
                    ),
                    attach_repository_origin=False,
                )
            )
            normalized["execution_contract"][
                "reason"
            ] = "explicit_non_repository_outcome"
            return normalized
        if isinstance(existing_contract, dict) and existing_contract.get("type"):
            contract_type = str(existing_contract.get("type") or "").strip().lower()
            repo_like = (
                contract_type == "repository"
                or existing_contract.get("repository_required") is True
                or isinstance(existing_contract.get("repository_contract"), dict)
            )
            if repo_like and report_deliverable:
                # A report task cannot be silently upgraded to repo_change via
                # metadata.execution_contract.type='repository'.  Preserve the
                # registered repository context but keep an operator_result-shaped
                # contract, and never raise the missing-registered-contract error.
                normalized["execution_contract"] = self._report_context_execution_contract(
                    normalized,
                    project,
                    required_capabilities,
                    existing_contract=existing_contract,
                )
                return normalized
            if repo_like:
                merged_contract = dict(existing_contract)
                merged_contract.setdefault("schema", "mac.task_execution_contract.v1")
                merged_contract.setdefault("type", "repository")
                merged_contract.setdefault("evidence_type", "repo_change")
                repository_contract = merged_contract.get("repository_contract")
                if not isinstance(repository_contract, dict) or not repository_contract.get("schema"):
                    origin_contract = origin_dict.get("repository_contract")
                    if isinstance(origin_contract, dict) and origin_contract.get("schema"):
                        merged_contract["repository_contract"] = origin_contract
                    else:
                        repo = self._repository_for_project(project)
                        if repo is not None:
                            contract = repo.metadata.get("repository_contract")
                            if not isinstance(contract, dict) or not contract.get("schema"):
                                contract = self._repository_contract_for_repo(repo)
                            origin_dict.setdefault("type", "direct_task")
                            origin_dict.setdefault("repository_id", repo.id)
                            origin_dict.setdefault("repository_name", repo.name)
                            origin_dict.setdefault("repository_path", repo.path)
                            origin_dict.setdefault("source", repo.source)
                            origin_dict["repository_contract"] = contract
                            normalized["origin"] = origin_dict
                            acc_metadata = (
                                dict(normalized.get("acc_metadata"))
                                if isinstance(normalized.get("acc_metadata"), dict)
                                else {}
                            )
                            acc_metadata.setdefault("workflow_role", "work")
                            acc_metadata.setdefault("repository_contract_schema", contract["schema"])
                            acc_metadata.setdefault("repository_contract_project", contract["project"])
                            normalized["acc_metadata"] = acc_metadata
                            merged_contract.setdefault("quality", "strong")
                            merged_contract.setdefault("source", "registered_project")
                            merged_contract["repository_id"] = repo.id
                            merged_contract["repository_path"] = repo.path
                            merged_contract["repository_contract"] = contract
                        else:
                            project_repository_url = self._project_repository_url(project)
                            if project_repository_url and not origin_dict.get("onboarding"):
                                raise ValidationError(
                                    "project %s advertises repository_url %s but has no registered "
                                    "repository contract; complete onboarding, ensure .mac/project.yaml "
                                    "exists in the hub-visible checkout, then run `mac admin bridge repository "
                                    "register <name> <path> --project %s` before creating normal tasks"
                                    % (project, project_repository_url, project)
                                )
                repository_contract = merged_contract.get("repository_contract")
                if isinstance(repository_contract, dict):
                    contract_copy = dict(repository_contract)
                    declared_default = str(
                        contract_copy.get("default_branch") or ""
                    ).strip()
                    declared_canonical = str(
                        contract_copy.get("canonical_branch") or ""
                    ).strip()
                    if (
                        declared_default
                        and declared_canonical
                        and declared_default != declared_canonical
                    ):
                        raise ValidationError(
                            "repository execution contract default_branch and "
                            "canonical_branch must match"
                        )
                    branch = (
                        declared_default
                        or declared_canonical
                        or str(
                            origin_dict.get("default_branch")
                            or origin_dict.get("canonical_branch")
                            or DEFAULT_PROJECT_BRANCH
                        ).strip()
                    )
                    try:
                        branch = validate_git_ref(branch)
                    except ValueError as exc:
                        raise ValidationError(
                            "repository execution contract branch is invalid: %s"
                            % exc
                        ) from exc
                    contract_copy["default_branch"] = branch
                    contract_copy.pop("canonical_branch", None)
                    merged_contract["repository_contract"] = contract_copy
                normalized["execution_contract"] = merged_contract
            return normalized
        repository_contract = origin_dict.get("repository_contract")
        if isinstance(repository_contract, dict) and repository_contract.get("schema"):
            contract_copy = dict(repository_contract)
            branch = str(
                contract_copy.get("default_branch")
                or contract_copy.get("canonical_branch")
                or origin_dict.get("default_branch")
                or origin_dict.get("canonical_branch")
                or DEFAULT_PROJECT_BRANCH
            ).strip()
            try:
                branch = validate_git_ref(branch)
            except ValueError as exc:
                raise ValidationError(
                    "repository execution contract branch is invalid: %s" % exc
                ) from exc
            contract_copy["default_branch"] = branch
            contract_copy.pop("canonical_branch", None)
            origin_dict["repository_contract"] = contract_copy
            normalized["origin"] = origin_dict
            normalized["execution_contract"] = {
                "schema": "mac.task_execution_contract.v1",
                "type": "repository",
                "quality": "strong",
                "source": "task_origin",
                "evidence_type": "repo_change",
                "repository_contract": contract_copy,
            }
            return normalized
        repo = self._repository_for_project(project)
        if repo is not None and report_deliverable:
            # Registered repository exists, but the declared report deliverable
            # keeps its operator_result contract; only repository context is
            # recorded, never a repo_change coupling.
            normalized["execution_contract"] = self._report_context_execution_contract(
                normalized,
                project,
            )
            return normalized
        if repo is not None:
            contract = repo.metadata.get("repository_contract")
            if not isinstance(contract, dict) or not contract.get("schema"):
                contract = self._repository_contract_for_repo(repo)
            origin_dict.setdefault("type", "direct_task")
            origin_dict.setdefault("repository_id", repo.id)
            origin_dict.setdefault("repository_name", repo.name)
            origin_dict.setdefault("repository_path", repo.path)
            origin_dict.setdefault("source", repo.source)
            origin_dict["repository_contract"] = contract
            normalized["origin"] = origin_dict
            acc_metadata = (
                dict(normalized.get("acc_metadata"))
                if isinstance(normalized.get("acc_metadata"), dict)
                else {}
            )
            acc_metadata.setdefault("workflow_role", "work")
            acc_metadata.setdefault("repository_contract_schema", contract["schema"])
            acc_metadata.setdefault("repository_contract_project", contract["project"])
            normalized["acc_metadata"] = acc_metadata
            normalized["execution_contract"] = {
                "schema": "mac.task_execution_contract.v1",
                "type": "repository",
                "quality": "strong",
                "source": "registered_project",
                "evidence_type": "repo_change",
                "repository_id": repo.id,
                "repository_path": repo.path,
                "repository_contract": contract,
            }
            return normalized
        project_repository_url = self._project_repository_url(project)
        if project_repository_url and not origin_dict.get("onboarding"):
            raise ValidationError(
                "project %s advertises repository_url %s but has no registered "
                "repository contract; complete onboarding, ensure .mac/project.yaml "
                "exists in the hub-visible checkout, then run `mac admin bridge repository "
                "register <name> <path> --project %s` before creating normal tasks"
                % (project, project_repository_url, project)
            )
        policy = normalized.get("policy") if isinstance(normalized.get("policy"), dict) else {}
        evidence_type = str(
            normalized.get("evidence_type")
            or policy.get("evidence_type")
            or policy.get("expected_evidence_type")
            or "operator_result"
        ).strip()
        normalized["execution_contract"] = {
            "schema": "mac.task_execution_contract.v1",
            "type": "operator_directive",
            "quality": "weak",
            "source": "task_crud",
            "repository_required": False,
            "evidence_type": evidence_type,
            "required_capabilities": required_capabilities,
            "reason": "no_registered_repository_or_task_repository_contract",
        }
        return normalized

    def _report_context_execution_contract(
        self,
        normalized: Dict[str, Any],
        project: Optional[str],
        required_capabilities: Optional[List[str]] = None,
        *,
        existing_contract: Optional[Dict[str, Any]] = None,
        attach_repository_origin: bool = True,
    ) -> JsonDict:
        """Build the non-repository contract for a project-scoped report task.

        Records the registered repository's identity in ``origin`` /
        ``acc_metadata`` for reviewer reproducibility, then returns an
        ``operator_result``-shaped execution contract.  It never attaches a
        ``repository_contract`` and never raises the missing-registered-contract
        error, so a declared report stays off the repo_change path even when the
        project has a registered repository contract.
        """

        origin = normalized.get("origin")
        origin_dict = dict(origin) if isinstance(origin, dict) else {}
        repo = self._repository_for_project(project)
        contract: Optional[Dict[str, Any]] = None
        if repo is not None:
            contract = repo.metadata.get("repository_contract")
            if not isinstance(contract, dict) or not contract.get("schema"):
                contract = self._repository_contract_for_repo(repo)
            if attach_repository_origin:
                origin_dict.setdefault("type", "direct_task")
                origin_dict.setdefault("repository_id", repo.id)
                origin_dict.setdefault("repository_name", repo.name)
                origin_dict.setdefault("repository_path", repo.path)
                origin_dict.setdefault("source", repo.source)
                normalized["origin"] = origin_dict
            else:
                # Repository identity remains available in repository_context
                # below, but must not look executable to worker repo discovery.
                for key in (
                    "repository_contract",
                    "repository_path",
                    "repository_url",
                ):
                    origin_dict.pop(key, None)
                if origin_dict:
                    normalized["origin"] = origin_dict
                else:
                    normalized.pop("origin", None)

        acc_metadata = (
            dict(normalized.get("acc_metadata"))
            if isinstance(normalized.get("acc_metadata"), dict)
            else {}
        )
        acc_metadata.setdefault("workflow_role", "work")
        if isinstance(contract, dict) and contract.get("schema"):
            acc_metadata.setdefault("repository_contract_schema", contract["schema"])
        if isinstance(contract, dict) and contract.get("project"):
            acc_metadata.setdefault("repository_contract_project", contract["project"])
        normalized["acc_metadata"] = acc_metadata

        evidence_type = self._report_evidence_type(normalized, existing_contract)
        return report_repository_context_execution_contract(
            evidence_type=evidence_type,
            repository_id=getattr(repo, "id", None) if repo is not None else None,
            repository_name=getattr(repo, "name", None) if repo is not None else None,
            repository_path=getattr(repo, "path", None) if repo is not None else None,
            repository_contract_schema=acc_metadata.get("repository_contract_schema"),
            repository_contract_project=acc_metadata.get("repository_contract_project"),
            workflow_role=acc_metadata.get("workflow_role"),
            required_capabilities=required_capabilities or [],
        )

    def _report_evidence_type(
        self,
        normalized: Dict[str, Any],
        existing_contract: Optional[Dict[str, Any]] = None,
    ) -> str:
        """Resolve the report evidence type, honoring an explicit report kind.

        Mirrors the no-repository report path: prefer an explicitly declared
        report evidence type (e.g. ``investigation``) when already set, else fall
        back to ``operator_result``.  A repo-coupled ``repo_change`` value that
        leaked in via ``metadata.execution_contract`` is ignored so a report is
        never upgraded to repo_change through it.
        """

        policy = (
            normalized.get("policy")
            if isinstance(normalized.get("policy"), dict)
            else {}
        )
        candidates = [
            normalized.get("evidence_type"),
            policy.get("evidence_type"),
            policy.get("expected_evidence_type"),
        ]
        if isinstance(existing_contract, dict):
            candidates.insert(0, existing_contract.get("evidence_type"))
        for candidate in candidates:
            text = str(candidate or "").strip()
            if text and text != "repo_change":
                return text
        return "operator_result"

    def _project_repository_url(self, project: Optional[str]) -> Optional[str]:
        return self.project_repositories.project_repository_url(project)

    def _repository_for_project(self, project: Optional[str]) -> Optional[ProjectRepository]:
        return self.project_repositories.repository_for_project(project)

    def get_task(self, task_id: str) -> Task:
        resolved = self._resolve_task_id(task_id)
        row = self.store.query_one("SELECT * FROM tasks WHERE id = ?", (resolved,))
        if row is None:
            raise NotFoundError("task not found: %s" % resolved)
        return self._task_from_row(row)

    def _canonical_dependency_ids(
        self, dependencies: Optional[Iterable[str]]
    ) -> List[str]:
        """Resolve dependency references once at the public write boundary.

        Prefixes are accepted through the same git-style resolver as
        ``get_task``; persistence receives only full, existing task ids.
        """

        canonical: List[str] = []
        seen: set[str] = set()
        for dependency_ref in coerce_list(dependencies):
            dependency_id = self.get_task(dependency_ref).id
            if dependency_id not in seen:
                canonical.append(dependency_id)
                seen.add(dependency_id)
        return canonical

    # Minimum number of hex characters (after the "task_" prefix) required for
    # a prefix lookup.  Matches the requirement in the task description.
    _TASK_PREFIX = "task_"
    _TASK_FULL_HEX_LEN = 32  # uuid4().hex is always 32 hex digits
    _TASK_MIN_PREFIX_HEX = 6  # require at least 6 hex chars after "task_"

    def _resolve_task_id(self, task_id: str) -> str:
        """Expand an unambiguous task-id prefix to its full id (git-style).

        Rules
        -----
        * A *full* id (``task_`` + exactly 32 hex chars) is returned as-is
          without a database round-trip.
        * A *prefix* is ``task_`` followed by 6–31 lowercase hex chars.
          Fewer than 6 hex chars is rejected immediately (too short to be
          safe against accidental collisions).
        * Exactly one match → returns the full id.
        * Zero matches → raises :exc:`~mac.models.NotFoundError`.
        * Two or more matches → raises :exc:`~mac.models.AmbiguousIdError`
          with the list of candidate ids.
        * Anything that does not look like a task id (no ``task_`` prefix, or
          a non-hex suffix) is returned unchanged so that callers using
          synthetic / fixture ids continue to work.
        """
        prefix = self._TASK_PREFIX
        if not task_id.startswith(prefix):
            return task_id
        hex_part = task_id[len(prefix):]
        # Full id — no lookup needed.
        if len(hex_part) == self._TASK_FULL_HEX_LEN and hex_part.isalnum():
            return task_id
        # Validate that this looks like a hex prefix at all.
        if not hex_part or not all(c in "0123456789abcdef" for c in hex_part.lower()):
            return task_id
        hex_part = hex_part.lower()
        if len(hex_part) < self._TASK_MIN_PREFIX_HEX:
            raise ValidationError(
                "task-id prefix too short: need at least %d hex chars after '%s', got %d"
                % (self._TASK_MIN_PREFIX_HEX, prefix, len(hex_part))
            )
        # Prefix lookup without LIKE: ``_`` is a wildcard in SQL LIKE and
        # previously allowed ``task_abcdef`` to bind ``taskXabcdef...``.
        literal_prefix = prefix + hex_part
        rows = self.store.query_all(
            "SELECT id FROM tasks WHERE substr(id, 1, ?) = ?",
            (len(literal_prefix), literal_prefix),
        )
        matched = [row["id"] for row in rows]
        if not matched:
            raise NotFoundError("task not found: %s" % task_id)
        if len(matched) == 1:
            return matched[0]
        raise AmbiguousIdError(
            "ambiguous task-id prefix '%s' matches %d tasks: %s"
            % (task_id, len(matched), ", ".join(sorted(matched))),
            candidates=sorted(matched),
        )

    def list_tasks(
        self,
        state: Optional[Any] = None,
        tenant_id: Optional[str] = None,
        *,
        project: Optional[str] = None,
        limit: Optional[int] = None,
        created_by_human: Optional[str] = None,
    ) -> List[Task]:
        # mac-5ayd: dispatch_once / claim_next used to pull EVERY open
        # task into Python and sort in memory on every tick. Pass an
        # explicit ``limit`` from those hot paths so the working set
        # stays bounded; default None keeps full-list semantics for
        # admin / CLI listings.
        #
        # mac-perf: push project and state filters into SQL so the hub
        # does not transfer full task rows for irrelevant projects over
        # the SSH tunnel. With 110+ tasks and per-task metadata of ~1KB
        # this halves (or better) the response payload when the CLI is
        # scoped to a single project.
        where: list = []
        params: list = []
        if state:
            # A sequence selects several states in one query. The CLI's default
            # view needs "every ACTIVE state" and used to have no way to ask
            # for it, so it asked for everything instead -- 8,162 rows on this
            # hub, 7,573 of them terminal.
            if isinstance(state, (list, tuple, set, frozenset)):
                values = [_state_value(item) for item in state]
                if values:
                    where.append(
                        "state IN (%s)" % ",".join("?" for _ in values)
                    )
                    params.extend(values)
            else:
                where.append("state = ?")
                params.append(_state_value(state))
        if project is not None:
            where.append("project = ?")
            params.append(project)
        if created_by_human:
            # Pushed into SQL like the others: "my tasks" on a busy hub must
            # not mean "transfer everyone's tasks and discard most of them".
            where.append("created_by_human = ?")
            params.append(str(created_by_human))
        where_clause = (" WHERE " + " AND ".join(where)) if where else ""
        sql = "SELECT * FROM tasks" + where_clause + " ORDER BY priority DESC, created_at"
        if limit is not None:
            sql += " LIMIT ?"
            params.append(int(max(1, limit)))
        rows = self.store.query_all(sql, tuple(params))
        tasks = [self._task_from_row(row) for row in rows]
        if tenant_id is not None:
            tasks = [task for task in tasks if self._task_tenant_id(task) == tenant_id]
        return tasks

    def _non_terminal_tasks(self) -> List[Task]:
        """Every task that is not in a terminal state, filtered in SQL.

        The positive state list is deliberate: `state IN (...)` uses
        idx_tasks_state_priority, while `state NOT IN (...)` does not. Measured
        on the fleet hub, the two forms of the same question differed by 4.5x.
        """
        active = sorted({state.value for state in TaskState} - set(TERMINAL_TASK_STATES))
        placeholders = ", ".join("?" for _ in active)
        rows = self.store.query_all(
            "SELECT * FROM tasks WHERE state IN (%s) "
            "ORDER BY priority DESC, created_at" % placeholders,
            tuple(active),
        )
        return [self._task_from_row(row) for row in rows]

    def ready_tasks(
        self,
        *,
        project: Optional[str] = None,
        tenant_id: Optional[str] = None,
        limit: Optional[int] = None,
    ) -> List[Task]:
        return self.dispatch.ready_tasks(
            project=project,
            tenant_id=tenant_id,
            limit=limit,
        )

    def explain_task_dispatch(
        self,
        task_id: Any,
        *,
        agents: Optional[Iterable[Agent]] = None,
        candidate_limit: int = 60,
        record_observation: bool = False,
    ) -> JsonDict:
        return self.dispatch.explain_task_dispatch(
            task_id,
            agents=agents,
            candidate_limit=candidate_limit,
            record_observation=record_observation,
        )

    # -- task groups and bulk operations ---------------------------------
    #
    # Flat delegations so the HTTP client can mirror them: RemoteDispatch
    # forwards ControlPlane methods, and a nested `cp.task_batches.select`
    # would not proxy.

    def select_tasks(
        self,
        expression: str,
        *,
        limit: Optional[int] = None,
        sample: int = 20,
    ) -> JsonDict:
        """Preview the group an expression names.

        Bounded by the sample size unless the caller asks for more: a preview
        needs the true size and a handful of examples, not the group. `matched`
        is a COUNT and stays exact however large the group is, so the bound is
        a display choice rather than a correctness one -- 66,666 matches
        reported in 0.038s while fetching twenty rows.
        """
        return self.task_batches.select(
            expression, limit=limit if limit is not None else sample
        ).to_dict(sample=sample)

    def apply_task_batch(
        self,
        expression: str,
        operation: str,
        *,
        actor: str = "human",
        apply: bool = False,
        expect_count: Optional[int] = None,
        expect_token: Optional[str] = None,
        limit: Optional[int] = None,
        **options: Any,
    ) -> JsonDict:
        """Run one operation over the group, dry by default."""
        return self.task_batches.apply(
            expression,
            operation,
            actor=actor,
            apply=apply,
            expect_count=expect_count,
            expect_token=expect_token,
            limit=limit,
            **options,
        ).to_dict()

    def park_unsatisfiable_tasks(
        self,
        *,
        actor: str = "unsatisfiable-requirements-sweep",
        apply: bool = False,
        limit: Optional[int] = None,
    ) -> JsonDict:
        """Park open tasks no agent can satisfy. Dry by default."""
        return self.unsatisfiable_parker.sweep(actor=actor, apply=apply, limit=limit)

    def save_task_group(
        self,
        name: str,
        expression: str,
        *,
        description: str = "",
        actor: str = "human",
    ) -> JsonDict:
        return self.task_groups.save(
            name, expression, description=description, actor=actor
        )

    def list_task_groups(self) -> List[JsonDict]:
        return self.task_groups.list()

    def get_task_group(self, name: str) -> JsonDict:
        return self.task_groups.get(name)

    def delete_task_group(self, name: str) -> JsonDict:
        self.task_groups.delete(name)
        return {"name": name, "deleted": True}

    def check_sandbox_bom_drift(self, *, actor: str = "hub", project: Optional[str] = None) -> Dict[str, Any]:
        """Has a contract change made the reviewed sandbox manifest stale?

        Called when a repository registration appears or a project is deleted,
        because those are the only two events that can change the union of
        contracts. Without this the manifest goes stale silently and the fleet
        keeps running an image that no longer matches what projects declare --
        which is the exact failure the derivation was built to end, just moved
        one step later.

        It FILES a task; it does not publish an image. An automated path from
        "someone registered a repo" to "every worker is running a new image"
        would be a supply-chain hole, and the frozen-input hash exists to make
        that step reviewed.
        """
        try:
            manifest_path = committed_manifest_path()
            if manifest_path is None:
                return {"checked": False, "reason": "no committed manifest in this tree"}
            committed = json.loads(manifest_path.read_text(encoding="utf-8"))
            derived = derive_bom(
                [repository.to_dict() for repository in self.list_project_repositories()]
            )
            drift = manifest_drift(committed, derived)
            # Filed only when something is NEWLY REQUIRED. Both directions are
            # still reported, but they are not the same kind of problem:
            #
            #   added    a contract needs a tool the image lacks. Work breaks,
            #            or an agent quietly edits source until it compiles.
            #   removed  a package nothing asks for any more. Hygiene.
            #
            # Filing on removal was actively harmful. Deleting a project can
            # only ever remove requirements, and there is no project left to
            # own the ticket -- so every deletion left an unowned task in the
            # "unassigned" bucket that nothing would claim or close. It also
            # fired constantly in any control plane whose registrations differ
            # from the reviewed manifest, which is every dev and test hub.
            #
            # Removal drift is surfaced by `mac admin sandbox-image bom --compare`, which
            # exits non-zero on drift in either direction, so CI still catches
            # a stale manifest.
            if not (drift.get("added_commands") or drift.get("added_packages")):
                return {"checked": True, "drift": drift, "filed": None}
            marker = {
                "schema": BOM_SCHEMA,
                "added_commands": drift.get("added_commands") or [],
                "removed_commands": drift.get("removed_commands") or [],
            }
            signature = json_dumps(marker)
            # Ask the database the question instead of reading the table.
            #
            # This runs on every agent registration. It used to pull EVERY task
            # into Python -- 8,372 rows, 116MB on the fleet hub -- to look at one
            # metadata key. Unbounded list_tasks() takes over 200 SECONDS there.
            #
            # The state list is POSITIVE (the non-terminal states) rather than
            # `NOT IN (terminal)`, because only the positive form uses
            # idx_tasks_state_priority. Measured on the fleet hub:
            #
            #   NOT IN (terminal) + `->` equality    1950ms  (seq scan, detoasts
            #                                                 all 8,062 rows)
            #   state IN (non-terminal) + equality    427ms  (index scan 0.65ms,
            #                                                 detoasts only 582)
            #
            # Nearly all of the remaining time is detoasting metadata_json for
            # the surviving rows -- at 14KB/row every `->` reads the whole
            # document -- which is why narrowing by state FIRST is what matters.
            #
            # Deliberately NOT using `@>` here. The GIN index on metadata_json
            # looks like the right answer and is not: forcing it measured 889ms
            # against 219ms for a plain sequential scan, and the planner refuses
            # it on its own. See task_747dbbdf.
            #
            # The jsonb equality is also stricter than the string comparison it
            # replaces: json_dumps(...) == json_dumps(...) depended on key
            # ordering; jsonb compares by value.
            active = tuple(
                sorted({state.value for state in TaskState} - set(TERMINAL_TASK_STATES))
            )
            placeholders = ", ".join("?" for _ in active)
            already_reported = self.store.query_one(
                "SELECT 1 FROM tasks "
                "WHERE state IN (%s) "
                "AND metadata_json -> 'sandbox_bom_drift' = ?::jsonb "
                "LIMIT 1" % placeholders,
                active + (signature,),
            )
            if already_reported is not None:
                # Same drift already reported. Re-filing per registration
                # would bury the one report that matters.
                return {"checked": True, "drift": drift, "filed": None}
            filed = self.create_task(
                "Sandbox BOM drift: the reviewed image no longer matches the contracts",
                description="\n".join(
                    [
                        "A repository contract changed, so the union of required "
                        "commands no longer matches deploy/openshell/sandbox-bom.json.",
                        "",
                        "  newly required : %s" % (", ".join(drift.get("added_commands") or []) or "(none)"),
                        "  no longer required: %s" % (", ".join(drift.get("removed_commands") or []) or "(none)"),
                        "",
                        "A command that is newly required and absent from the image "
                        "means a coding agent on that repo will provision it per task, "
                        "or -- worse -- edit the source until it builds without it.",
                        "",
                        "To resolve:",
                        "  1. mac admin sandbox-image bom --containerfile deploy/openshell/mac-hermes.Containerfile",
                        "  2. add anything it reports to the Containerfile, and",
                        "     mac admin sandbox-image bom --write deploy/openshell/sandbox-bom.json",
                        "  3. publish the image through the reviewed workflow, then",
                        "     mac admin sandbox-image rollout --image <digest> --manifest deploy/openshell/sandbox-bom.json",
                        "",
                        "Step 3 is a barrier task per worker: each one drains before it "
                        "updates, so the fleet rolls rather than stopping.",
                    ]
                ),
                project=project,
                metadata={
                    "sandbox_bom_drift": marker,
                    # Staged, NOT dispatchable. An open task is fleet-claimed
                    # within minutes, and what an agent would do with this one
                    # is edit the Containerfile and publish an image -- the
                    # unreviewed supply-chain path this whole design exists to
                    # keep closed. It is a decision for a human or an LLM to
                    # pick up deliberately, so it waits to be started.
                    "no_dispatch": True,
                },
                actor=actor,
            )
            return {"checked": True, "drift": drift, "filed": filed.id}
        except Exception as exc:  # noqa: BLE001
            # A diagnostic must never be why a registration fails -- but a
            # blanket swallow hides its own bugs, and this one did: an
            # unsupported json_dumps kwarg made every check report "no drift"
            # while looking healthy. Name the error so the next one is visible.
            return {
                "checked": False,
                "reason": "drift check failed: %s: %s" % (type(exc).__name__, exc),
            }

    def roll_out_sandbox_image(
        self,
        image_ref: str,
        *,
        bom: Optional[Mapping[str, Any]] = None,
        actor: str = "human",
        project: Optional[str] = None,
    ) -> Dict[str, Any]:
        """File one barrier task per agent to install a reviewed image.

        Rolling, not fleet-wide: each agent drains and updates independently,
        so the fleet keeps working through the rollout instead of stopping at
        once. Deduplicated per (agent, image) because a rollout re-filed on
        every tick would queue a barrier per tick, and barriers quiesce their
        agent -- the worker would stop taking work permanently.
        """
        image_ref = validate_image_ref(image_ref)
        agents = [agent.to_dict() for agent in self.list_agents()]
        plan = plan_rollout(
            agents,
            image_ref,
            bom=bom or {},
            # Ask SQL for the non-terminal tasks rather than reading all of
            # them and discarding most in Python. On the fleet hub the table is
            # 8,372 rows / 116MB and ~89% of it is terminal, so this fetched
            # (and detoasted) roughly nine rows for every one it kept.
            already_scheduled=scheduled_rollouts(self._non_terminal_tasks()),
        )
        filed: List[str] = []
        skipped: List[str] = []
        for item in plan:
            try:
                task = self.create_task(
                    item["title"],
                    description=item["description"],
                    project=project,
                    metadata=item["metadata"],
                    actor=actor,
                )
            except (ValidationError, TransitionError, NotFoundError):
                # One unfilable worker must not abort the rollout for the rest:
                # a partial roll is recoverable by re-running, an aborted one
                # leaves whichever workers were reached in an unknown mix.
                skipped.append(item["agent_id"])
            else:
                filed.append(task.id)
        return {
            "schema": ROLLOUT_SCHEMA,
            "image": image_ref,
            "filed": filed,
            "skipped": skipped,
            "agents_considered": len(agents),
        }

    def record_sandbox_excursion(
        self,
        delta: Any,
        *,
        project: Optional[str],
        task_id: Optional[str] = None,
        actor: str = "sandbox-excursion",
    ) -> JsonDict:
        """File a task against the project whose contract the image did not cover.

        The excursion record has always been written by the executor and never
        read: it rides back inside mac.sandbox_verification.v1, lands on a check
        item, and stops. The visible consequence is the Containerfile's package
        list, which is a manual ledger of these incidents transcribed by a human
        months after each one.

        This never blocks or fails anything. The work already succeeded --
        provisioning saw to that -- and a contract may legitimately be wrong or
        stale, so the excursion is a REPORT for audit, not a gate.

        Deduplicated per (project, command): one missing tool is one task
        however many tasks trip over it, because noise is what stops these
        being read.
        """
        from mac.sandbox_excursion import (
            dedupe_key,
            excursion_commands,
            excursion_description,
            excursion_from_delta,
            excursion_metadata,
            excursion_title,
            existing_excursion_commands,
        )

        excursion = excursion_from_delta(delta, project=project, task_id=task_id)
        if excursion is None:
            return {"schema": "mac.sandbox_excursion_report.v1", "filed": [], "skipped": []}

        try:
            open_tasks = self.list_tasks("open", project=project)
        except Exception:  # noqa: BLE001 - a report must never break the caller
            open_tasks = []
        already = existing_excursion_commands(open_tasks)

        filed: List[str] = []
        skipped: List[str] = []
        for command in excursion_commands(excursion):
            if dedupe_key(project, command) in already:
                skipped.append(command)
                continue
            try:
                created = self.create_task(
                    excursion_title(project, command),
                    description=excursion_description(excursion, command),
                    project=project,
                    metadata=excursion_metadata(excursion, command),
                    actor=actor,
                )
            except Exception:  # noqa: BLE001 - never break the executing task
                skipped.append(command)
                continue
            filed.append(created.id)
            already.add(dedupe_key(project, command))

        if filed:
            try:
                self.record_log(
                    "sandbox.excursion_filed",
                    level="warning",
                    subject_type="project",
                    subject_id=project or "unknown",
                    detail={
                        "project": project,
                        "observed_on_task_id": task_id,
                        "commands": excursion_commands(excursion),
                        "filed_task_ids": filed,
                    },
                )
            except Exception:  # noqa: BLE001 - diagnostic only
                pass

        return {
            "schema": "mac.sandbox_excursion_report.v1",
            "project": project,
            "observed_on_task_id": task_id,
            "filed": filed,
            "skipped": skipped,
            "excursion": excursion,
        }

    def search_tasks(
        self,
        query: str,
        *,
        project: Optional[str] = None,
        tenant_id: Optional[str] = None,
        limit: int = 50,
    ) -> List[Task]:
        """Keyword search across title/description (parity with bd search)."""
        like = "%" + (query or "") + "%"
        where = ["(title LIKE ? OR description LIKE ?)"]
        params: list = [like, like]
        if project is not None:
            where.append("project = ?")
            params.append(project)
        rows = self.store.query_all(
            "SELECT * FROM tasks WHERE %s ORDER BY priority DESC, created_at DESC LIMIT ?"
            % " AND ".join(where),
            tuple(params + [int(limit)]),
        )
        tasks = [self._task_from_row(row) for row in rows]
        if tenant_id is not None:
            tasks = [t for t in tasks if self._task_tenant_id(t) == tenant_id]
        return tasks

    def task_stats(
        self,
        *,
        project: Optional[str] = None,
        tenant_id: Optional[str] = None,
    ) -> Dict[str, int]:
        """Task counts by state (parity with bd stats).

        ``reviewing_parked`` is reported alongside the states whenever it is
        non-zero: the count of REVIEWING tasks that are approved but have no
        publication destination, so nothing will ever move them to COMPLETED.
        Without it a permanently parked task is counted under ``reviewing`` and
        is indistinguishable from work in flight — which is how four of them sat
        unnoticed for four days (task_ce6c8ea3). It is an addition, not a
        reclassification: ``reviewing`` still counts every reviewing task, so
        the state counts continue to sum to the task total.
        """
        if tenant_id is not None:
            tasks = self.list_tasks(tenant_id=tenant_id)
            if project is not None:
                tasks = [t for t in tasks if t.project == project]
            counts: Dict[str, int] = {}
            for t in tasks:
                counts[t.state] = counts.get(t.state, 0) + 1
            return self._with_parked_reviewing_count(dict(sorted(counts.items())), project)
        where = ""
        params: list = []
        if project is not None:
            where = " WHERE project = ?"
            params.append(project)
        rows = self.store.query_all(
            "SELECT state, COUNT(*) AS n FROM tasks%s GROUP BY state ORDER BY state" % where,
            tuple(params),
        )
        counts = {row["state"]: int(row["n"]) for row in rows}
        return self._with_parked_reviewing_count(counts, project)

    def _with_parked_reviewing_count(
        self,
        counts: Dict[str, int],
        project: Optional[str],
    ) -> Dict[str, int]:
        """Add ``reviewing_parked`` to ``counts`` when there is anything to add.

        Resolving a publication target per task costs a project lookup, so this
        short-circuits when nothing is in REVIEWING at all — which is the usual
        case, and keeps `mac task stats` as cheap as it was.  A failure here
        must not take the stats call down with it: the counts are the primary
        answer and the parked count is an annotation on them.
        """
        if not counts.get(TaskState.REVIEWING.value):
            return counts
        try:
            parked = self.parked_reviewing_tasks(limit=1_000_000)
        except Exception:  # noqa: BLE001 - an annotation must not break the counts
            return counts
        if project is not None:
            parked = [item for item in parked if item.get("project") == project]
        if parked:
            counts["reviewing_parked"] = len(parked)
        return counts

    def diagnostics_report(
        self,
        *,
        names: Optional[Sequence[str]] = None,
    ) -> Dict[str, Any]:
        """Run read-only control-plane health checks against this authority.

        This is the single hub-native entry point for ``mac admin diagnostics``.  It
        executes every registered check (or just ``names``) against this
        ControlPlane's authoritative store — SQLite or PostgreSQL — and returns
        the JSON-able report from :func:`mac.diagnostics.summarize`.  Serving
        the report here (and over the matching hub API route) means a remote
        client never falls back to direct SQL or an accidental local database:
        the checks always run where the durable authority lives.  The report is
        derived on demand from current state, so it emits no periodic events.
        """
        from mac import diagnostics

        report = diagnostics.summarize(
            diagnostics.run_diagnostics(self, names=list(names) if names else None)
        )
        # The machine-readable data-source identity is always present at the top
        # level, even under a narrowed check selection, so every report names the
        # authoritative backend it ran against.
        report.setdefault("data_source", diagnostics.backend_identity(self))
        return report

    def task_flow_report(
        self,
        *,
        project: Optional[str] = None,
        since_hours: float = 24.0,
        warning_seconds: float = 300.0,
        critical_seconds: float = 600.0,
        refresh_limit: int = 100,
    ) -> JsonDict:
        """Return fleet throughput, stranding, and contention from ledger truth.

        The fleet is loaded once and reused by every ready-task explanation so
        this operator query does not recreate the overview-query overload it is
        intended to diagnose.
        """

        try:
            since_value = float(since_hours)
            warning_value = float(warning_seconds)
            critical_value = float(critical_seconds)
            refresh_value = int(refresh_limit)
        except (TypeError, ValueError) as exc:
            raise ValidationError(
                "task-flow report thresholds and limits must be numeric"
            ) from exc
        if not 0 < since_value <= 24 * 90:
            raise ValidationError("since_hours must be in (0, 2160]")
        if warning_value <= 0:
            raise ValidationError("warning_seconds must be positive")
        if critical_value < warning_value:
            raise ValidationError(
                "critical_seconds must be greater than or equal to warning_seconds"
            )
        if not 0 <= refresh_value <= 500:
            raise ValidationError("refresh_limit must be between 0 and 500")
        agents = self.list_agents()
        idle_worker_count = sum(
            1
            for agent in agents
            if agent.status == AgentStatus.IDLE.value
        )

        def explain(task_id: str) -> JsonDict:
            return self.explain_task_dispatch(task_id, agents=agents)

        return self.task_flow.report(
            project=project,
            since_hours=since_value,
            warning_seconds=warning_value,
            critical_seconds=critical_value,
            refresh_limit=refresh_value,
            dispatch_explainer=explain,
            idle_worker_count=idle_worker_count,
        )


    def update_task(
        self,
        task_id: str,
        *,
        title: Optional[str] = None,
        description: Optional[str] = None,
        project: Optional[str] = None,
        priority: Optional[int] = None,
        required_capabilities: Optional[Iterable[str]] = None,
        dependencies: Optional[Iterable[str]] = None,
        metadata: Optional[Dict[str, Any]] = None,
        max_attempts: Optional[int] = None,
        created_by_human: Optional[str] = None,
        actor: str = "human",
        _preserve_control_plane_publication_metadata: bool = False,
    ) -> Task:
        """Change a task's fields, stopping and restarting it if it is in flight.

        ADR 0020. A RUNNING or CLAIMED task is never modified in place: the
        ledger would hold one description while the executor worked from
        another, read at claim time, with nothing to reconcile them. That is
        not hypothetical -- a task's acceptance criteria were rewritten
        mid-execution on 2026-08-20, and correct work came within a hand-check
        of being judged against criteria written after it.

        Rather than refusing the edit and making every caller compose
        stop -> modify -> start, the cycle lives HERE. The caller asks for an
        update and gets an update; underneath, the executor is aborted, the
        lease revoked, the change applied and the task restarted. A composed
        cycle can be abandoned between steps, which is how a task ends up
        stopped and forgotten, or edited and never restarted. Putting it below
        the API makes atomicity structural rather than a rule callers must
        remember.

        The restart re-enters from the top: the next agent re-derives
        everything from the task as it now stands (see
        :meth:`start_stopped_task`).
        """

        # Kept as an explicit mapping rather than **kwargs: the public
        # signature above is introspected by the control-plane contract tests,
        # and collapsing it to **kwargs silently removed update_task from their
        # parametrization -- the method still worked and simply stopped being
        # covered.
        fields: Dict[str, Any] = {
            "title": title,
            "description": description,
            "project": project,
            "priority": priority,
            "required_capabilities": required_capabilities,
            "dependencies": dependencies,
            "metadata": metadata,
            "max_attempts": max_attempts,
            "created_by_human": created_by_human,
            "actor": actor,
            "_preserve_control_plane_publication_metadata": (
                _preserve_control_plane_publication_metadata
            ),
        }

        changes_scope = any(
            fields.get(name) is not None for name in self.SCOPE_BEARING_TASK_FIELDS
        )
        task = self.get_task(task_id)
        if not changes_scope or task.state not in self.IN_FLIGHT_TASK_STATES:
            return self._update_task_fields(task_id, **fields)

        self.stop_task(
            task_id,
            actor=actor,
            reason="stopped to apply an update to an in-flight task (ADR 0020)",
        )
        # A failure here leaves the task STOPPED rather than restarting it with
        # a half-applied edit. A stopped task is visible and recoverable; a task
        # running against a partial change is the split brain this exists to
        # remove.
        self._update_task_fields(task_id, **fields)
        return self.start_stopped_task(task_id, actor=actor)

    def _update_task_fields(
        self,
        task_id: str,
        *,
        title: Optional[str] = None,
        description: Optional[str] = None,
        project: Optional[str] = None,
        priority: Optional[int] = None,
        required_capabilities: Optional[Iterable[str]] = None,
        dependencies: Optional[Iterable[str]] = None,
        metadata: Optional[Dict[str, Any]] = None,
        max_attempts: Optional[int] = None,
        created_by_human: Optional[str] = None,
        actor: str = "human",
        _preserve_control_plane_publication_metadata: bool = False,
    ) -> Task:
        task = self.get_task(task_id)
        updates: List[str] = []
        params: List[Any] = []
        detail: JsonDict = {}
        new_project = task.project
        new_capabilities = list(task.required_capabilities)
        new_metadata = ensure_json_object(task.metadata)
        dependency_ids: Optional[List[str]] = None
        preserved_publication_metadata: JsonDict = {}
        if title is not None:
            title_value = str(title or "").strip()
            if not title_value:
                raise ValidationError("task title is required")
            updates.append("title = ?")
            params.append(title_value)
            detail["title"] = title_value
        if description is not None:
            updates.append("description = ?")
            params.append(str(description or ""))
            detail["description_changed"] = True
        if created_by_human is not None:
            # Re-filing a task under a different person. Admin-only at the API,
            # because the filer decides which private agents may run it, and it
            # is needed for exactly two operator jobs: backfilling a ledger
            # that predates recorded filers, and repairing a mis-filed task.
            owner_value = str(created_by_human).strip()
            resolved_owner = (
                self._resolve_agent_owner(owner_value) if owner_value else None
            )
            updates.append("created_by_human = ?")
            params.append(resolved_owner)
            detail["created_by_human"] = resolved_owner
        if project is not None:
            new_project = str(project).strip() or None
            updates.append("project = ?")
            params.append(new_project)
            detail["project"] = new_project
        if priority is not None:
            updates.append("priority = ?")
            params.append(int(priority))
            detail["priority"] = int(priority)
        if dependencies is not None:
            dep_ids = self._canonical_dependency_ids(dependencies)
            if task.id in dep_ids:
                raise ValidationError("task cannot depend on itself")
            dependency_ids = dep_ids
            updates.append("dependencies = ?")
            params.append(json_dumps(dep_ids))
            detail["dependencies"] = dep_ids
            if task.state in {
                TaskState.OPEN.value,
                TaskState.WAITING.value,
                TaskState.BLOCKED.value,
            }:
                next_state = TaskState.WAITING.value if dep_ids else TaskState.OPEN.value
                updates.append("state = ?")
                params.append(next_state)
                detail["state"] = next_state
        should_reconcile_metadata = metadata is not None or project is not None or required_capabilities is not None
        explicit_required_capabilities_update = required_capabilities is not None
        if required_capabilities is not None:
            new_capabilities = coerce_list(required_capabilities)
        if metadata is not None:
            new_metadata = ensure_json_object(metadata)
            if _preserve_control_plane_publication_metadata:
                persisted_metadata = ensure_json_object(task.metadata)
                for key in (
                    "managed_fast_lane",
                ):
                    # Internal callers may round-trip a task's metadata while
                    # changing an unrelated controller-owned field.  Never
                    # trust the supplied derived value: remove it before the
                    # public validation gate, then restore only the exact value
                    # already persisted by the control plane.
                    new_metadata.pop(key, None)
                    if key in persisted_metadata:
                        preserved_publication_metadata[key] = persisted_metadata[key]
            self._reject_reserved_break_glass_metadata(new_metadata)
        dependency_quarantine = (
            ensure_json_object(new_metadata.get("dependency_quarantine"))
            if dependency_ids is not None
            else {}
        )
        if dependency_quarantine:
            new_metadata.pop("dependency_quarantine", None)
            if (
                dependency_quarantine.get("applied_no_dispatch")
                and new_metadata.get("no_dispatch") is True
            ):
                new_metadata.pop("no_dispatch", None)
            should_reconcile_metadata = True
            detail["dependency_quarantine_cleared"] = True
        if should_reconcile_metadata:
            new_capabilities, new_metadata = self._apply_project_task_defaults(
                new_project,
                new_capabilities,
                ensure_json_object(new_metadata),
            )
            new_metadata = self._normalize_task_execution_contract(
                new_metadata,
                new_project,
                new_capabilities,
            )
            new_capabilities, new_metadata = self._decouple_repository_commands_from_capabilities(
                new_capabilities,
                new_metadata,
            )
            if preserved_publication_metadata:
                new_metadata.update(preserved_publication_metadata)
            if explicit_required_capabilities_update or new_capabilities != list(task.required_capabilities):
                updates.append("required_capabilities = ?")
                params.append(json_dumps(new_capabilities))
                detail["required_capabilities"] = new_capabilities
            updates.append("metadata = ?")
            params.append(json_dumps(new_metadata))
            if metadata is not None:
                detail["metadata_changed"] = True
            else:
                detail["metadata_reconciled"] = True
        if max_attempts is not None:
            if int(max_attempts) < 1:
                raise ValidationError("max_attempts must be >= 1")
            updates.append("max_attempts = ?")
            params.append(int(max_attempts))
            detail["max_attempts"] = int(max_attempts)
        if not updates:
            return task
        updates.append("updated_at = ?")
        params.append(utcnow())
        params.append(task.id)
        with self.store.transaction() as conn:
            if dependency_ids is not None:
                lock_dependency_nodes(
                    conn,
                    task_id=task.id,
                    dependency_ids=dependency_ids,
                )
                cycle = dependency_cycle_path(
                    conn,
                    task_id=task.id,
                    dependency_ids=dependency_ids,
                )
                if cycle is not None:
                    raise ValidationError(
                        "task dependency cycle: %s" % " -> ".join(cycle)
                    )
            conn.execute(
                "UPDATE tasks SET %s WHERE id = ?" % ", ".join(updates),
                tuple(params),
            )
            if dependency_ids is not None:
                replace_task_edges(
                    conn,
                    task_id=task.id,
                    dependency_ids=dependency_ids,
                    updated_at=str(params[-2]),
                )
        updated = self.get_task(task.id)
        self._record_history(
            task.id,
            "task.updated",
            actor,
            task.state,
            updated.state,
            detail,
        )
        return updated

    def append_task_activity(
        self,
        task_id: str,
        phase: str,
        actor: str,
        summary: str,
        *,
        detail: Optional[Mapping[str, Any]] = None,
        max_entries: int = 24,
        lease_id: Optional[str] = None,
        trusted_internal: bool = True,
    ) -> Task:
        """Append a short, human-readable entry to the task's per-task activity
        narrative (``task.metadata['activity']``).

        This is a glanceable, additive record of what happened on a task -- what
        the worker did, what the reviewer found/fixed, environment changes made to
        build/test -- a few lines per phase, the way a person watching the
        claude/codex/cursor CLI would summarize it. It deliberately does NOT touch
        evidence, history, or the verification pipeline (those remain the durable
        forensic logs); it is surfaced by ``mac task summary`` / ``task show``.
        """
        summary = str(summary or "").strip()
        if not summary:
            return self.get_task(task_id)
        phase = (str(phase or "").strip().lower() or "note")[:24]
        # Keep it glanceable: a few lines, bounded length.
        lines = [ln.rstrip() for ln in summary.splitlines() if ln.strip()][:6]
        summary = "\n".join(lines)[:1200]
        task = self.get_task(task_id)
        fenced_lease_id: Optional[str] = None
        reviewer_authorized = False
        if not trusted_internal:
            if task.state in {TaskState.CLAIMED.value, TaskState.RUNNING.value}:
                self._require_exact_lease_actor(task, actor, lease_id)
                fenced_lease_id = str(lease_id or "").strip()
            else:
                reviewer_authorized = self.store.query_one(
                    "SELECT 1 FROM reviews WHERE task_id = ? "
                    "AND reviewer_agent_id = ? AND status = ? LIMIT 1",
                    (task.id, actor, ReviewStatus.PENDING.value),
                ) is not None
                if not reviewer_authorized:
                    raise AuthorizationError(
                        "activity author is neither the active lease actor nor pending reviewer"
                    )
        now = utcnow()
        with self.store.transaction() as conn:
            if fenced_lease_id:
                self._require_exact_lease_actor_in_transaction(
                    conn,
                    task_id=task.id,
                    agent_id=actor,
                    lease_id=fenced_lease_id,
                    allowed_states=(TaskState.CLAIMED.value, TaskState.RUNNING.value),
                )
            else:
                task_lock = conn.execute(
                    "UPDATE tasks SET updated_at = updated_at WHERE id = ?",
                    (task.id,),
                )
                if task_lock.rowcount != 1:
                    raise NotFoundError("task not found: %s" % task.id)
                if reviewer_authorized:
                    review_lock = conn.execute(
                        "UPDATE reviews SET status = status "
                        "WHERE task_id = ? AND reviewer_agent_id = ? AND status = ?",
                        (task.id, actor, ReviewStatus.PENDING.value),
                    )
                    if review_lock.rowcount < 1:
                        raise AuthorizationError("review activity authority changed")
            current_row = conn.execute(
                "SELECT metadata FROM tasks WHERE id = ?", (task.id,)
            ).fetchone()
            if current_row is None:
                raise NotFoundError("task not found: %s" % task.id)
            metadata = json_loads(current_row["metadata"], {})
            activity = metadata.get("activity")
            if not isinstance(activity, list):
                activity = []
            entry: JsonDict = {
                "phase": phase,
                "actor": str(actor or "")[:120],
                "summary": summary,
                "at": now,
            }
            if detail:
                entry["detail"] = ensure_json_object(dict(detail))
            activity.append(entry)
            metadata["activity"] = activity[-max_entries:]
            conn.execute(
                "UPDATE tasks SET metadata = ?, updated_at = ? WHERE id = ?",
                (json_dumps(metadata), now, task.id),
            )
        return self.get_task(task_id)

    def _persist_task_metadata_narrow(
        self,
        task_id: str,
        metadata: Dict[str, Any],
        *,
        actor: str = "human",
        detail: Optional[Dict[str, Any]] = None,
    ) -> Task:
        """Persist a task's metadata exactly as supplied (trusted internal).

        This is a narrow, control-plane-authorized metadata write for callers
        that have already computed the authoritative metadata object and must
        preserve control-plane-owned fields (e.g. ``managed_fast_lane``)
        byte-for-byte.  Unlike :meth:`update_task`, it does NOT run the
        user-input guard (:meth:`_reject_reserved_break_glass_metadata`) or
        re-run project-default/execution-contract/capability reconciliation,
        so it never mutates or rejects controller-owned routing metadata.
        Only the ``metadata`` column and ``updated_at`` are touched.
        """
        task = self.get_task(task_id)
        # RESOLVED id from here on. `get_task` expands an abbreviation
        # (task_78bf3c52 -> the full 32-hex id); the raw argument does not.
        # Using it below did two different kinds of damage:
        #
        #   * `UPDATE tasks ... WHERE id = <abbreviation>` matched ZERO rows
        #     and reported success -- a metadata write that silently wrote
        #     nothing, which is the worse of the two because nothing failed.
        #   * `_record_history` wrote it into task_history.task_id, a foreign
        #     key into tasks, so the insert raised and the request 500'd:
        #
        #       insert or update on table "task_history" violates foreign key
        #       constraint "task_history_task_id_fkey"
        #       DETAIL: Key (task_id)=(task_78bf3c52) is not present in tables
        #
        # `mac task list` prints short ids by default, so this was reachable by
        # copying what the CLI had just shown you: `mac task release <short>`
        # 500'd every time, and release is the ONLY way out of a --no-dispatch
        # hold (claim refuses, and open -> completed is not a legal move).
        resolved_id = task.id
        new_metadata = ensure_json_object(metadata)
        now = utcnow()
        self.store.execute(
            "UPDATE tasks SET metadata = ?, updated_at = ? WHERE id = ?",
            (json_dumps(new_metadata), now, resolved_id),
        )
        history_detail: JsonDict = {"metadata_changed": True}
        if detail:
            history_detail.update(ensure_json_object(dict(detail)))
        updated = self.get_task(resolved_id)
        self._record_history(
            resolved_id,
            "task.updated",
            actor,
            task.state,
            updated.state,
            history_detail,
        )
        return updated

    def release_task(self, task_id: str, *, actor: str = "human") -> Task:
        """Clear a per-task dispatch hold (``no_dispatch``), un-staging it.

        The inverse of ``mac task create --no-dispatch``: once released the
        task becomes eligible for autonomous claim and re-appears in the ready
        queue (subject to dependencies, capability match, and any project-level
        pause). No-op if the task is not held.
        """
        task = self.get_task(task_id)
        md = ensure_json_object(task.metadata)
        if not md.pop("no_dispatch", None):
            return task
        # Releasing a staged task is a narrow, control-plane-authorized
        # mutation: remove the ``no_dispatch`` hold while preserving every
        # other field byte-for-byte.  Routing metadata such as
        # ``managed_fast_lane``
        # is control-plane-owned and may have been attached
        # after creation; it must NOT be routed through the user-input guard
        # (``_reject_reserved_break_glass_metadata``) or re-normalized via
        # project-default/execution-contract/capability reconciliation on
        # release.  Persist the exact metadata directly instead.
        return self._persist_task_metadata_narrow(
            task_id,
            md,
            actor=actor,
            detail={"released": True},
        )

    def _task_decompose_depth(self, task: Task, *, _max_walk: int = 64) -> int:
        """Count ancestors above *task* via the parent_task_id chain.

        0 = a root task (no parent). Cycle- and runaway-safe: the walk is
        bounded and de-dups visited ids. Used to enforce the decomposition
        depth cap so a deep chain of child-of-child tasks can't recurse forever.
        """
        depth = 0
        current = task
        seen: set = set()
        for _ in range(_max_walk):
            meta = ensure_json_object(current.metadata)
            relationships = ensure_json_object(meta.get("relationships"))
            parent_id = relationships.get("parent_task_id") or meta.get("parent_task_id")
            if not parent_id or parent_id in seen:
                break
            seen.add(parent_id)
            try:
                current = self.get_task(str(parent_id))
            except NotFoundError:
                break
            depth += 1
        return depth

    def add_child_tasks(
        self,
        task_id: str,
        children: Iterable[Dict[str, Any]],
        *,
        actor: str = "human",
        lease_id: Optional[str] = None,
        trusted_internal: bool = True,
    ) -> JsonDict:
        parent = self.get_task(task_id)
        # Decomposition is the SUBMITTER's declaration, enforced here rather
        # than only described in the executor prompt: prompt text is advice to
        # a model, and this is the part that holds when the model decides
        # otherwise.
        #
        # Scoped to UNTRUSTED callers -- an executing agent acting under a
        # lease. An operator or an internal coordinator adding children IS the
        # submitter declaring, and work-package assembly legitimately builds
        # its own graph. The defect was an agent splitting a task nobody asked
        # to split; it was not "children are bad".
        requested = list(children)
        children = requested
        fenced_lease_id: Optional[str] = None
        if not trusted_internal:
            if parent.state not in {TaskState.CLAIMED.value, TaskState.RUNNING.value}:
                raise AuthorizationError(
                    "non-admin child creation requires an active task lease"
                )
            self._require_exact_lease_actor(parent, actor, lease_id)
            fenced_lease_id = str(lease_id or "").strip()
            # Only now that the caller is proven to hold this task's lease:
            # decomposition is the submitter's declaration, and an executing
            # agent may not overrule it. Authorization first, policy second --
            # otherwise a worker probing a peer task learns its policy instead
            # of being told it has no business asking.
            allowed, refusal = check_children_allowed(parent, len(requested))
            if not allowed:
                raise ValidationError("cannot add child tasks: %s" % refusal)
        if parent.state not in {
            TaskState.OPEN.value,
            TaskState.WAITING.value,
            TaskState.BLOCKED.value,
            TaskState.CLAIMED.value,
            TaskState.RUNNING.value,
        }:
            raise ValidationError(
                "child tasks can only be added to open, waiting, blocked, claimed, or running tasks"
            )

        # --- Decomposition guardrails (T1) -----------------------------------
        # Server-side backstop against the runaway auto-decompose that hit the
        # live fleet. Refuse to decompose handoff/plan-note tasks, refuse beyond
        # the depth cap, and bound the cumulative child count per parent.
        parent_metadata = ensure_json_object(parent.metadata)
        if parent_metadata.get("no_decompose"):
            raise ValidationError(
                "task %s is marked no_decompose (handoff/plan note) — refusing to "
                "create child tasks; execute or stage it directly" % parent.id
            )
        max_depth = _int_env("MAC_MAX_DECOMPOSE_DEPTH", DEFAULT_MAX_DECOMPOSE_DEPTH)
        depth = self._task_decompose_depth(parent)
        if depth >= max_depth:
            raise ValidationError(
                "decomposition depth limit reached: task %s is at depth %d (max %d) "
                "— execute it directly instead of decomposing further"
                % (parent.id, depth, max_depth)
            )

        specs = [ensure_json_object(spec) for spec in children]
        if not specs:
            raise ValidationError("at least one child task is required")

        max_children = _int_env(
            "MAC_MAX_CHILD_TASKS_PER_PARENT", DEFAULT_MAX_CHILD_TASKS_PER_PARENT
        )
        existing_children = _metadata_string_list(
            ensure_json_object(parent_metadata.get("relationships")).get("child_task_ids")
        )
        projected = len(existing_children) + len(specs)
        if projected > max_children:
            raise ValidationError(
                "child task limit exceeded for %s: %d existing + %d requested = %d "
                "(max %d) — split into a smaller plan or raise "
                "MAC_MAX_CHILD_TASKS_PER_PARENT"
                % (parent.id, len(existing_children), len(specs), projected, max_children)
            )

        # Allocate every child id before validating dependencies so one atomic
        # request can express a real sibling DAG.  ``node_id`` is a request-local
        # symbolic key; ``depends_on`` may reference earlier keys and is resolved
        # here to the durable task ids stored in ``dependencies``.  Previously
        # the planner prompt claimed list order implied dependencies, but this
        # method never implemented that claim, so every child arrived runnable.
        allocated_child_ids = [new_id("task") for _ in specs]
        node_index_by_id: Dict[str, int] = {}
        node_ids: List[Optional[str]] = []
        for index, spec in enumerate(specs, start=1):
            raw_node_id = spec.get("node_id")
            if raw_node_id is None:
                node_ids.append(None)
                continue
            node_id = str(raw_node_id).strip()
            if not node_id:
                raise ValidationError("child task %d node_id cannot be blank" % index)
            if node_id in node_index_by_id:
                raise ValidationError("child task node_id %r is duplicated" % node_id)
            node_index_by_id[node_id] = index - 1
            node_ids.append(node_id)

        prepared: List[JsonDict] = []
        for index, spec in enumerate(specs, start=1):
            title = str(spec.get("title") or "").strip()
            if not title:
                raise ValidationError("child task %d title is required" % index)
            legacy_dependencies = _unique_ordered(
                _metadata_string_list(spec.get("dependencies"))
            )
            symbolic_dependencies = (
                _unique_ordered(_metadata_string_list(spec.get("depends_on")))
                if spec.get("depends_on") is not None
                else None
            )
            if (
                symbolic_dependencies is not None
                and legacy_dependencies
                and symbolic_dependencies != legacy_dependencies
            ):
                raise ValidationError(
                    "child task %d supplies conflicting dependencies and depends_on" % index
                )
            dependency_refs = (
                symbolic_dependencies
                if symbolic_dependencies is not None
                else legacy_dependencies
            )
            child_dependencies: List[str] = []
            for dependency_ref in dependency_refs:
                if dependency_ref == parent.id:
                    raise ValidationError("child task cannot depend on its parent")
                sibling_index = node_index_by_id.get(dependency_ref)
                if sibling_index is not None:
                    if sibling_index >= index - 1:
                        raise ValidationError(
                            "child task %d depends_on %r, which must reference an earlier "
                            "sibling node_id" % (index, dependency_ref)
                        )
                    dependency_id = allocated_child_ids[sibling_index]
                else:
                    dependency_id = self.get_task(dependency_ref).id
                    if dependency_id == parent.id:
                        raise ValidationError("child task cannot depend on its parent")
                child_dependencies.append(dependency_id)
            child_dependencies = _unique_ordered(child_dependencies)
            child_project = (
                str(spec.get("project")).strip()
                if spec.get("project") is not None
                else parent.project
            )
            child_project = child_project or None
            child_capabilities = (
                coerce_list(spec.get("required_capabilities"))
                if spec.get("required_capabilities") is not None
                else list(parent.required_capabilities)
            )
            child_metadata = ensure_json_object(spec.get("metadata"))
            dependency_policy = ensure_json_object(
                child_metadata.get("dependency_policy")
            )
            dependency_policy.setdefault("on_unsatisfied", "supervise")
            child_metadata["dependency_policy"] = dependency_policy
            # Cooperative children get exactly the existing bounded,
            # deterministic environment-repair path.  The repair mechanism has
            # its own recursion guard, so inheriting this opt-in cannot create
            # repair-of-repair chains.
            repair_policy = ensure_json_object(child_metadata.get("repair_policy"))
            repair_policy.setdefault("environment_prerequisite", True)
            child_metadata["repair_policy"] = repair_policy
            relationships = ensure_json_object(child_metadata.get("relationships"))
            relationships["parent_task_id"] = parent.id
            relationships["relationship"] = "child"
            relationships["blocks"] = _unique_ordered(
                [*_metadata_string_list(relationships.get("blocks")), parent.id]
            )
            child_metadata["relationships"] = relationships
            child_metadata.setdefault("parent_task_id", parent.id)
            child_metadata.setdefault("parent_task_title", parent.title)
            coordination = ensure_json_object(child_metadata.get("coordination"))
            coordination.update(
                {
                    "mode": "cooperative_child",
                    "integration_task_id": parent.id,
                    "require_distinct_agent": True,
                }
            )
            if node_ids[index - 1] is not None:
                coordination["plan_node_id"] = node_ids[index - 1]
                coordination["depends_on_nodes"] = list(dependency_refs)
            child_metadata["coordination"] = coordination
            normalized_metadata = self._normalize_task_execution_contract(
                child_metadata,
                child_project,
                child_capabilities,
            )
            normalized_metadata, optimizer_assignment = (
                self.optimizer.prepare_task_assignment(
                    allocated_child_ids[index - 1],
                    child_project,
                    normalized_metadata,
                )
            )
            prepared.append(
                {
                    "id": allocated_child_ids[index - 1],
                    "title": title,
                    "description": str(spec.get("description") or ""),
                    "project": child_project,
                    "priority": int(
                        spec["priority"]
                        if spec.get("priority") is not None
                        else parent.priority
                    ),
                    "state": (
                        TaskState.WAITING.value
                        if child_dependencies
                        else TaskState.OPEN.value
                    ),
                    "required_capabilities": child_capabilities,
                    "dependencies": child_dependencies,
                    "metadata": normalized_metadata,
                    "optimizer_assignment": optimizer_assignment,
                    "max_attempts": int(
                        spec["max_attempts"]
                        if spec.get("max_attempts") is not None
                        else parent.max_attempts
                    ),
                }
            )
            if prepared[-1]["max_attempts"] < 1:
                raise ValidationError("child task max_attempts must be >= 1")

        now = utcnow()
        child_ids = [item["id"] for item in prepared]
        parent_dependencies = _unique_ordered(
            [*self._canonical_task_dependency_ids(parent.id), *child_ids]
        )
        parent_metadata = ensure_json_object(parent.metadata)
        parent_dependency_policy = ensure_json_object(
            parent_metadata.get("dependency_policy")
        )
        parent_dependency_policy.setdefault("on_unsatisfied", "supervise")
        parent_dependency_policy.setdefault("join", "all_settled")
        parent_metadata["dependency_policy"] = parent_dependency_policy
        parent_repair_policy = ensure_json_object(
            parent_metadata.get("repair_policy")
        )
        parent_repair_policy.setdefault("environment_prerequisite", True)
        parent_metadata["repair_policy"] = parent_repair_policy
        parent_relationships = ensure_json_object(parent_metadata.get("relationships"))
        parent_relationships["child_task_ids"] = _unique_ordered(
            [*_metadata_string_list(parent_relationships.get("child_task_ids")), *child_ids]
        )
        parent_relationships["blocked_by_task_ids"] = parent_dependencies
        parent_metadata["relationships"] = parent_relationships
        parent_coordination = ensure_json_object(parent_metadata.get("coordination"))
        parent_coordination.update(
            {
                "mode": "cooperative_integration",
                "phase": "awaiting_children",
                "failure_policy": parent_dependency_policy["on_unsatisfied"],
                "join_policy": parent_dependency_policy["join"],
                "child_task_ids": _unique_ordered(
                    [
                        *_metadata_string_list(parent_coordination.get("child_task_ids")),
                        *child_ids,
                    ]
                ),
                "require_distinct_agent": True,
            }
        )
        parent_metadata["coordination"] = parent_coordination

        release_lease_id = parent.lease_id
        with self.store.transaction() as conn:
            # Serialize decomposition with every other parent graph rewrite.
            # The plan was prepared from ``parent`` above, so fail and retry if
            # that snapshot changed while this transaction waited for the row.
            parent_lock = conn.execute(
                "UPDATE tasks SET updated_at = updated_at WHERE id = ?",
                (parent.id,),
            )
            if parent_lock.rowcount != 1:
                raise NotFoundError("task not found: %s" % parent.id)
            current_parent = conn.execute(
                "SELECT updated_at FROM tasks WHERE id = ?",
                (parent.id,),
            ).fetchone()
            if (
                current_parent is None
                or str(current_parent["updated_at"]) != str(parent.updated_at)
            ):
                raise TransitionError(
                    "parent task changed while decomposition was being prepared; retry"
                )
            if fenced_lease_id:
                self._require_exact_lease_actor_in_transaction(
                    conn,
                    task_id=parent.id,
                    agent_id=actor,
                    lease_id=fenced_lease_id,
                    allowed_states=(parent.state,),
                )
            for child in prepared:
                conn.execute(
                    """
                    INSERT INTO tasks (
                        id, title, description, project, priority, state,
                        required_capabilities, dependencies, metadata,
                        owner_agent_id, lease_id, leased_until, attempt_count,
                        max_attempts, started_at, completed_at, created_at, updated_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, NULL, NULL, 0, ?, NULL, NULL, ?, ?)
                    """,
                    (
                        child["id"],
                        child["title"],
                        child["description"],
                        child["project"],
                        child["priority"],
                        child["state"],
                        json_dumps(child["required_capabilities"]),
                        json_dumps(child["dependencies"]),
                        json_dumps(child["metadata"]),
                        child["max_attempts"],
                        now,
                        now,
                    ),
                )
            for child in prepared:
                cycle = dependency_cycle_path(
                    conn,
                    task_id=child["id"],
                    dependency_ids=child["dependencies"],
                )
                if cycle is not None:
                    raise ValidationError(
                        "task dependency cycle: %s" % " -> ".join(cycle)
                    )
                replace_task_edges(
                    conn,
                    task_id=child["id"],
                    dependency_ids=child["dependencies"],
                    updated_at=now,
                )
            for child in prepared:
                child_creation_detail = {
                    "title": child["title"],
                    "parent_task_id": parent.id,
                    "relationship": "child",
                    "dependencies": child["dependencies"],
                }
                self._record_history(
                    child["id"],
                    "task.created",
                    actor,
                    None,
                    child["state"],
                    child_creation_detail,
                    conn=conn,
                )
                if child["optimizer_assignment"] is not None:
                    self.optimizer.insert_assignment(
                        conn, child["optimizer_assignment"]
                    )
            if release_lease_id:
                conn.execute(
                    "UPDATE leases SET status = ?, updated_at = ? WHERE id = ? AND status = ?",
                    (LeaseStatus.RELEASED.value, now, release_lease_id, LeaseStatus.ACTIVE.value),
                )
                self._consume_break_glass_authorizations(
                    conn,
                    task_id=task_id,
                    lease_id=release_lease_id,
                    now=now,
                )
            parent_where = "WHERE id = ? AND state = ?"
            parent_guards: List[Any] = [parent.id, parent.state]
            if fenced_lease_id:
                parent_where += " AND lease_id = ?"
                parent_guards.append(fenced_lease_id)
            parent_update = conn.execute(
                """
                UPDATE tasks
                SET dependencies = ?, metadata = ?, state = ?, owner_agent_id = NULL,
                    lease_id = NULL, leased_until = NULL, updated_at = ?
                """ + parent_where,
                tuple(
                    [
                        json_dumps(parent_dependencies),
                        json_dumps(parent_metadata),
                        TaskState.WAITING.value,
                        now,
                    ]
                    + parent_guards
                ),
            )
            if parent_update.rowcount != 1:
                raise TransitionError("parent assignment changed during decomposition")
            cycle = dependency_cycle_path(
                conn,
                task_id=parent.id,
                dependency_ids=parent_dependencies,
            )
            if cycle is not None:
                raise ValidationError(
                    "task dependency cycle: %s" % " -> ".join(cycle)
                )
            replace_task_edges(
                conn,
                task_id=parent.id,
                dependency_ids=parent_dependencies,
                updated_at=now,
            )
            if parent.owner_agent_id:
                self._set_agent_idle(parent.owner_agent_id, conn=conn)
            detail = {
                "reason": "waiting_on_dependencies",
                "child_task_ids": child_ids,
                "blocked_by_task_ids": parent_dependencies,
                "released_lease_id": release_lease_id,
                "dependency_graph": [
                    {
                        "node_id": node_ids[index],
                        "task_id": child["id"],
                        "dependencies": child["dependencies"],
                    }
                    for index, child in enumerate(prepared)
                ],
            }
            self._record_history(
                parent.id,
                "task.children_added",
                actor,
                parent.state,
                TaskState.WAITING.value,
                detail,
                conn=conn,
            )

        self.drain_task_transition_outbox(task_id=parent.id, limit=20)
        return {
            "parent": self.get_task(parent.id).to_dict(),
            "children": [self.get_task(child_id).to_dict() for child_id in child_ids],
            "relationships": {
                "blocked_by": parent_dependencies,
                "blocks": [],
                "children": child_ids,
            },
        }

    def delete_task(self, task_id: str, *, force: bool = False, actor: str = "human") -> None:
        task = self.get_task(task_id)
        with self.store.transaction() as conn:
            if self.store.backend_identity().get("backend") == "postgres":
                # Dependency rewrites lock task nodes in canonical ID order.
                # Deletion otherwise has to discover dependents after locking
                # the target, which inverts that order and can deadlock with a
                # concurrent update.  Serialize the small dependency-graph
                # mutation section on PostgreSQL; SQLite transactions are
                # already single-writer.
                conn.execute(
                    "LOCK TABLE tasks, task_edges IN SHARE ROW EXCLUSIVE MODE"
                )
            target_lock = conn.execute(
                "UPDATE tasks SET updated_at = updated_at WHERE id = ?",
                (task.id,),
            )
            if target_lock.rowcount != 1:
                raise NotFoundError("task not found: %s" % task.id)
            active = conn.execute(
                "SELECT 1 FROM leases WHERE task_id = ? AND status = ? LIMIT 1",
                (task.id, LeaseStatus.ACTIVE.value),
            ).fetchone()
            if active is not None:
                raise ValidationError(
                    "task cannot be deleted while it has an active lease"
                )
            dependent_rows = conn.execute(
                "SELECT task_id FROM task_edges WHERE dependency_task_id = ? "
                "ORDER BY task_id",
                (task.id,),
            ).fetchall()
            dependent_ids = [str(row["task_id"]) for row in dependent_rows]
            lock_dependency_nodes(
                conn,
                task_id=task.id,
                dependency_ids=dependent_ids,
            )
            dependents = []
            for dependent_id in dependent_ids:
                dependent_row = conn.execute(
                    "SELECT * FROM tasks WHERE id = ?",
                    (dependent_id,),
                ).fetchone()
                if dependent_row is not None:
                    dependents.append(self._task_from_row(dependent_row))
            if dependents and not force:
                raise ValidationError(
                    "task has dependent tasks: %s"
                    % ", ".join(item.id for item in dependents)
                )
            for dependent in dependents:
                remaining = [
                    dep_id
                    for dep_id in self._canonical_task_dependency_ids(
                        dependent.id,
                        conn=conn,
                    )
                    if dep_id != task.id
                ]
                next_state = (
                    TaskState.OPEN.value
                    if dependent.state == TaskState.WAITING.value and not remaining
                    else dependent.state
                )
                updated_at = utcnow()
                conn.execute(
                    """
                    UPDATE tasks SET dependencies = ?, state = ?, updated_at = ?
                    WHERE id = ?
                    """,
                    (json_dumps(remaining), next_state, updated_at, dependent.id),
                )
                replace_task_edges(
                    conn,
                    task_id=dependent.id,
                    dependency_ids=remaining,
                    updated_at=updated_at,
                )
            conn.execute("DELETE FROM tasks WHERE id = ?", (task.id,))
        self.record_notification(
            "task.deleted",
            "Task deleted: %s" % task.title,
            "Task was deleted by %s." % actor,
            subject_type="task",
            subject_id=task.id,
            channels=["dashboard"],
            metadata={"actor": actor, "force": force},
        )

    @staticmethod
    def _project_item_project_key(item: JsonDict) -> str:
        return str(item.get("project") or item.get("source") or "unassigned")

    @staticmethod
    def _repository_project_key(repository: JsonDict) -> str:
        return str(
            repository.get("project")
            or repository.get("name")
            or repository.get("source")
            or "unassigned"
        )

    def list_projects(self) -> List[JsonDict]:
        return self._hermes_project_contexts(
            self.list_tasks(),
            self.list_agents(),
            [item.to_dict() for item in self.list_project_items()],
            [repository.to_dict() for repository in self.list_project_repositories()],
            [project.to_dict() for project in self.list_project_records()],
        )

    def create_project(
        self,
        name: str,
        description: str = "",
        *,
        metadata: Optional[Dict[str, Any]] = None,
        status: str = "active",
        actor: str = "human",
        project_id: Optional[str] = None,
        dispatch_paused: Optional[bool] = None,
    ) -> ProjectRecord:
        project_name = str(name or "").strip()
        if not project_name:
            raise ValidationError("project name is required")
        if _ONBOARDING_REMOTE_URL_RE.match(project_name):
            # A git URL is not a project name. Storing it as one produces a
            # junk project (name == URL, no repo linkage, nothing cloned).
            # Point the caller at the URL-only onboarding path instead.
            raise ValidationError(
                "project name looks like a git URL (%r); to register a project "
                "from a repository URL use `mac project register %s` "
                "(POST /projects/register), which clones the repo and reads "
                "its README/AGENTS/PLAN to build the project."
                % (project_name, project_name)
            )
        existing = self.store.query_one(
            "SELECT * FROM projects WHERE name = ?",
            (project_name,),
        )
        project_metadata = ensure_json_object(metadata)
        if actor:
            project_metadata.setdefault("created_by", actor)
        if dispatch_paused is not None:
            project_metadata["dispatch_paused"] = bool(dispatch_paused)
        if existing is not None:
            return self._project_record_from_row(existing)
        now = utcnow()
        pid = project_id or new_id("project")
        status_value = str(status or "active")
        with self.store.transaction() as conn:
            conn.execute(
                """
                INSERT INTO projects (id, name, description, metadata, status, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    pid,
                    project_name,
                    str(description or ""),
                    json_dumps(project_metadata),
                    status_value,
                    now,
                    now,
                ),
            )
            self._record_project_event(
                conn,
                pid,
                "project.created",
                actor,
                {
                    "project_id": pid,
                    "project_name": project_name,
                    "status": status_value,
                    "metadata_keys": sorted(project_metadata.keys()),
                },
                now,
            )
        notification_body = str(description or "Project %s was created." % project_name)
        self.record_notification(
            "project.created",
            "Project created: %s" % project_name,
            notification_body,
            subject_type="project",
            subject_id=project_name,
            channels=["dashboard", "hermes"],
            metadata={"project": project_name, "actor": actor},
        )
        return self.get_project_record(project_name)

    def get_project_record(self, name_or_id: str) -> ProjectRecord:
        row = self.store.query_one(
            "SELECT * FROM projects WHERE name = ? OR id = ?",
            (name_or_id, name_or_id),
        )
        if row is None:
            raise NotFoundError("project record not found: %s" % name_or_id)
        return self._project_record_from_row(row)

    def list_project_records(self) -> List[ProjectRecord]:
        rows = self.store.query_all("SELECT * FROM projects ORDER BY name, id")
        return [self._project_record_from_row(row) for row in rows]

    def get_project(self, project: str) -> JsonDict:
        project_key = str(project or "unassigned").strip() or "unassigned"
        summaries = {
            str(summary.get("project")): summary
            for summary in self.list_projects()
            if isinstance(summary, dict)
        }
        summary = summaries.get(project_key)
        if summary is None:
            raise NotFoundError("project not found: %s" % project_key)

        tasks = [
            task.to_dict()
            for task in self.list_tasks()
            if self._hermes_task_project_key(task) == project_key
        ]
        bridge_items = [
            item.to_dict()
            for item in self.list_project_items()
            if self._project_item_project_key(item.to_dict()) == project_key
        ]
        project_repositories = [
            repository.to_dict()
            for repository in self.list_project_repositories()
            if self._repository_project_key(repository.to_dict()) == project_key
        ]
        return {
            "project": project_key,
            "summary": summary,
            "record": (
                self.get_project_record(project_key).to_dict()
                if summary.get("project_id")
                else None
            ),
            "tasks": tasks,
            "bridge_items": bridge_items,
            "project_repositories": project_repositories,
        }

    def update_project(
        self,
        name_or_id: str,
        *,
        name: Optional[str] = None,
        description: Optional[str] = None,
        metadata: Optional[Dict[str, Any]] = None,
        status: Optional[str] = None,
        repository_registration: Optional[str] = None,
        default_branch: Optional[str] = None,
        actor: str = "human",
    ) -> ProjectRecord:
        project = self.get_project_record(name_or_id)
        registration_changed = (
            repository_registration is not None or default_branch is not None
        )
        normalized_registration: Optional[Tuple[str, str, str]] = None
        if registration_changed:
            project_metadata = ensure_json_object(
                metadata if metadata is not None else project.metadata
            )
            current_identity = _project_registration_from_metadata(
                ensure_json_object(project.metadata)
            )
            registration_value = str(repository_registration or "").strip()
            if not registration_value:
                if current_identity is None:
                    raise ValidationError(
                        "project has no repository registration; provide "
                        "GIT_URL#BRANCH"
                    )
                registration_value = current_identity[0]
            normalized_registration = _normalize_repository_registration(
                registration_value,
                default_branch=default_branch,
            )
            repository_url, branch, registration = normalized_registration
            self._assert_project_registration_available(
                repository_url,
                branch,
                exclude_project_id=project.id,
            )
            project_metadata["repository_url"] = repository_url
            project_metadata["default_branch"] = branch
            project_metadata["repository_registration"] = registration
            metadata = project_metadata
        updates: List[str] = []
        params: List[Any] = []
        new_name = project.name
        if name is not None:
            name_value = str(name or "").strip()
            if not name_value:
                raise ValidationError("project name is required")
            updates.append("name = ?")
            params.append(name_value)
            new_name = name_value
        changed_fields: List[str] = []
        if name is not None and new_name != project.name:
            changed_fields.append("name")
        if description is not None:
            updates.append("description = ?")
            params.append(str(description or ""))
            if str(description or "") != project.description:
                changed_fields.append("description")
        if metadata is not None:
            updates.append("metadata = ?")
            params.append(json_dumps(ensure_json_object(metadata)))
            changed_fields.append("metadata")
        if status is not None:
            status_value = str(status or "").strip().lower()
            if status_value not in {"active", "inactive", "archived"}:
                raise ValidationError("unsupported project status: %s" % status_value)
            updates.append("status = ?")
            params.append(status_value)
            if status_value != project.status:
                changed_fields.append("status")
        if not updates:
            return project
        now = utcnow()
        with self.store.transaction() as conn:
            updates.append("updated_at = ?")
            params.append(now)
            params.append(project.id)
            try:
                conn.execute(
                    "UPDATE projects SET %s WHERE id = ?" % ", ".join(updates),
                    tuple(params),
                )
            except Exception as exc:  # noqa: BLE001 - normalize sqlite uniqueness errors.
                if "UNIQUE" in str(exc).upper():
                    raise ValidationError("project already exists: %s" % new_name) from exc
                raise
            if new_name != project.name:
                conn.execute("UPDATE tasks SET project = ?, updated_at = ? WHERE project = ?", (new_name, now, project.name))
                conn.execute("UPDATE project_repositories SET project = ?, updated_at = ? WHERE project = ?", (new_name, now, project.name))
            if new_name != project.name or normalized_registration is not None:
                repository_url = (
                    normalized_registration[0]
                    if normalized_registration is not None
                    else None
                )
                branch = (
                    normalized_registration[1]
                    if normalized_registration is not None
                    else None
                )
                rows = conn.execute(
                    "SELECT id, metadata FROM project_repositories WHERE project = ?",
                    (new_name,),
                ).fetchall()
                for row in rows:
                    repository_metadata = ensure_json_object(
                        json_loads(row["metadata"], {})
                    )
                    contract = ensure_json_object(
                        repository_metadata.get("repository_contract")
                    )
                    if repository_url is not None:
                        contract_remote = str(
                            contract.get("canonical_remote_url") or ""
                        ).strip()
                        if contract_remote:
                            try:
                                same_remote = canonical_git_remote_identity(
                                    contract_remote
                                ) == canonical_git_remote_identity(repository_url)
                            except ValueError as exc:
                                raise ValidationError(
                                    "registered repository URL is invalid: %s"
                                    % exc
                                ) from exc
                            if not same_remote:
                                raise ValidationError(
                                    "cannot retarget project %s from %s to %s "
                                    "while a checkout is registered; unregister "
                                    "and register the new repository instead"
                                    % (
                                        new_name,
                                        contract_remote,
                                        repository_url,
                                    )
                                )
                        contract["canonical_remote_url"] = repository_url
                        contract["default_branch"] = branch
                    if contract:
                        contract["project"] = new_name
                        repository_metadata["repository_contract"] = contract
                        conn.execute(
                            "UPDATE project_repositories SET metadata = ?, "
                            "updated_at = ? WHERE id = ?",
                            (
                                json_dumps(repository_metadata),
                                now,
                                row["id"],
                            ),
                        )
            self._record_project_event(
                conn,
                project.id,
                "project.updated",
                actor,
                {
                    "project_id": project.id,
                    "project_name": new_name,
                    "previous_name": project.name,
                    "changed_fields": sorted(set(changed_fields)),
                    "previous_status": project.status,
                    "status": status_value if status is not None else project.status,
                },
                now,
            )
        self.record_notification(
            "project.updated",
            "Project updated: %s" % new_name,
            "Project was updated by %s." % actor,
            subject_type="project",
            subject_id=new_name,
            channels=["dashboard", "hermes"],
            metadata={"previous_name": project.name, "actor": actor},
        )
        return self.get_project_record(new_name)

    def set_project_dispatch(
        self,
        name_or_id: str,
        *,
        paused: bool,
        actor: str = "human",
    ) -> ProjectRecord:
        """Pause or resume autonomous dispatch for an entire project.

        Persists ``metadata.dispatch_paused`` on the project record. When
        paused, the project's open tickets are hidden from the ready queue and
        rejected by autonomous claim (reason ``project_dispatch_paused``);
        operators can still start them explicitly. This is the project-level
        onboarding gate that complements the per-task ``no_dispatch`` hold.
        """
        project = self.get_project_record(name_or_id)
        md = ensure_json_object(project.metadata)
        md["dispatch_paused"] = bool(paused)
        return self.update_project(project.id, metadata=md, actor=actor)

    def delete_project(self, name_or_id: str, *, force: bool = False, actor: str = "human") -> None:
        project = self.get_project_record(name_or_id)
        # project= is pushed into SQL; list_tasks() already supports it. Reading
        # every task in every project to keep one project's is the same
        # whole-table scan that made a one-row insert take 100s (task_e3caa954).
        tasks = self.list_tasks(project=project.name)
        repo_rows = self.store.query_all(
            "SELECT id FROM project_repositories WHERE project = ?",
            (project.name,),
        )
        if (tasks or repo_rows) and not force:
            blockers = []
            if tasks:
                blockers.append("%d task(s)" % len(tasks))
            if repo_rows:
                blockers.append("%d repository registration(s)" % len(repo_rows))
            raise ValidationError("project has linked records: %s" % ", ".join(blockers))
        now = utcnow()
        with self.store.transaction() as conn:
            if force:
                conn.execute("UPDATE tasks SET project = NULL, updated_at = ? WHERE project = ?", (now, project.name))
                conn.execute("UPDATE project_repositories SET enabled = 0, updated_at = ? WHERE project = ?", (now, project.name))
            self._record_project_event(
                conn,
                project.id,
                "project.deleted",
                actor,
                {
                    "project_id": project.id,
                    "project_name": project.name,
                    "force": bool(force),
                    "task_count": len(tasks),
                    "project_repository_count": len(repo_rows),
                },
                now,
            )
            conn.execute("DELETE FROM projects WHERE id = ?", (project.id,))
        self.record_notification(
            "project.deleted",
            "Project deleted: %s" % project.name,
            "Project was deleted by %s." % actor,
            subject_type="project",
            subject_id=project.name,
            channels=["dashboard"],
            metadata={"actor": actor, "force": force},
        )
        # The other direction matters too: a deleted project may have been the
        # only thing requiring a package, and a tool nothing asks for is still
        # sitting in the security boundary with nothing that would ever notice.
        self.check_sandbox_bom_drift(actor=actor)

    def task_detail(
        self,
        task_id: str,
        *,
        history_limit: Optional[int] = None,
        evidence_limit: Optional[int] = None,
        review_limit: Optional[int] = None,
        publication_limit: Optional[int] = None,
    ) -> JsonDict:
        task = self.get_task(task_id)
        resolved_task_id = task.id
        task_payload = task.to_dict()
        detail = {
            "task": task_payload,
            "history": [
                event.to_dict()
                for event in self.task_history(resolved_task_id, limit=history_limit)
            ],
            "evidence": [
                item.to_dict()
                for item in self.list_evidence(resolved_task_id, limit=evidence_limit)
            ],
            "reviews": [
                item.to_dict()
                for item in self.list_reviews(resolved_task_id, limit=review_limit)
            ],
            "publications": [
                item.to_dict()
                for item in self.list_publications(
                    resolved_task_id, limit=publication_limit
                )
            ],
            "llm_usage": self.observability.task_llm_usage(resolved_task_id),
        }
        flow_rows = self.store.query_all(
            "SELECT * FROM task_flow_spans WHERE task_id = ? "
            "ORDER BY attempt, started_at, stage",
            (resolved_task_id,),
        )
        if not flow_rows:
            self.task_flow.rebuild_task(resolved_task_id)
            flow_rows = self.store.query_all(
                "SELECT * FROM task_flow_spans WHERE task_id = ? "
                "ORDER BY attempt, started_at, stage",
                (resolved_task_id,),
            )
        detail["flow"] = {
            "schema": "mac.task_flow_detail.v1",
            "spans": [
                {
                    **{key: row[key] for key in row.keys()},
                    "metadata": json_loads(row["metadata"], {}),
                }
                for row in flow_rows
            ],
            "completions": [
                {
                    **{key: row[key] for key in row.keys()},
                    "per_stage_durations": json_loads(
                        row["per_stage_durations"], {}
                    ),
                    "metadata": json_loads(row["metadata"], {}),
                }
                for row in self.store.query_all(
                    "SELECT * FROM task_completions WHERE task_id = ? "
                    "ORDER BY attempt",
                    (resolved_task_id,),
                )
            ],
        }
        detail["profile"] = self._task_execution_profile(detail)
        return detail

    def _task_execution_profile(self, detail: Mapping[str, Any]) -> JsonDict:
        """Derive a bounded, read-only task cost and progress profile.

        This intentionally uses only task-attributed ledger records. It never
        calls a model and never executes an overview query, so operators can
        inspect an over-thinking task without adding more work to it.
        """
        task = (
            detail.get("task")
            if isinstance(detail.get("task"), Mapping)
            else {}
        )
        task_id = str(task.get("id") or "")
        llm_usage = (
            detail.get("llm_usage")
            if isinstance(detail.get("llm_usage"), Mapping)
            else {}
        )
        routes = [
            item
            for item in llm_usage.get("routes", [])
            if isinstance(item, Mapping)
        ]
        kpis = derive_task_kpis(
            detail,
            routes,
            outcome_horizon_seconds=0.0,
        )

        rows = self.store.query_all(
            """
            SELECT phase, command_id, duration_ms, returncode,
                   stdout_bytes, stderr_bytes
            FROM command_audit
            WHERE task_id = ?
            ORDER BY created_at DESC, id DESC
            LIMIT 1001
            """,
            (task_id,),
        )
        truncated = len(rows) > 1000
        rows = rows[:1000]
        terminal_rows = [
            row
            for row in rows
            if str(row["phase"] or "") in {"completed", "failed", "timeout", "error"}
        ]
        command_duration_ms = sum(
            float(row["duration_ms"] or 0.0) for row in terminal_rows
        )
        command_failures = sum(
            1
            for row in terminal_rows
            if str(row["phase"] or "") != "completed"
            or (
                row["returncode"] is not None
                and int(row["returncode"]) != 0
            )
        )
        command_output_bytes = sum(
            int(row["stdout_bytes"] or 0) + int(row["stderr_bytes"] or 0)
            for row in terminal_rows
        )

        state_dwell_ms: Dict[str, float] = {}
        history = [
            item
            for item in detail.get("history", [])
            if isinstance(item, Mapping)
        ]
        current_state = "open"
        cursor = parse_time(str(task.get("created_at") or utcnow()))
        for event in history:
            observed_at = parse_time(str(event.get("created_at") or cursor.isoformat()))
            if observed_at >= cursor:
                state_dwell_ms[current_state] = (
                    state_dwell_ms.get(current_state, 0.0)
                    + (observed_at - cursor).total_seconds() * 1000.0
                )
            next_state = str(event.get("to_state") or "")
            if next_state:
                current_state = next_state
            cursor = max(cursor, observed_at)
        terminal_at = task.get("completed_at")
        end = parse_time(str(terminal_at or utcnow()))
        if end >= cursor:
            state_dwell_ms[current_state] = (
                state_dwell_ms.get(current_state, 0.0)
                + (end - cursor).total_seconds() * 1000.0
            )

        evidence_count = len(detail.get("evidence", []))
        publication_count = len(detail.get("publications", []))
        review_count = len(detail.get("reviews", []))
        route_count = int(kpis.get("route_count") or 0)
        total_tokens = int(kpis.get("total_tokens") or 0)
        provider_attempts = sum(
            int(item.get("upstream_attempt_count") or 0) for item in routes
        )
        signals: List[JsonDict] = []
        if route_count >= 10 and evidence_count + publication_count == 0:
            signals.append(
                {
                    "code": "model_work_without_durable_output",
                    "severity": "warning",
                    "detail": (
                        "%d model routes produced no evidence or publication"
                        % route_count
                    ),
                }
            )
        if provider_attempts > route_count:
            signals.append(
                {
                    "code": "provider_retry_churn",
                    "severity": "warning",
                    "detail": "%d upstream attempts across %d model routes"
                    % (provider_attempts, route_count),
                }
            )
        if command_failures >= 3:
            signals.append(
                {
                    "code": "command_failure_churn",
                    "severity": "warning",
                    "detail": "%d failed terminal command records"
                    % command_failures,
                }
            )
        if total_tokens >= 250_000 and publication_count == 0:
            signals.append(
                {
                    "code": "high_token_work_without_publication",
                    "severity": "warning",
                    "detail": "%d tokens with no publication" % total_tokens,
                }
            )

        return {
            "schema": "mac.task_execution_profile.v1",
            "task_id": task_id,
            "kpis": kpis,
            "commands": {
                "terminal_count": len(terminal_rows),
                "failure_count": command_failures,
                "duration_ms": round(command_duration_ms, 3),
                "output_bytes": command_output_bytes,
                "truncated": truncated,
            },
            "provider_attempt_count": provider_attempts,
            "state_dwell_ms": {
                key: round(value, 3)
                for key, value in sorted(state_dwell_ms.items())
            },
            "progress": {
                "evidence_count": evidence_count,
                "review_count": review_count,
                "publication_count": publication_count,
            },
            "signals": signals,
        }



    def authorize_task_break_glass(
        self,
        task_id: str,
        agent_id: str,
        *,
        reason: str,
        authorized_by: str,
        ttl_seconds: int = 900,
    ) -> BreakGlassAuthorization:
        """Authorize one OPEN task to run directly on one trusted agent host.

        This record is the authority.  Task metadata is intentionally ignored,
        so a prompt, imported ticket, or ordinary task author cannot opt itself
        out of sandbox confinement.  The authorization is short-lived until
        claimed and single-use once bound to a lease.
        """

        task = self.get_task(task_id)
        agent = self.get_agent(agent_id)
        reason = str(reason or "").strip()
        authorized_by = str(authorized_by or "").strip()
        if task.state != TaskState.OPEN.value:
            raise ValidationError("break-glass authorization requires an open task")
        if metadata_declares_read_only_report_repository(task.metadata):
            raise ValidationError(
                "read-only repository reports cannot use host break-glass execution"
            )
        if isinstance(ensure_json_object(task.metadata).get("review_context"), dict):
            raise ValidationError(
                "review tasks cannot use host break-glass execution"
            )
        if not reason:
            raise ValidationError("break-glass reason is required")
        if not authorized_by:
            raise ValidationError("break-glass authorizer is required")
        ttl = int(ttl_seconds)
        if ttl < BREAK_GLASS_MIN_TTL_SECONDS or ttl > BREAK_GLASS_MAX_TTL_SECONDS:
            raise ValidationError(
                "break-glass ttl_seconds must be between %d and %d"
                % (BREAK_GLASS_MIN_TTL_SECONDS, BREAK_GLASS_MAX_TTL_SECONDS)
            )
        machine = self.get_machine(agent.machine_id)
        if not machine.trusted:
            raise AuthorizationError(
                "break-glass host execution requires a trusted machine"
            )
        if agent.health_status != HealthStatus.HEALTHY.value:
            raise ValidationError(
                "break-glass target agent must be healthy"
            )
        authorization_id = new_id("breakglass")
        metadata = {
            "schema": BREAK_GLASS_AUTHORIZATION_SCHEMA,
            "single_use": True,
            "bypasses": [
                "agent_dispatch_hold",
                "task_dispatch_hold",
                "project_dispatch_pause",
                "worker_claim_policy",
                "task_agent_compatibility",
                "openshell",
            ],
        }
        with self.store.transaction() as conn:
            # Serialize authorization creation with claim_task on the task row.
            # Without this lock an authorization for B could be inserted after
            # A's dispatch preflight while A was concurrently claiming, leaving
            # an active authorization stranded on B after A owned the task.
            task_lock = conn.execute(
                "UPDATE tasks SET updated_at = updated_at WHERE id = ?",
                (task.id,),
            )
            if task_lock.rowcount != 1:
                raise NotFoundError("task not found: %s" % task.id)
            current_task = conn.execute(
                "SELECT state, lease_id FROM tasks WHERE id = ?", (task.id,)
            ).fetchone()
            if (
                current_task is None
                or current_task["state"] != TaskState.OPEN.value
                or current_task["lease_id"] is not None
            ):
                raise ValidationError(
                    "break-glass authorization requires an open unleased task"
                )
            existing = conn.execute(
                """
                SELECT * FROM task_break_glass_authorizations
                WHERE task_id = ? AND status = 'active'
                ORDER BY created_at DESC LIMIT 1
                """,
                (task.id,),
            ).fetchone()
            if existing is not None:
                conn.execute(
                    "UPDATE task_break_glass_authorizations SET status = status "
                    "WHERE id = ?",
                    (existing["id"],),
                )
                existing = conn.execute(
                    "SELECT * FROM task_break_glass_authorizations WHERE id = ?",
                    (existing["id"],),
                ).fetchone()
            now = self._lease_authority_now_in_transaction(conn)
            expires_at = (
                parse_time(now) + timedelta(seconds=ttl)
            ).isoformat(timespec="microseconds")
            if (
                existing is not None
                and existing["status"] == "active"
                and self._timestamp_is_after(existing["expires_at"], now)
            ):
                raise ValidationError(
                    "task %s already has an active break-glass authorization"
                    % task.id
                )
            if existing is not None and existing["status"] == "active":
                conn.execute(
                    "UPDATE task_break_glass_authorizations SET status = 'expired' "
                    "WHERE id = ? AND status = 'active'",
                    (existing["id"],),
                )
            conn.execute(
                """
                INSERT INTO task_break_glass_authorizations (
                    id, task_id, agent_id, execution_boundary, reason,
                    authorized_by, status, metadata, created_at, expires_at,
                    claimed_at, lease_id, consumed_at, revoked_at, revoked_by,
                    revoke_reason
                ) VALUES (?, ?, ?, ?, ?, ?, 'active', ?, ?, ?, NULL, NULL, NULL, NULL, NULL, NULL)
                """,
                (
                    authorization_id,
                    task.id,
                    agent.id,
                    BREAK_GLASS_EXECUTION_BOUNDARY,
                    reason,
                    authorized_by,
                    json_dumps(metadata),
                    now,
                    expires_at,
                ),
            )
            self._record_history(
                task.id,
                "task.break_glass_authorized",
                authorized_by,
                task.state,
                task.state,
                {
                    "authorization_id": authorization_id,
                    "agent_id": agent.id,
                    "execution_boundary": BREAK_GLASS_EXECUTION_BOUNDARY,
                    "expires_at": expires_at,
                    "reason": reason,
                },
                conn=conn,
            )
        self.record_log(
            "task.break_glass.authorized",
            layer="control_plane",
            source=authorized_by,
            level="warning",
            subject_type="task",
            subject_id=task.id,
            detail={
                "authorization_id": authorization_id,
                "agent_id": agent.id,
                "execution_boundary": BREAK_GLASS_EXECUTION_BOUNDARY,
                "expires_at": expires_at,
                "reason": reason,
            },
        )
        return self.get_task_break_glass_authorization(authorization_id)

    def get_task_break_glass_authorization(
        self, authorization_id: str
    ) -> BreakGlassAuthorization:
        row = self.store.query_one(
            "SELECT * FROM task_break_glass_authorizations WHERE id = ?",
            (authorization_id,),
        )
        if row is None:
            raise NotFoundError(
                "break-glass authorization %s not found" % authorization_id
            )
        return self._break_glass_authorization_from_row(row)

    def list_task_break_glass_authorizations(
        self,
        *,
        task_id: Optional[str] = None,
        agent_id: Optional[str] = None,
        status: Optional[str] = None,
        limit: int = 100,
    ) -> List[BreakGlassAuthorization]:
        clauses: List[str] = []
        params: List[Any] = []
        if task_id is not None:
            resolved = self.get_task(task_id).id
            clauses.append("task_id = ?")
            params.append(resolved)
        if agent_id is not None:
            self.get_agent(agent_id)
            clauses.append("agent_id = ?")
            params.append(agent_id)
        if status is not None:
            clauses.append("status = ?")
            params.append(str(status))
        where = (" WHERE " + " AND ".join(clauses)) if clauses else ""
        params.append(max(1, min(int(limit), 1000)))
        rows = self.store.query_all(
            "SELECT * FROM task_break_glass_authorizations%s "
            "ORDER BY created_at DESC, id DESC LIMIT ?" % where,
            tuple(params),
        )
        return [self._break_glass_authorization_from_row(row) for row in rows]

    def revoke_task_break_glass(
        self,
        authorization_id: str,
        *,
        revoked_by: str,
        reason: str,
    ) -> BreakGlassAuthorization:
        authorization = self.get_task_break_glass_authorization(authorization_id)
        revoked_by = str(revoked_by or "").strip()
        reason = str(reason or "").strip()
        if not revoked_by or not reason:
            raise ValidationError("break-glass revoker and reason are required")
        if authorization.status != "active":
            raise ValidationError(
                "only an unclaimed active break-glass authorization can be revoked"
            )
        now = utcnow()
        task = self.get_task(authorization.task_id)
        with self.store.transaction() as conn:
            updated = conn.execute(
                """
                UPDATE task_break_glass_authorizations
                SET status = 'revoked', revoked_at = ?, revoked_by = ?, revoke_reason = ?
                WHERE id = ? AND status = 'active'
                """,
                (now, revoked_by, reason, authorization.id),
            )
            if updated.rowcount != 1:
                raise ValidationError("break-glass authorization changed concurrently")
            self._record_history(
                task.id,
                "task.break_glass_revoked",
                revoked_by,
                task.state,
                task.state,
                {
                    "authorization_id": authorization.id,
                    "agent_id": authorization.agent_id,
                    "reason": reason,
                },
                conn=conn,
            )
        return self.get_task_break_glass_authorization(authorization.id)

    def task_ledger_audit(
        self,
        *,
        project: Optional[str] = None,
        verify_git: bool = True,
        offset: int = 0,
        limit: Optional[int] = None,
    ) -> JsonDict:
        """Read and reconcile every task against its durable proof.

        The task identifiers and ``updated_at`` values are sampled before and
        after detail collection.  The report therefore discloses concurrent
        ledger mutations instead of presenting a moving target as an atomic
        snapshot.  Repository inspection is read-only and never fetches.
        """

        from mac.task_ledger_audit import build_task_ledger_audit

        started_at = utcnow()
        start_models = self.list_tasks(project=project)
        start_tasks = [task.to_dict() for task in start_models]
        try:
            offset_value = max(0, int(offset))
            limit_value = None if limit is None else max(1, int(limit))
        except (TypeError, ValueError) as exc:
            raise ValidationError("task audit offset and limit must be integers") from exc
        page_models = start_models[offset_value:]
        if limit_value is not None:
            page_models = page_models[:limit_value]
        details: List[JsonDict] = []
        detail_errors: List[JsonDict] = []
        for task in page_models:
            try:
                details.append(self.task_detail(task.id))
            except MACError as exc:
                detail_errors.append(
                    {
                        "task_id": task.id,
                        "error": str(exc),
                    }
                )
        end_tasks = [task.to_dict() for task in self.list_tasks(project=project)]
        repositories = [
            repository.to_dict()
            for repository in self.list_project_repositories(enabled=True)
        ]
        return build_task_ledger_audit(
            details,
            repositories,
            snapshot_started_at=started_at,
            snapshot_finished_at=utcnow(),
            start_tasks=start_tasks,
            end_tasks=end_tasks,
            detail_errors=detail_errors,
            project=project,
            verify_git=verify_git,
            all_tasks=start_tasks,
            pagination={"offset": offset_value, "limit": limit_value, "returned": len(page_models), "total": len(start_models)},
        )

    def assign_review_experiment(
        self,
        task_id: str,
        *,
        experiment_id: str,
        arm: Optional[str] = None,
        arms: Optional[Dict[str, Any]] = None,
        assignment_probability: Optional[float] = None,
        blind: bool = False,
        blind_arms: Optional[Iterable[str]] = None,
        policy_version: str = "v1",
        hypothesis: str = "",
        stratum: str = "",
        actor: str = "human",
    ) -> JsonDict:
        """Persist a replayable review-strategy assignment on a task.

        Weighted assignment is deterministic from experiment/task/policy ids,
        so callers can reproduce the choice while the stored probability keeps
        future off-policy analysis possible.
        """
        from mac.review_experiments import build_assignment, parse_assignment

        task = self.get_task(task_id)
        assignment = build_assignment(
            task_id=task_id,
            experiment_id=experiment_id,
            arm=arm,
            arms=arms,
            assignment_probability=assignment_probability,
            blind=blind,
            blind_arms=blind_arms,
            policy_version=policy_version,
            hypothesis=hypothesis,
            stratum=stratum,
            assigned_by=actor,
        )
        existing = parse_assignment(task.metadata)
        if existing is not None:
            immutable_fields = (
                "experiment_id",
                "arm",
                "assignment_method",
                "assignment_probability",
                "blind",
                "blind_arms",
                "policy_version",
                "arm_distribution",
                "hypothesis",
                "stratum",
            )
            if all(existing.get(key) == assignment.get(key) for key in immutable_fields):
                return existing
            raise ValidationError("review experiment assignment is immutable")
        if (
            task.state != TaskState.OPEN.value
            or task.owner_agent_id is not None
            or task.lease_id is not None
        ):
            raise ValidationError(
                "review experiment assignment must occur before a task is claimed"
            )
        metadata = ensure_json_object(task.metadata)
        metadata["review_experiment"] = assignment
        self.update_task(task_id, metadata=metadata, actor=actor)
        self._record_history(
            task_id,
            "task.review_experiment_assigned",
            actor,
            task.state,
            task.state,
            {
                "experiment_id": assignment["experiment_id"],
                "arm": assignment["arm"],
                "assignment_method": assignment["assignment_method"],
                "assignment_probability": assignment["assignment_probability"],
                "blind": assignment["blind"],
                "policy_version": assignment["policy_version"],
            },
        )
        return assignment

    def record_review_outcome(
        self,
        task_id: str,
        *,
        kind: str,
        status: str,
        finding_id: str = "",
        severity_weight: float = 1.0,
        source: str = "operator",
        detail: Optional[Dict[str, Any]] = None,
        actor: str = "human",
    ) -> JsonDict:
        """Attach a validated or delayed outcome without mutating evidence."""
        from mac.review_experiments import append_outcome, build_outcome

        task = self.get_task(task_id)
        outcome = build_outcome(
            kind=kind,
            status=status,
            finding_id=finding_id,
            severity_weight=severity_weight,
            source=source,
            detail=detail,
            observed_by=actor,
        )
        metadata = append_outcome(task.metadata, outcome)
        self.update_task(task_id, metadata=metadata, actor=actor)
        self._record_history(
            task_id,
            "task.review_outcome_recorded",
            actor,
            task.state,
            task.state,
            {
                "outcome_id": outcome["id"],
                "kind": outcome["kind"],
                "status": outcome["status"],
                "finding_id": outcome["finding_id"],
                "severity_weight": outcome["severity_weight"],
                "source": outcome["source"],
            },
        )
        return outcome

    def review_observation(self, task_id: str) -> JsonDict:
        from mac.review_experiments import build_observation

        detail = self.task_detail(task_id)
        review_subject_ids = [
            "review_%s" % review.get("id")
            for review in detail.get("reviews", [])
            if isinstance(review, dict) and review.get("id")
        ]
        routes = []
        seen_route_ids = set()
        for subject_id in [task_id, *review_subject_ids]:
            for route in self.list_observability(
                kind="log",
                name="llm.route",
                subject_type="task",
                subject_id=subject_id,
                limit=1000,
            ):
                route_id = getattr(route, "id", None)
                if route_id and route_id in seen_route_ids:
                    continue
                if route_id:
                    seen_route_ids.add(route_id)
                routes.append(route)
        return build_observation(
            detail,
            llm_routes=[item.to_dict() for item in routes],
        )

    def review_experiment_report(
        self,
        experiment_id: str,
        *,
        project: Optional[str] = None,
        min_tasks_per_arm: int = 5,
        min_validated_outcomes_per_arm: int = 3,
    ) -> JsonDict:
        from mac.review_experiments import build_report, parse_assignment

        observations = []
        for task in self.list_tasks():
            if project is not None and task.project != project:
                continue
            assignment = parse_assignment(task.metadata)
            if assignment is None or assignment.get("experiment_id") != experiment_id:
                continue
            observations.append(self.review_observation(task.id))
        return build_report(
            experiment_id,
            observations,
            min_tasks_per_arm=min_tasks_per_arm,
            min_validated_outcomes_per_arm=min_validated_outcomes_per_arm,
        )

