    def task_summary(self, task_id: str) -> JsonDict:
        task = self.get_task(task_id).to_dict()
        resolved_task_id = str(task["id"])
        evidence = [item.to_dict() for item in self.list_evidence(resolved_task_id)]
        reviews = [item.to_dict() for item in self.list_reviews(resolved_task_id)]
        approved_reviews = [review for review in reviews if review["status"] == ReviewStatus.APPROVED.value]
        publications = [
            pub.to_dict()
            for pub in self.reviews.list_publications(resolved_task_id)
            if pub.status == PublicationStatus.PUBLISHED.value
        ]
        parts = ["%s is %s" % (task["title"], task["state"])]
        if task["owner_agent_id"]:
            parts.append("owner=%s" % task["owner_agent_id"])
        if evidence:
            parts.append("%d evidence item(s)" % len(evidence))
        if approved_reviews:
            parts.append("%d approved review(s)" % len(approved_reviews))
        if publications:
            parts.append("published to %s" % publications[-1]["target"])
        return {
            "task_id": resolved_task_id,
            "title": task["title"],
            "state": task["state"],
            "owner_agent_id": task["owner_agent_id"],
            "evidence_count": len(evidence),
            "review_count": len(reviews),
            "approved_review_count": len(approved_reviews),
            "publications": publications,
            "origin": task["metadata"].get("origin"),
            "memory_boundary": task["metadata"].get("memory_boundary"),
            "summary": "; ".join(parts),
        }

    #: zlib level 6. Measured against what Postgres already does for free:
    #: TOAST/pglz gets 2.8x on this text, zlib-6 gets a net 1.4x on top of that
    #: for 2ms, and lzma only reached 1.6x for 42ms. Level 9 was within 1% of
    #: level 6 and several times the cost.
    TRANSCRIPT_COMPRESSION = "zlib"
    TRANSCRIPT_COMPRESSION_LEVEL = 6

    def _index_transcript_turn(
        self,
        task: Any,
        *,
        transcript_id: str,
        sequence: int,
        prompt: str,
        response: str,
        agent_id: Optional[str],
        coding_agent: Optional[str],
        created_at: str,
    ) -> None:
        """Hand the plaintext to the vector store, if one is configured.

        BEST EFFORT, like the transcript write itself. A vector store that is
        absent, slow or broken must not fail a task whose work is already done
        and whose record is about to be stored durably in Postgres -- Postgres
        remains the system of record, and the index is a derived view that can
        be rebuilt from it.
        """
        writer = getattr(self, "vector_writer", None)
        if writer is None:
            return
        try:
            writer.embed_transcript_turn(
                task_id=task.id,
                transcript_id=transcript_id,
                sequence=sequence,
                prompt=prompt,
                response=response,
                agent_id=agent_id,
                coding_agent=coding_agent,
                project=getattr(task, "project", None),
                created_at=created_at,
            )
        except Exception as exc:  # noqa: BLE001 - a derived index is not the record
            logging.getLogger(__name__).warning(
                "transcript not indexed for %s: %s", task.id, exc
            )

    @classmethod
    def _compress_transcript(
        cls, prompt: str, response: str, stderr: str
    ) -> tuple[bytes, str]:
        """The three texts as one compressed stream, plus the codec that made it.

        Together rather than separately: prompt and response usually quote the
        same source, so one stream can reuse what it has already seen where
        three cannot.
        """
        import json as _json
        import zlib

        blob = _json.dumps(
            {"prompt": prompt, "response": response, "stderr": stderr},
            separators=(",", ":"),
        ).encode("utf-8")
        return (
            zlib.compress(blob, cls.TRANSCRIPT_COMPRESSION_LEVEL),
            cls.TRANSCRIPT_COMPRESSION,
        )

    @classmethod
    def _decompress_transcript(cls, payload: Any, codec: Any) -> Dict[str, str]:
        """Bytes back to the three texts. Unreadable payloads degrade to empty
        strings rather than raising: a transcript that cannot be decoded must
        not make the task it belongs to unreadable."""
        import json as _json
        import zlib

        empty = {"prompt": "", "response": "", "stderr": ""}
        if payload is None:
            return empty
        name = str(codec or "none").strip().lower()
        try:
            raw = bytes(payload)
            if name == "zlib":
                raw = zlib.decompress(raw)
            elif name not in {"none", ""}:
                return {**empty, "stderr": "[unreadable: unknown codec %r]" % name}
            decoded = _json.loads(raw.decode("utf-8"))
        except Exception:  # noqa: BLE001 - a bad row must not break the read
            return {**empty, "stderr": "[unreadable transcript payload]"}
        if not isinstance(decoded, dict):
            return empty
        return {key: str(decoded.get(key) or "") for key in empty}

    @staticmethod
    def _sha256_text_static(value: str) -> str:
        import hashlib

        return "sha256:" + hashlib.sha256(value.encode("utf-8")).hexdigest()

    #: One turn of a coding-CLI session can be enormous (a whole repository
    #: pasted into a prompt, a model that streams for ten minutes). Stored
    #: whole, a handful of tasks would dominate the database -- which is
    #: precisely how action_events reached 16GB and wedged the hub. Each field
    #: is capped and the record says so, so a reader can never mistake a
    #: shortened transcript for the complete exchange.
    TRANSCRIPT_FIELD_LIMIT = 1_000_000

    def record_task_transcript(
        self,
        task_id: str,
        *,
        prompt: str = "",
        response: str = "",
        stderr: str = "",
        agent_id: Optional[str] = None,
        command_id: Optional[str] = None,
        coding_agent: Optional[str] = None,
        model: Optional[str] = None,
        returncode: Optional[int] = None,
        started_at: Optional[str] = None,
        completed_at: Optional[str] = None,
        duration_ms: Optional[float] = None,
        metadata: Optional[Dict[str, Any]] = None,
        actor: str = "worker",
    ) -> JsonDict:
        """Store what the coding CLI was asked and what it answered.

        The executor previously kept sha256(stdout) and a byte count. That
        proves an output existed and supports nothing else: no summary, no
        knowledge base, no answering "why did the agent do that".

        The hashes are kept ALONGSIDE the text, not replaced by it. A stored
        transcript can be edited; a hash recorded at the time cannot be made to
        match a doctored one, so the pair is worth more than either alone.
        """
        task = self.get_task(task_id)

        def _cap(value: Any) -> tuple[str, bool]:
            text = "" if value is None else str(value)
            if len(text) <= self.TRANSCRIPT_FIELD_LIMIT:
                return text, False
            keep = self.TRANSCRIPT_FIELD_LIMIT
            return (
                text[:keep]
                + "\n[truncated: %d of %d characters kept]" % (keep, len(text)),
                True,
            )

        prompt_text, prompt_cut = _cap(prompt)
        response_text, response_cut = _cap(response)
        stderr_text, stderr_cut = _cap(stderr)
        truncated = prompt_cut or response_cut or stderr_cut
        now = utcnow()
        record_id = new_id("transcript")
        existing = self.store.query_all(
            "SELECT sequence FROM task_agent_transcripts WHERE task_id = ?",
            (task.id,),
        )
        sequence = max(
            (int(row["sequence"] or 0) for row in existing), default=-1
        ) + 1
        # INDEXED BEFORE COMPRESSION, deliberately. The plaintext is in hand
        # exactly once -- here. Feeding the vector store later would mean
        # reading every row back and inflating it again purely to index it,
        # which is work that is free at this point in the path.
        self._index_transcript_turn(
            task,
            transcript_id=record_id,
            sequence=sequence,
            prompt=prompt_text,
            response=response_text,
            agent_id=agent_id,
            coding_agent=coding_agent,
            created_at=now,
        )
        payload, codec = self._compress_transcript(
            prompt_text, response_text, stderr_text
        )
        with self.store.transaction() as conn:
            conn.execute(
                "INSERT INTO task_agent_transcripts "
                "(id, task_id, agent_id, command_id, sequence, coding_agent, model, "
                " payload, compression, returncode, started_at, completed_at, "
                " duration_ms, truncated, prompt_sha256, response_sha256, metadata, "
                " created_at) "
                "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    record_id,
                    task.id,
                    str(agent_id or "") or None,
                    str(command_id or "") or None,
                    sequence,
                    str(coding_agent or "") or None,
                    str(model or "") or None,
                    payload,
                    codec,
                    int(returncode) if returncode is not None else None,
                    started_at,
                    completed_at,
                    float(duration_ms) if duration_ms is not None else None,
                    1 if truncated else 0,
                    # Hashed BEFORE capping, so the digest describes what the
                    # CLI actually produced rather than what survived storage.
                    self._sha256_text_static(str(prompt or "")),
                    self._sha256_text_static(str(response or "")),
                    json_dumps(ensure_json_object(metadata or {})),
                    now,
                ),
            )
        return {
            "id": record_id,
            "task_id": task.id,
            "sequence": sequence,
            "truncated": truncated,
        }

    def task_transcript(self, task_id: str, *, limit: Optional[int] = None) -> List[JsonDict]:
        """The session in order: turn 0 first, as it happened."""
        task = self.get_task(task_id)
        sql = (
            "SELECT * FROM task_agent_transcripts WHERE task_id = ? "
            "ORDER BY sequence ASC, created_at ASC"
        )
        params: List[Any] = [task.id]
        if limit:
            sql += " LIMIT ?"
            params.append(int(limit))
        rows = self.store.query_all(sql, tuple(params))
        return [self._transcript_row(row) for row in rows]

    def _transcript_row(self, row: Any) -> JsonDict:
        keys = row.keys() if hasattr(row, "keys") else {}
        # Compression is a STORAGE detail: every reader above this line sees the
        # same three strings it always did, so the API shape is unchanged.
        texts = self._decompress_transcript(
            row["payload"] if "payload" in keys else None,
            row["compression"] if "compression" in keys else "none",
        )
        return {
            "id": row["id"],
            "task_id": row["task_id"],
            "agent_id": row["agent_id"],
            "command_id": row["command_id"],
            "sequence": int(row["sequence"] or 0),
            "coding_agent": row["coding_agent"],
            "model": row["model"],
            "prompt": texts["prompt"],
            "response": texts["response"],
            "stderr": texts["stderr"],
            "returncode": row["returncode"],
            "started_at": row["started_at"],
            "completed_at": row["completed_at"],
            "duration_ms": row["duration_ms"],
            "truncated": bool(row["truncated"]),
            "prompt_sha256": row["prompt_sha256"],
            "response_sha256": row["response_sha256"],
            "metadata": json_loads(row["metadata"], {}) if "metadata" in keys else {},
            "created_at": row["created_at"],
        }

    def export_task(self, task_id: str, *, include_transcript: bool = True) -> JsonDict:
        """One task, whole, in a form another system can consume.

        The point of keeping transcripts is doing something with them -- handing
        a task to a summarising model, committing the summary, embedding it for
        retrieval. That wants ONE self-contained document rather than four
        endpoints stitched together by every caller.
        """
        task = self.get_task(task_id)
        document: JsonDict = {
            "schema": "mac.task_export.v1",
            "exported_at": utcnow(),
            "task": task.to_dict(),
            "history": [event.to_dict() for event in self.task_history(task.id)],
        }
        if include_transcript:
            document["transcript"] = self.task_transcript(task.id)
        return document

    def task_history(
        self,
        task_id: str,
        limit: Optional[int] = None,
    ) -> List[HistoryEvent]:
        resolved_task_id = self.get_task(task_id).id
        limit_value = None if limit is None else max(0, int(limit))
        if limit_value == 0:
            return []
        if limit_value is None:
            rows = self.store.query_all(
                "SELECT * FROM task_history WHERE task_id = ? ORDER BY created_at, id",
                (resolved_task_id,),
            )
        else:
            rows = list(
                reversed(
                    self.store.query_all(
                        """
                        SELECT * FROM task_history
                        WHERE task_id = ?
                        ORDER BY created_at DESC, id DESC
                        LIMIT ?
                        """,
                        (resolved_task_id, limit_value),
                    )
                )
            )
        return [self._history_from_row(row) for row in rows]

    # Unified audit / event stream

    EVENT_SUBJECT_TYPES = (
        "task",
        "rollout",
        "eval_set",
        "secret",
        "environment",
        "conversation_thread",
        "vector_ref",
        "action_event",
        "agent",
        "project",
        "fleet",
        "service",
    )

    def _list_recent_events_bounded(self, limit: int) -> List[JsonDict]:
        """Merge bounded, index-friendly reads from the unified event sources.

        SQLite cannot push ``ORDER BY ... LIMIT`` through the ``events``
        ``UNION ALL`` view. On a long-running hub that made an unfiltered
        ``limit=100`` request scan and sort millions of action rows. Reading at
        most ``limit`` rows from each source is exact: no source can contribute
        more than ``limit`` rows to the global top ``limit``. The final merge is
        tiny and preserves the view's newest-first contract.
        """

        events: List[JsonDict] = []

        def add(
            event_id: Any,
            subject_type: str,
            subject_id: Any,
            event_type: Any,
            actor: Any,
            detail: Any,
            created_at: Any,
        ) -> None:
            events.append(
                {
                    "id": event_id,
                    "subject_type": subject_type,
                    "subject_id": subject_id,
                    "event_type": event_type,
                    "actor": actor,
                    "detail": ensure_json_object(detail),
                    "created_at": created_at,
                }
            )

        task_rows = self.store.query_all(
            """
            SELECT id, task_id, event_type, actor, detail,
                   from_state, to_state, created_at
            FROM task_history
            ORDER BY created_at DESC, id DESC
            LIMIT ?
            """,
            (limit,),
        )
        for row in task_rows:
            detail = ensure_json_object(json_loads(row["detail"], {}))
            detail.update(
                {"from_state": row["from_state"], "to_state": row["to_state"]}
            )
            add(
                row["id"],
                "task",
                row["task_id"],
                row["event_type"],
                row["actor"],
                detail,
                row["created_at"],
            )


        simple_sources = (
            ("rollout_events", "rollout", "rollout_id"),
            ("eval_set_events", "eval_set", "eval_set_id"),
            ("environment_events", "environment", "environment_id"),
            ("project_events", "project", "project_id"),
            ("fleet_events", "fleet", "fleet_id"),
            ("agent_lifecycle_events", "agent", "agent_id"),
            ("agent_events", "agent", "agent_id"),
        )
        for table, subject_type, subject_column in simple_sources:
            rows = self.store.query_all(
                "SELECT id, %s AS subject_id, event_type, actor, detail, created_at "
                "FROM %s ORDER BY created_at DESC, id DESC LIMIT ?"
                % (subject_column, table),
                (limit,),
            )
            for row in rows:
                add(
                    row["id"],
                    subject_type,
                    row["subject_id"],
                    row["event_type"],
                    row["actor"],
                    json_loads(row["detail"], {}),
                    row["created_at"],
                )

        secret_rows = self.store.query_all(
            """
            SELECT id, secret_id, result, accessor_agent_id, purpose,
                   expires_at, revealed_at, created_at
            FROM secret_access_audit
            ORDER BY created_at DESC, id DESC
            LIMIT ?
            """,
            (limit,),
        )
        for row in secret_rows:
            add(
                row["id"],
                "secret",
                row["secret_id"],
                "secret.%s" % row["result"],
                row["accessor_agent_id"],
                {
                    "purpose": row["purpose"],
                    "expires_at": row["expires_at"],
                    "revealed_at": row["revealed_at"],
                },
                row["created_at"],
            )

        command_rows = self.store.query_all(
            """
            SELECT id, command_id, agent_id, phase, argv, cwd, task_id,
                   lease_id, started_at, completed_at, duration_ms, returncode,
                   stdout_sha256, stderr_sha256, stdout_bytes, stderr_bytes,
                   metadata, created_at
            FROM command_audit
            ORDER BY created_at DESC, id DESC
            LIMIT ?
            """,
            (limit,),
        )
        for row in command_rows:
            argv = json_loads(row["argv"], [])
            add(
                row["id"],
                "task" if row["task_id"] is not None else "agent",
                row["task_id"] or row["agent_id"],
                "command.%s" % row["phase"],
                row["agent_id"],
                {
                    "command_id": row["command_id"],
                    "agent_id": row["agent_id"],
                    "argv0": argv[0] if isinstance(argv, list) and argv else None,
                    "argv_redacted": True,
                    "cwd": row["cwd"],
                    "task_id": row["task_id"],
                    "lease_id": row["lease_id"],
                    "started_at": row["started_at"],
                    "completed_at": row["completed_at"],
                    "duration_ms": row["duration_ms"],
                    "returncode": row["returncode"],
                    "stdout_sha256": row["stdout_sha256"],
                    "stderr_sha256": row["stderr_sha256"],
                    "stdout_bytes": row["stdout_bytes"],
                    "stderr_bytes": row["stderr_bytes"],
                    "metadata": json_loads(row["metadata"], {}),
                },
                row["created_at"],
            )

        action_rows = self.store.query_all(
            """
            SELECT event_id, timestamp, agent_id, hermes_instance_id, task_id,
                   session_id, sandbox_id, actor, action_type, action_name,
                   subject_type, subject_id, outcome, severity, policy_id,
                   policy_version, command_id, parent_event_id, attributes,
                   redaction_state
            FROM action_events
            ORDER BY timestamp DESC, event_id DESC
            LIMIT ?
            """,
            (limit,),
        )
        for row in action_rows:
            event_id = row["event_id"]
            add(
                event_id,
                row["subject_type"] or "action_event",
                row["subject_id"] or event_id,
                "action.%s.%s" % (row["action_type"], row["action_name"]),
                row["actor"],
                {
                    "schema": "mac.action_event.v1",
                    "agent_id": row["agent_id"],
                    "hermes_instance_id": row["hermes_instance_id"],
                    "task_id": row["task_id"],
                    "session_id": row["session_id"],
                    "sandbox_id": row["sandbox_id"],
                    "action_type": row["action_type"],
                    "action_name": row["action_name"],
                    "outcome": row["outcome"],
                    "severity": row["severity"],
                    "policy_id": row["policy_id"],
                    "policy_version": row["policy_version"],
                    "command_id": row["command_id"],
                    "parent_event_id": row["parent_event_id"],
                    "redaction_state": row["redaction_state"],
                    "attributes": json_loads(row["attributes"], {}),
                },
                row["timestamp"],
            )

        conversation_rows = self.store.query_all(
            """
            SELECT id, platform_binding_id, external_thread_id,
                   latest_task_id, summary, last_seen_at
            FROM conversation_threads
            ORDER BY last_seen_at DESC, id DESC
            LIMIT ?
            """,
            (limit,),
        )
        for row in conversation_rows:
            add(
                row["id"],
                "conversation_thread",
                row["id"],
                "gateway.thread_tracked",
                "gateway",
                {
                    "platform_binding_id": row["platform_binding_id"],
                    "external_thread_id": row["external_thread_id"],
                    "latest_task_id": row["latest_task_id"],
                    "summary": row["summary"],
                },
                row["last_seen_at"],
            )

        vector_rows = self.store.query_all(
            """
            SELECT id, memory_id, created_by, vector_db, collection, point_id,
                   embedding_model, created_at
            FROM vector_refs
            ORDER BY created_at DESC, id DESC
            LIMIT ?
            """,
            (limit,),
        )
        for row in vector_rows:
            add(
                row["id"],
                "vector_ref",
                row["memory_id"],
                "vector.indexed",
                row["created_by"],
                {
                    "vector_db": row["vector_db"],
                    "collection": row["collection"],
                    "point_id": row["point_id"],
                    "embedding_model": row["embedding_model"],
                },
                row["created_at"],
            )

        events.sort(
            key=lambda event: (str(event["created_at"]), str(event["id"])),
            reverse=True,
        )
        return events[:limit]

    def list_events(
        self,
        subject_type: Optional[str] = None,
        subject_id: Optional[str] = None,
        actor: Optional[str] = None,
        event_type: Optional[str] = None,
        event_type_prefix: Optional[str] = None,
        since: Optional[str] = None,
        until: Optional[str] = None,
        limit: int = 100,
    ) -> List[JsonDict]:
        """Query the unified audit stream, including work-package measurements.

        Filters compose with AND. Results are newest-first; cap is 1000 to keep
        a single page bounded. Operators asking "what happened" should reach for
        this method instead of joining per-resource audit tables.
        """
        if subject_type is not None and subject_type not in self.EVENT_SUBJECT_TYPES:
            raise ValidationError(
                "unsupported event subject_type: %s (allowed: %s)"
                % (subject_type, ", ".join(self.EVENT_SUBJECT_TYPES))
            )
        limit_value = min(max(1, int(limit)), 1000)
        if all(
            value is None
            for value in (
                subject_type,
                subject_id,
                actor,
                event_type,
                event_type_prefix,
                since,
                until,
            )
        ):
            return self._list_recent_events_bounded(limit_value)
        clauses: List[str] = []
        params: List[Any] = []
        if subject_type is not None:
            clauses.append("subject_type = ?")
            params.append(subject_type)
        if subject_id is not None:
            clauses.append("subject_id = ?")
            params.append(subject_id)
        if actor is not None:
            clauses.append("actor = ?")
            params.append(actor)
        if event_type is not None:
            clauses.append("event_type = ?")
            params.append(event_type)
        if event_type_prefix is not None:
            escaped = event_type_prefix.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
            clauses.append("event_type LIKE ? ESCAPE '\\'")
            params.append(escaped + "%")
        if since is not None:
            clauses.append("created_at >= ?")
            params.append(since)
        if until is not None:
            clauses.append("created_at <= ?")
            params.append(until)
        sql = "SELECT id, subject_type, subject_id, event_type, actor, detail, created_at FROM events"
        if clauses:
            sql += " WHERE " + " AND ".join(clauses)
        sql += " ORDER BY created_at DESC, id DESC LIMIT ?"
        params.append(limit_value)
        rows = self.store.query_all(sql, tuple(params))
        return [
            {
                "id": row["id"],
                "subject_type": row["subject_type"],
                "subject_id": row["subject_id"],
                "event_type": row["event_type"],
                "actor": row["actor"],
                "detail": json_loads(row["detail"], {}),
                "created_at": row["created_at"],
            }
            for row in rows
        ]

