    # Short-retention command audit -------------------------------------

    # mac-6m14: scrub common secret-bearing argv shapes before writing.
    _SECRET_KEY_HINTS = (
        "password",
        "passwd",
        "secret",
        "token",
        "apikey",
        "api_key",
        "api-key",
        "credential",
        "auth",
    )
    # High-entropy bare values: anything resembling a base64/hex blob of
    # ≥ 32 chars and not a path, URL, or numeric.
    _ARGV_BARE_HIGH_ENTROPY_RE = re.compile(r"^[A-Za-z0-9+/=_-]{32,}$")

    @classmethod
    def _scrub_argv(cls, argv: Iterable[str]) -> List[str]:
        """Replace secret-bearing argv elements with redaction markers.

        Common patterns:
          ``--token=abc123`` -> ``--token=<redacted>``
          ``--password sekret`` -> ``--password <redacted>`` (best-effort
            via key-then-value matching)
          ``ghp_abcdef...`` (bare 32+ char alphanum) -> ``<redacted>``
        """
        out: List[str] = []
        skip_next = False
        for raw in argv:
            item = str(raw)
            if skip_next:
                out.append("<redacted>")
                skip_next = False
                continue
            # --foo=bar where the key contains a secret hint
            if item.startswith("-") and "=" in item:
                key_part, _sep, value = item.partition("=")
                if any(hint in key_part.lower() for hint in cls._SECRET_KEY_HINTS) and value:
                    out.append("%s=<redacted>" % key_part)
                    continue
            # --foo  <value>: key flag followed by a separate value
            if item.startswith("-") and any(
                hint in item.lower() for hint in cls._SECRET_KEY_HINTS
            ):
                out.append(item)
                skip_next = True
                continue
            # Bare high-entropy values; skip URLs and absolute paths.
            if (
                cls._ARGV_BARE_HIGH_ENTROPY_RE.match(item)
                and "/" not in item
                and ":" not in item
                and not item.isdigit()
            ):
                out.append("<redacted>")
                continue
            out.append(item)
        return out

    def record_command_audit(
        self,
        agent_id: str,
        phase: str,
        argv: Iterable[str],
        cwd: str,
        command_id: Optional[str] = None,
        task_id: Optional[str] = None,
        lease_id: Optional[str] = None,
        started_at: Optional[str] = None,
        completed_at: Optional[str] = None,
        duration_ms: Optional[float] = None,
        returncode: Optional[int] = None,
        stdout_sha256: Optional[str] = None,
        stderr_sha256: Optional[str] = None,
        stdout_bytes: Optional[int] = None,
        stderr_bytes: Optional[int] = None,
        metadata: Optional[Dict[str, Any]] = None,
        retention_seconds: Optional[int] = None,
    ) -> CommandAuditRecord:
        self.get_agent(agent_id)
        phase_value = str(phase or "").strip().lower()
        if phase_value not in COMMAND_AUDIT_PHASES:
            raise ValidationError("unsupported command audit phase: %s" % phase)
        argv_raw = [str(item) for item in argv]
        if not argv_raw:
            raise ValidationError("command audit requires argv")
        # mac-6m14: scrub before persisting so secrets on argv never
        # land in command_audit or observability detail.
        argv_list = self._scrub_argv(argv_raw)
        cwd_value = str(cwd or "").strip()
        if not cwd_value:
            raise ValidationError("command audit requires cwd")
        if task_id:
            self.get_task(task_id)
        audit_id = new_id("cmda")
        cid = command_id or new_id("cmd")
        now = utcnow()
        detail = ensure_json_object(metadata or {})
        retention = self._command_audit_retention_seconds(retention_seconds)
        cutoff = (
            parse_time(now) - timedelta(seconds=retention)
        ).isoformat(timespec="microseconds")
        with self.store.transaction() as conn:
            conn.execute(
                """
                INSERT INTO command_audit (
                    id, command_id, agent_id, phase, argv, cwd, task_id, lease_id,
                    started_at, completed_at, duration_ms, returncode,
                    stdout_sha256, stderr_sha256, stdout_bytes, stderr_bytes,
                    metadata, created_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    audit_id,
                    cid,
                    agent_id,
                    phase_value,
                    json_dumps(argv_list),
                    cwd_value,
                    task_id,
                    lease_id,
                    started_at,
                    completed_at,
                    duration_ms,
                    returncode,
                    stdout_sha256,
                    stderr_sha256,
                    stdout_bytes,
                    stderr_bytes,
                    json_dumps(detail),
                    now,
                ),
            )
            self.action_events.project_command_audit(
                conn,
                audit_id=audit_id,
                command_id=cid,
                agent_id=agent_id,
                phase=phase_value,
                argv=argv_list,
                cwd=cwd_value,
                task_id=task_id,
                lease_id=lease_id,
                started_at=started_at,
                completed_at=completed_at,
                duration_ms=duration_ms,
                returncode=returncode,
                stdout_sha256=stdout_sha256,
                stderr_sha256=stderr_sha256,
                stdout_bytes=stdout_bytes,
                stderr_bytes=stderr_bytes,
                metadata=detail,
                timestamp=now,
            )
            conn.execute("DELETE FROM command_audit WHERE created_at < ?", (cutoff,))
            self.observability.insert_observation(
                conn,
                "log",
                "command.%s" % phase_value,
                "worker",
                agent_id,
                "error" if phase_value in {"failed", "timeout", "error"} else "info",
                None,
                "",
                "task" if task_id else "agent",
                task_id or agent_id,
                {
                    "command_id": cid,
                    "argv": argv_list,
                    "cwd": cwd_value,
                    "task_id": task_id,
                    "lease_id": lease_id,
                    "duration_ms": duration_ms,
                    "returncode": returncode,
                    **detail,
                },
                now,
            )
        return self.get_command_audit(audit_id)

    def get_command_audit(self, audit_id: str) -> CommandAuditRecord:
        row = self.store.query_one("SELECT * FROM command_audit WHERE id = ?", (audit_id,))
        if row is None:
            raise NotFoundError("command audit record not found: %s" % audit_id)
        return self._command_audit_from_row(row)

    def list_command_audit(
        self,
        agent_id: Optional[str] = None,
        task_id: Optional[str] = None,
        command_id: Optional[str] = None,
        phase: Optional[str] = None,
        since: Optional[str] = None,
        until: Optional[str] = None,
        limit: int = 200,
    ) -> List[CommandAuditRecord]:
        self.prune_command_audit()
        clauses: List[str] = []
        params: List[Any] = []
        if agent_id is not None:
            clauses.append("agent_id = ?")
            params.append(agent_id)
        if task_id is not None:
            clauses.append("task_id = ?")
            params.append(task_id)
        if command_id is not None:
            clauses.append("command_id = ?")
            params.append(command_id)
        if phase is not None:
            phase_value = str(phase).strip().lower()
            if phase_value not in COMMAND_AUDIT_PHASES:
                raise ValidationError("unsupported command audit phase: %s" % phase)
            clauses.append("phase = ?")
            params.append(phase_value)
        if since is not None:
            clauses.append("created_at >= ?")
            params.append(since)
        if until is not None:
            clauses.append("created_at <= ?")
            params.append(until)
        sql = "SELECT * FROM command_audit"
        if clauses:
            sql += " WHERE " + " AND ".join(clauses)
        sql += " ORDER BY created_at DESC, id DESC LIMIT ?"
        params.append(min(max(1, int(limit)), 1000))
        return [
            self._command_audit_from_row(row)
            for row in self.store.query_all(sql, tuple(params))
        ]

    def prune_command_audit(self, older_than: Optional[str] = None) -> int:
        cutoff = older_than
        if cutoff is None:
            now = utcnow()
            retention = self._command_audit_retention_seconds(None)
            cutoff = (
                parse_time(now) - timedelta(seconds=retention)
            ).isoformat(timespec="microseconds")
        cursor = self.store.execute(
            "DELETE FROM command_audit WHERE created_at < ?", (cutoff,)
        )
        return int(cursor.rowcount or 0)

    def _command_audit_retention_seconds(self, override: Optional[int]) -> int:
        if override is not None:
            return max(60, int(override))
        raw = os.environ.get("MAC_COMMAND_AUDIT_RETENTION_SECONDS")
        if raw:
            return max(60, int(raw))
        return 24 * 60 * 60

    # ------------------------------------------------------------------
    # Evidence-reuse decision records
    #
    # Durable audit trail of prior-executor-evidence reuse decisions made
    # by recovery logic when review infrastructure fails. See
    # ``mac.evidence_reuse_verifier`` for the fail-closed verifier whose
    # structured result is persisted here.
    # ------------------------------------------------------------------
    def record_evidence_reuse(
        self,
        task_id: str,
        source_evidence_id: str,
        reused: bool,
        *,
        verification: Optional[Mapping[str, Any]] = None,
        problems: Optional[Iterable[str]] = None,
        remote_url: Optional[str] = None,
        expected_head_sha: Optional[str] = None,
        decided_by: str = "control-plane",
        reused_by_agent_id: Optional[str] = None,
        reuse_context: str = "",
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> EvidenceReuseRecord:
        """Persist one evidence-reuse decision and return the stored record.

        ``task_id`` must reference an existing task. ``verification`` is the
        serialised structured result (e.g. ``ReuseVerificationResult.to_dict``)
        that backed the decision; ``problems`` is the convenience list of
        human-readable failure descriptions when reuse was refused.
        """
        self.get_task(task_id)
        source_id = str(source_evidence_id or "").strip()
        if not source_id:
            raise ValidationError("evidence reuse requires source_evidence_id")
        verification_payload = ensure_json_object(verification or {})
        if problems is None:
            raw_problems = verification_payload.get("problems")
            problem_list = [str(p) for p in raw_problems] if isinstance(raw_problems, list) else []
        else:
            problem_list = [str(p) for p in problems]
        decided = str(decided_by or "").strip() or "control-plane"
        # Reuse provenance: default the acting agent to the deciding identity
        # when the caller does not name one explicitly.
        reused_by = str(reused_by_agent_id or "").strip() or decided
        context = str(reuse_context or "").strip()
        metadata_payload = ensure_json_object(metadata or {})
        record_id = new_id("evreuse")
        now = utcnow()
        self.store.execute(
            """
            INSERT INTO evidence_reuse_records (
                id, task_id, source_evidence_id, remote_url, expected_head_sha,
                reused, verification, problems, decided_by, created_at,
                reused_by_agent_id, reuse_context, metadata
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                record_id,
                task_id,
                source_id,
                remote_url,
                expected_head_sha,
                1 if reused else 0,
                json_dumps(verification_payload),
                json_dumps(problem_list),
                decided,
                now,
                reused_by,
                context,
                json_dumps(metadata_payload),
            ),
        )
        self._record_history(
            task_id,
            "evidence.reuse_recorded",
            reused_by,
            None,
            None,
            {
                "record_id": record_id,
                "source_evidence_id": source_id,
                "prior_evidence_id": source_id,
                "reused": bool(reused),
                "reuse_context": context,
                "decided_by": decided,
            },
        )
        return self.get_evidence_reuse(record_id)

    def get_evidence_reuse(self, record_id: str) -> EvidenceReuseRecord:
        row = self.store.query_one(
            "SELECT * FROM evidence_reuse_records WHERE id = ?", (record_id,)
        )
        if row is None:
            raise NotFoundError("evidence reuse record not found: %s" % record_id)
        return self._evidence_reuse_from_row(row)

    def list_evidence_reuse(
        self,
        task_id: Optional[str] = None,
        source_evidence_id: Optional[str] = None,
        reused: Optional[bool] = None,
        limit: int = 200,
    ) -> List[EvidenceReuseRecord]:
        clauses: List[str] = []
        params: List[Any] = []
        if task_id is not None:
            clauses.append("task_id = ?")
            params.append(task_id)
        if source_evidence_id is not None:
            clauses.append("source_evidence_id = ?")
            params.append(source_evidence_id)
        if reused is not None:
            clauses.append("reused = ?")
            params.append(1 if reused else 0)
        sql = "SELECT * FROM evidence_reuse_records"
        if clauses:
            sql += " WHERE " + " AND ".join(clauses)
        sql += " ORDER BY created_at DESC, id DESC LIMIT ?"
        params.append(min(max(1, int(limit)), 1000))
        return [
            self._evidence_reuse_from_row(row)
            for row in self.store.query_all(sql, tuple(params))
        ]

    def _evidence_reuse_from_row(self, row: Any) -> EvidenceReuseRecord:
        keys = row.keys() if hasattr(row, "keys") else ()
        return EvidenceReuseRecord(
            row["id"],
            row["task_id"],
            row["source_evidence_id"],
            row["remote_url"],
            row["expected_head_sha"],
            bool(row["reused"]),
            json_loads(row["verification"], {}),
            json_loads(row["problems"], []),
            row["decided_by"],
            row["created_at"],
            row["reused_by_agent_id"] if "reused_by_agent_id" in keys else "",
            row["reuse_context"] if "reuse_context" in keys else "",
            json_loads(row["metadata"], {}) if "metadata" in keys else {},
        )

    def get_evidence_reuse_records(self, task_id: str) -> List[EvidenceReuseRecord]:
        """Return every evidence-reuse record for ``task_id`` (oldest first)."""
        self.get_task(task_id)
        return [
            self._evidence_reuse_from_row(row)
            for row in self.store.query_all(
                "SELECT * FROM evidence_reuse_records WHERE task_id = ?"
                " ORDER BY created_at, id",
                (task_id,),
            )
        ]

    def list_dead_letters(
        self,
        tenant_id: Optional[str] = None,
        *,
        limit: int = 100,
        cursor: Optional[str] = None,
    ) -> List[Task]:
        return self.list_dead_letters_page(
            tenant_id=tenant_id,
            limit=limit,
            cursor=cursor,
        )["tasks"]

    def list_dead_letters_page(
        self,
        tenant_id: Optional[str] = None,
        *,
        limit: int = 100,
        cursor: Optional[str] = None,
    ) -> JsonDict:
        limit_value = max(1, min(int(limit), 1000))
        # Every FAILED task is a dead letter. Requiring an exhausted attempt
        # budget hid the largest failure population from the surface built to
        # surface failures: a task killed by the retry verdict goes terminal
        # with attempt_count=1 against max_attempts=3, so it never matched.
        clauses = ["state = ?"]
        params: List[Any] = [TaskState.FAILED.value]
        if tenant_id is not None:
            clauses.append(
                "COALESCE("
                "NULLIF(json_extract(metadata, '$.origin.tenant_id'), ''), "
                "NULLIF(json_extract(metadata, '$.tenant_id'), '')"
                ") = ?"
            )
            params.append(tenant_id)
        decoded = self._decode_scan_cursor(cursor, "dead-letters")
        if decoded is not None:
            updated_at, task_id = decoded
            clauses.append("(updated_at > ? OR (updated_at = ? AND id > ?))")
            params.extend([updated_at, updated_at, task_id])
        params.append(limit_value + 1)
        rows = self.store.query_all(
            "SELECT * FROM tasks WHERE %s "
            "ORDER BY updated_at, id LIMIT ?" % " AND ".join(clauses),
            tuple(params),
        )
        has_more = len(rows) > limit_value
        tasks = [self._task_from_row(row) for row in rows[:limit_value]]
        next_cursor = (
            self._encode_scan_cursor(
                "dead-letters",
                tasks[-1].updated_at,
                tasks[-1].id,
            )
            if has_more and tasks
            else None
        )
        return {
            "tasks": tasks,
            "next_cursor": next_cursor,
            "has_more": has_more,
        }

    def _encode_scan_cursor(self, kind: str, position: str, item_id: str) -> str:
        payload = json_dumps(
            {"kind": kind, "position": position, "item_id": item_id}
        ).encode("utf-8")
        encoded = base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")
        return "v1:%s" % encoded

    def _decode_scan_cursor(
        self,
        cursor: Optional[str],
        kind: str,
    ) -> Optional[Tuple[str, str]]:
        if cursor is None:
            return None
        raw = str(cursor).strip()
        if not raw.startswith("v1:"):
            raise ValidationError("invalid %s cursor" % kind)
        encoded = raw[3:]
        try:
            padding = "=" * (-len(encoded) % 4)
            payload = json_loads(
                base64.urlsafe_b64decode((encoded + padding).encode("ascii")).decode(
                    "utf-8"
                ),
                {},
            )
            payload_kind = str(payload["kind"])
            position = str(payload["position"])
            item_id = str(payload["item_id"])
        except (binascii.Error, KeyError, TypeError, ValueError, UnicodeError):
            raise ValidationError("invalid %s cursor" % kind) from None
        if payload_kind != kind or not position or not item_id:
            raise ValidationError("invalid %s cursor" % kind)
        return position, item_id

    def close_task(
        self,
        task_id: str,
        target_state: str,
        actor: str,
        detail: Optional[Dict[str, Any]] = None,
        *,
        drain_outbox: bool = True,
    ) -> Task:
        """Operator boundary for an ordinary task's terminal close.

        Worker-authored transitions belong to :meth:`transition_task` and are
        fenced to an exact active lease.  This separate public operation is
        for an authenticated operator that has already been authorized by the
        transport (or for an explicitly selected local authority).  It is
        deliberately limited to the two ``task close`` outcomes; package-
        linked tasks remain protected by the generic lifecycle guard in
        :meth:`_transition_task_impl` and must advance through their package
        controller instead.
        """

        target = _state_value(target_state)
        if target not in {
            TaskState.COMPLETED.value,
            TaskState.CANCELLED.value,
        }:
            raise ValidationError(
                "operator close only supports completed or cancelled"
            )
        return self._transition_task_impl(
            task_id,
            target,
            actor,
            detail,
            lease_id=None,
            trusted_internal=True,
            drain_outbox=drain_outbox,
            conn=None,
        )

    def transition_task(
        self,
        task_id: str,
        target_state: str,
        actor: str,
        detail: Optional[Dict[str, Any]] = None,
        *,
        lease_id: Optional[str] = None,
        drain_outbox: bool = True,
    ) -> Task:
        return self._transition_task_impl(
            task_id,
            target_state,
            actor,
            detail,
            lease_id=lease_id,
            trusted_internal=False,
            drain_outbox=drain_outbox,
            conn=None,
        )

    def request_task_input(
        self,
        task_id: str,
        questions: Sequence[Any],
        actor: str,
        *,
        why: str = "",
        drain_outbox: bool = True,
    ) -> Task:
        """Park a task on an unanswered human question.

        This is NOT a failure path. The work is still wanted; it simply cannot
        proceed until a person answers. Parked tasks are excluded from every
        sweeper, reaper, and dispatch pass, so they wait indefinitely instead
        of burning their attempt budget on a blocker no code path can clear.

        An agent that discovers mid-flight that it needs an answer reaches this
        state through the ordinary lease-fenced worker transition. This trusted
        entry point exists for operators parking a task they do not hold.
        """
        detail: JsonDict = {"questions": list(questions or [])}
        if str(why or "").strip():
            detail["why"] = why
        return self._transition_task_internal(
            task_id,
            TaskState.NEEDS_INPUT.value,
            actor,
            detail,
            drain_outbox=drain_outbox,
        )

    #: Answering a parked question is a judgement, not automatically a
    #: release. "resume" returns the task to the dispatch pool; any
    #: CANCELLATION_DISPOSITION closes it using the vocabulary the rest of the
    #: system already speaks (superseded, duplicate, not_applicable, ...).
    ANSWER_RESUME = "resume"

    @property
    def answer_dispositions(self) -> Tuple[str, ...]:
        from mac.repository_hygiene import CANCELLATION_DISPOSITIONS

        return (self.ANSWER_RESUME, *CANCELLATION_DISPOSITIONS)

    def answer_task_input(
        self,
        task_id: str,
        answer: str,
        actor: str,
        *,
        disposition: str,
        replaced_by: Optional[str] = None,
        drain_outbox: bool = True,
    ) -> Task:
        """Record the answer to a parked question and dispose of the task.

        ``disposition`` is REQUIRED and has no default. This used to transition
        unconditionally to OPEN -- "answer" meant "release to the dispatch
        pool" -- which is wrong for the most common kind of answer. During the
        2026-08-03 needs_input triage, twelve of twenty-seven parked questions
        were answered "no longer necessary" or "superseded"; answering them put
        twelve unwanted tasks straight back in front of the fleet, and each had
        to be cancelled immediately afterwards. An answer that means "stop"
        must not be expressible only as "go".

        ``resume`` returns the task to OPEN. Any other value must be a
        CANCELLATION_DISPOSITION -- ``superseded``, ``duplicate``,
        ``not_applicable``, ``deferred``, ``failed_attempt``, ``preserve`` --
        and closes the task with that reason. Deliberately the SAME vocabulary
        `mac task cancel` uses, so a task closed by an answer is
        indistinguishable downstream from one closed directly, and the existing
        auto-cleanup rules for duplicate/superseded/not_applicable still apply.

        The outstanding question set is folded into ``needs_input_history``
        either way, so what was asked stays auditable next to what was decided.
        """
        if not str(answer or "").strip():
            raise ValidationError("an answer is required to dispose of a parked task")
        current = self.get_task(task_id)
        if current.state != TaskState.NEEDS_INPUT.value:
            # Answering a task nobody asked about used to succeed and do
            # nothing: the transition to OPEN is a no-op from OPEN, so the
            # answer was accepted, discarded, and never folded into
            # needs_input_history. Harmless one at a time; actively misleading
            # from a bulk answer, which would report the task as answered.
            raise ValidationError(
                "task %s is %s, not awaiting input; there is no question to "
                "answer" % (task_id, current.state)
            )
        disposition = str(disposition or "").strip().lower()
        allowed = self.answer_dispositions
        if disposition not in allowed:
            raise ValidationError(
                "answer disposition must be one of %s, got %r. Answering is a "
                "judgement: say whether the answer releases the task (resume) "
                "or closes it, and why." % (", ".join(allowed), disposition)
            )
        replacement = str(replaced_by or "").strip()
        if replacement and disposition == self.ANSWER_RESUME:
            raise ValidationError(
                "replaced_by only applies when the answer closes the task"
            )
        if replacement:
            # Fail loudly rather than record a dangling pointer: a superseding
            # id that does not resolve is worse than none.
            replacement = self.get_task(replacement).id

        if disposition == self.ANSWER_RESUME:
            return self._transition_task_internal(
                task_id,
                TaskState.OPEN.value,
                actor,
                {
                    "answer": answer,
                    "reason": "human answered outstanding question",
                    "answer_disposition": disposition,
                },
                drain_outbox=drain_outbox,
            )

        detail: Dict[str, Any] = {
            "answer": answer,
            "reason": "answered: %s" % answer,
            "answer_disposition": disposition,
            "disposition": disposition,
        }
        if replacement:
            # Canonical key: repository_hygiene validates supersession on
            # `replacement_task_id`, and reusing it means a task closed by an
            # answer participates in the same cleanup rules as one closed by
            # `mac task cancel`.
            detail["replacement_task_id"] = replacement
        return self._transition_task_internal(
            task_id,
            TaskState.CANCELLED.value,
            actor,
            detail,
            drain_outbox=drain_outbox,
        )

    # ------------------------------------------------------------------
    # ADR 0020: a running task is not edited in place.
    # ------------------------------------------------------------------

    #: States in which an executor holds, or is about to hold, the task. An
    #: edit applied here would produce two versions of the truth: the ledger's
    #: and the one the agent read at claim time. CLAIMED counts because the
    #: agent holds the lease and is about to read the task.
    IN_FLIGHT_TASK_STATES = (TaskState.RUNNING.value, TaskState.CLAIMED.value)

    #: Fields that change WHAT THE AGENT SHOULD BUILD. Only these trigger the
    #: stop/restart cycle on an in-flight task.
    #:
    #: The discriminator is the field, not the state, and that distinction is
    #: load-bearing. Gating on state alone made every internal bookkeeping
    #: write -- lease repair, transition records, restart counters, of which
    #: there are a dozen call sites -- abort and restart the task it was
    #: recording against. Two scheduler-safety tests caught it by asserting a
    #: repaired task still held its lease; it no longer did, because writing
    #: metadata had silently revoked it.
    #:
    #: `metadata` is deliberately absent: an agent does not work from metadata,
    #: so changing it cannot produce the split brain this guards. `priority`
    #: and `max_attempts` are absent too -- they are scheduling attributes
    #: rather than work definitions, they change nothing the agent is building,
    #: and the next claim picks them up anyway. Stopping live work to reprioritise
    #: it would cost more than it protects.
    SCOPE_BEARING_TASK_FIELDS = (
        "title",
        "description",
        "project",
        "required_capabilities",
        "dependencies",
    )

    def stop_task(
        self,
        task_id: str,
        *,
        actor: str,
        reason: str = "",
        drain_outbox: bool = True,
    ) -> Task:
        """Abort in-flight work and park the task under an operator hold.

        The transition clears the lease. Loop workers poll assignment authority
        while an executor runs and terminate the active subprocess tree when
        that lease is no longer current, which is the same mechanism `cancel`
        relies on -- but STOPPED is not terminal, so the work is not recorded
        as abandoned.

        The abort is therefore EVENTUAL, not instantaneous: it completes when
        the worker next polls. That is recorded as ``abort_confirmed: False``
        rather than assumed, because "probably stopped" and "stopped" are
        different facts and an operator has to be able to tell them apart.
        """

        task = self.get_task(task_id)
        if task.state == TaskState.STOPPED.value:
            return task
        if task.state in TERMINAL_TASK_STATES:
            raise TransitionError(
                "cannot stop a %s task; stopping is for live work" % task.state
            )
        detail: JsonDict = {
            "reason": str(reason or "").strip() or "operator stopped the task",
            "previous_state": task.state,
            "was_in_flight": task.state in self.IN_FLIGHT_TASK_STATES,
            # Recorded, never assumed. The worker confirms by releasing the
            # lease; until then a process may still be running against this.
            "abort_confirmed": False,
        }
        if task.owner_agent_id:
            detail["aborted_agent_id"] = task.owner_agent_id
        if task.lease_id:
            detail["revoked_lease_id"] = task.lease_id
        return self._transition_task_internal(
            task_id,
            TaskState.STOPPED.value,
            actor,
            detail,
            drain_outbox=drain_outbox,
        )

    def start_stopped_task(
        self,
        task_id: str,
        *,
        actor: str,
        drain_outbox: bool = True,
    ) -> Task:
        """Return a stopped task to the queue, re-entered from the top.

        Deliberately NOT a resume. The task goes back to OPEN (or WAITING when
        the edit left dependencies unmet, evaluated NOW rather than assumed),
        and is claimed afresh. The state machine enforces this: STOPPED has no
        edge to RUNNING or CLAIMED.

        Resuming would preserve conclusions the previous attempt drew from the
        pre-edit task -- which moves the split brain from mid-flight to
        across-attempts instead of removing it. If the edit changed nothing
        material there was no reason to stop the task; if it did, the previous
        attempt's reasoning is exactly what must not survive.
        """

        task = self.get_task(task_id)
        if task.state != TaskState.STOPPED.value:
            raise TransitionError(
                "task is %s, not stopped; nothing to start" % task.state
            )

        # Evaluate dependencies at THIS moment. An edit that added a blocker
        # must come back blocked, not claimable.
        unmet = self._unmet_dependency_ids(task)
        target = TaskState.WAITING.value if unmet else TaskState.OPEN.value

        metadata = ensure_json_object(task.metadata)
        # Restarts are counted separately from attempts. An operator stopping a
        # task to correct its scope must not consume its retry budget -- it
        # failed at nothing. But a restart must not reset the attempt counter
        # either, or a repeatedly edited task could never exhaust its attempts
        # and would be unkillable.
        restarts = int(metadata.get("restart_count") or 0) + 1

        detail: JsonDict = {
            "reason": "operator restarted the task",
            "restart_count": restarts,
            "reentry": "from_top",
            "unmet_dependencies": list(unmet),
        }
        self.update_task(
            task_id,
            metadata={**metadata, "restart_count": restarts},
            actor=actor,
        )
        return self._transition_task_internal(
            task_id, target, actor, detail, drain_outbox=drain_outbox
        )

    def _unmet_dependency_ids(self, task: Task) -> List[str]:
        """Dependency ids that have not satisfied this task's join policy."""

        unmet: List[str] = []
        for dep_id in list(task.dependencies or []):
            try:
                dep = self.get_task(dep_id)
            except NotFoundError:
                continue
            if dep.state != TaskState.COMPLETED.value:
                unmet.append(dep_id)
        return unmet

    def _transition_task_internal(
        self,
        task_id: str,
        target_state: str,
        actor: str,
        detail: Optional[Dict[str, Any]] = None,
        *,
        drain_outbox: bool = True,
    ) -> Task:
        """Trusted service-only transition path.

        Public callers must use :meth:`transition_task`, whose active-task
        writes require an exact lease fence.  Internal services may use this
        private entry point only after performing their own authority check
        (for example ``start_task`` validates owner/delegate plus lease first).
        """
        return self._transition_task_impl(
            task_id,
            target_state,
            actor,
            detail,
            lease_id=None,
            trusted_internal=True,
            drain_outbox=drain_outbox,
            conn=None,
        )

    def _transition_task_in_transaction(
        self,
        conn: Any,
        task_id: str,
        target_state: str,
        actor: str,
        detail: Optional[Dict[str, Any]] = None,
    ) -> Task:
        return self._transition_task_impl(
            task_id,
            target_state,
            actor,
            detail,
            lease_id=None,
            trusted_internal=True,
            drain_outbox=False,
            conn=conn,
        )

    def _transition_task_impl(
        self,
        task_id: str,
        target_state: str,
        actor: str,
        detail: Optional[Dict[str, Any]] = None,
        *,
        lease_id: Optional[str],
        trusted_internal: bool,
        drain_outbox: bool,
        conn: Optional[Any],
    ) -> Task:
        return self.task_transitions._transition_task_impl(
            task_id,
            target_state,
            actor,
            detail,
            lease_id=lease_id,
            trusted_internal=trusted_internal,
            drain_outbox=drain_outbox,
            conn=conn,
        )

    def _terminal_dependency_replacement(self, dep_id: str) -> Optional[str]:
        return self.task_transitions._terminal_dependency_replacement(dep_id)

    def _resolve_waiting_dependents_of(self, dep_id: str, dep_state: str, actor: str) -> None:
        return self.task_transitions._resolve_waiting_dependents_of(dep_id, dep_state, actor)

    def recover_stranded_dependents(
        self,
        *,
        limit: int = 500,
        dry_run: bool = True,
        max_rounds: int = 10,
        actor: str = "strand-recovery",
    ) -> JsonDict:
        """Re-supervise WAITING tasks left behind by a terminal dependency.

        Repairs damage from the unsupervision bug: a startup migration
        reverted supervised BLOCKED tasks to WAITING, and the
        ``dependency_resolution`` marker then stopped counting, because
        ``_dependency_state_satisfies_join`` requires BLOCKED *and* the marker.
        Those tasks waited forever on a dependency that will never complete,
        and so did their integration parents. Fixing the migration stops NEW
        stranding; nothing re-supervises what was already reverted.

        This re-runs the ordinary reconciler for each terminal dependency that
        still has WAITING dependents. It is deliberately NOT a second
        implementation of that logic: reusing it keeps replacement
        substitution, ``cancel_scope``, work-package deferral, and the
        integration-parent rule identical to the live path. In particular a
        cooperative-integration parent correctly STAYS waiting, so its
        ``all_settled`` join can settle on the newly supervised child rather
        than being blocked itself.

        Idempotent: once a dependency's dependents are BLOCKED they no longer
        select, so a second run is a no-op. Opening the now-settled parents is
        left to the ordinary dispatcher sweep -- this stays a repair, not a
        dispatcher.
        """

        def _bounded(name: str, value: Any, *, default: int, ceiling: int) -> int:
            """Coerce a caller-supplied bound, rejecting garbage as a MACError.

            This is a public facade method, so a bad argument must surface as a
            ValidationError rather than a TypeError from deep inside the loop.
            """
            if value is None:
                return default
            try:
                coerced = int(value)
            except (TypeError, ValueError):
                raise ValidationError(
                    "%s must be an integer, got %r" % (name, value)
                ) from None
            return max(1, min(ceiling, coerced))

        limit = _bounded("limit", limit, default=500, ceiling=10000)
        max_rounds = _bounded("max_rounds", max_rounds, default=10, ceiling=100)

        def _unsatisfiable_dependencies() -> List[Any]:
            """Dependencies that will never complete, with WAITING dependents.

            Terminal (failed/cancelled) OR already supervised. The supervised
            case is what unwinds a CHAIN: with implement(failed) <- test <-
            verify, only `test` has a terminal dependency. `verify` waits on
            `test`, which is BLOCKED and unsatisfiable, so `verify` will never
            run either -- but the live reconciler only propagates on terminal
            transitions, so nothing ever marks it and the integration parent
            waits on it forever. Measured on the live ledger: without this,
            168 tasks are re-supervised and ZERO parents become dispatchable.
            """
            return list(
                self.store.query_all(
                    """
                    SELECT DISTINCT e.dependency_task_id AS dep_id, d.state AS dep_state
                    FROM task_edges e
                    JOIN tasks t ON t.id = e.task_id
                    JOIN tasks d ON d.id = e.dependency_task_id
                    WHERE t.state = ?
                      AND (
                        d.state IN (?, ?)
                        OR (d.state = ? AND json_extract(
                              d.metadata, '$.dependency_resolution.status') = ?)
                      )
                    ORDER BY e.dependency_task_id
                    LIMIT ?
                    """,
                    (
                        TaskState.WAITING.value,
                        TaskState.FAILED.value,
                        TaskState.CANCELLED.value,
                        TaskState.BLOCKED.value,
                        "unsatisfied",
                        limit,
                    ),
                )
                or []
            )

        report: JsonDict = {
            "schema": "mac.strand_recovery.v1",
            "dry_run": bool(dry_run),
            "terminal_dependencies": 0,
            "dependents_examined": 0,
            "supervised": 0,
            "unchanged": 0,
            "rounds": 0,
            "errors": [],
        }

        # A chain unwinds one hop per round: supervising `test` is what makes
        # `verify` visible as stranded. Bounded so a cycle or a persistent
        # failure cannot spin; the loop stops as soon as a round changes
        # nothing, and a dry run never needs more than one round because it
        # mutates nothing to cascade from.
        seen_dependencies: set = set()
        rounds_allowed = 1 if dry_run else max_rounds
        for round_index in range(1, rounds_allowed + 1):
            rows = _unsatisfiable_dependencies()
            report["rounds"] = round_index
            supervised_this_round = 0

            for row in rows:
                dep_id = str(row["dep_id"])
                dep_state = str(row["dep_state"])
                if dep_id in seen_dependencies:
                    continue
                waiting_before = [
                    str(record["id"])
                    for record in (
                        self.store.query_all(
                            "SELECT t.id FROM task_edges e JOIN tasks t ON t.id = e.task_id "
                            "WHERE e.dependency_task_id = ? AND t.state = ?",
                            (dep_id, TaskState.WAITING.value),
                        )
                        or []
                    )
                ]
                if not waiting_before:
                    continue
                report["terminal_dependencies"] += 1
                report["dependents_examined"] += len(waiting_before)
                if dry_run:
                    continue
                seen_dependencies.add(dep_id)
                try:
                    self._resolve_waiting_dependents_of(dep_id, dep_state, actor)
                except Exception as exc:  # noqa: BLE001 - one dependency must not stop the sweep
                    report["errors"].append({"dependency": dep_id, "error": str(exc)[:300]})
                    continue
                for task_id in waiting_before:
                    try:
                        if self.get_task(task_id).state != TaskState.WAITING.value:
                            report["supervised"] += 1
                            supervised_this_round += 1
                        else:
                            report["unchanged"] += 1
                    except NotFoundError:
                        report["unchanged"] += 1

            if dry_run or supervised_this_round == 0:
                break

        return report

    def reopen_task(
        self,
        task_id: str,
        actor: str,
        reason: Optional[str] = None,
    ) -> Task:
        """Recovery action: return a stuck/terminal task to OPEN so it can be
        retried or reconciled.

        Valid from ``failed``/``cancelled`` (resets ``attempt_count`` and clears
        ``completed_at`` so the requeue isn't immediately re-exhausted) and from
        ``blocked``; the state machine rejects reopening an already-``completed``
        task. Records who reopened it and why. Counterpart to
        :meth:`force_complete_task`.
        """
        task = self.get_task(task_id)
        detail: Dict[str, Any] = {"via": "operator_reopen"}
        if reason:
            detail["reason"] = reason
        return self._transition_task_internal(
            task.id, TaskState.OPEN.value, actor, detail
        )

    def force_complete_task(
        self,
        task_id: str,
        actor: str,
        reason: Optional[str] = None,
    ) -> Task:
        """Operator override: mark a task COMPLETED from any state, subject to
        one remaining gate.

        For reconciling work done out-of-band (e.g. a task whose change merged
        via a PR) or recovering a task stranded in a terminal state where the
        normal review→publish path can no longer run. It deliberately bypasses
        both the review/evidence completion gate and ``validate_transition`` --
        the recovery case is precisely ``failed -> completed``, which
        ``TASK_TRANSITIONS`` forbids -- so it records who forced it, the prior
        state, and why. Recovery counterpart to :meth:`reopen_task`.

        NOT bypassed: a repo-coupled task still has to satisfy
        :meth:`_require_canonical_integration_proof`, so forcing one complete
        without a canonical integration record raises. Only report deliverables
        and tasks without a repository execution contract complete
        unconditionally.
        """
        task = self.get_task(task_id)
        # get_task accepts unambiguous display prefixes, but every mutation and
        # foreign-keyed audit row must use the canonical full identifier.
        task_id = task.id
        if task.state == TaskState.COMPLETED.value:
            return task
        self._require_canonical_integration_proof(task)
        now = utcnow()
        detail: Dict[str, Any] = {"via": "operator_force_complete", "from_state": task.state}
        if reason:
            detail["reason"] = reason
        metadata = ensure_json_object(task.metadata)
        metadata["repository_ref_lifecycle"] = repository_ref_lifecycle_for_transition(
            TaskState.COMPLETED.value,
            detail,
            now=now,
        )
        with self.store.transaction() as conn:
            if task.lease_id:
                conn.execute(
                    "UPDATE leases SET status = ?, updated_at = ? WHERE id = ? AND status = ?",
                    (LeaseStatus.RELEASED.value, now, task.lease_id, LeaseStatus.ACTIVE.value),
                )
                self._consume_break_glass_authorizations(
                    conn,
                    task_id=task.id,
                    lease_id=task.lease_id,
                    now=now,
                )
            if task.owner_agent_id:
                self._set_agent_idle(task.owner_agent_id, conn=conn)
            conn.execute(
                """
                UPDATE tasks
                SET state = ?, owner_agent_id = NULL, lease_id = NULL, leased_until = NULL,
                    completed_at = COALESCE(completed_at, ?), metadata = ?, updated_at = ?
                WHERE id = ?
                """,
                (TaskState.COMPLETED.value, now, json_dumps(metadata), now, task_id),
            )
            self._record_history(
                task_id,
                "task.force_completed",
                actor,
                task.state,
                TaskState.COMPLETED.value,
                detail,
                conn=conn,
            )
            self.task_ledger.enqueue_outbox(
                conn,
                task_id=task_id,
                event_type="task.lifecycle",
                actor=actor,
                from_state=task.state,
                to_state=TaskState.COMPLETED.value,
                detail=detail,
                created_at=now,
            )
        self.drain_task_transition_outbox(task_id=task_id, limit=20)
        return self.get_task(task_id)

    @staticmethod
    def _repository_contract_for_task(task: Task) -> JsonDict:
        """Return the repository contract carried by a repository task."""
        metadata = ensure_json_object(task.metadata)
        if metadata_declares_report_deliverable(metadata):
            # Reports may inspect an exact repository base, but no code is
            # integrated. Their reviewed operator_result is the completion
            # proof; canonical Git integration is categorically inapplicable.
            return {}
        execution = ensure_json_object(metadata.get("execution_contract"))
        origin = ensure_json_object(metadata.get("origin"))
        contract = ensure_json_object(execution.get("repository_contract"))
        if not contract:
            contract = ensure_json_object(origin.get("repository_contract"))
        if str(execution.get("type") or "").strip().lower() != "repository":
            return {}
        return contract

    def _require_canonical_integration_proof(self, task: Task) -> None:
        """Refuse repository completion until a guarded canonical push is durable.

        An approved review proves that an executor attempt was acceptable; it
        does not prove that the reviewed ref survived parallel integration.
        The deterministic finalizer records ``canonical_integration`` only
        after its guarded push has verified the canonical branch remotely.
        Require that record on both ordinary and operator completion paths.
        """
        contract = self._repository_contract_for_task(task)
        if not contract:
            return
        try:
            canonical_branch = resolve_task_repository_branch(
                task.to_dict(),
                legacy_branch=contract.get("canonical_branch"),
                default_branch="main",
            )
        except ValueError as exc:
            raise ValidationError(
                "canonical integration proof branch is invalid: %s" % exc
            ) from exc
        canonical_ref = "refs/heads/%s" % canonical_branch
        for evidence in reversed(self.list_evidence(task.id)):
            metadata = ensure_json_object(evidence.metadata)
            manifest = ensure_json_object(metadata.get("verification")) or metadata
            repo = ensure_json_object(manifest.get("repo"))
            integration = ensure_json_object(manifest.get("canonical_integration"))
            head_sha = str(repo.get("head_sha") or "").strip()
            proof_sha = str(
                integration.get("canonical_tip_sha") or integration.get("head_sha") or ""
            ).strip()
            reviewed_sha = str(integration.get("reviewed_head_sha") or "").strip()
            proof_carries_reviewed_head = (
                _GIT_SHA_RE.match(reviewed_sha)
                and reviewed_sha == head_sha
                and integration.get("contains_reviewed_head") is True
            )
            # A squash-merged pull request lands the reviewed *content* under a
            # new canonical SHA, so neither SHA equality nor ancestry can hold.
            # The forge reporting the merge of exactly this reviewed head IS the
            # integration proof. Kept as tight as the ancestry branch: the proof
            # must name this evidence's reviewed commit and carry the explicit
            # squash marker the publication path writes.
            proof_squash_merged = (
                _GIT_SHA_RE.match(reviewed_sha)
                and reviewed_sha == head_sha
                and integration.get("squash_merged") is True
            )
            if (
                str(integration.get("status") or "").strip().lower() in {"pass", "passed"}
                and integration.get("remote_verified") is True
                and str(integration.get("canonical_ref") or "").strip() == canonical_ref
                and _GIT_SHA_RE.match(head_sha)
                and _GIT_SHA_RE.match(proof_sha)
                and (
                    head_sha == proof_sha
                    or proof_carries_reviewed_head
                    or proof_squash_merged
                )
            ):
                return
        raise ValidationError(
            "repository task completion requires durable canonical integration proof "
            "(canonical_integration.status=pass, remote_verified=true, and a "
            "matching canonical branch SHA)"
        )

    def claim_task_v2(
        self,
        task_id: str,
        agent_id: str,
        lease_seconds: int = 900,
    ) -> JsonDict:
        """Atomically commit an allocator-v2 task/agent proposal.

        The allocator has already evaluated the same hub-owned snapshot used
        by ``ready`` and dispatch diagnostics.  This transaction repeats only
        mutable safety and ownership predicates under locks; it deliberately
        does not re-introduce worker-local source, command, coding-route,
        persona, canary, or metadata filters.
        """

        claimed, lease = self.claim_task(
            task_id,
            agent_id,
            lease_seconds=lease_seconds,
            sync_beads=False,
            assignment_allocator="authoritative-hub",
            authoritative_allocator_v2=True,
        )
        agent = self.get_agent(agent_id)
        return {
            "task": self._assignment_task_payload(claimed, lease),
            "agent": agent.to_dict(),
            "lease": lease.to_dict(),
        }

    def claim_task(
        self,
        task_id: str,
        agent_id: str,
        lease_seconds: int = 900,
        *,
        sync_beads: bool = True,
        allow_cooperative_reuse: bool = False,
        assignment_allocator: str = "control-plane",
        authoritative_allocator_v2: bool = False,
    ) -> Tuple[Task, Lease]:
        lease_seconds = self._validated_task_lease_seconds(lease_seconds)
        task = self.get_task(task_id)
        task_id = task.id
        agent = self._require_live_agent(agent_id)
        if (
            task.state in {TaskState.WAITING.value, TaskState.BLOCKED.value}
            and self._canonical_task_dependency_ids(task.id)
            and self._dependencies_satisfied(task)
            and not self._blocked_task_requires_manual_repair(task)
        ):
            task = self._prepare_cooperative_integration_task(task)
            task = self._transition_task_internal(
                task_id,
                TaskState.OPEN.value,
                "dispatcher",
                {"reason": "dependencies satisfied"},
            )
        if task.state != TaskState.OPEN.value:
            raise TransitionError("only open tasks can be claimed")
        # mac-1g3u: the tenant gate also runs as an explicit chokepoint
        # in claim_task itself, not only through _agent_available_for.
        # A future dispatch path that forgets the broader eligibility
        # check still hits this assertion because every claim must go
        # through claim_task. The richer Python policy lives in
        # _machine_allows_tenant; this is the redundant safety belt.
        machine = self.get_machine(agent.machine_id)
        task_tenant = self._task_tenant_id(task)
        if not self._machine_allows_tenant(machine, task_tenant):
            raise AuthorizationError(
                "machine %s tenant policy refuses tenant %s for task %s"
                % (machine.id, task_tenant, task_id)
            )
        # Candidate availability is an advisory fast path only. Always call it
        # so dispatch telemetry and test barriers observe the preflight, but do
        # not let a replica-local clock or stale mutable snapshot make the
        # authorization decision. The locked snapshot below is authoritative.
        if not authoritative_allocator_v2:
            self._agent_available_for(
                agent, task, allow_cooperative_reuse=allow_cooperative_reuse
            )
        if task.attempt_count >= task.max_attempts:
            target_state, detail = self._exhausted_attempt_terminal_transition(
                task,
                {"reason": "max attempts"},
            )
            self._transition_task_internal(
                task_id, target_state, "dispatcher", detail
            )
            raise TransitionError("task %s exhausted max_attempts" % task_id)
        lease_id = new_id("lease")
        # Distinct cooperative executors are a placement preference in
        # allocator v2, never a lease-denying predicate.  The legacy claim
        # path retains its historical family lock for explicit/manual callers.
        coordination_related_ids = (
            set()
            if authoritative_allocator_v2
            else self._coordination_related_task_ids(task)
        )
        coordination_lock_task_id: Optional[str] = None
        if coordination_related_ids:
            relationships = ensure_json_object(
                ensure_json_object(task.metadata).get("relationships")
            )
            coordination_lock_task_id = str(
                relationships.get("parent_task_id")
                or ensure_json_object(task.metadata).get("parent_task_id")
                or task.id
            ).strip()
        with self.store.transaction() as conn:
            # Claims for the same agent must serialize before capacity is
            # counted.  The earlier availability check is useful for a cheap
            # rejection, but it cannot be the authority: two dispatchers can
            # both observe one free slot.  Locking the agent row and repeating
            # the count closes that race on both SQLite and PostgreSQL.
            agent_lock = conn.execute(
                "UPDATE agents SET updated_at = updated_at "
                "WHERE id = ? AND deleted_at IS NULL",
                (agent_id,),
            )
            if agent_lock.rowcount != 1:
                raise ValidationError("agent %s is unavailable" % agent_id)
            agent_row = conn.execute(
                "SELECT * FROM agents WHERE id = ?", (agent_id,)
            ).fetchone()
            if agent_row is None:
                raise ValidationError("agent %s is unavailable" % agent_id)
            current_agent = self._agent_from_row(agent_row)
            active_count_row = conn.execute(
                """
                SELECT COUNT(*) AS count FROM leases l
                JOIN tasks t ON t.lease_id = l.id
                WHERE l.agent_id = ?
                  AND l.status = ?
                  AND t.owner_agent_id = ?
                """,
                (agent_id, LeaseStatus.ACTIVE.value, agent_id),
            ).fetchone()
            active_count = int(
                active_count_row["count"] if active_count_row is not None else 0
            )
            if coordination_lock_task_id:
                # Serialize family participation across dispatchers.  The
                # eligibility check above is intentionally repeated while a
                # shared parent-row lock is held, closing the race where two
                # child claims could otherwise assign the same agent before
                # either lease became visible.
                family_lock = conn.execute(
                    "UPDATE tasks SET updated_at = updated_at WHERE id = ?",
                    (coordination_lock_task_id,),
                )
                if family_lock.rowcount != 1:
                    raise ValidationError(
                        "cooperative task family lock %s is unavailable"
                        % coordination_lock_task_id
                    )
                placeholders = ",".join("?" for _ in coordination_related_ids)
                # Expired leases (crashed attempts) do not count as participation
                # — see _coordination_excluded_agent_ids.  allow_cooperative_reuse
                # relaxes the distinct-executor rule entirely when the dispatcher
                # has determined the whole pool is otherwise exhausted.
                prior_participation = (
                    None
                    if allow_cooperative_reuse
                    else conn.execute(
                        "SELECT 1 FROM leases WHERE agent_id = ? "
                        "AND task_id IN (%s) AND status != ? LIMIT 1" % placeholders,
                        (
                            agent_id,
                            *sorted(coordination_related_ids),
                            LeaseStatus.EXPIRED.value,
                        ),
                    ).fetchone()
                )
                if prior_participation is not None:
                    raise ValidationError(
                        "agent %s already participated in cooperative task family for %s"
                        % (agent_id, task_id)
                    )
            # Lock and re-read the task after the agent capacity lock.  The
            # task's dependency list and every dependency state below are now
            # checked in the same transaction as the claim write, so an OPEN
            # task with incomplete prerequisites cannot slip through a stale
            # dispatcher candidate snapshot.
            task_lock = conn.execute(
                "UPDATE tasks SET updated_at = updated_at WHERE id = ?",
                (task_id,),
            )
            if task_lock.rowcount != 1:
                raise NotFoundError("task not found: %s" % task_id)
            task_row = conn.execute(
                "SELECT * FROM tasks WHERE id = ?", (task_id,)
            ).fetchone()
            if task_row is None:
                raise NotFoundError("task not found: %s" % task_id)
            current_task = self._task_from_row(task_row)
            if (
                current_task.state != TaskState.OPEN.value
                or current_task.lease_id is not None
            ):
                raise TransitionError("task %s was claimed by another agent" % task_id)
            if not authoritative_allocator_v2:
                self._assert_current_read_only_report_task_contract(
                    current_task,
                    conn=conn,
                )
            dependency_join = self._dependency_join_policy(current_task)
            for dependency_id in self._canonical_task_dependency_ids(
                current_task.id,
                conn=conn,
            ):
                dependency_row = conn.execute(
                    "SELECT state, metadata FROM tasks WHERE id = ?", (dependency_id,)
                ).fetchone()
                if (
                    dependency_row is None
                    or not self._dependency_state_satisfies_join(
                        str(dependency_row["state"]),
                        json_loads(dependency_row["metadata"], {}),
                        dependency_join,
                    )
                ):
                    raise TransitionError(
                        "task %s dependencies are not complete" % task_id
                    )
            if current_task.attempt_count >= current_task.max_attempts:
                raise TransitionError("task %s exhausted max_attempts" % task_id)
            project_paused = False
            project_registered = current_task.project is None
            if current_task.project:
                # A project pause is part of claim authority, so serialize
                # against activation/pause writes and inspect the same row in
                # this transaction. Implicit projects have no row and remain
                # active by design.
                conn.execute(
                    "UPDATE projects SET updated_at = updated_at "
                    "WHERE name = ? OR id = ?",
                    (current_task.project, current_task.project),
                )
                project_row = conn.execute(
                    "SELECT status, metadata FROM projects WHERE name = ? OR id = ?",
                    (current_task.project, current_task.project),
                ).fetchone()
                if project_row is not None:
                    project_registered = True
                    project_metadata = json_loads(project_row["metadata"], {})
                    project_paused = (
                        str(project_row["status"] or "active") != "active"
                        or bool(project_metadata.get("dispatch_paused"))
                    )
            machine_lock = conn.execute(
                "UPDATE machines SET updated_at = updated_at WHERE id = ?",
                (current_agent.machine_id,),
            )
            if machine_lock.rowcount != 1:
                raise ValidationError("agent machine is unavailable")
            machine_row = conn.execute(
                "SELECT * FROM machines WHERE id = ?",
                (current_agent.machine_id,),
            ).fetchone()
            if machine_row is None:
                raise ValidationError("agent machine is unavailable")
            current_machine = self._machine_from_row(machine_row)
            required_runtime_digest = None
            role_reason = self._claim_role_ineligibility_reason_in_transaction(
                conn,
                agent=current_agent,
                task=current_task,
                machine=current_machine,
            )
            if not authoritative_allocator_v2:
                required_runtime_digest = (
                    self._task_required_runtime_digest_in_transaction(
                        conn, current_task
                    )
                )
            # The task row lock serializes this read with authorization
            # creation. Lock the one ACTIVE record as well so its revoke/claim
            # CAS cannot wait until after we sample time. An authorization for
            # another agent reserves the task; it must never be silently left
            # active after a different worker claims the task.
            break_glass_row = conn.execute(
                """
                SELECT * FROM task_break_glass_authorizations
                WHERE task_id = ? AND status = 'active'
                ORDER BY created_at DESC LIMIT 1
                """,
                (current_task.id,),
            ).fetchone()
            if break_glass_row is not None:
                conn.execute(
                    "UPDATE task_break_glass_authorizations SET status = status "
                    "WHERE id = ?",
                    (break_glass_row["id"],),
                )
                break_glass_row = conn.execute(
                    "SELECT * FROM task_break_glass_authorizations WHERE id = ?",
                    (break_glass_row["id"],),
                ).fetchone()

            # This is deliberately after every potentially blocking claim lock.
            # A lease therefore receives its full TTL even if the transaction
            # waited behind another hub replica.
            now = self._lease_authority_now_in_transaction(conn)
            break_glass: Optional[BreakGlassAuthorization] = None
            if (
                break_glass_row is not None
                and break_glass_row["status"] == "active"
            ):
                if self._timestamp_is_after(break_glass_row["expires_at"], now):
                    break_glass = self._break_glass_authorization_from_row(
                        break_glass_row
                    )
                else:
                    conn.execute(
                        "UPDATE task_break_glass_authorizations "
                        "SET status = 'expired' WHERE id = ? AND status = 'active'",
                        (break_glass_row["id"],),
                    )
            if break_glass is not None:
                if break_glass.agent_id != current_agent.id:
                    raise AuthorizationError(
                        "task %s is reserved by break-glass authorization for agent %s"
                        % (current_task.id, break_glass.agent_id)
                    )
                if break_glass.execution_boundary != BREAK_GLASS_EXECUTION_BOUNDARY:
                    raise AuthorizationError(
                        "task break-glass execution boundary is invalid"
                    )
                role_reason = None
            if authoritative_allocator_v2:
                ineligible_reason = self._claim_snapshot_v2_ineligibility_reason(
                    agent=current_agent,
                    task=current_task,
                    machine=current_machine,
                    active_count=active_count,
                    project_registered=project_registered,
                    project_paused=project_paused,
                    break_glass=break_glass,
                    role_reason=role_reason,
                )
            else:
                ineligible_reason = self._claim_snapshot_ineligibility_reason(
                    agent=current_agent,
                    task=current_task,
                    machine=current_machine,
                    active_count=active_count,
                    project_paused=project_paused,
                    break_glass=break_glass,
                    required_runtime_digest=required_runtime_digest,
                    role_reason=role_reason,
                )
            if ineligible_reason is not None:
                raise ValidationError(
                    "agent %s cannot claim task %s: %s"
                    % (agent_id, task_id, ineligible_reason)
                )
            expires_at = (
                parse_time(now) + timedelta(seconds=lease_seconds)
            ).isoformat(timespec="microseconds")
            # Prepare the lease and, for a linked work-package task, its exact
            # immutable assignment/WIP authority before changing the ordinary
            # task row.  The database claim guard can therefore fail closed for
            # mixed-version hubs that know only the legacy task state machine.
            conn.execute(
                """
                INSERT INTO leases (id, task_id, agent_id, expires_at, status, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                (lease_id, task_id, agent_id, expires_at, LeaseStatus.ACTIVE.value, now, now),
            )
            # Atomic claim: the UPDATE only succeeds if the task is still OPEN and
            # unleased. rowcount==0 means another dispatcher already took it.
            cursor = conn.execute(
                """
                UPDATE tasks
                SET state = ?, owner_agent_id = ?, lease_id = ?, leased_until = ?,
                    attempt_count = attempt_count + 1, updated_at = ?
                WHERE id = ? AND state = ? AND lease_id IS NULL
                """,
                (
                    TaskState.CLAIMED.value,
                    agent_id,
                    lease_id,
                    expires_at,
                    now,
                    task_id,
                    TaskState.OPEN.value,
                ),
            )
            if cursor.rowcount != 1:
                raise TransitionError("task %s was claimed by another agent" % task_id)
            if break_glass is not None:
                authorization_update = conn.execute(
                    """
                    UPDATE task_break_glass_authorizations
                    SET status = 'claimed', claimed_at = ?, lease_id = ?
                    WHERE id = ? AND task_id = ? AND agent_id = ?
                      AND status = 'active'
                    """,
                    (
                        now,
                        lease_id,
                        break_glass.id,
                        task.id,
                        agent.id,
                    ),
                )
                if authorization_update.rowcount != 1:
                    raise ValidationError(
                        "break-glass authorization expired or changed during claim"
                    )
            # Assignment is the HUB acting, not the agent reporting. Stamping
            # last_seen_at here let the hub vouch for an agent's liveness on the
            # strength of its own decision to use it, which closes a loop: a
            # worker whose host is gone still looks idle, the tick assigns to
            # it, the assignment refreshes last_seen, the staleness sweep never
            # fires, and it keeps drawing work forever.
            #
            # Seen live: three HGX runners were stopped and their pods deleted,
            # and the hub went on reporting them busy, with fresh last_seen
            # values and real tasks attached -- tasks that could not run and
            # would sit until their leases expired.
            #
            # An agent-initiated claim is different: the agent is demonstrably
            # there, so it still refreshes its own liveness.
            if str(assignment_allocator or "").strip() == "authoritative-hub":
                conn.execute(
                    """
                    UPDATE agents
                    SET status = ?, current_task_id = ?, updated_at = ?
                    WHERE id = ?
                    """,
                    (AgentStatus.BUSY.value, task_id, now, agent_id),
                )
            else:
                conn.execute(
                    """
                    UPDATE agents
                    SET status = ?, current_task_id = ?, updated_at = ?, last_seen_at = ?
                    WHERE id = ?
                    """,
                    (AgentStatus.BUSY.value, task_id, now, now, agent_id),
                )
            detail = {"lease_id": lease_id, "expires_at": expires_at}
            if break_glass is not None:
                detail["break_glass_authorization_id"] = break_glass.id
                detail["execution_boundary"] = break_glass.execution_boundary
            self._record_history(
                task_id,
                "task.claimed",
                agent_id,
                task.state,
                TaskState.CLAIMED.value,
                detail,
                conn=conn,
            )
        claimed_task = self.get_task(task_id)
        if sync_beads:
            self.drain_task_transition_outbox(task_id=task_id, limit=20)
        return claimed_task, self.get_lease(lease_id)


    def list_task_transition_outbox(
        self,
        *,
        status: str = "pending",
        task_id: Optional[str] = None,
        limit: int = 100,
    ) -> List[TaskTransitionOutbox]:
        return self.task_transitions.list_task_transition_outbox(
            status=status, task_id=task_id, limit=limit
        )

    def drain_task_transition_outbox(
        self,
        *,
        task_id: Optional[str] = None,
        limit: int = 100,
    ) -> JsonDict:
        return self.task_transitions.drain_task_transition_outbox(
            task_id=task_id, limit=limit
        )

    def drain_task_transition_outbox_best_effort(
        self,
        *,
        task_id: Optional[str] = None,
        limit: int = 100,
    ) -> JsonDict:
        return self.task_transitions.drain_task_transition_outbox_best_effort(
            task_id=task_id, limit=limit
        )

    def _process_task_transition_outbox_item(self, item: TaskTransitionOutbox) -> None:
        return self.task_transitions._process_task_transition_outbox_item(item)

    def start_task(
        self,
        task_id: str,
        agent_id: str,
        *,
        lease_id: Optional[str] = None,
        drain_outbox: bool = True,
    ) -> Task:
        task = self.get_task(task_id)
        # PR2c (spec §6.3): accept either the lease owner OR a delegated
        # actor (recorded via delegate_lease). Renewal / release stay
        # strictly owner-only and are unchanged.
        self._require_lease_actor(task, agent_id, lease_id)
        current_lease_id = str(task.lease_id or "")
        # A loop worker may restart after it moved an assignment to RUNNING but
        # before it recorded evidence.  Starting the same, still-active lease
        # is idempotent so the worker can resume execution instead of stranding
        # the dispatcher-owned assignment on an invalid RUNNING -> RUNNING
        # transition.
        if task.state == TaskState.RUNNING.value:
            with self.store.transaction() as conn:
                self._require_exact_lease_actor_in_transaction(
                    conn,
                    task_id=task.id,
                    agent_id=agent_id,
                    lease_id=current_lease_id,
                    allowed_states=(TaskState.RUNNING.value,),
                )
            return self.get_task(task.id)
        return self.transition_task(
            task_id,
            TaskState.RUNNING.value,
            agent_id,
            {},
            lease_id=current_lease_id,
            drain_outbox=drain_outbox,
        )

    def submit_for_review(
        self,
        task_id: str,
        agent_id: str,
        *,
        lease_id: Optional[str] = None,
        drain_outbox: bool = True,
    ) -> Task:
        task = self.get_task(task_id)
        # PR2c (spec §6.3): accept either the lease owner OR a delegated
        # actor (recorded via delegate_lease).
        self._require_lease_actor(task, agent_id, lease_id)
        reviewed = self.transition_task(
            task_id,
            TaskState.NEEDS_REVIEW.value,
            agent_id,
            {},
            lease_id=str(task.lease_id or ""),
            drain_outbox=drain_outbox,
        )
        # Event, not sweep: start the review workflow the moment work is
        # submitted instead of waiting up to a full tick interval.
        self._nudge_review_workflow(task_id)
        return reviewed


    def _require_review_ready(self, task: Task) -> Evidence:
        evidence, assessment = self._default_review_evidence(task)
        if evidence is None:
            problems: List[str] = []
            for rejected in assessment.get("rejected_evidence", []) or []:
                if isinstance(rejected, dict):
                    problems.extend(str(item) for item in rejected.get("problems", []) or [])
            if not problems:
                problems = [str(assessment.get("reason") or "no verifiable evidence")]
            raise ValidationError(
                "task needs verifiable evidence before review: %s"
                % "; ".join(problems[:8])
            )
        return evidence

    def add_evidence(
        self,
        task_id: str,
        kind: str,
        uri: str,
        summary: str,
        created_by: str,
        checksum: Optional[str] = None,
        metadata: Optional[Dict[str, Any]] = None,
        *,
        lease_id: Optional[str] = None,
        artifacts: Optional[List[Dict[str, Any]]] = None,
        sync_beads: bool = True,
        _trusted_internal: bool = False,
    ) -> Evidence:
        if not kind or not uri or not summary:
            raise ValidationError("evidence requires kind, uri, and summary")
        try:
            kind = normalize_evidence_kind(kind)
        except ValueError as exc:
            raise ValidationError(str(exc)) from exc
        if kind == "publication" and not checksum:
            raise ValidationError("publication evidence requires a checksum")
        task = self.get_task(task_id)
        # Prefix resolution is part of the public id-taking contract.  Persist
        # evidence, artifacts, and history under the canonical foreign key,
        # not the caller's shortened display id.
        task_id = task.id
        fenced_lease_id: Optional[str] = None
        fenced_review_id: Optional[str] = None
        fenced_review_status: Optional[str] = None
        if _trusted_internal:
            pass
        elif task.state in {TaskState.CLAIMED.value, TaskState.RUNNING.value}:
            self._require_lease_actor(task, created_by, lease_id)
            fenced_lease_id = str(task.lease_id or "")
        elif task.state == TaskState.REVIEWING.value:
            fenced_review_status = (
                ReviewStatus.APPROVED.value
                if kind == "publication"
                else ReviewStatus.PENDING.value
            )
            review_rows = self.store.query_all(
                "SELECT id FROM reviews WHERE task_id = ? "
                "AND reviewer_agent_id = ? AND status = ? "
                "ORDER BY created_at DESC, id DESC LIMIT 2",
                (task_id, created_by, fenced_review_status),
            )
            if len(review_rows) != 1:
                raise AuthorizationError(
                    "review evidence requires one current review assigned to the author"
                )
            if fenced_review_status == ReviewStatus.PENDING.value:
                evidence_metadata = ensure_json_object(metadata)
                verification = ensure_json_object(
                    evidence_metadata.get("verification")
                )
                is_review_verdict = (
                    str(verification.get("evidence_type") or "").strip().lower()
                    == "review_verdict"
                )
                review_id = str(review_rows[0]["id"])
                try:
                    protocol_returncode: Optional[int] = int(
                        evidence_metadata.get("returncode")
                    )
                except (TypeError, ValueError):
                    protocol_returncode = None
                is_protocol_failure = (
                    kind == "review"
                    and str(evidence_metadata.get("review_id") or "").strip()
                    == review_id
                    and protocol_returncode is not None
                    and protocol_returncode != 0
                )
                if not is_review_verdict and not is_protocol_failure:
                    raise AuthorizationError(
                        "post-lease review evidence must be a review_verdict "
                        "or a fenced nonzero review attempt"
                    )
                current_target = str(
                    ensure_json_object(
                        ensure_json_object(task.metadata).get("review_target")
                    ).get("executor_evidence_id")
                    or ""
                ).strip()
                reviewed_target = str(
                    (
                        verification.get("reviewed_evidence_id")
                        if is_review_verdict
                        else evidence_metadata.get("executor_evidence_id")
                    )
                    or ""
                ).strip()
                if not current_target or reviewed_target != current_target:
                    raise AuthorizationError(
                        "review evidence must target the current executor evidence revision"
                    )
            fenced_review_id = str(review_rows[0]["id"])
        else:
            raise AuthorizationError(
                "evidence author requires an active lease or assigned pending review"
            )
        # mem-11: reject `operator_result` evidence_type when the task's
        # execution contract declared a repository contract (or set
        # repository_required=true). The original `task_d7c51a0b`
        # incident hinged on bullwinkle emitting operator_result evidence
        # for a code task; the validator accepted it because
        # OperatorResultValidator only requires *any* summary string,
        # which then sent the review loop hunting a remote_ref that was
        # never pushed.
        self._enforce_repo_coupled_evidence_type(task, metadata)
        now = utcnow()
        evidence_id = new_id("ev")
        stored_artifacts = self._prepare_evidence_artifacts(
            evidence_id,
            task_id,
            artifacts or [],
            now,
        )
        metadata_obj = dict(ensure_json_object(metadata))
        metadata_obj.pop("durable_artifacts", None)
        if stored_artifacts:
            metadata_obj["durable_artifacts"] = {
                "schema": "mac.evidence_artifacts.v1",
                "count": len(stored_artifacts),
                "artifacts": [
                    self._evidence_artifact_public_dict(item, include_content=False)
                    for item in stored_artifacts
                ],
            }
        with self.store.transaction() as conn:
            if fenced_review_id:
                task_lock = conn.execute(
                    "UPDATE tasks SET updated_at = updated_at WHERE id = ?",
                    (task_id,),
                )
                if task_lock.rowcount != 1:
                    raise NotFoundError("task not found: %s" % task_id)
                current_task_row = conn.execute(
                    "SELECT state, metadata FROM tasks WHERE id = ?",
                    (task_id,),
                ).fetchone()
                review_lock = conn.execute(
                    "UPDATE reviews SET status = status WHERE id = ? "
                    "AND task_id = ? AND reviewer_agent_id = ? AND status = ?",
                    (
                        fenced_review_id,
                        task_id,
                        created_by,
                        fenced_review_status,
                    ),
                )
                if (
                    current_task_row is None
                    or current_task_row["state"] != TaskState.REVIEWING.value
                    or review_lock.rowcount != 1
                ):
                    raise AuthorizationError(
                        "review assignment changed before evidence was recorded"
                    )
                current_metadata = ensure_json_object(
                    json_loads(current_task_row["metadata"], {})
                )
                if fenced_review_status == ReviewStatus.PENDING.value:
                    current_target = str(
                        ensure_json_object(current_metadata.get("review_target")).get(
                            "executor_evidence_id"
                        )
                        or ""
                    ).strip()
                    verification = ensure_json_object(
                        metadata_obj.get("verification")
                    )
                    reviewed_target = str(
                        verification.get("reviewed_evidence_id")
                        or metadata_obj.get("executor_evidence_id")
                        or ""
                    ).strip()
                    if not current_target or reviewed_target != current_target:
                        raise AuthorizationError(
                            "review target changed before verdict evidence was recorded"
                        )
            if fenced_lease_id:
                self._require_exact_lease_actor_in_transaction(
                    conn,
                    task_id=task_id,
                    agent_id=created_by,
                    lease_id=fenced_lease_id,
                    allowed_states=(
                        TaskState.CLAIMED.value,
                        TaskState.RUNNING.value,
                    ),
                )
            conn.execute(
                """
                INSERT INTO evidence (id, task_id, kind, uri, summary, checksum, metadata, created_by, created_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    evidence_id,
                    task_id,
                    kind,
                    uri,
                    summary,
                    checksum,
                    json_dumps(metadata_obj),
                    created_by,
                    now,
                ),
            )
            for artifact in stored_artifacts:
                conn.execute(
                    """
                    INSERT INTO evidence_artifacts (
                        id, evidence_id, task_id, name, artifact_type, source_uri,
                        content_type, encoding, size_bytes, sha256, content_base64,
                        content_uri, truncated, metadata, created_at
                    )
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        artifact.id,
                        artifact.evidence_id,
                        artifact.task_id,
                        artifact.name,
                        artifact.artifact_type,
                        artifact.source_uri,
                        artifact.content_type,
                        artifact.encoding,
                        artifact.size_bytes,
                        artifact.sha256,
                        artifact.content_base64 or "",
                        artifact.content_uri or "",
                        1 if artifact.truncated else 0,
                        json_dumps(artifact.metadata),
                        artifact.created_at,
                    ),
                )
            self._record_history(
                task_id,
                "task.evidence_added",
                created_by,
                None,
                None,
                {
                    "evidence_id": evidence_id,
                    "kind": kind,
                    "uri": uri,
                    "artifact_count": len(stored_artifacts),
                    "lease_id": fenced_lease_id,
                    "review_id": fenced_review_id,
                },
                conn=conn,
            )
        evidence = self.get_evidence(evidence_id)
        self._capture_runtime_delta_from_evidence(evidence, task)
        return evidence

    def _prepare_evidence_artifacts(
        self,
        evidence_id: str,
        task_id: str,
        artifacts: List[Dict[str, Any]],
        created_at: str,
    ) -> List[EvidenceArtifact]:
        if not artifacts:
            return []
        if len(artifacts) > MAX_EVIDENCE_ARTIFACTS:
            raise ValidationError(
                "evidence accepts at most %d durable artifacts" % MAX_EVIDENCE_ARTIFACTS
            )
        max_bytes = _evidence_artifact_max_bytes()
        total_max_bytes = _evidence_artifact_total_max_bytes()
        total_bytes = 0
        prepared: List[EvidenceArtifact] = []
        for index, item in enumerate(artifacts):
            if not isinstance(item, dict):
                raise ValidationError("evidence artifact %d must be an object" % index)
            encoding = str(item.get("encoding") or "base64").strip().lower()
            if encoding != "base64":
                raise ValidationError("evidence artifact %d uses unsupported encoding" % index)
            if "content_base64" not in item:
                raise ValidationError("evidence artifact %d requires content_base64" % index)
            raw_b64 = str(item.get("content_base64") or "").strip()
            try:
                content = base64.b64decode(raw_b64.encode("ascii"), validate=True)
            except Exception as exc:  # noqa: BLE001
                raise ValidationError("evidence artifact %d has invalid base64: %s" % (index, exc))
            if len(content) > max_bytes:
                raise ValidationError(
                    "evidence artifact %d exceeds %d bytes"
                    % (index, max_bytes)
                )
            if total_bytes + len(content) > total_max_bytes:
                raise ValidationError(
                    "evidence artifacts exceed aggregate limit of %d bytes"
                    % total_max_bytes
                )
            total_bytes += len(content)
            declared_size = item.get("size_bytes")
            if declared_size not in {None, ""}:
                try:
                    declared_size_int = int(declared_size)
                except (TypeError, ValueError):
                    raise ValidationError("evidence artifact %d size_bytes is invalid" % index)
                if declared_size_int != len(content):
                    raise ValidationError(
                        "evidence artifact %d size_bytes does not match content" % index
                    )
            digest = "sha256:%s" % hashlib.sha256(content).hexdigest()
            declared_sha = str(item.get("sha256") or "").strip()
            if declared_sha and declared_sha != digest:
                raise ValidationError("evidence artifact %d sha256 does not match content" % index)
            # Externalize bytes to the hub blob store when configured: the
            # ledger row keeps digest/size/metadata + a content_uri, so ledger
            # DB growth decouples from artifact volume. Small payloads stay
            # inline (cheaper next to their metadata); failures fall back to
            # inline so evidence capture never depends on the blob volume.
            content_b64 = base64.b64encode(content).decode("ascii")
            content_uri = ""
            blob_root = evidence_blobs.blob_root()
            if blob_root is not None and len(content) > evidence_blobs.inline_max_bytes():
                try:
                    content_uri = evidence_blobs.store_blob(blob_root, content)
                    content_b64 = ""
                except OSError:
                    content_uri = ""
            prepared.append(
                EvidenceArtifact(
                    id=new_id("eva"),
                    evidence_id=evidence_id,
                    task_id=task_id,
                    name=self._normalize_evidence_artifact_name(item.get("name"), index),
                    artifact_type=(
                        str(item.get("artifact_type") or item.get("kind") or "artifact").strip()[:64]
                        or "artifact"
                    ),
                    source_uri=str(item.get("source_uri") or item.get("uri") or "").strip()[:2048],
                    content_type=(
                        str(item.get("content_type") or "application/octet-stream").strip()[:128]
                        or "application/octet-stream"
                    ),
                    encoding="base64",
                    size_bytes=len(content),
                    sha256=digest,
                    content_base64=content_b64,
                    truncated=_evidence_artifact_bool(item.get("truncated")),
                    metadata=ensure_json_object(item.get("metadata")),
                    created_at=created_at,
                    content_uri=content_uri,
                )
            )
        return prepared

    def _normalize_evidence_artifact_name(self, value: Any, index: int) -> str:
        name = str(value or "").strip().replace("\\", "/")
        name = name.rsplit("/", 1)[-1].strip()
        if not name or name in {".", ".."}:
            name = "artifact-%02d" % (index + 1)
        return name[:160]

    def _evidence_artifact_public_dict(
        self,
        artifact: EvidenceArtifact,
        *,
        include_content: bool,
    ) -> JsonDict:
        data = artifact.to_dict()
        if not include_content:
            data.pop("content_base64", None)
            data.pop("metadata", None)
        return data

    def list_evidence_artifacts(self, evidence_id: str) -> List[JsonDict]:
        self.get_evidence(evidence_id)
        rows = self.store.query_all(
            """
            SELECT * FROM evidence_artifacts
            WHERE evidence_id = ?
            ORDER BY created_at, id
            """,
            (evidence_id,),
        )
        return [
            self._evidence_artifact_public_dict(
                self._evidence_artifact_from_row(row),
                include_content=False,
            )
            for row in rows
        ]

    def get_evidence_artifact(self, evidence_id: str, artifact_id: str) -> JsonDict:
        row = self.store.query_one(
            """
            SELECT * FROM evidence_artifacts
            WHERE evidence_id = ? AND id = ?
            """,
            (evidence_id, artifact_id),
        )
        if row is None:
            raise NotFoundError("evidence artifact not found: %s" % artifact_id)
        artifact = self._evidence_artifact_from_row(row)
        # Externalized bytes: materialize content from the blob store so the
        # response shape is identical to an inline row. Verified read — a
        # missing or corrupted blob fails closed rather than returning wrong
        # bytes under a valid-looking digest.
        if not artifact.content_base64 and artifact.content_uri:
            root = evidence_blobs.blob_root()
            if root is None:
                raise NotFoundError(
                    "evidence artifact %s content is externalized but no blob store "
                    "is configured (set %s)" % (artifact_id, evidence_blobs.BLOB_DIR_ENV)
                )
            try:
                content = evidence_blobs.read_blob(
                    root, artifact.content_uri, expected_sha256=artifact.sha256
                )
            except FileNotFoundError:
                raise NotFoundError(
                    "evidence artifact %s blob is missing from the blob store" % artifact_id
                )
            except evidence_blobs.BlobIntegrityError as exc:
                raise ValidationError(str(exc))
            artifact.content_base64 = base64.b64encode(content).decode("ascii")
        return self._evidence_artifact_public_dict(
            artifact,
            include_content=True,
        )

    def _capture_runtime_delta_from_evidence(
        self,
        evidence: Evidence,
        task: Task,
    ) -> None:
        metadata = evidence.metadata if isinstance(evidence.metadata, dict) else {}
        verification = metadata.get("verification")
        delta = None
        if isinstance(verification, dict) and isinstance(verification.get("environment_delta"), dict):
            delta = verification.get("environment_delta")
        elif isinstance(metadata.get("environment_delta"), dict):
            delta = metadata.get("environment_delta")
        if not isinstance(delta, dict):
            return
        runtime_meta = task.metadata.get("runtime") if isinstance(task.metadata, dict) else {}
        if not isinstance(runtime_meta, dict):
            runtime_meta = {}
        try:
            self.propose_runtime_delta(
                task.id,
                evidence.created_by,
                str(delta.get("package_manager") or ""),
                delta.get("commands") if isinstance(delta.get("commands"), list) else [],
                (
                    delta.get("added_dependencies")
                    if isinstance(delta.get("added_dependencies"), list)
                    else delta.get("dependencies")
                    if isinstance(delta.get("dependencies"), list)
                    else []
                ),
                str(delta.get("reason") or "worker proposed task-local dependency delta"),
                project=str(delta.get("project") or task.project or "").strip() or None,
                base_runtime_id=(
                    str(delta.get("base_runtime_id") or runtime_meta.get("runtime_environment_id") or "").strip()
                    or None
                ),
                base_runtime_digest=(
                    str(delta.get("base_runtime_digest") or runtime_meta.get("runtime_digest") or "").strip()
                    or None
                ),
                lockfile_path=str(delta.get("lockfile_path") or "").strip() or None,
                lockfile_digest=str(delta.get("lockfile_digest") or "").strip() or None,
                evidence_id=evidence.id,
            )
        except Exception as exc:  # noqa: BLE001 - evidence is already durable.
            try:
                self.record_log(
                    "runtime_delta.capture_failed",
                    layer="control_plane",
                    source=evidence.created_by,
                    level="warning",
                    subject_type="task",
                    subject_id=task.id,
                    detail={
                        "evidence_id": evidence.id,
                        "error": str(exc),
                    },
                )
            except Exception:
                pass

    def _enforce_repo_coupled_evidence_type(
        self,
        task: Task,
        metadata: Optional[Dict[str, Any]],
    ) -> None:
        """mem-11: refuse to accept operator_result evidence for a task
        that the dispatcher staged with a repository contract.

        The verification block inside metadata carries the proposed
        evidence_type. Tasks whose execution_contract.type='repository'
        or whose execution_contract.repository_required is True are
        "repo-coupled" — they must use one of the strict evidence types
        (repo_change / documentation / test / artifact / no_change /
        review_verdict) that exercises `require_pushed_repo_anchor()`
        downstream. The soft `operator_result` type bypasses that
        anchor check and was the bug that produced the runaway review
        loop on `task_d7c51a0b04bd...`.
        """
        if not isinstance(metadata, dict):
            return
        # An operator-declared report/answer task is expected to produce
        # operator_result — that is the whole point of the declaration, so do
        # not apply the repo-coupled bar to it. (The bar still protects tasks
        # that carry a repository contract without such a declaration.)
        if metadata_declares_report_deliverable(task.metadata):
            return
        verification = metadata.get("verification")
        if not isinstance(verification, dict):
            return
        evidence_type = str(verification.get("evidence_type") or "").strip().lower()
        if evidence_type != "operator_result":
            return
        contract = (
            task.metadata.get("execution_contract")
            if isinstance(task.metadata, dict)
            else None
        )
        if not isinstance(contract, dict):
            return
        is_repo_coupled = (
            str(contract.get("type") or "").strip().lower() == "repository"
            or contract.get("repository_required") is True
        )
        if not is_repo_coupled:
            return
        raise ValidationError(
            "operator_result evidence cannot be recorded for a repo-coupled "
            "task (execution_contract.type=repository or "
            "repository_required=true); use repo_change / test / documentation "
            "/ artifact / no_change / review_verdict instead. Task: %s"
            % task.id
        )


    def get_evidence(self, evidence_id: str) -> Evidence:
        row = self.store.query_one("SELECT * FROM evidence WHERE id = ?", (evidence_id,))
        if row is None:
            raise NotFoundError("evidence not found: %s" % evidence_id)
        return self._evidence_from_row(row)

    def list_evidence(
        self,
        task_id: str,
        limit: Optional[int] = None,
    ) -> List[Evidence]:
        resolved_task_id = self._resolve_task_id(task_id)
        limit_value = None if limit is None else max(0, int(limit))
        if limit_value == 0:
            return []
        if limit_value is None:
            rows = self.store.query_all(
                "SELECT * FROM evidence WHERE task_id = ? ORDER BY created_at, id",
                (resolved_task_id,),
            )
        else:
            rows = list(
                reversed(
                    self.store.query_all(
                        """
                        SELECT * FROM evidence
                        WHERE task_id = ?
                        ORDER BY created_at DESC, id DESC
                        LIMIT ?
                        """,
                        (resolved_task_id, limit_value),
                    )
                )
            )
        return [self._evidence_from_row(row) for row in rows]

    def renew_lease(self, lease_id: str, agent_id: str, lease_seconds: int = 900) -> Lease:
        lease_seconds = self._validated_task_lease_seconds(lease_seconds)
        with self.store.transaction() as conn:
            lease_lock = conn.execute(
                "UPDATE leases SET updated_at = updated_at WHERE id = ?",
                (lease_id,),
            )
            if lease_lock.rowcount != 1:
                raise NotFoundError("lease not found: %s" % lease_id)
            lease_row = conn.execute(
                "SELECT * FROM leases WHERE id = ?", (lease_id,)
            ).fetchone()
            if lease_row is None:
                raise NotFoundError("lease not found: %s" % lease_id)
            if lease_row["agent_id"] != agent_id:
                raise AuthorizationError("agent does not own lease")
            if lease_row["status"] != LeaseStatus.ACTIVE.value:
                raise ValidationError("only active leases can be renewed")
            task_id = str(lease_row["task_id"])
            task_lock = conn.execute(
                "UPDATE tasks SET updated_at = updated_at WHERE id = ?",
                (task_id,),
            )
            if task_lock.rowcount != 1:
                raise ValidationError("lease task no longer exists")
            agent_lock = conn.execute(
                "UPDATE agents SET updated_at = updated_at WHERE id = ?",
                (agent_id,),
            )
            if agent_lock.rowcount != 1:
                raise ValidationError("lease owner no longer exists")
            task_row = conn.execute(
                "SELECT state, lease_id, owner_agent_id, leased_until "
                "FROM tasks WHERE id = ?",
                (task_id,),
            ).fetchone()
            now = self._lease_authority_now_in_transaction(conn)
            if not self._timestamp_is_after(lease_row["expires_at"], now):
                raise ValidationError("expired leases cannot be renewed")
            if (
                task_row is None
                or task_row["lease_id"] != lease_id
                or task_row["owner_agent_id"] != agent_id
                or task_row["state"]
                not in {TaskState.CLAIMED.value, TaskState.RUNNING.value}
                or not task_row["leased_until"]
                or not self._timestamp_is_after(task_row["leased_until"], now)
            ):
                raise ValidationError("lease is no longer attached to an active task")
            expires_at = (
                parse_time(now) + timedelta(seconds=lease_seconds)
            ).isoformat(timespec="microseconds")
            lease_cursor = conn.execute(
                """
                UPDATE leases
                SET expires_at = ?, updated_at = ?
                WHERE id = ? AND agent_id = ? AND status = ?
                """,
                (
                    expires_at,
                    now,
                    lease_id,
                    agent_id,
                    LeaseStatus.ACTIVE.value,
                ),
            )
            if lease_cursor.rowcount != 1:
                raise ValidationError("only unexpired active leases can be renewed")
            task_cursor = conn.execute(
                """
                UPDATE tasks
                SET leased_until = ?, updated_at = ?
                WHERE id = ?
                  AND lease_id = ?
                  AND owner_agent_id = ?
                  AND state IN (?, ?)
                """,
                (
                    expires_at,
                    now,
                    task_id,
                    lease_id,
                    agent_id,
                    TaskState.CLAIMED.value,
                    TaskState.RUNNING.value,
                ),
            )
            if task_cursor.rowcount != 1:
                raise ValidationError("lease is no longer attached to an active task")
            conn.execute(
                """
                UPDATE agents
                SET status = ?, current_task_id = ?, updated_at = ?, last_seen_at = ?
                WHERE id = ?
                """,
                (AgentStatus.BUSY.value, task_id, now, now, agent_id),
            )
        self._record_history(task_id, "task.lease_renewed", agent_id, None, None, {"lease_id": lease_id})
        heartbeat_agent = self.get_agent(agent_id)
        self._maybe_advance_reviews_on_heartbeat(heartbeat_agent)
        self._maybe_drain_notifications_on_heartbeat(heartbeat_agent)
        return self.get_lease(lease_id)

    @staticmethod
    def _validated_task_lease_seconds(value: int) -> int:
        try:
            seconds = int(value)
        except (TypeError, ValueError):
            raise ValidationError("lease_seconds must be an integer") from None
        maximum = max(1, _int_env("MAC_MAX_TASK_LEASE_SECONDS", 3600))
        if seconds <= 0 or seconds > maximum:
            raise ValidationError(
                "lease_seconds must be between 1 and %d" % maximum
            )
        return seconds

    @staticmethod
    def _lease_datetime(value: Any) -> datetime:
        """Normalize a persisted or driver-native timestamp for lease logic."""
        if isinstance(value, datetime):
            parsed = value
        else:
            text = str(value or "").strip()
            if text.endswith("Z"):
                text = text[:-1] + "+00:00"
            try:
                parsed = datetime.fromisoformat(text)
            except (TypeError, ValueError):
                raise ValidationError("invalid lease timestamp: %r" % value) from None
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)

    @classmethod
    def _timestamp_is_after(cls, value: Any, boundary: Any) -> bool:
        """Compare timestamp values semantically, never as TEXT collation."""
        return cls._lease_datetime(value) > cls._lease_datetime(boundary)

    def _lease_authority_now_in_transaction(self, conn: Any) -> str:
        """Sample the lease authority clock after transaction locks are held.

        PostgreSQL is the shared clock for a multi-replica hub. ``clock_timestamp``
        is intentional: unlike ``CURRENT_TIMESTAMP`` it advances after a row-lock
        wait instead of freezing at transaction start. SQLite is supported only
        as a single-hub authority, so its process clock is sampled at this same
        late point. The injected clock is a deterministic test seam.
        """
        if self._lease_clock is not None:
            raw = self._lease_clock()
        elif type(self.store).__module__ == "mac.store_postgres":
            row = conn.execute(
                "SELECT clock_timestamp() AS authoritative_now"
            ).fetchone()
            if row is None:
                raise ValidationError("database lease clock is unavailable")
            raw = row["authoritative_now"]
        else:
            raw = utcnow()
        return self._lease_datetime(raw).isoformat(timespec="microseconds")

    def get_lease(self, lease_id: str) -> Lease:
        row = self.store.query_one("SELECT * FROM leases WHERE id = ?", (lease_id,))
        if row is None:
            raise NotFoundError("lease not found: %s" % lease_id)
        return self._lease_from_row(row)

    def delegate_lease(
        self,
        lease_id: str,
        owner_agent_id: str,
        to_agent_id: str,
    ) -> Lease:
        """Delegate lifecycle authorship on a lease's task to another agent.

        Per spec §6.3 (Option B), the dispatcher (``mac-runner``) holds
        the lease but the role-specialised Job pod authors lifecycle
        transitions and evidence. This call records the delegation so
        ``start_task`` / ``submit_for_review`` / ``add_evidence`` accept
        the delegate as a legitimate actor.

        Renewal and release stay strictly owner-only — see the spec.
        """
        lease = self.get_lease(lease_id)
        if lease.agent_id != owner_agent_id:
            raise AuthorizationError("only the lease owner can delegate")
        # Verify the target agent exists; this also implicitly enforces
        # the agents-table FK that the schema declares so SQLite (no FK
        # enforcement by default) matches Postgres semantics.
        self.get_agent(to_agent_id)
        with self.store.transaction() as conn:
            target_lock = conn.execute(
                "UPDATE agents SET updated_at = updated_at "
                "WHERE id = ? AND deleted_at IS NULL",
                (to_agent_id,),
            )
            if target_lock.rowcount != 1:
                raise ValidationError("delegated agent is unavailable")
            self._require_exact_lease_actor_in_transaction(
                conn,
                task_id=lease.task_id,
                agent_id=owner_agent_id,
                lease_id=lease_id,
                allowed_states=(TaskState.CLAIMED.value, TaskState.RUNNING.value),
            )
            now = self._lease_authority_now_in_transaction(conn)
            delegated = conn.execute(
                """
                UPDATE leases
                SET delegated_agent_id = ?, updated_at = ?
                WHERE id = ? AND agent_id = ? AND status = ?
                """,
                (
                    to_agent_id,
                    now,
                    lease_id,
                    owner_agent_id,
                    LeaseStatus.ACTIVE.value,
                ),
            )
            if delegated.rowcount != 1:
                raise AuthorizationError("lease delegation authority changed")
            self._record_history(
                lease.task_id,
                "task.lease_delegated",
                owner_agent_id,
                None,
                None,
                {"lease_id": lease_id, "delegated_agent_id": to_agent_id},
                conn=conn,
            )
        return self.get_lease(lease_id)

    def _is_lease_actor(self, task: Task, agent_id: str) -> bool:
        """Return whether ``agent_id`` is named by the current lease.

        This intentionally does not establish authority by itself; callers
        that mutate active work must also validate the lease-attempt fence.
        """
        if not task.lease_id:
            return False
        try:
            lease = self.get_lease(task.lease_id)
        except NotFoundError:
            return False
        return lease.agent_id == agent_id or (
            bool(lease.delegated_agent_id)
            and lease.delegated_agent_id == agent_id
        )

    def _lease_actor_allowed(
        self,
        task: Task,
        agent_id: str,
        lease_id: Optional[str] = None,
    ) -> bool:
        """Return True if ``agent_id`` may author lifecycle transitions
        on ``task`` per spec §6.3 (Option B).

        Allowed actors:
          * the task's current owner (``task.owner_agent_id``); or
          * the agent recorded in the task's active lease's
            ``delegated_agent_id`` (set via :meth:`delegate_lease`).
        """
        if not task.lease_id:
            return False
        try:
            lease = self.get_lease(task.lease_id)
        except NotFoundError:
            return False
        if lease.status != LeaseStatus.ACTIVE.value:
            return False
        if lease.agent_id != agent_id and lease.delegated_agent_id != agent_id:
            return False
        supplied_lease_id = str(lease_id or "").strip()
        if supplied_lease_id:
            return supplied_lease_id == lease.id

        # Bounded compatibility for pre-fence callers: omission is safe only
        # while this actor identity has participated in exactly one lease
        # attempt for the task. A different agent may safely be the second
        # owner, but once the same owner/delegate identity reacquires the task,
        # an omitted token could be its old process and is rejected.
        count_row = self.store.query_one(
            "SELECT COUNT(*) AS count FROM leases "
            "WHERE task_id = ? AND (agent_id = ? OR delegated_agent_id = ?)",
            (task.id, agent_id, agent_id),
        )
        return int(count_row["count"] if count_row is not None else 0) == 1

    def _require_exact_lease_actor(
        self,
        task: Task,
        agent_id: str,
        lease_id: Optional[str],
    ) -> None:
        """Require an exact current-attempt fence for a public transition."""
        supplied_lease_id = str(lease_id or "").strip()
        if not supplied_lease_id:
            raise AuthorizationError(
                "current lease_id is required for active task transitions"
            )
        if not self._lease_actor_allowed(task, agent_id, supplied_lease_id):
            raise AuthorizationError("agent does not own the current task lease")

    def _require_lease_actor(
        self,
        task: Task,
        agent_id: str,
        lease_id: Optional[str],
    ) -> None:
        if self._lease_actor_allowed(task, agent_id, lease_id):
            return
        if self._is_lease_actor(task, agent_id) and not str(lease_id or "").strip():
            raise AuthorizationError(
                "current lease_id is required after a task has been reacquired"
            )
        raise AuthorizationError("agent does not own the current task lease")

    def _require_exact_lease_actor_in_transaction(
        self,
        conn: Any,
        *,
        task_id: str,
        agent_id: str,
        lease_id: str,
        allowed_states: Sequence[str],
    ) -> None:
        """Lock and validate the active assignment in the write transaction.

        Lease then task is the same lock order used by release/expiry paths.
        This closes the validation-to-write race where lease A is checked,
        reassigned as B, and A's delayed INSERT/UPDATE lands on B's attempt.
        """
        supplied_lease_id = str(lease_id or "").strip()
        if not supplied_lease_id:
            raise AuthorizationError("current lease_id is required")
        lease_lock = conn.execute(
            "UPDATE leases SET updated_at = updated_at WHERE id = ?",
            (supplied_lease_id,),
        )
        if lease_lock.rowcount != 1:
            raise AuthorizationError("task lease does not exist")
        task_lock = conn.execute(
            "UPDATE tasks SET updated_at = updated_at WHERE id = ?",
            (task_id,),
        )
        if task_lock.rowcount != 1:
            raise NotFoundError("task not found: %s" % task_id)
        row = conn.execute(
            """
            SELECT t.state AS task_state, t.lease_id AS current_lease_id,
                   l.task_id AS lease_task_id, l.agent_id AS lease_agent_id,
                   l.delegated_agent_id AS delegated_agent_id,
                   l.status AS lease_status, l.expires_at AS lease_expires_at
            FROM tasks t
            LEFT JOIN leases l ON l.id = ?
            WHERE t.id = ?
            """,
            (supplied_lease_id, task_id),
        ).fetchone()
        if row is None:
            raise NotFoundError("task not found: %s" % task_id)
        if (
            row["current_lease_id"] != supplied_lease_id
            or row["lease_task_id"] != task_id
            or row["lease_status"] != LeaseStatus.ACTIVE.value
        ):
            raise AuthorizationError("lease fence is not the task's active lease")
        if row["task_state"] not in set(allowed_states):
            raise TransitionError("task state changed during fenced write; retry")
        now = self._lease_authority_now_in_transaction(conn)
        if not self._timestamp_is_after(row["lease_expires_at"], now):
            raise AuthorizationError("task lease has expired")
        if (
            row["lease_agent_id"] != agent_id
            and row["delegated_agent_id"] != agent_id
        ):
            raise AuthorizationError("agent does not own the current task lease")

    def expire_leases(
        self,
        now: Optional[str] = None,
        *,
        grace_seconds: Optional[int] = None,
        limit: int = 100,
        cursor: Optional[str] = None,
    ) -> List[Task]:
        return self._expire_leases_page(
            now=now,
            grace_seconds=grace_seconds,
            limit=limit,
            cursor=cursor,
        )["tasks"]

    def _expire_leases_page(
        self,
        now: Optional[str] = None,
        *,
        grace_seconds: Optional[int] = None,
        limit: int = 100,
        cursor: Optional[str] = None,
    ) -> JsonDict:
        # mac-vgw9: when `now` is auto-derived, subtract a small tolerance
        # so an NTP step forward doesn't mass-expire every lease. When
        # the caller passes `now` explicitly, honor it exactly (callers
        # use this for deterministic tests or for manually advancing the
        # clock). Operators can also pass an explicit ``grace_seconds``.
        if now is not None:
            grace = grace_seconds or 0
            cutoff_dt = parse_time(now) - timedelta(seconds=int(grace))
        else:
            grace = 30 if grace_seconds is None else int(grace_seconds)
            cutoff_dt = parse_time(utcnow()) - timedelta(seconds=grace)
        cutoff = cutoff_dt.isoformat(timespec="microseconds")
        limit_value = max(1, min(int(limit), 1000))
        # Candidate selection is deliberately advisory: a skewed process clock
        # may over-select, and a renewal may land before row processing. The
        # per-row transaction below re-reads against the authority clock. Also
        # resume a prior crash that durably fenced a lease EXPIRED but did not
        # yet detach its task.
        clauses = [
            "((l.status = ? AND l.expires_at <= ?) "
            "OR (l.status = ? AND t.lease_id = l.id))"
        ]
        params: List[Any] = [
            LeaseStatus.ACTIVE.value,
            cutoff,
            LeaseStatus.EXPIRED.value,
        ]
        decoded = self._decode_scan_cursor(cursor, "expired-leases")
        if decoded is not None:
            expires_at, lease_id = decoded
            clauses.append(
                "(l.expires_at > ? OR (l.expires_at = ? AND l.id > ?))"
            )
            params.extend([expires_at, expires_at, lease_id])
        params.append(limit_value + 1)
        rows = self.store.query_all(
            "SELECT l.* FROM leases AS l "
            "LEFT JOIN tasks AS t ON t.lease_id = l.id "
            "WHERE %s ORDER BY l.expires_at, l.id LIMIT ?"
            % " AND ".join(clauses),
            tuple(params),
        )
        has_more = len(rows) > limit_value
        rows = rows[:limit_value]
        recovered: List[Task] = []
        for row in rows:
            try:
                task = self._expire_lease_row(row, grace_seconds=grace)
            except Exception as exc:  # noqa: BLE001 - isolate corrupt lease rows.
                try:
                    self.record_log(
                        "lease.recovery.failed",
                        layer="control_plane",
                        source="dispatcher",
                        level="error",
                        subject_type="lease",
                        subject_id=str(row["id"]),
                        detail={"lease_id": str(row["id"]), "error": str(exc)},
                    )
                except Exception:
                    pass
                continue
            if task is not None:
                recovered.append(task)
        next_cursor = (
            self._encode_scan_cursor(
                "expired-leases",
                str(rows[-1]["expires_at"]),
                str(rows[-1]["id"]),
            )
            if has_more and rows
            else None
        )
        return {
            "tasks": recovered,
            "next_cursor": next_cursor,
            "has_more": has_more,
        }

    def _expire_lease_row(
        self,
        row: Any,
        *,
        grace_seconds: int = 0,
        force_expire: bool = False,
        decision_override: Optional[Mapping[str, Any]] = None,
    ) -> Optional[Task]:
        candidate = self._lease_from_row(row)
        # Phase 1 is the authority decision. Lease then task matches the fence
        # lock order used by renew/worker writes. A renewed lease is re-read
        # after the wait and left ACTIVE; process-clock skew can only make this
        # scan do extra work, never expire a DB-live assignment.
        with self.store.transaction() as conn:
            lease_lock = conn.execute(
                "UPDATE leases SET updated_at = updated_at WHERE id = ?",
                (candidate.id,),
            )
            if lease_lock.rowcount != 1:
                return None
            lease_row = conn.execute(
                "SELECT * FROM leases WHERE id = ?", (candidate.id,)
            ).fetchone()
            if lease_row is None:
                return None
            task_id = str(lease_row["task_id"])
            task_lock = conn.execute(
                "UPDATE tasks SET updated_at = updated_at WHERE id = ?",
                (task_id,),
            )
            if task_lock.rowcount != 1:
                return None
            attached = conn.execute(
                "SELECT lease_id FROM tasks WHERE id = ?", (task_id,)
            ).fetchone()
            if attached is None or attached["lease_id"] != candidate.id:
                return None
            status = str(lease_row["status"])
            if status == LeaseStatus.ACTIVE.value:
                authority_now = self._lease_authority_now_in_transaction(conn)
                if not force_expire:
                    cutoff = (
                        parse_time(authority_now)
                        - timedelta(seconds=max(0, int(grace_seconds)))
                    ).isoformat(timespec="microseconds")
                    if self._timestamp_is_after(lease_row["expires_at"], cutoff):
                        return None
                fenced = conn.execute(
                    "UPDATE leases SET status = ?, updated_at = ? "
                    "WHERE id = ? AND status = ? AND expires_at = ?",
                    (
                        LeaseStatus.EXPIRED.value,
                        authority_now,
                        candidate.id,
                        LeaseStatus.ACTIVE.value,
                        lease_row["expires_at"],
                    ),
                )
                if fenced.rowcount != 1:
                    return None
            elif status != LeaseStatus.EXPIRED.value:
                return None

        # The EXPIRED fence is durable before classification/repair work. If
        # this process crashes, the scan above includes EXPIRED leases still
        # attached to a task and resumes this idempotent finalization; renewal
        # can never resurrect the assignment between the two phases. A durable
        # per-lease claim prevents concurrent sweepers from both creating the
        # same repair work. Stale claims are reclaimable after a bounded delay;
        # repair creation below has a deterministic id and the final task write
        # is an exact lease CAS, so crash recovery remains idempotent.
        finalizer_token = self._claim_lease_expiry_finalization(candidate.id)
        if finalizer_token is None:
            return None
        lease = self.get_lease(candidate.id)
        task = self.get_task(lease.task_id)
        if task.lease_id != lease.id:
            return None
        decision_row = self.store.query_one(
            "SELECT expiry_finalization_decision FROM leases WHERE id = ?",
            (lease.id,),
        )
        raw_decision = (
            decision_row["expiry_finalization_decision"]
            if decision_row is not None
            else None
        )
        decision = ensure_json_object(
            raw_decision
            if isinstance(raw_decision, Mapping)
            else json_loads(raw_decision, {})
        )
        if decision.get("schema") == "mac.lease_expiry_decision.v1":
            if decision_override is not None and decision != ensure_json_object(
                decision_override
            ):
                raise ValidationError(
                    "stored lease expiry decision conflicts with the requested decision"
                )
            if (
                decision.get("lease_id") != lease.id
                or decision.get("task_id") != task.id
            ):
                raise ValidationError(
                    "stored lease expiry decision belongs to a different assignment"
                )
            target_state = str(decision.get("target_state") or "")
            transition_history_detail = ensure_json_object(decision.get("detail"))
            reset_attempt_count = bool(decision.get("reset_attempt_count"))
            attempt_count_after = decision.get("attempt_count_after")
            if target_state not in {
                TaskState.OPEN.value,
                TaskState.WAITING.value,
                TaskState.FAILED.value,
                TaskState.CANCELLED.value,
            }:
                raise ValidationError("stored lease expiry decision is invalid")
            if reset_attempt_count and target_state != TaskState.WAITING.value:
                raise ValidationError(
                    "stored lease expiry decision has an invalid attempt reset"
                )
            if attempt_count_after is not None and (
                isinstance(attempt_count_after, bool)
                or not isinstance(attempt_count_after, int)
                or attempt_count_after < 0
                or attempt_count_after > task.attempt_count
            ):
                raise ValidationError(
                    "stored lease expiry decision has an invalid attempt count"
                )
        else:
            override = ensure_json_object(decision_override)
            if override:
                if override.get("schema") != "mac.lease_expiry_decision.v1":
                    raise ValidationError("lease expiry decision override is invalid")
                if (
                    override.get("lease_id") != lease.id
                    or override.get("task_id") != task.id
                ):
                    raise ValidationError(
                        "lease expiry decision override belongs to another assignment"
                    )
                target_state = str(override.get("target_state") or "")
                transition_history_detail = ensure_json_object(override.get("detail"))
                reset_attempt_count = bool(override.get("reset_attempt_count"))
                attempt_count_after = override.get("attempt_count_after")
                if target_state not in {
                    TaskState.OPEN.value,
                    TaskState.WAITING.value,
                    TaskState.FAILED.value,
                    TaskState.CANCELLED.value,
                }:
                    raise ValidationError("lease expiry decision override is invalid")
                if reset_attempt_count and target_state != TaskState.WAITING.value:
                    raise ValidationError(
                        "lease expiry decision override has an invalid attempt reset"
                    )
                if attempt_count_after is not None and (
                    isinstance(attempt_count_after, bool)
                    or not isinstance(attempt_count_after, int)
                    or attempt_count_after < 0
                    or attempt_count_after > task.attempt_count
                ):
                    raise ValidationError(
                        "lease expiry decision override has an invalid attempt count"
                    )
                decision = dict(override)
            else:
                is_exhausted = task.attempt_count >= task.max_attempts
        # When the lease expires and the task has exhausted its retry budget,
        # call _exhausted_attempt_terminal_transition before the guarded
        # transaction.  This stamps failure_class on the task metadata,
        # creates an environment/contract repair task when appropriate, and
        # returns the real target state (FAILED, WAITING, or CANCELLED).
        # The call must precede the transaction because FAILED→WAITING is not
        # a valid post-hoc state transition.
                if is_exhausted:
                    target_state, exhausted_detail = self._exhausted_attempt_terminal_transition(
                        task,
                        {
                            "lease_id": lease.id,
                            "agent_id": lease.agent_id,
                            "_defer_attempt_reset": True,
                        },
                    )
                    transition_history_detail = exhausted_detail
                    reset_attempt_count = bool(
                        transition_history_detail.get("reset_attempt_count")
                    )
                else:
                    target_state = TaskState.OPEN.value
                    transition_history_detail = {
                        "lease_id": lease.id,
                        "agent_id": lease.agent_id,
                    }
                    reset_attempt_count = False
                attempt_count_after = None
                decision = {
                    "schema": "mac.lease_expiry_decision.v1",
                    "lease_id": lease.id,
                    "task_id": task.id,
                    "target_state": target_state,
                    "reset_attempt_count": reset_attempt_count,
                    "detail": transition_history_detail,
                }
            with self.store.transaction() as conn:
                decision_lock = conn.execute(
                    "UPDATE leases SET updated_at = updated_at WHERE id = ?",
                    (lease.id,),
                )
                if decision_lock.rowcount != 1:
                    return None
                persisted = conn.execute(
                    "UPDATE leases SET expiry_finalization_decision = ?, "
                    "updated_at = ? WHERE id = ? AND status = ? "
                    "AND expiry_finalizer_token = ? "
                    "AND expiry_finalization_decision IS NULL",
                    (
                        json_dumps(decision),
                        self._lease_authority_now_in_transaction(conn),
                        lease.id,
                        LeaseStatus.EXPIRED.value,
                        finalizer_token,
                    ),
                )
                if persisted.rowcount != 1:
                    current = conn.execute(
                        "SELECT expiry_finalization_decision FROM leases WHERE id = ?",
                        (lease.id,),
                    ).fetchone()
                    raw_existing = (
                        current["expiry_finalization_decision"]
                        if current is not None
                        else None
                    )
                    existing = ensure_json_object(
                        raw_existing
                        if isinstance(raw_existing, Mapping)
                        else json_loads(raw_existing, {})
                    )
                    if existing != decision:
                        return None
        with self.store.transaction() as conn:
            lease_lock = conn.execute(
                "UPDATE leases SET updated_at = updated_at WHERE id = ?",
                (lease.id,),
            )
            if lease_lock.rowcount != 1:
                return None
            finalizer_row = conn.execute(
                "SELECT status, expiry_finalizer_token, expiry_finalized_at, "
                "expiry_finalization_decision "
                "FROM leases WHERE id = ?",
                (lease.id,),
            ).fetchone()
            if (
                finalizer_row is None
                or finalizer_row["status"] != LeaseStatus.EXPIRED.value
                or finalizer_row["expiry_finalizer_token"] != finalizer_token
                or finalizer_row["expiry_finalized_at"] is not None
                or ensure_json_object(
                    finalizer_row["expiry_finalization_decision"]
                    if isinstance(
                        finalizer_row["expiry_finalization_decision"], Mapping
                    )
                    else json_loads(
                        finalizer_row["expiry_finalization_decision"], {}
                    )
                )
                != decision
            ):
                return None
            task_lock = conn.execute(
                "UPDATE tasks SET updated_at = updated_at WHERE id = ?",
                (task.id,),
            )
            if task_lock.rowcount != 1:
                return None
            current_task_row = conn.execute(
                "SELECT * FROM tasks WHERE id = ?", (task.id,)
            ).fetchone()
            if current_task_row is None or current_task_row["lease_id"] != lease.id:
                detached_at = self._lease_authority_now_in_transaction(conn)
                conn.execute(
                    "UPDATE leases SET expiry_finalized_at = ?, "
                    "expiry_finalizer_token = NULL, updated_at = ? "
                    "WHERE id = ? AND expiry_finalizer_token = ?",
                    (
                        detached_at,
                        detached_at,
                        lease.id,
                        finalizer_token,
                    ),
                )
                return None
            current_task = self._task_from_row(current_task_row)
            timestamp = self._lease_authority_now_in_transaction(conn)
            cur = conn.execute(
                """
                UPDATE tasks
                SET state = ?, owner_agent_id = NULL, lease_id = NULL,
                    leased_until = NULL,
                    attempt_count = CASE
                        WHEN ? = 1 THEN ?
                        WHEN ? = 1 THEN 0
                        ELSE attempt_count
                    END,
                    completed_at = CASE
                        WHEN ? = ? AND completed_at IS NULL THEN ?
                        ELSE completed_at
                    END,
                    updated_at = ?
                WHERE id = ? AND lease_id = ?
                """,
                (
                    target_state,
                    1 if attempt_count_after is not None else 0,
                    attempt_count_after if attempt_count_after is not None else 0,
                    1 if reset_attempt_count else 0,
                    target_state,
                    TaskState.FAILED.value,
                    timestamp,
                    timestamp,
                    task.id,
                    lease.id,
                ),
            )
            if cur.rowcount == 0:
                return None
            self._consume_break_glass_authorizations(
                conn,
                task_id=task.id,
                lease_id=lease.id,
                now=timestamp,
            )
            conn.execute(
                """
                UPDATE agents
                SET status = ?, current_task_id = NULL, updated_at = ?
                WHERE id = ? AND current_task_id = ?
                """,
                (AgentStatus.IDLE.value, timestamp, lease.agent_id, task.id),
            )
            self._record_history(
                task.id,
                "task.lease_expired",
                "dispatcher",
                current_task.state,
                target_state,
                transition_history_detail,
                conn=conn,
            )
            finalized = conn.execute(
                "UPDATE leases SET expiry_finalized_at = ?, "
                "expiry_finalizer_token = NULL, updated_at = ? "
                "WHERE id = ? AND expiry_finalizer_token = ? "
                "AND expiry_finalized_at IS NULL",
                (timestamp, timestamp, lease.id, finalizer_token),
            )
            if finalized.rowcount != 1:
                raise TransitionError("lease expiry finalizer ownership changed; retry")
        recovered = self.get_task(task.id)
        try:
            self._record_expired_lease_zombie_signal(lease)
        except Exception as exc:  # noqa: BLE001 - lease recovery has already committed.
            self.record_log(
                "agent.expired_lease_zombie_signal_failed",
                level="warning",
                layer="control_plane",
                source="dispatcher",
                subject_type="agent",
                subject_id=lease.agent_id,
                detail={
                    "agent_id": lease.agent_id,
                    "lease_id": lease.id,
                    "task_id": lease.task_id,
                    "error": str(exc),
                },
            )
        self.drain_task_transition_outbox(task_id=task.id, limit=20)
        return recovered


    def _claim_lease_expiry_finalization(self, lease_id: str) -> Optional[str]:
        """Claim the side-effecting half of lease expiry exactly once at a time.

        The ACTIVE -> EXPIRED decision is already durable when this runs. A
        claim is deliberately separate so a crashed sweeper can be resumed.
        Only an expired lease still attached to its task is claimable. A live
        claim blocks peers; after the bounded stale interval a peer may take it
        over and safely repeat only idempotent preparation before the final CAS.
        """

        token = new_id("lease-finalizer")
        stale_seconds = max(
            1,
            min(
                _int_env("MAC_LEASE_EXPIRY_FINALIZER_STALE_SECONDS", 300),
                3600,
            ),
        )
        with self.store.transaction() as conn:
            locked = conn.execute(
                "UPDATE leases SET updated_at = updated_at WHERE id = ?",
                (lease_id,),
            )
            if locked.rowcount != 1:
                return None
            row = conn.execute(
                "SELECT task_id, status, expiry_finalizer_token, "
                "expiry_finalizer_claimed_at, expiry_finalized_at "
                "FROM leases WHERE id = ?",
                (lease_id,),
            ).fetchone()
            if (
                row is None
                or row["status"] != LeaseStatus.EXPIRED.value
                or row["expiry_finalized_at"] is not None
            ):
                return None
            task_id = str(row["task_id"])
            task_lock = conn.execute(
                "UPDATE tasks SET updated_at = updated_at WHERE id = ?",
                (task_id,),
            )
            if task_lock.rowcount != 1:
                return None
            attached = conn.execute(
                "SELECT lease_id FROM tasks WHERE id = ?", (task_id,)
            ).fetchone()
            if attached is None or attached["lease_id"] != lease_id:
                return None
            authority_now = self._lease_authority_now_in_transaction(conn)
            existing_token = str(row["expiry_finalizer_token"] or "").strip()
            existing_claimed_at = row["expiry_finalizer_claimed_at"]
            if existing_token and existing_claimed_at is not None:
                stale_cutoff = (
                    parse_time(authority_now) - timedelta(seconds=stale_seconds)
                ).isoformat(timespec="microseconds")
                try:
                    if self._timestamp_is_after(existing_claimed_at, stale_cutoff):
                        return None
                except (TypeError, ValueError):
                    # Malformed legacy timestamps are treated as stale. The
                    # exact token/time CAS below still prevents dual ownership.
                    pass
            if existing_token and existing_claimed_at is not None:
                claimed = conn.execute(
                    "UPDATE leases SET expiry_finalizer_token = ?, "
                    "expiry_finalizer_claimed_at = ?, updated_at = ? "
                    "WHERE id = ? AND status = ? "
                    "AND expiry_finalizer_token = ? "
                    "AND expiry_finalizer_claimed_at = ? "
                    "AND expiry_finalized_at IS NULL",
                    (
                        token,
                        authority_now,
                        authority_now,
                        lease_id,
                        LeaseStatus.EXPIRED.value,
                        row["expiry_finalizer_token"],
                        existing_claimed_at,
                    ),
                )
            elif existing_token:
                claimed = conn.execute(
                    "UPDATE leases SET expiry_finalizer_token = ?, "
                    "expiry_finalizer_claimed_at = ?, updated_at = ? "
                    "WHERE id = ? AND status = ? "
                    "AND expiry_finalizer_token = ? "
                    "AND expiry_finalizer_claimed_at IS NULL "
                    "AND expiry_finalized_at IS NULL",
                    (
                        token,
                        authority_now,
                        authority_now,
                        lease_id,
                        LeaseStatus.EXPIRED.value,
                        row["expiry_finalizer_token"],
                    ),
                )
            else:
                claimed = conn.execute(
                    "UPDATE leases SET expiry_finalizer_token = ?, "
                    "expiry_finalizer_claimed_at = ?, updated_at = ? "
                    "WHERE id = ? AND status = ? "
                    "AND expiry_finalizer_token IS NULL "
                    "AND expiry_finalized_at IS NULL",
                    (
                        token,
                        authority_now,
                        authority_now,
                        lease_id,
                        LeaseStatus.EXPIRED.value,
                    ),
                )
            return token if claimed.rowcount == 1 else None

    def _agent_is_virtual(self, agent_id: str) -> bool:
        """True for hub-driven virtual agents (e.g. the hub_verify review
        verifier) that have no worker process of their own."""
        try:
            agent = self.get_agent(agent_id)
        except NotFoundError:
            return False
        return bool(ensure_json_object(agent.resources).get("virtual"))

    def _record_expired_lease_zombie_signal(self, lease: Lease) -> None:
        # Virtual, hub-driven agents (the hub_verify review verifier) have no
        # worker process and by design never emit executor telemetry, so the
        # "consecutive lease expiries without telemetry" zombie signal — which
        # exists to bench dead REAL hosts — is a category error for them. Every
        # in-hub review the verifier drives would otherwise look like a zombie
        # expiry, quarantining the verifier and stalling the whole review stage.
        if self._agent_is_virtual(lease.agent_id):
            return
        had_telemetry = self._lease_attempt_telemetry_exists(lease)
        now = utcnow()
        with self.store.transaction() as conn:
            row = conn.execute(
                """
                SELECT consecutive_lease_expiries_no_telemetry
                FROM agents
                WHERE id = ?
                """,
                (lease.agent_id,),
            ).fetchone()
            if row is None:
                return
            previous_count = int(row["consecutive_lease_expiries_no_telemetry"] or 0)
            next_count = 0 if had_telemetry else previous_count + 1
            conn.execute(
                """
                UPDATE agents
                SET consecutive_lease_expiries_no_telemetry = ?, updated_at = ?
                WHERE id = ?
                """,
                (next_count, now, lease.agent_id),
            )
        self._maybe_auto_quarantine_agent(
            lease,
            previous_count=previous_count,
            next_count=next_count,
            had_telemetry=had_telemetry,
        )

    def _lease_attempt_telemetry_exists(self, lease: Lease) -> bool:
        actor_ids = [lease.agent_id]
        if lease.delegated_agent_id:
            actor_ids.append(lease.delegated_agent_id)
        actor_ids = list(dict.fromkeys(actor_ids))
        placeholders = ", ".join("?" for _ in actor_ids)
        evidence = self.store.query_one(
            """
            SELECT id
            FROM evidence
            WHERE task_id = ?
              AND created_by IN (%s)
              AND created_at >= ?
            ORDER BY created_at
            LIMIT 1
            """ % placeholders,
            tuple([lease.task_id, *actor_ids, lease.created_at]),
        )
        if evidence is not None:
            return True
        rows = self.store.query_all(
            """
            SELECT detail
            FROM observability_events
            WHERE name = ?
              AND subject_type = ?
              AND subject_id = ?
              AND created_at >= ?
            ORDER BY created_at
            """,
            ("executor.started", "task", lease.task_id, lease.created_at),
        )
        actors = set(actor_ids)
        for row in rows:
            detail = json_loads(row["detail"], {})
            if str(detail.get("agent_id") or "") in actors:
                return True
        return False

    def _maybe_auto_quarantine_agent(
        self,
        lease: Lease,
        *,
        previous_count: int,
        next_count: int,
        had_telemetry: bool,
    ) -> None:
        threshold = _agent_quarantine_threshold()
        stream_age = self.unconsumed_control_stream_age_seconds(lease.agent_id)
        stream_age_signal = (
            stream_age is not None and stream_age > _agent_zombie_stream_age_seconds()
        )
        # The stream-age signal is corroboration, not a quarantine on its own.
        # Adding it to the expiry count meant ONE expired lease on an agent
        # that had not drained its control stream reached the default
        # threshold of 2 and benched the worker -- with no automatic release.
        # Require real repeated expiries first, then let stream age corroborate.
        if next_count < 1:
            return
        current_signals = next_count + (1 if stream_age_signal else 0)
        if next_count < threshold and current_signals < threshold + 1:
            return
        agent = self.get_agent(lease.agent_id)
        if agent.dispatch_hold:
            return
        held = self.set_agent_dispatch_hold(lease.agent_id, AUTO_QUARANTINE_REASON)
        request_id = "auto-quarantine-%s" % lease.id
        detail = {
            "agent_id": lease.agent_id,
            "lease_id": lease.id,
            "task_id": lease.task_id,
            "reason": AUTO_QUARANTINE_REASON,
            "threshold": threshold,
            "previous_consecutive_expiries_no_telemetry": previous_count,
            "consecutive_expiries_no_telemetry": next_count,
            "had_attempt_telemetry": had_telemetry,
            "unconsumed_control_stream_age_seconds": stream_age,
            "unconsumed_control_stream_age_signal": stream_age_signal,
        }
        self.record_log(
            "agent.auto_quarantined",
            level="warning",
            layer="control_plane",
            source="dispatcher",
            subject_type="agent",
            subject_id=lease.agent_id,
            detail=detail,
        )
        try:
            self.publish_agentbus_content(
                sender_agent_id=held.id,
                recipient_agent_id=held.id,
                content_type=REFLECT_REQUEST_CONTENT_TYPE,
                topic=REFLECT_REQUEST_TOPIC,
                payload=reflect_request_payload(
                    sender_agent_id=held.id,
                    request_id=request_id,
                    query=(
                        "Auto-quarantine diagnostic: your last lease expired "
                        "without executor.started telemetry or task evidence. "
                        "Report whether your worker loop is alive, whether "
                        "AgentBus control messages are being consumed, and the "
                        "last task action you attempted."
                    ),
                ),
            )
        except Exception as exc:  # noqa: BLE001 - quarantine must not depend on AgentBus.
            self.record_log(
                "agent.auto_quarantine_reflect_failed",
                level="warning",
                layer="control_plane",
                source="dispatcher",
                subject_type="agent",
                subject_id=lease.agent_id,
                detail={**detail, "error": str(exc)},
            )

    def _expire_leases_sweep_page(self, *, limit: int) -> JsonDict:
        claim = self.reconciliation.claim("expired-lease-sweep")
        if claim is None:
            return {
                "tasks": [],
                "next_cursor": None,
                "has_more": False,
                "skipped": "lease_held",
            }
        try:
            result = self._expire_leases_page(limit=limit, cursor=claim.cursor)
        except Exception:
            self.reconciliation.abandon(claim)
            raise
        self.reconciliation.complete(claim, cursor=result.get("next_cursor"))
        return result

    def release_lease(self, lease_id: str, agent_id: str) -> Task:
        lease = self.get_lease(lease_id)
        if lease.agent_id != agent_id:
            raise AuthorizationError("agent does not own lease")
        task = self.get_task(lease.task_id)
        now = utcnow()
        with self.store.transaction() as conn:
            # mac-79s1: guard the lease UPDATE on status='active'. If
            # the lease was already expired/released by the hub or another
            # path, this UPDATE affects 0 rows and we must NOT proceed to
            # clobber the task row — by then it may have a new owner.
            cur = conn.execute(
                "UPDATE leases SET status = ?, updated_at = ? WHERE id = ? AND status = ?",
                (LeaseStatus.RELEASED.value, now, lease_id, LeaseStatus.ACTIVE.value),
            )
            if cur.rowcount == 0:
                raise TransitionError(
                    "lease %s is no longer active (already released or expired)" % lease_id
                )
            self._consume_break_glass_authorizations(
                conn,
                task_id=task.id,
                lease_id=lease_id,
                now=now,
            )
            # mac-79s1: guard the task UPDATE on the lease still pointing at
            # this lease and being owned by this agent. If a new owner has
            # taken over, the row count is 0 and we refuse.
            cur = conn.execute(
                """
                UPDATE tasks
                SET state = ?, owner_agent_id = NULL, lease_id = NULL, leased_until = NULL, updated_at = ?
                WHERE id = ? AND lease_id = ? AND owner_agent_id = ?
                """,
                (TaskState.OPEN.value, now, task.id, lease_id, agent_id),
            )
            if cur.rowcount == 0:
                raise TransitionError(
                    "task %s has been reclaimed by another owner; refusing to release" % task.id
                )
            conn.execute(
                "UPDATE agents SET status = ?, current_task_id = NULL, updated_at = ? WHERE id = ?",
                (AgentStatus.IDLE.value, now, agent_id),
            )
            detail = {"lease_id": lease_id}
            self._record_history(
                task.id,
                "task.lease_released",
                agent_id,
                task.state,
                TaskState.OPEN.value,
                detail,
                conn=conn,
            )
        self.drain_task_transition_outbox(task_id=task.id, limit=20)
        return self.get_task(task.id)

    # Fleet registry

    def register_machine(
        self,
        hostname: str,
        labels: Optional[Dict[str, Any]] = None,
        resources: Optional[Dict[str, Any]] = None,
        trusted: bool = True,
        machine_id: Optional[str] = None,
        hardware: Optional[Dict[str, Any]] = None,
    ) -> Machine:
        if not hostname:
            raise ValidationError("hostname is required")
        now = utcnow()
        mid = machine_id or new_id("machine")
        labels_json = self._resolved_json_column("machines", "labels", mid, labels)
        resources_json = self._resolved_json_column("machines", "resources", mid, resources)
        # When the caller does not pass an explicit hardware snapshot, fall back to
        # resources["hardware"] (the field the worker places its detect_hardware()
        # result into).  This keeps machine.hardware in sync for callers that embed
        # the detected hardware inside the resources bag rather than as a top-level
        # parameter, without requiring a separate agent-registration step.
        resolved_hardware = hardware
        if resolved_hardware is None and isinstance(resources, dict):
            candidate = resources.get("hardware")
            if isinstance(candidate, dict):
                resolved_hardware = candidate
        hardware_json = self._resolved_json_column("machines", "hardware", mid, resolved_hardware)
        self.store.execute(
            """
            INSERT INTO machines (id, hostname, labels, resources, trusted, created_at, updated_at, last_seen_at, hardware)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(id) DO UPDATE SET
                hostname = excluded.hostname,
                labels = excluded.labels,
                resources = excluded.resources,
                trusted = excluded.trusted,
                updated_at = excluded.updated_at,
                last_seen_at = excluded.last_seen_at,
                hardware = excluded.hardware
            """,
            (
                mid,
                hostname,
                labels_json,
                resources_json,
                1 if trusted else 0,
                now,
                now,
                now,
                hardware_json,
            ),
        )
        return self.get_machine(mid)

    def get_machine(self, machine_id: str) -> Machine:
        row = self.store.query_one("SELECT * FROM machines WHERE id = ?", (machine_id,))
        if row is None:
            raise NotFoundError("machine not found: %s" % machine_id)
        return self._machine_from_row(row)

    def list_machines(self) -> List[Machine]:
        return [self._machine_from_row(row) for row in self.store.query_all("SELECT * FROM machines ORDER BY hostname")]

    # Fleets are user-facing collections of agents. They intentionally do not
    # own machines or tasks; those remain independent first-class objects.

    def create_fleet(
        self,
        name: str,
        description: str = "",
        *,
        status: str = "active",
        metadata: Optional[Dict[str, Any]] = None,
        tenant_id: Optional[str] = None,
        agent_ids: Optional[Iterable[str]] = None,
        fleet_id: Optional[str] = None,
        actor: str = "human",
    ) -> Fleet:
        fleet_name = str(name or "").strip()
        if not fleet_name:
            raise ValidationError("fleet name is required")
        if tenant_id:
            self.get_tenant(tenant_id)
        normalized_status = str(status or "active").strip().lower()
        if normalized_status not in {"active", "inactive", "retired"}:
            raise ValidationError("unsupported fleet status: %s" % normalized_status)
        members = self._validated_fleet_agent_ids(agent_ids or [])
        now = utcnow()
        metadata_value = ensure_json_object(metadata)
        if actor:
            metadata_value.setdefault("created_by", actor)
        fid = fleet_id or new_id("fleet")
        with self.store.transaction() as conn:
            try:
                conn.execute(
                    """
                    INSERT INTO fleets (
                        id, name, description, status, metadata, tenant_id, created_at, updated_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        fid,
                        fleet_name,
                        str(description or ""),
                        normalized_status,
                        json_dumps(metadata_value),
                        tenant_id,
                        now,
                        now,
                    ),
                )
            except Exception as exc:  # noqa: BLE001 - normalize sqlite uniqueness errors.
                if "UNIQUE" in str(exc).upper():
                    raise ValidationError("fleet already exists: %s" % fleet_name) from exc
                raise
            self._replace_fleet_members(conn, fid, members, now)
            self._record_fleet_event(
                conn,
                fid,
                "fleet.created",
                actor,
                {
                    "fleet_id": fid,
                    "fleet_name": fleet_name,
                    "status": normalized_status,
                    "tenant_id": tenant_id,
                    "agent_ids": members,
                    "agent_count": len(members),
                    "metadata_keys": sorted(metadata_value.keys()),
                },
                now,
            )
        self.record_notification(
            "fleet.created",
            "Fleet created: %s" % fleet_name,
            str(description or "Fleet %s was created." % fleet_name),
            subject_type="fleet",
            subject_id=fid,
            channels=["dashboard", "hermes"],
            metadata={"fleet": fleet_name, "actor": actor},
        )
        return self.get_fleet(fid)

    def get_fleet(self, fleet_id_or_name: str) -> Fleet:
        row = self.store.query_one(
            "SELECT * FROM fleets WHERE id = ? OR name = ?",
            (fleet_id_or_name, fleet_id_or_name),
        )
        if row is None:
            raise NotFoundError("fleet not found: %s" % fleet_id_or_name)
        return self._fleet_from_row(row)

    def list_fleets(
        self,
        *,
        status: Optional[str] = None,
        tenant_id: Optional[str] = None,
    ) -> List[Fleet]:
        clauses: List[str] = []
        params: List[Any] = []
        if status:
            clauses.append("status = ?")
            params.append(str(status).strip().lower())
        if tenant_id is not None:
            clauses.append("tenant_id = ?")
            params.append(tenant_id)
        where = (" WHERE " + " AND ".join(clauses)) if clauses else ""
        rows = self.store.query_all(
            "SELECT * FROM fleets%s ORDER BY name, id" % where,
            tuple(params),
        )
        return [self._fleet_from_row(row) for row in rows]

    def update_fleet(
        self,
        fleet_id_or_name: str,
        *,
        name: Optional[str] = None,
        description: Optional[str] = None,
        status: Optional[str] = None,
        metadata: Optional[Dict[str, Any]] = None,
        tenant_id: Optional[str] = None,
        agent_ids: Optional[Iterable[str]] = None,
        actor: str = "human",
    ) -> Fleet:
        fleet = self.get_fleet(fleet_id_or_name)
        updates: List[str] = []
        params: List[Any] = []
        changed_fields: List[str] = []
        new_name = fleet.name
        new_status = fleet.status
        new_tenant_id = fleet.tenant_id
        if name is not None:
            name_value = str(name or "").strip()
            if not name_value:
                raise ValidationError("fleet name is required")
            updates.append("name = ?")
            params.append(name_value)
            new_name = name_value
            if name_value != fleet.name:
                changed_fields.append("name")
        if description is not None:
            updates.append("description = ?")
            params.append(str(description or ""))
            if str(description or "") != fleet.description:
                changed_fields.append("description")
        if status is not None:
            status_value = str(status or "").strip().lower()
            if status_value not in {"active", "inactive", "retired"}:
                raise ValidationError("unsupported fleet status: %s" % status_value)
            updates.append("status = ?")
            params.append(status_value)
            new_status = status_value
            if status_value != fleet.status:
                changed_fields.append("status")
        if metadata is not None:
            updates.append("metadata = ?")
            params.append(json_dumps(ensure_json_object(metadata)))
            changed_fields.append("metadata")
        if tenant_id is not None:
            tenant_value = tenant_id.strip()
            if tenant_value:
                self.get_tenant(tenant_value)
                updates.append("tenant_id = ?")
                params.append(tenant_value)
                new_tenant_id = tenant_value
            else:
                updates.append("tenant_id = NULL")
                new_tenant_id = None
            if new_tenant_id != fleet.tenant_id:
                changed_fields.append("tenant_id")
        members = None
        if agent_ids is not None:
            members = self._validated_fleet_agent_ids(agent_ids)
            if members != fleet.agent_ids:
                changed_fields.append("agent_ids")
        if not updates and members is None:
            return fleet
        now = utcnow()
        with self.store.transaction() as conn:
            if updates:
                updates.append("updated_at = ?")
                params.append(now)
                params.append(fleet.id)
                try:
                    conn.execute(
                        "UPDATE fleets SET %s WHERE id = ?" % ", ".join(updates),
                        tuple(params),
                    )
                except Exception as exc:  # noqa: BLE001 - normalize sqlite uniqueness errors.
                    if "UNIQUE" in str(exc).upper():
                        raise ValidationError("fleet already exists: %s" % name) from exc
                    raise
            if members is not None:
                self._replace_fleet_members(conn, fleet.id, members, now)
                conn.execute("UPDATE fleets SET updated_at = ? WHERE id = ?", (now, fleet.id))
            next_members = members if members is not None else fleet.agent_ids
            previous_members = set(fleet.agent_ids)
            next_member_set = set(next_members)
            self._record_fleet_event(
                conn,
                fleet.id,
                "fleet.updated",
                actor,
                {
                    "fleet_id": fleet.id,
                    "fleet_name": new_name,
                    "previous_name": fleet.name,
                    "changed_fields": sorted(set(changed_fields)),
                    "previous_status": fleet.status,
                    "status": new_status,
                    "previous_tenant_id": fleet.tenant_id,
                    "tenant_id": new_tenant_id,
                    "agent_ids": next_members,
                    "added_agent_ids": sorted(next_member_set - previous_members),
                    "removed_agent_ids": sorted(previous_members - next_member_set),
                },
                now,
            )
        self.record_notification(
            "fleet.updated",
            "Fleet updated: %s" % new_name,
            "Fleet membership or metadata changed.",
            subject_type="fleet",
            subject_id=fleet.id,
            channels=["dashboard"],
            metadata={"actor": actor},
        )
        return self.get_fleet(fleet.id)

    def delete_fleet(self, fleet_id_or_name: str, *, actor: str = "human") -> None:
        fleet = self.get_fleet(fleet_id_or_name)
        now = utcnow()
        with self.store.transaction() as conn:
            self._record_fleet_event(
                conn,
                fleet.id,
                "fleet.deleted",
                actor,
                {
                    "fleet_id": fleet.id,
                    "fleet_name": fleet.name,
                    "status": fleet.status,
                    "tenant_id": fleet.tenant_id,
                    "agent_ids": fleet.agent_ids,
                    "agent_count": len(fleet.agent_ids),
                },
                now,
            )
            conn.execute("DELETE FROM fleets WHERE id = ?", (fleet.id,))

    def observe_fleet_agent(
        self,
        fleet_id_or_name: str,
        agent_id: str,
        *,
        source: str = "mac-agent",
        metadata: Optional[Dict[str, Any]] = None,
        actor: str = "mac-agent",
    ) -> Fleet:
        """Record live fleet presence without changing configured membership.

        ``fleet_agents`` is the desired/configured membership reconciled from
        deployment topology. Agent startup and heartbeat code should use this
        observation path so unmanaged runtime drift is visible but does not
        silently become canonical fleet topology.
        """
        fleet = self.get_fleet(fleet_id_or_name)
        self.get_agent(agent_id)
        now = utcnow()
        metadata_value = ensure_json_object(metadata)
        source_value = str(source or "runtime").strip() or "runtime"
        was_configured = agent_id in set(fleet.agent_ids)
        with self.store.transaction() as conn:
            conn.execute(
                """
                INSERT INTO fleet_agent_observations (
                    fleet_id, agent_id, source, metadata, first_seen_at, last_seen_at
                ) VALUES (?, ?, ?, ?, ?, ?)
                ON CONFLICT(fleet_id, agent_id) DO UPDATE SET
                    source = excluded.source,
                    metadata = excluded.metadata,
                    last_seen_at = excluded.last_seen_at
                """,
                (
                    fleet.id,
                    agent_id,
                    source_value,
                    json_dumps(metadata_value),
                    now,
                    now,
                ),
            )
            self._record_fleet_event(
                conn,
                fleet.id,
                "fleet.agent_observed",
                actor,
                {
                    "fleet_id": fleet.id,
                    "fleet_name": fleet.name,
                    "agent_id": agent_id,
                    "source": source_value,
                    "configured": was_configured,
                    "unmanaged": not was_configured,
                    "metadata_keys": sorted(metadata_value.keys()),
                },
                now,
            )
        return self.get_fleet(fleet.id)

    def _validated_fleet_agent_ids(self, agent_ids: Iterable[str]) -> List[str]:
        normalized = coerce_list(str(agent_id).strip() for agent_id in (agent_ids or []))
        for agent_id in normalized:
            self.get_agent(agent_id)
        return normalized

    def _replace_fleet_members(self, conn: Any, fleet_id: str, agent_ids: List[str], now: str) -> None:
        conn.execute("DELETE FROM fleet_agents WHERE fleet_id = ?", (fleet_id,))
        # Use execute() per row, not executemany(): executemany is not part of
        # the StoreConnection protocol — the Postgres _Transaction has no such
        # method (only SQLite's connection happens to). Member lists are small.
        for agent_id in agent_ids:
            conn.execute(
                "INSERT INTO fleet_agents (fleet_id, agent_id, created_at) VALUES (?, ?, ?)",
                (fleet_id, agent_id, now),
            )

    def _agent_id_for_registration_identity(
        self, name: str, capabilities: List[str]
    ) -> Optional[str]:
        rows = self.store.query_all(
            "SELECT id, capabilities FROM agents WHERE name = ? ORDER BY created_at, id",
            (name,),
        )
        for row in rows:
            if coerce_list(json_loads(row["capabilities"], [])) == capabilities:
                return row["id"]
        return None

    #: The only two answers. Anything else is a typo that would otherwise be
    #: stored and then silently treated as "not private".
    AGENT_VISIBILITIES = frozenset({"private", "shared"})

    def _resolve_agent_owner(self, owner_human_id: Any) -> Optional[str]:
        """A username or id -> the stable human id, or a refusal.

        Accepting a free-text owner would make the ownership gate compare two
        strings that were never the same principal, and the failure would show
        up as an agent nobody can dispatch to.
        """
        requested = str(owner_human_id or "").strip()
        if not requested:
            return None
        try:
            return self.get_human_by_username(requested).id
        except NotFoundError:
            pass
        try:
            return self.get_human(requested).id
        except NotFoundError:
            raise ValidationError(
                "no such human %r: an agent's owner must be a registered "
                "principal, not a free-text string" % requested
            ) from None

    def register_agent(
        self,
        machine_id: str,
        name: str,
        capabilities: Optional[Iterable[str]] = None,
        resources: Optional[Dict[str, Any]] = None,
        agent_id: Optional[str] = None,
        persona_instance_id: Optional[str] = None,
        hermes_instance_id: Optional[str] = None,
        actor: str = "human",
        status: Optional[str] = None,
        health_status: Optional[str] = None,
        instance_kind: Optional[str] = None,
        allow_resurrection: bool = False,
        owner_human_id: Optional[str] = None,
        visibility: Optional[str] = None,
    ) -> Agent:
        self.get_machine(machine_id)
        resolved_owner = self._resolve_agent_owner(owner_human_id)
        # PRIVATE is the safe default for a NEW owned agent, but it is a
        # COMMUNICATION default, not a capacity one: the hub does not talk to
        # anyone but the owner about it unless the owner grants permission.
        # Since 2026-08-17 it no longer restricts which tasks the agent may
        # claim -- see allocator._eligibility_rejections. The COLUMN defaults
        # to 'shared' so existing agents are untouched; this default governs
        # new registrations only.
        resolved_visibility = str(visibility or "").strip().lower() or (
            "private" if resolved_owner else "shared"
        )
        if resolved_visibility not in self.AGENT_VISIBILITIES:
            raise ValidationError(
                "agent visibility must be 'private' or 'shared', got %r"
                % resolved_visibility
            )
        if resolved_visibility == "private" and not resolved_owner:
            raise ValidationError(
                "a private agent needs an owner: without one nobody can use it, "
                "including the person who registered it"
            )
        if not name:
            raise ValidationError("agent name is required")
        # ``persona_instance_id`` is the runtime-neutral linkage name; accept
        # the deprecated ``hermes_instance_id`` keyword for one release. The
        # persisted ``agents`` column remains ``hermes_instance_id`` during the
        # migration boundary.
        if persona_instance_id is not None:
            hermes_instance_id = persona_instance_id
        if hermes_instance_id is not None:
            # Confirms the soul exists before binding. The identity layer
            # is what gates role assignment downstream.
            self.identity.get_persona_instance(hermes_instance_id)
        now = utcnow()
        aid = agent_id or new_id("agent")
        existing_agent_row = self.store.query_one(
            "SELECT id, status, health_status, instance_kind, deleted_at "
            "FROM agents WHERE id = ?",
            (aid,),
        )
        if capabilities is None:
            existing_caps = self.store.query_one(
                "SELECT capabilities FROM agents WHERE id = ?", (aid,)
            )
            capabilities_json = (
                existing_caps["capabilities"] if existing_caps is not None else json_dumps([])
            )
            capability_list = coerce_list(json_loads(capabilities_json, []))
        else:
            capability_list = coerce_list(capabilities)
            capabilities_json = json_dumps(capability_list)
        if existing_agent_row is None:
            existing_identity_agent_id = self._agent_id_for_registration_identity(
                name, capability_list
            )
            if existing_identity_agent_id is not None:
                aid = existing_identity_agent_id
                existing_agent_row = self.store.query_one(
                    "SELECT id, status, health_status, instance_kind, deleted_at "
                    "FROM agents WHERE id = ?",
                    (aid,),
                )
        if instance_kind is None:
            instance_kind_value = (
                str(existing_agent_row["instance_kind"])
                if existing_agent_row is not None
                else AgentInstanceKind.STATIC.value
            )
        else:
            instance_kind_value = _state_value(instance_kind).strip()
        try:
            AgentInstanceKind(instance_kind_value)
        except ValueError:
            raise ValidationError(
                "unsupported agent instance_kind: %s" % instance_kind_value
            )
        resource_value = self._agent_resources_with_preserved_control_plane_fields(aid, resources)
        resources_json = json_dumps(resource_value)
        registration_status = AgentStatus.IDLE.value
        registration_health = HealthStatus.HEALTHY.value
        requested_status = _state_value(status) if status is not None else None
        requested_health = (
            _state_value(health_status) if health_status is not None else None
        )
        if requested_status is not None:
            try:
                AgentStatus(requested_status)
            except ValueError:
                raise ValidationError(
                    "unsupported registration status: %s" % requested_status
                )
            if requested_status != AgentStatus.DRAINING.value:
                raise ValidationError(
                    "agent registration may only request the draining barrier state"
                )
        if requested_health is not None:
            try:
                HealthStatus(requested_health)
            except ValueError:
                raise ValidationError(
                    "unsupported registration health_status: %s" % requested_health
                )
            if requested_status != AgentStatus.DRAINING.value:
                raise ValidationError(
                    "registration health_status requires a draining barrier"
                )
        if requested_status == AgentStatus.DRAINING.value:
            registration_status = requested_status
            registration_health = requested_health or HealthStatus.DEGRADED.value
        # Re-registration is an identity/resource refresh, not authorization to
        # escape an operator/deployment drain. Preserve the fail-closed state
        # atomically until a later heartbeat explicitly clears it. An explicitly
        # authorized tombstone resurrection returns through the idle path.
        elif (
            existing_agent_row is not None
            and existing_agent_row["deleted_at"] is None
            and existing_agent_row["status"] == AgentStatus.DRAINING.value
        ):
            registration_status = AgentStatus.DRAINING.value
            registration_health = str(
                existing_agent_row["health_status"] or HealthStatus.DEGRADED.value
            )
        health_value = self._project_agent_health_for_resources(
            registration_health,
            registration_health,
            resource_value,
        ) or registration_health
        # Preserve hermes_instance_id across re-registrations when the caller
        # didn't pass one, so an ops re-register doesn't accidentally orphan
        # the agent from its soul.
        if hermes_instance_id is None:
            existing_soul = self.store.query_one(
                "SELECT hermes_instance_id FROM agents WHERE id = ?", (aid,)
            )
            hermes_instance_id = (
                existing_soul["hermes_instance_id"] if existing_soul is not None else None
            )
        # Attestation key. mac-ng2: every agent gets an HMAC-SHA256 key
        # at first registration. The cleartext key is returned ONCE in
        # the registration response so the operator can deploy it to
        # the worker; the ciphertext is stored under the same Fernet
        # used for secrets. Re-registrations preserve the existing key
        # — rotating it would invalidate all in-flight signed evidence.
        attestation_key_plaintext: Optional[str] = None
        existing_key_row = self.store.query_one(
            "SELECT attestation_key_ciphertext FROM agents WHERE id = ?", (aid,)
        )
        if existing_key_row is not None and existing_key_row["attestation_key_ciphertext"]:
            attestation_ciphertext = existing_key_row["attestation_key_ciphertext"]
        else:
            attestation_key_plaintext = _generate_attestation_key()
            attestation_ciphertext = self.secrets._encrypt(attestation_key_plaintext)
        event_type = "agent.reregistered" if existing_agent_row is not None else "agent.registered"
        with self.store.transaction() as conn:
            # Linearize self-reported resources with controller-owned fields.
            # A heartbeat/registration that read resources before an admin
            # revocation must observe the revocation after acquiring this row
            # lock and cannot resurrect either approval or projected marker.
            conn.execute(
                "UPDATE agents SET updated_at = updated_at WHERE id = ?",
                (aid,),
            )
            resource_value = self._agent_resources_with_preserved_control_plane_fields(
                aid, resources, conn=conn
            )
            resources_json = json_dumps(resource_value)
            health_value = self._project_agent_health_for_resources(
                registration_health,
                registration_health,
                resource_value,
            ) or registration_health
            registration_write = conn.execute(
                """
                INSERT INTO agents (
                    id, machine_id, name, instance_kind, capabilities, resources,
                    status, health_status,
                    current_task_id, created_at, updated_at, last_seen_at,
                    hermes_instance_id, attestation_key_ciphertext,
                    owner_human_id, visibility
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(id) DO UPDATE SET
                    machine_id = excluded.machine_id,
                    name = excluded.name,
                    instance_kind = excluded.instance_kind,
                    capabilities = excluded.capabilities,
                    resources = excluded.resources,
                    status = CASE
                        WHEN excluded.status = 'draining' THEN excluded.status
                        WHEN agents.deleted_at IS NULL AND agents.status = 'draining'
                            THEN agents.status
                        ELSE excluded.status
                    END,
                    health_status = CASE
                        WHEN excluded.status = 'draining' THEN excluded.health_status
                        WHEN agents.deleted_at IS NULL AND agents.status = 'draining'
                            THEN agents.health_status
                        ELSE excluded.health_status
                    END,
                    updated_at = excluded.updated_at,
                    last_seen_at = excluded.last_seen_at,
                    hermes_instance_id = excluded.hermes_instance_id,
                    attestation_key_ciphertext = excluded.attestation_key_ciphertext,
                    -- An administratively-authorized resurrection means the
                    -- identity is back (e.g. a recreated pod re-deploying), so
                    -- clear the tombstone and the decommission dispatch hold.
                    -- `agents.*` is the pre-update row, so non-deleted agents keep
                    -- any operator-set hold; only a decommissioned one is cleared.
                    deleted_at = NULL,
                    dispatch_hold = CASE WHEN agents.deleted_at IS NOT NULL THEN 0 ELSE agents.dispatch_hold END,
                    dispatch_hold_reason = CASE WHEN agents.deleted_at IS NOT NULL THEN NULL ELSE agents.dispatch_hold_reason END,
                    dispatch_hold_at = CASE WHEN agents.deleted_at IS NOT NULL THEN NULL ELSE agents.dispatch_hold_at END
                WHERE agents.deleted_at IS NULL OR ? = 1
                """,
                (
                    aid,
                    machine_id,
                    name,
                    instance_kind_value,
                    capabilities_json,
                    resources_json,
                    registration_status,
                    health_value,
                    now,
                    now,
                    now,
                    hermes_instance_id,
                    attestation_ciphertext,
                    resolved_owner,
                    resolved_visibility,
                    int(bool(allow_resurrection)),
                ),
            )
            if registration_write.rowcount != 1:
                raise AuthorizationError(
                    "agent resurrection requires administrative authority"
                )
            self._record_agent_lifecycle_event(
                conn,
                aid,
                event_type,
                actor,
                {
                    "agent_id": aid,
                    "agent_name": name,
                    "machine_id": machine_id,
                    "instance_kind": instance_kind_value,
                    "capabilities": json_loads(capabilities_json, []),
                    "resource_keys": sorted(ensure_json_object(json_loads(resources_json, {})).keys()),
                    "status": registration_status,
                    "health_status": health_value,
                    "hermes_instance_id": hermes_instance_id,
                },
                now,
            )
            self._mirror_agent_reported_hardware_to_machine(
                conn, machine_id, resource_value, now
            )
        agent = self.get_agent(aid)
        self._ensure_agent_nap_schedule(agent.id, actor=actor)
        agent = self.get_agent(aid)
        # Stash the cleartext key on the returned agent so the API layer
        # can surface it to the caller on first registration. The Agent
        # dataclass itself never persists this — it's an attribute set
        # only on the in-memory object returned from this call.
        if attestation_key_plaintext is not None:
            agent.attestation_key = attestation_key_plaintext  # type: ignore[attr-defined]
        return agent

    def _agent_attestation_key(self, agent_id: str) -> Optional[str]:
        """Decrypted HMAC key for an agent, or None if the row predates
        the attestation-key column."""
        row = self.store.query_one(
            "SELECT attestation_key_ciphertext FROM agents WHERE id = ?", (agent_id,)
        )
        if row is None or not row["attestation_key_ciphertext"]:
            return None
        try:
            return self.secrets._decrypt(row["attestation_key_ciphertext"])
        except Exception:  # noqa: BLE001 - corrupt or rotated key shouldn't crash review
            return None

    def _agent_attestation_prev_key(self, agent_id: str) -> Optional[str]:
        """Decrypted HMAC key that was active BEFORE the most recent rotation,
        or None if the agent has never rotated (or the column predates it).

        Used to verify a verdict signed under the prior key before a routine
        rotation, so a re-key does not invalidate already-signed evidence
        (mac-s2vz followup)."""
        row = self.store.query_one(
            "SELECT attestation_key_prev_ciphertext FROM agents WHERE id = ?",
            (agent_id,),
        )
        if row is None or not row["attestation_key_prev_ciphertext"]:
            return None
        try:
            return self.secrets._decrypt(row["attestation_key_prev_ciphertext"])
        except Exception:  # noqa: BLE001 - a corrupt prev key shouldn't crash review
            return None

    ATTESTATION_KEY_HISTORY_LIMIT = 5

    def _agent_attestation_history_keys(self, agent_id: str) -> List[str]:
        """Decrypted attestation keys retired before the immediate previous one.

        A fleet release rotates every participating agent at once
        (fleet_release_epoch_service). With only ``prev`` retained, two
        releases put in-flight review evidence permanently out of reach and the
        task parks in waiting_for_verifiable_evidence with no diagnosis --
        observed live 2026-07-30, when one release orphaned 66 tasks.
        """

        row = self.store.query_one(
            "SELECT attestation_key_history_ciphertext FROM agents WHERE id = ?",
            (agent_id,),
        )
        if row is None:
            return []
        try:
            raw = row["attestation_key_history_ciphertext"]
        except (KeyError, IndexError):  # column predates this build
            return []
        if not raw:
            return []
        keys: List[str] = []
        for item in json_loads(raw, []) or []:
            if not isinstance(item, Mapping):
                continue
            ciphertext = item.get("ciphertext")
            if not ciphertext:
                continue
            try:
                keys.append(self.secrets._decrypt(str(ciphertext)))
            except Exception:  # noqa: BLE001 - one corrupt entry must not hide the rest
                continue
        return keys

    def _attestation_history_after_rotation(
        self, agent_id: str, *, rotated_at: str, conn: Any = None
    ) -> str:
        """Push the outgoing key onto a bounded, timestamped key history."""

        reader = conn if conn is not None else self.store
        row = reader.execute(
            "SELECT attestation_key_ciphertext, attestation_key_history_ciphertext "
            "FROM agents WHERE id = ?",
            (agent_id,),
        ).fetchone()
        outgoing = None
        history = []
        if row is not None:
            try:
                outgoing = row["attestation_key_ciphertext"]
            except (KeyError, IndexError):
                outgoing = None
            try:
                history = list(json_loads(row["attestation_key_history_ciphertext"], []) or [])
            except (KeyError, IndexError):
                history = []
        if outgoing:
            history.insert(0, {"ciphertext": outgoing, "rotated_at": rotated_at})
        return json_dumps(history[: self.ATTESTATION_KEY_HISTORY_LIMIT])

    def _verify_manifest_against_retained_keys(
        self,
        signed_by: str,
        manifest: Mapping[str, Any],
        signature: str,
    ) -> bool:
        """Try every retained generation for this signer.

        Only keys this hub already holds for that agent are tried, so this
        widens how long a signature stays verifiable without widening who is
        allowed to sign.
        """

        prev_key = self._agent_attestation_prev_key(signed_by)
        candidates = [prev_key] if prev_key is not None else []
        candidates.extend(self._agent_attestation_history_keys(signed_by))
        for candidate in candidates:
            if verify_verification_manifest_signature(candidate, manifest, signature):
                return True
        return False

    def rotate_agent_attestation_key(self, agent_id: str) -> str:
        """Rotate and return the cleartext HMAC key for one agent.

        Registration returns the first key exactly once. This explicit
        recovery path is for deploy/bootstrap cases where the host-local
        environment lost that one-time value before the worker could sign
        evidence. It intentionally rotates instead of exporting the old
        secret; in-flight signatures from the previous key will no longer
        verify — and the rotation timestamp is recorded so the verifier
        can produce a clearer "key was rotated" error for pending
        verdicts signed under the previous key (mac-s2vz).
        """
        key = _generate_attestation_key()
        now = utcnow()
        # Retain the current key as the previous key BEFORE overwriting it, so
        # verdicts signed under it prior to this rotation can still be verified
        # against the key that was active at signing time (mac-s2vz followup).
        with self.store.transaction() as conn:
            locked = conn.execute(
                "UPDATE agents SET updated_at = updated_at "
                "WHERE id = ? AND deleted_at IS NULL",
                (agent_id,),
            )
            if locked.rowcount != 1:
                raise NotFoundError("agent not found: %s" % agent_id)
            self.fleet_release_epochs.assert_agent_unreserved_in_transaction(
                conn, agent_id
            )
            conn.execute(
                """
                UPDATE agents
                SET attestation_key_prev_ciphertext = attestation_key_ciphertext,
                    attestation_key_history_ciphertext = ?,
                    attestation_key_ciphertext = ?,
                    attestation_key_rotated_at = ?,
                    updated_at = ?
                WHERE id = ?
                """,
                (
                    self._attestation_history_after_rotation(
                        agent_id, rotated_at=now, conn=conn
                    ),
                    self.secrets._encrypt(key),
                    now,
                    now,
                    agent_id,
                ),
            )
        return key

    def verify_agent_attestation_challenge(
        self,
        agent_id: str,
        challenge: JsonDict,
        signature: str,
    ) -> bool:
        self.get_agent(agent_id)
        if not isinstance(challenge, dict):
            return False
        key = self._agent_attestation_key(agent_id)
        if key is None:
            return False
        return verify_verification_manifest_signature(key, challenge, signature)

    @staticmethod
    def _validated_deployment_attestation_probe(
        agent_id: str, probe: Mapping[str, Any]
    ) -> tuple[str, str, Dict[str, Any], str]:
        """Validate the secret-free, deployment-owner key probe.

        The probe does not authorize recovery by itself: the API route is
        admin-only and the fleet deployer additionally holds the target's
        fenced deployment lock.  Its purpose is to make the recovery decision
        explicit and auditable while ensuring a valid installed key is never
        rotated merely because a deploy was rerun.
        """

        expected_keys = {
            "schema",
            "state",
            "agent_id",
            "deployment_id",
            "challenge",
            "signature",
        }
        if not isinstance(probe, Mapping) or set(probe) != expected_keys:
            raise ValidationError("attestation-key recovery probe is malformed")
        if probe.get("schema") != "mac.agent_attestation_key_probe.v1":
            raise ValidationError("attestation-key recovery probe schema is unsupported")
        if probe.get("agent_id") != agent_id:
            raise ValidationError("attestation-key recovery probe agent does not match")
        deployment_id = str(probe.get("deployment_id") or "").strip()
        if not deployment_id:
            raise ValidationError("attestation-key recovery probe lacks deployment id")
        state = str(probe.get("state") or "").strip()
        challenge = probe.get("challenge")
        signature = str(probe.get("signature") or "")
        if state == "missing":
            if challenge != {} or signature:
                raise ValidationError("missing-key probe must not carry a signature")
            return state, deployment_id, {}, ""
        if state != "present" or not isinstance(challenge, dict):
            raise ValidationError("attestation-key recovery probe state is unsupported")
        if set(challenge) != {
            "schema",
            "purpose",
            "agent_id",
            "deployment_id",
            "nonce",
        }:
            raise ValidationError("attestation-key recovery challenge is malformed")
        if (
            challenge.get("schema") != "mac.agent_attestation_challenge.v1"
            or challenge.get("purpose") != "fleet-deploy-attestation-key-proof"
            or challenge.get("agent_id") != agent_id
            or challenge.get("deployment_id") != deployment_id
            or len(str(challenge.get("nonce") or "")) < 32
            or not signature.startswith("v1:")
        ):
            raise ValidationError("attestation-key recovery challenge is invalid")
        return state, deployment_id, challenge, signature

    def recover_agent_attestation_key(
        self, agent_id: str, probe: Mapping[str, Any]
    ) -> str:
        """Rotate only when the deployment-owned probe is missing or stale.

        This is the deployment recovery primitive.  Unlike the historical
        worker-side ``--rotate-missing``/``--rotate-invalid`` path, it runs
        under administrator authority and linearizes the probe decision with
        the key rotation.  A valid installed key fails closed without change.
        """

        state, deployment_id, challenge, signature = (
            self._validated_deployment_attestation_probe(agent_id, probe)
        )
        now = utcnow()
        with self.store.transaction() as conn:
            locked = conn.execute(
                "UPDATE agents SET updated_at = updated_at "
                "WHERE id = ? AND deleted_at IS NULL",
                (agent_id,),
            )
            if locked.rowcount != 1:
                raise NotFoundError("agent not found: %s" % agent_id)
            self.fleet_release_epochs.assert_agent_unreserved_in_transaction(
                conn, agent_id
            )
            row = conn.execute(
                "SELECT attestation_key_ciphertext FROM agents WHERE id = ?",
                (agent_id,),
            ).fetchone()
            current_key: Optional[str] = None
            if row is not None and row["attestation_key_ciphertext"]:
                try:
                    current_key = self.secrets._decrypt(
                        row["attestation_key_ciphertext"]
                    )
                except Exception:  # noqa: BLE001 - corrupt authority is stale.
                    current_key = None
            if (
                state == "present"
                and current_key is not None
                and verify_verification_manifest_signature(
                    current_key, challenge, signature
                )
            ):
                raise ValidationError(
                    "attestation key is already valid; recovery rotation refused"
                )
            key = _generate_attestation_key()
            conn.execute(
                """
                UPDATE agents
                SET attestation_key_prev_ciphertext = attestation_key_ciphertext,
                    attestation_key_history_ciphertext = ?,
                    attestation_key_ciphertext = ?,
                    attestation_key_rotated_at = ?,
                    updated_at = ?
                WHERE id = ?
                """,
                (
                    self._attestation_history_after_rotation(
                        agent_id, rotated_at=now, conn=conn
                    ),
                    self.secrets._encrypt(key),
                    now,
                    now,
                    agent_id,
                ),
            )
            self._record_agent_lifecycle_event(
                conn,
                agent_id,
                "agent.attestation_key.recovered",
                "fleet-deploy",
                {
                    "agent_id": agent_id,
                    "deployment_id": deployment_id,
                    "probe_state": state,
                    "reason": "missing" if state == "missing" else "stale",
                },
                now,
            )
        return key

    @staticmethod
    def _report_executor_startup_proof_matches(
        agent_id: str,
        resources: Mapping[str, Any],
        expected_attestation: Mapping[str, Any],
        expected_startup_timestamp: str,
    ) -> bool:
        startup = resources.get("startup_self_test")
        checks = startup.get("checks") if isinstance(startup, Mapping) else None
        return bool(
            isinstance(startup, Mapping)
            # Shared with the allocator's advisory gate: one definition of
            # "this self-test clears the agent", so the two cannot drift again.
            and startup_self_test_clears_dispatch(startup, agent_id=agent_id)
            and startup.get("timestamp") == expected_startup_timestamp
            and isinstance(checks, Mapping)
            and checks.get("openshell_executor_config") is True
            and checks.get("report_repository_executor_attestation") is True
            and startup.get("report_repository_executor_attestation")
            == expected_attestation
        )

    @classmethod
    def _report_executor_release_ready(
        cls, agent_id: str, resources: Mapping[str, Any]
    ) -> bool:
        attestation = resources.get(REPORT_REPOSITORY_EXECUTOR_ATTESTATION_KEY)
        startup = resources.get("startup_self_test")
        timestamp = (
            str(startup.get("timestamp") or "")
            if isinstance(startup, Mapping)
            else ""
        )
        return bool(
            agent_has_read_only_report_repository_executor(resources)
            and valid_read_only_report_repository_executor_attestation(attestation)
            and timestamp
            and cls._report_executor_startup_proof_matches(
                agent_id, resources, attestation, timestamp
            )
        )

    def approve_agent_report_repository_executor(
        self,
        agent_id: str,
        expected_attestation: Mapping[str, Any],
        expected_startup_timestamp: str,
        *,
        actor: str = "fleet-deploy",
    ) -> Agent:
        """CAS-install approval for the exact current worker/startup proof.

        Workers can publish an attestation, but only an administrator-driven
        deployment may create this approval.  The derived dispatch marker is
        projected in the same transaction and disappears automatically if a
        later heartbeat reports different artifacts.
        """

        if not valid_read_only_report_repository_executor_attestation(
            expected_attestation
        ):
            raise ValidationError("report executor attestation is malformed")
        timestamp = str(expected_startup_timestamp or "").strip()
        if not timestamp:
            raise ValidationError("report executor startup timestamp is required")
        now = utcnow()
        with self.store.transaction() as conn:
            locked = conn.execute(
                "UPDATE agents SET updated_at = updated_at "
                "WHERE id = ? AND deleted_at IS NULL",
                (agent_id,),
            )
            if locked.rowcount != 1:
                raise NotFoundError("agent not found: %s" % agent_id)
            self.fleet_release_epochs.assert_agent_unreserved_in_transaction(
                conn, agent_id
            )
            row = conn.execute(
                "SELECT resources FROM agents WHERE id = ?", (agent_id,)
            ).fetchone()
            resources = ensure_json_object(json_loads(row["resources"], {}))
            current_attestation = resources.get(
                REPORT_REPOSITORY_EXECUTOR_ATTESTATION_KEY
            )
            if current_attestation != expected_attestation:
                raise ValidationError(
                    "report executor attestation changed before controller approval"
                )
            if resources.get(
                "openshell_required"
            ) is not True and not report_repository_executor_attestation_is_host_install(
                expected_attestation
            ):
                raise ValidationError("report executor requires OpenShell policy")
            if not self._report_executor_startup_proof_matches(
                agent_id, resources, expected_attestation, timestamp
            ):
                raise ValidationError(
                    "report executor startup proof does not match current attestation"
                )
            approval = read_only_report_repository_executor_approval(
                runtime_image_ref=str(expected_attestation["runtime_image_ref"]),
                policy_sha256=str(expected_attestation["policy_sha256"]),
                openshell_bin_path=str(expected_attestation["openshell_bin_path"]),
                openshell_bin_sha256=str(
                    expected_attestation["openshell_bin_sha256"]
                ),
                executor_path=str(expected_attestation["executor_path"]),
                executor_sha256=str(expected_attestation["executor_sha256"]),
                platform=str(expected_attestation["platform"]),
                isolation_posture=str(expected_attestation["isolation_posture"]),
                python_path=str(expected_attestation["python_path"]),
                python_sha256=str(expected_attestation["python_sha256"]),
                executor_script_path=str(
                    expected_attestation["executor_script_path"]
                ),
                executor_script_sha256=str(
                    expected_attestation["executor_script_sha256"]
                ),
                source_root=str(expected_attestation["source_root"]),
                source_bundle_sha256=str(
                    expected_attestation["source_bundle_sha256"]
                ),
            )
            resources[REPORT_REPOSITORY_EXECUTOR_APPROVAL_KEY] = approval
            resources = self._project_report_repository_executor_marker(resources)
            if not agent_has_read_only_report_repository_executor(resources):
                raise ValidationError(
                    "report executor controller marker was not derived"
                )
            conn.execute(
                "UPDATE agents SET resources = ?, updated_at = ? WHERE id = ?",
                (json_dumps(resources), now, agent_id),
            )
            self._record_agent_lifecycle_event(
                conn,
                agent_id,
                "agent.report_repository_executor.approved",
                str(actor or "fleet-deploy"),
                {
                    "agent_id": agent_id,
                    "startup_timestamp": timestamp,
                    "runtime_image_ref": expected_attestation["runtime_image_ref"],
                    "policy_sha256": expected_attestation["policy_sha256"],
                    "source_bundle_sha256": expected_attestation[
                        "source_bundle_sha256"
                    ],
                },
                now,
            )
        return self.get_agent(agent_id)

    def revoke_agent_report_repository_executor(
        self,
        agent_id: str,
        reason: str,
        *,
        actor: str = "fleet-deploy",
    ) -> Agent:
        reason_value = str(reason or "").strip()
        if not reason_value:
            raise ValidationError("report executor revocation reason is required")
        now = utcnow()
        with self.store.transaction() as conn:
            locked = conn.execute(
                "UPDATE agents SET updated_at = updated_at "
                "WHERE id = ? AND deleted_at IS NULL",
                (agent_id,),
            )
            if locked.rowcount != 1:
                raise NotFoundError("agent not found: %s" % agent_id)
            self.fleet_release_epochs.assert_agent_unreserved_in_transaction(
                conn, agent_id
            )
            row = conn.execute(
                "SELECT resources FROM agents WHERE id = ?", (agent_id,)
            ).fetchone()
            resources = ensure_json_object(json_loads(row["resources"], {}))
            resources.pop(REPORT_REPOSITORY_EXECUTOR_APPROVAL_KEY, None)
            resources.pop(REPORT_REPOSITORY_EXECUTOR_RESOURCE_KEY, None)
            conn.execute(
                "UPDATE agents SET resources = ?, updated_at = ? WHERE id = ?",
                (json_dumps(resources), now, agent_id),
            )
            self._record_agent_lifecycle_event(
                conn,
                agent_id,
                "agent.report_repository_executor.revoked",
                str(actor or "fleet-deploy"),
                {"agent_id": agent_id, "reason": reason_value},
                now,
            )
        return self.get_agent(agent_id)

    def get_agent(self, agent_id: str) -> Agent:
        row = self.store.query_one("SELECT * FROM agents WHERE id = ?", (agent_id,))
        if row is None:
            raise NotFoundError("agent not found: %s" % agent_id)
        return self._agent_from_row(row)

    # -- curiosity quarantine (hub-mediated) -------------------------------
    #
    # The ledger lives inside the mac-openclaw-<agent> sandbox and a dispatched
    # task runs in a different mac-task-* sandbox that cannot reach it, so
    # adjudication was impossible from the one place it needed to happen
    # (task_3a4503f0). One implementation here serves both transports: the
    # local CLI on the host, and the hub API for every sandboxed caller.

    def _curiosity(self) -> Any:
        service = getattr(self, "_curiosity_service", None)
        if service is None:
            from mac.curiosity_service import CuriosityService

            service = CuriosityService()
            self._curiosity_service = service
        return service

    def _curiosity_call(self, operation: Any) -> Dict[str, Any]:
        """Translate curiosity failures into the domain errors callers expect.

        The service layer speaks ValueError / RuntimeError because it is also
        usable outside the control plane, but every public ControlPlane method
        must raise a domain error (tests/test_control_plane_public_contract.py).
        """
        from mac.curiosity_service import (
            CuriosityCommandError,
            CuriosityUnavailable,
        )

        try:
            return operation()
        except ValueError as exc:
            raise ValidationError(str(exc)) from exc
        except CuriosityUnavailable as exc:
            # A host with no OpenClaw gateway has no ledger. That is a fact
            # about the host, not a transient fault to retry.
            raise NotFoundError(str(exc)) from exc
        except CuriosityCommandError as exc:
            raise ValidationError(str(exc)) from exc

    def list_curiosity_candidates(
        self, status: Optional[str] = None
    ) -> Dict[str, Any]:
        """Quarantined/approved/rejected curiosity candidates for this host."""
        return self._curiosity_call(
            lambda: self._curiosity().list_candidates(status)
        )

    def decide_curiosity_candidate(
        self,
        candidate_id: str,
        decision: str,
        *,
        actor: str,
        reason: str,
        approval_id: str,
    ) -> Dict[str, Any]:
        """Approve or reject one candidate, recording the external judgment."""
        return self._curiosity_call(
            lambda: self._curiosity().decide(
                decision,
                candidate_id,
                actor=actor,
                reason=reason,
                approval_id=approval_id,
            )
        )

    def list_agents(self, *, include_deleted: bool = False) -> List[Agent]:
        sql = "SELECT * FROM agents"
        if not include_deleted:
            sql += " WHERE deleted_at IS NULL"
        sql += " ORDER BY name, id"
        rows = self.store.query_all(sql)
        return [self._agent_from_row(row) for row in rows]

    def update_agent(
        self,
        agent_id: str,
        *,
        name: Optional[str] = None,
        capabilities: Optional[Iterable[str]] = None,
        resources: Optional[Dict[str, Any]] = None,
        status: Optional[str] = None,
        health_status: Optional[str] = None,
        persona_instance_id: Optional[str] = None,
        hermes_instance_id: Optional[str] = None,
        instance_kind: Optional[str] = None,
        owner_human_id: Optional[str] = None,
        visibility: Optional[str] = None,
        actor: str = "human",
    ) -> Agent:
        # ``persona_instance_id`` is the runtime-neutral linkage name; accept the
        # deprecated ``hermes_instance_id`` keyword for one release.
        if persona_instance_id is not None:
            hermes_instance_id = persona_instance_id
        agent_before = self.get_agent(agent_id)
        updates: List[str] = []
        params: List[Any] = []
        changed_fields: List[str] = []
        next_name = agent_before.name
        next_status = agent_before.status
        next_health_status = agent_before.health_status
        next_hermes_instance_id = agent_before.persona_instance_id
        next_instance_kind = agent_before.instance_kind
        requested_resource_value: Optional[Dict[str, Any]] = None
        resource_param_index: Optional[int] = None
        if name is not None:
            name_value = name.strip()
            if not name_value:
                raise ValidationError("agent name is required")
            updates.append("name = ?")
            params.append(name_value)
            next_name = name_value
            if name_value != agent_before.name:
                changed_fields.append("name")
        if capabilities is not None:
            capability_list = coerce_list(capabilities)
            updates.append("capabilities = ?")
            params.append(json_dumps(capability_list))
            if capability_list != agent_before.capabilities:
                changed_fields.append("capabilities")
        if resources is not None:
            requested_resource_value = ensure_json_object(resources)
            approval = requested_resource_value.get(
                REPORT_REPOSITORY_EXECUTOR_APPROVAL_KEY
            )
            if approval is not None and not (
                valid_read_only_report_repository_executor_approval(approval)
            ):
                raise ValidationError(
                    "report_repository_executor_approval is malformed"
                )
            # Final approval preservation/revocation and marker projection are
            # repeated under the agent row lock below. This preliminary value
            # exists only for changed-field reporting.
            resource_value = self._admin_project_agent_resources(
                agent_before.resources, requested_resource_value
            )
            updates.append("resources = ?")
            resource_param_index = len(params)
            params.append(json_dumps(resource_value))
            if resource_value != agent_before.resources:
                changed_fields.append("resources")
        if status is not None:
            status_value = _state_value(status)
            try:
                AgentStatus(status_value)
            except ValueError:
                raise ValidationError("unsupported agent status: %s" % status_value)
            if status_value == AgentStatus.IDLE.value and self._agent_has_active_lease(agent_id):
                raise ValidationError("agent cannot be set idle while holding an active lease")
            if status_value == AgentStatus.OFFLINE.value:
                self._expire_agent_active_leases(agent_id, utcnow(), "agent_update_offline")
            updates.append("status = ?")
            params.append(status_value)
            next_status = status_value
            if status_value != agent_before.status:
                changed_fields.append("status")
            if status_value in {AgentStatus.IDLE.value, AgentStatus.OFFLINE.value}:
                updates.append("current_task_id = NULL")
        if health_status is not None:
            health_value = _state_value(health_status)
            try:
                HealthStatus(health_value)
            except ValueError:
                raise ValidationError("unsupported agent health_status: %s" % health_value)
            updates.append("health_status = ?")
            params.append(health_value)
            next_health_status = health_value
            if health_value != agent_before.health_status:
                changed_fields.append("health_status")
        if hermes_instance_id is not None:
            hermes_value = hermes_instance_id.strip()
            if hermes_value:
                self.identity.get_persona_instance(hermes_value)
                updates.append("hermes_instance_id = ?")
                params.append(hermes_value)
                next_hermes_instance_id = hermes_value
            else:
                updates.append("hermes_instance_id = NULL")
                next_hermes_instance_id = None
            if next_hermes_instance_id != agent_before.persona_instance_id:
                changed_fields.append("hermes_instance_id")
        if instance_kind is not None:
            instance_kind_value = _state_value(instance_kind).strip()
            try:
                AgentInstanceKind(instance_kind_value)
            except ValueError:
                raise ValidationError(
                    "unsupported agent instance_kind: %s" % instance_kind_value
                )
            updates.append("instance_kind = ?")
            params.append(instance_kind_value)
            next_instance_kind = instance_kind_value
            if instance_kind_value != agent_before.instance_kind:
                changed_fields.append("instance_kind")
        # Ownership is changeable after registration on purpose. Hardware is
        # handed over, people leave, and a fleet that could only set an owner
        # at registration would force a re-register -- which loses the agent's
        # history -- to correct one field.
        next_owner = agent_before.owner_human_id
        next_visibility = agent_before.visibility
        if owner_human_id is not None:
            owner_value = str(owner_human_id).strip()
            if owner_value:
                owner_value = self._resolve_agent_owner(owner_value)
                updates.append("owner_human_id = ?")
                params.append(owner_value)
                next_owner = owner_value
            else:
                updates.append("owner_human_id = NULL")
                next_owner = None
            if next_owner != agent_before.owner_human_id:
                changed_fields.append("owner_human_id")
        if visibility is not None:
            visibility_value = _state_value(visibility).strip().lower()
            if visibility_value not in self.AGENT_VISIBILITIES:
                raise ValidationError(
                    "unsupported agent visibility: %s (expected one of %s)"
                    % (visibility_value, ", ".join(sorted(self.AGENT_VISIBILITIES)))
                )
            # Refused rather than silently shared: a private agent with no
            # owner matches no filer, so it would quietly become capacity for
            # nobody and its work would sit undispatched with no explanation.
            if visibility_value == "private" and not next_owner:
                raise ValidationError(
                    "an agent cannot be private without an owner; "
                    "pass --owner as well"
                )
            updates.append("visibility = ?")
            params.append(visibility_value)
            next_visibility = visibility_value
            if visibility_value != agent_before.visibility:
                changed_fields.append("visibility")
        if not updates:
            return self.get_agent(agent_id)
        updates.append("updated_at = ?")
        now = utcnow()
        params.append(now)
        params.append(agent_id)
        with self.store.transaction() as conn:
            if requested_resource_value is not None and resource_param_index is not None:
                conn.execute(
                    "UPDATE agents SET updated_at = updated_at WHERE id = ?",
                    (agent_id,),
                )
                row = conn.execute(
                    "SELECT resources FROM agents WHERE id = ?", (agent_id,)
                ).fetchone()
                current_resources = ensure_json_object(
                    json_loads(row["resources"], {}) if row is not None else {}
                )
                resource_value = self._admin_project_agent_resources(
                    current_resources, requested_resource_value
                )
                params[resource_param_index] = json_dumps(resource_value)
            conn.execute(
                "UPDATE agents SET %s WHERE id = ?" % ", ".join(updates),
                tuple(params),
            )
            self._record_agent_lifecycle_event(
                conn,
                agent_id,
                "agent.updated",
                actor,
                {
                    "agent_id": agent_id,
                    "agent_name": next_name,
                    "previous_name": agent_before.name,
                    "changed_fields": sorted(set(changed_fields)),
                    "previous_status": agent_before.status,
                    "status": next_status,
                    "previous_health_status": agent_before.health_status,
                    "health_status": next_health_status,
                    "previous_hermes_instance_id": agent_before.persona_instance_id,
                    "hermes_instance_id": next_hermes_instance_id,
                    "previous_instance_kind": agent_before.instance_kind,
                    "instance_kind": next_instance_kind,
                    "previous_owner_human_id": agent_before.owner_human_id,
                    "owner_human_id": next_owner,
                    "previous_visibility": agent_before.visibility,
                    "visibility": next_visibility,
                },
                now,
            )
        return self.get_agent(agent_id)

    def update_agent_installed_packages(
        self,
        agent_id: str,
        installed_packages: Dict[str, Any],
        *,
        actor: str = "agent",
    ) -> Agent:
        """Record the agent's self-installed pip/npm footprint (its persistent
        "default footprint"). Kept separate from update_agent so a footprint
        report can't clobber capabilities/status. Re-registration preserves it
        (the register UPSERT does not touch this column)."""
        agent_before = self.get_agent(agent_id)
        payload = ensure_json_object(installed_packages)
        now = utcnow()
        pip = payload.get("pip")
        npm = payload.get("npm")
        with self.store.transaction() as conn:
            conn.execute(
                "UPDATE agents SET installed_packages = ?, updated_at = ? WHERE id = ?",
                (json_dumps(payload), now, agent_id),
            )
            self._record_agent_lifecycle_event(
                conn,
                agent_id,
                "agent.installed_packages_updated",
                actor,
                {
                    "agent_id": agent_id,
                    "agent_name": agent_before.name,
                    "pip_count": len(pip) if isinstance(pip, list) else 0,
                    "npm_count": len(npm) if isinstance(npm, list) else 0,
                },
                now,
            )
        return self.get_agent(agent_id)

    def disable_agent(self, agent_id: str, *, actor: str = "human") -> Agent:
        return self.update_agent(
            agent_id,
            status=AgentStatus.OFFLINE.value,
            health_status=HealthStatus.DEGRADED.value,
            actor=actor,
        )

    @staticmethod
    def _withdraw_service_claims_for_dispatch_hold(
        conn: Any, agent_id: str, now: str
    ) -> None:
        """Make the dispatch hold and service-routing fence one transaction."""

        conn.execute(
            "UPDATE service_claims SET status = ?, updated_at = ? "
            "WHERE agent_id = ? AND status = ?",
            (
                ServiceClaimStatus.RELEASED.value,
                now,
                agent_id,
                ServiceClaimStatus.ACTIVE.value,
            ),
        )

    def set_agent_dispatch_hold(self, agent_id: str, reason: str) -> "Agent":
        """Place a dispatch hold on an agent; held agents are skipped during claim-next.

        The hold is a pure DB update — the agent need not be reachable or online.
        """
        reason = str(reason or "").strip()
        if not reason:
            raise ValidationError("dispatch hold reason is required")
        self.get_agent(agent_id)  # raises NotFoundError if absent
        now = utcnow()
        with self.store.transaction() as conn:
            conn.execute(
                "UPDATE agents SET dispatch_hold = 1, dispatch_hold_reason = ?, dispatch_hold_at = ?, updated_at = ? WHERE id = ?",
                (reason, now, now, agent_id),
            )
            self._withdraw_service_claims_for_dispatch_hold(conn, agent_id, now)
        return self.get_agent(agent_id)

    def acquire_agent_dispatch_hold(
        self,
        agent_id: str,
        reason: str,
        *,
        expected_dispatch_hold: bool,
        expected_reason: Optional[str] = None,
    ) -> Tuple[bool, "Agent"]:
        """Acquire or replace a dispatch hold with compare-and-swap semantics.

        A caller acquiring an unheld agent must expect both the unheld state and
        its canonical ``NULL`` reason.  A caller replacing a hold must name the
        exact reason it currently owns.  The conditional update and the row
        read used for the response share one write transaction, so a stale
        deployment cannot overwrite a newer operator's hold.

        Returns ``(changed, agent)``.  A lost comparison is an ordinary
        ``changed=False`` result rather than an exception; an unknown agent is
        still reported as ``NotFoundError``.
        """

        reason = str(reason or "").strip()
        if not reason:
            raise ValidationError("dispatch hold reason is required")
        expected_reason_value: Optional[str] = None
        if expected_dispatch_hold:
            expected_reason_value = str(expected_reason or "").strip()
            if not expected_reason_value:
                raise ValidationError(
                    "expected dispatch hold reason is required when a hold is expected"
                )
        elif expected_reason is not None:
            raise ValidationError(
                "expected dispatch hold reason must be omitted when no hold is expected"
            )

        now = utcnow()
        with self.store.transaction() as conn:
            if expected_dispatch_hold:
                changed = conn.execute(
                    """
                    UPDATE agents
                    SET dispatch_hold = 1, dispatch_hold_reason = ?,
                        dispatch_hold_at = ?, updated_at = ?
                    WHERE id = ? AND dispatch_hold = 1
                        AND dispatch_hold_reason = ?
                    """,
                    (reason, now, now, agent_id, expected_reason_value),
                )
            else:
                changed = conn.execute(
                    """
                    UPDATE agents
                    SET dispatch_hold = 1, dispatch_hold_reason = ?,
                        dispatch_hold_at = ?, updated_at = ?
                    WHERE id = ? AND dispatch_hold = 0
                        AND dispatch_hold_reason IS NULL
                    """,
                    (reason, now, now, agent_id),
                )
            row = conn.execute(
                "SELECT * FROM agents WHERE id = ?", (agent_id,)
            ).fetchone()
            if row is None:
                raise NotFoundError("agent not found: %s" % agent_id)
            agent = self._agent_from_row(row)
            # Whether this caller acquired/replaced the hold or merely lost a
            # CAS to another hold owner, dispatch_hold implies zero active
            # service ownership.  The agent row was updated/read first, so this
            # shares the service sync lock order and closes the arm-phase race.
            if agent.dispatch_hold:
                self._withdraw_service_claims_for_dispatch_hold(
                    conn, agent_id, now
                )
        return changed.rowcount == 1, agent

    def release_agent_dispatch_hold(
        self,
        agent_id: str,
        reason: str,
    ) -> Tuple[bool, "Agent"]:
        """Release only the dispatch hold whose reason the caller names.

        The exact-reason predicate is part of the update itself.  This keeps a
        delayed deployment cleanup from clearing an operator or successor
        deployment hold that was installed after it last read the agent.
        """

        reason = str(reason or "").strip()
        if not reason:
            raise ValidationError("dispatch hold reason is required")
        now = utcnow()
        with self.store.transaction() as conn:
            released = conn.execute(
                """
                UPDATE agents
                SET dispatch_hold = 0, dispatch_hold_reason = NULL,
                    dispatch_hold_at = NULL, updated_at = ?
                WHERE id = ? AND dispatch_hold = 1
                    AND dispatch_hold_reason = ?
                """,
                (now, agent_id, reason),
            )
            row = conn.execute(
                "SELECT * FROM agents WHERE id = ?", (agent_id,)
            ).fetchone()
            if row is None:
                raise NotFoundError("agent not found: %s" % agent_id)
            agent = self._agent_from_row(row)
        return released.rowcount == 1, agent

    @staticmethod
    def _dispatch_hold_epoch_receipt_id(epoch_id: str) -> str:
        return "alce_epoch_%s" % hashlib.sha256(
            epoch_id.encode("utf-8")
        ).hexdigest()[:32]

    @staticmethod
    def _dispatch_hold_epoch_identity_payload(
        *,
        epoch_id: str,
        normalized: Sequence[Tuple[str, str]],
        requested_expectations: Sequence[Mapping[str, Any]],
        successor_reason: Optional[str],
    ) -> Dict[str, Any]:
        return {
            "epoch_id": epoch_id,
            "holds": [
                {"agent_id": agent_id, "hold_reason": reason}
                for agent_id, reason in normalized
            ],
            "outcome": (
                "successor_hold" if successor_reason is not None else "released"
            ),
            "successor_hold_reason": successor_reason,
            "expectations": [dict(item) for item in requested_expectations],
        }

    @staticmethod
    def _dispatch_hold_epoch_identity_sha256(payload: Mapping[str, Any]) -> str:
        return hashlib.sha256(
            json.dumps(
                dict(payload), sort_keys=True, separators=(",", ":")
            ).encode("utf-8")
        ).hexdigest()

    def _replayed_agent_dispatch_hold_epoch_agents(
        self,
        conn: Any,
        *,
        epoch_id: str,
        normalized: Sequence[Tuple[str, str]],
        requested_expectations: Sequence[Mapping[str, Any]],
        successor_reason_value: Optional[str],
        require_agent_rows: bool = True,
    ) -> Optional[List[Agent]]:
        """Read and validate one exact durable epoch without mutating it."""

        def query_one(sql: str, parameters: Tuple[Any, ...]) -> Any:
            if hasattr(conn, "query_one"):
                return conn.query_one(sql, parameters)
            return conn.execute(sql, parameters).fetchone()

        def query_all(sql: str, parameters: Tuple[Any, ...]) -> List[Any]:
            if hasattr(conn, "query_all"):
                return list(conn.query_all(sql, parameters))
            return list(conn.execute(sql, parameters).fetchall())

        epoch_outcome = (
            "successor_hold" if successor_reason_value is not None else "released"
        )
        receipt_event_type = (
            "agent.dispatch_hold_epoch_transitioned"
            if successor_reason_value is not None
            else "agent.dispatch_hold_epoch_released"
        )
        epoch_event_type = "agent.dispatch_hold_epoch_committed"
        epoch_receipt_id = self._dispatch_hold_epoch_receipt_id(epoch_id)
        requested_holds = [
            {"agent_id": agent_id, "hold_reason": reason}
            for agent_id, reason in normalized
        ]

        marker = query_one(
            "SELECT event_type, detail FROM agent_lifecycle_events WHERE id = ?",
            (epoch_receipt_id,),
        )
        marker_matches = marker is None
        if marker is not None and marker["event_type"] == epoch_event_type:
            marker_detail = ensure_json_object(json_loads(marker["detail"], {}))
            marker_holds = marker_detail.get("holds")
            marker_successor_reason = marker_detail.get("successor_hold_reason")
            if marker_successor_reason is not None:
                marker_successor_reason = str(marker_successor_reason).strip()
            marker_outcome = str(marker_detail.get("outcome") or "released")
            marker_expectations = marker_detail.get("expectations")
            expectations_match = (
                marker_expectations == list(requested_expectations)
                if isinstance(marker_expectations, list)
                else not requested_expectations
            )
            marker_matches = (
                str(marker_detail.get("epoch_id") or "") == epoch_id
                and isinstance(marker_holds, list)
                and marker_holds == requested_holds
                and marker_outcome == epoch_outcome
                and marker_successor_reason == successor_reason_value
                and expectations_match
            )
        if not marker_matches:
            raise ValidationError(
                "fleet release epoch id was already used with a different "
                "or incomplete hold set, successor outcome, or expectations"
            )

        if marker is None:
            receipt_rows = query_all(
                "SELECT agent_id, event_type, detail "
                "FROM agent_lifecycle_events WHERE event_type IN (?, ?)",
                (
                    "agent.dispatch_hold_epoch_released",
                    "agent.dispatch_hold_epoch_transitioned",
                ),
            )
        else:
            receipt_rows = []
            for agent_id, _reason in normalized:
                receipt_rows.extend(
                    query_all(
                        "SELECT agent_id, event_type, detail "
                        "FROM agent_lifecycle_events "
                        "WHERE agent_id = ? AND event_type = ?",
                        (agent_id, receipt_event_type),
                    )
                )
        observed_holds: List[Dict[str, str]] = []
        for receipt_row in receipt_rows:
            detail = ensure_json_object(json_loads(receipt_row["detail"], {}))
            if str(detail.get("epoch_id") or "") != epoch_id:
                continue
            if str(receipt_row["event_type"] or "") != receipt_event_type:
                raise ValidationError(
                    "fleet release epoch id was already used with a different "
                    "successor outcome"
                )
            if successor_reason_value is not None and str(
                detail.get("successor_hold_reason") or ""
            ) != successor_reason_value:
                raise ValidationError(
                    "fleet release epoch receipt has a different successor outcome"
                )
            observed_holds.append(
                {
                    "agent_id": str(receipt_row["agent_id"] or ""),
                    "hold_reason": str(detail.get("hold_reason") or ""),
                }
            )

        if marker is None and not observed_holds:
            return None
        observed_holds.sort(key=lambda item: item["agent_id"])
        if observed_holds != requested_holds:
            raise ValidationError(
                "fleet release epoch id was already used with a different "
                "or incomplete hold set or successor outcome"
            )
        if marker is None and requested_expectations:
            raise ValidationError(
                "legacy fleet release epoch receipt lacks expectation identity"
            )

        if not require_agent_rows:
            return []
        replayed: List[Agent] = []
        for agent_id, _reason in normalized:
            row = query_one(
                "SELECT * FROM agents WHERE id = ?", (agent_id,)
            )
            if row is None:
                raise NotFoundError(
                    "fleet release epoch receipt references missing agent: %s"
                    % agent_id
                )
            replayed.append(self._agent_from_row(row))
        return replayed

    def agent_dispatch_hold_epoch_status(
        self, epoch_id: str, identity_sha256: str
    ) -> Dict[str, Any]:
        """Return absent, exact committed, or identity mismatch without writes."""

        epoch_id = str(epoch_id or "").strip()
        if (
            not epoch_id
            or len(epoch_id.encode("utf-8")) > 512
            or any(not character.isprintable() for character in epoch_id)
        ):
            raise ValidationError("fleet release epoch id is invalid")
        identity_sha256 = str(identity_sha256 or "").strip()
        if not re.fullmatch(r"[0-9a-f]{64}", identity_sha256):
            raise ValidationError("fleet release epoch identity digest is invalid")

        epoch_receipt_id = self._dispatch_hold_epoch_receipt_id(epoch_id)
        conn = self.store
        marker = conn.query_one(
            "SELECT event_type, detail FROM agent_lifecycle_events WHERE id = ?",
            (epoch_receipt_id,),
        )
        if marker is None:
            return {
                "status": "absent",
                "epoch_id": epoch_id,
                "identity_sha256": identity_sha256,
            }
        if marker["event_type"] != "agent.dispatch_hold_epoch_committed":
            return {
                "status": "mismatch",
                "epoch_id": epoch_id,
                "identity_sha256": identity_sha256,
            }
        detail = ensure_json_object(json_loads(marker["detail"], {}))
        holds = detail.get("holds")
        expectations = detail.get("expectations")
        outcome = str(detail.get("outcome") or "released")
        successor_reason = detail.get("successor_hold_reason")
        if successor_reason is not None:
            successor_reason = str(successor_reason).strip()
        if (
            str(detail.get("epoch_id") or "") != epoch_id
            or not isinstance(holds, list)
            or not isinstance(expectations, list)
            or outcome not in {"released", "successor_hold"}
            or (outcome == "successor_hold") != (successor_reason is not None)
        ):
            return {
                "status": "mismatch",
                "epoch_id": epoch_id,
                "identity_sha256": identity_sha256,
            }
        normalized: List[Tuple[str, str]] = []
        for item in holds:
            if not isinstance(item, Mapping):
                break
            agent_id = str(item.get("agent_id") or "").strip()
            reason = str(item.get("hold_reason") or "").strip()
            if not agent_id or not reason:
                break
            normalized.append((agent_id, reason))
        else:
            normalized.sort(key=lambda item: item[0])
            if len(normalized) == len(set(agent_id for agent_id, _ in normalized)):
                identity = self._dispatch_hold_epoch_identity_payload(
                    epoch_id=epoch_id,
                    normalized=normalized,
                    requested_expectations=expectations,
                    successor_reason=successor_reason,
                )
                actual_digest = self._dispatch_hold_epoch_identity_sha256(identity)
                if actual_digest == identity_sha256:
                    try:
                        replayed = self._replayed_agent_dispatch_hold_epoch_agents(
                            conn,
                            epoch_id=epoch_id,
                            normalized=normalized,
                            requested_expectations=expectations,
                            successor_reason_value=successor_reason,
                            require_agent_rows=False,
                        )
                    except (NotFoundError, ValidationError):
                        replayed = None
                    if replayed is not None:
                        return {
                            "status": "committed",
                            "epoch_id": epoch_id,
                            "identity_sha256": actual_digest,
                            "outcome": outcome,
                            "successor_hold_reason": successor_reason,
                            "agent_ids": [agent_id for agent_id, _ in normalized],
                        }
        return {
            "status": "mismatch",
            "epoch_id": epoch_id,
            "identity_sha256": identity_sha256,
        }

    def release_agent_dispatch_holds_batch(
        self,
        holds: Iterable[Tuple[str, str]],
        *,
        epoch_id: str,
        actor: str = "fleet-deploy",
        expectations: Optional[Mapping[str, Mapping[str, Any]]] = None,
        successor_reason: Optional[str] = None,
    ) -> List["Agent"]:
        """Atomically release or hand off one exact fleet-cohort hold epoch.

        Every reason comparison and every update shares one transaction.  A
        stale or replaced hold therefore rolls the entire cohort back instead
        of exposing a mixed-generation interval in which early workers can
        claim while later workers remain fenced.  When ``successor_reason`` is
        supplied, every deployment hold is replaced directly by that successor
        hold without any committed or observable unheld state.
        """

        epoch_id = str(epoch_id or "").strip()
        if not epoch_id:
            raise ValidationError("fleet release epoch id is required")
        successor_reason_value: Optional[str] = None
        if successor_reason is not None:
            successor_reason_raw = str(successor_reason or "")
            if any(not character.isprintable() for character in successor_reason_raw):
                raise ValidationError(
                    "successor dispatch hold reason must be at most 512 UTF-8 "
                    "bytes and contain no control characters"
                )
            successor_reason_value = successor_reason_raw.strip()
            if not successor_reason_value:
                raise ValidationError("successor dispatch hold reason is required")
            if len(successor_reason_value.encode("utf-8")) > 512:
                raise ValidationError(
                    "successor dispatch hold reason must be at most 512 UTF-8 "
                    "bytes and contain no control characters"
                )
        normalized: List[Tuple[str, str]] = []
        seen: set[str] = set()
        try:
            hold_entries = iter(holds)
        except TypeError as exc:
            raise ValidationError("fleet release holds must be an iterable") from exc
        for entry in hold_entries:
            if not isinstance(entry, (list, tuple)) or len(entry) != 2:
                raise ValidationError(
                    "fleet release entries must be (agent_id, reason) pairs"
                )
            raw_agent_id, raw_reason = entry
            agent_id = str(raw_agent_id or "").strip()
            reason = str(raw_reason or "").strip()
            if not agent_id or not reason:
                raise ValidationError(
                    "fleet release entries require agent_id and reason"
                )
            if agent_id in seen:
                raise ValidationError(
                    "duplicate agent in fleet release epoch: %s" % agent_id
                )
            seen.add(agent_id)
            normalized.append((agent_id, reason))
        if not normalized:
            raise ValidationError("fleet release epoch requires at least one hold")
        if successor_reason_value is not None and any(
            reason == successor_reason_value for _agent_id, reason in normalized
        ):
            raise ValidationError(
                "successor dispatch hold reason must differ from every current hold"
            )
        # A stable lock order avoids two concurrent cohort releases deadlocking
        # merely because their callers supplied the same set in a different
        # order.  Epoch identity is set-based, so response ordering is likewise
        # deterministic.
        normalized.sort(key=lambda item: item[0])

        now = utcnow()
        agents: List[Agent] = []
        expected_by_agent = dict(expectations or {})
        requested_expectations: List[Dict[str, Any]] = []
        for agent_id, _reason in normalized:
            expected = ensure_json_object(expected_by_agent.get(agent_id))
            if not expected:
                continue
            requested_expectations.append(
                {
                    "agent_id": agent_id,
                    "generation": expected.get("generation"),
                    "baseline_seen": str(expected.get("baseline_seen") or "").strip(),
                    "principal_id": expected.get("principal_id"),
                    "require_authenticated": bool(
                        expected.get("require_authenticated")
                    ),
                    "require_report_executor": bool(
                        expected.get("require_report_executor")
                    ),
                }
            )

        epoch_outcome = (
            "successor_hold" if successor_reason_value is not None else "released"
        )
        receipt_event_type = (
            "agent.dispatch_hold_epoch_transitioned"
            if successor_reason_value is not None
            else "agent.dispatch_hold_epoch_released"
        )
        epoch_event_type = "agent.dispatch_hold_epoch_committed"
        epoch_receipt_id = "alce_epoch_%s" % hashlib.sha256(
            epoch_id.encode("utf-8")
        ).hexdigest()[:32]
        requested_holds = [
            {"agent_id": agent_id, "hold_reason": reason}
            for agent_id, reason in normalized
        ]

        def replayed_epoch_agents(conn: Any) -> Optional[List[Agent]]:
            """Return an exact prior commit, or reject partial/changed reuse."""

            return self._replayed_agent_dispatch_hold_epoch_agents(
                conn,
                epoch_id=epoch_id,
                normalized=normalized,
                requested_expectations=requested_expectations,
                successor_reason_value=successor_reason_value,
            )

        with self.store.transaction() as conn:
            # BEGIN IMMEDIATE already serializes SQLite writers, but Postgres
            # READ COMMITTED does not retain a lock for an ordinary SELECT.
            # Acquire every agent row in the same stable order before reading
            # readiness or active-work state. A concurrent heartbeat can no
            # longer replace idle/healthy/generation/principal proof between
            # validation and the hold-clearing UPDATE.
            for agent_id, _reason in normalized:
                locked = conn.execute(
                    "UPDATE agents SET updated_at = updated_at "
                    "WHERE id = ? AND deleted_at IS NULL",
                    (agent_id,),
                )
                if locked.rowcount != 1:
                    raise NotFoundError("agent not found: %s" % agent_id)
                reserved = conn.execute(
                    "SELECT epoch_id FROM fleet_release_epoch_agents "
                    "WHERE agent_id = ? AND open_state = 1",
                    (agent_id,),
                ).fetchone()
                if reserved is not None:
                    raise ValidationError(
                        "agent belongs to an open prepared fleet release epoch"
                    )
            replayed = replayed_epoch_agents(conn)
            if replayed is not None:
                return replayed

            # Claim the epoch with a deterministic primary key in the same
            # transaction as every release.  ON CONFLICT serializes concurrent
            # same-epoch requests on both SQLite and PostgreSQL without a new
            # schema object.  The marker is invisible unless the whole cohort
            # commits; rollback removes it together with all per-agent receipts.
            claimed_epoch = conn.execute(
                """
                INSERT INTO agent_lifecycle_events
                    (id, agent_id, event_type, actor, detail, created_at)
                VALUES (?, ?, ?, ?, ?, ?)
                ON CONFLICT(id) DO NOTHING
                """,
                (
                    epoch_receipt_id,
                    normalized[0][0],
                    epoch_event_type,
                    actor,
                    json_dumps(
                        {
                            "actor": actor,
                            "epoch_id": epoch_id,
                            "holds": requested_holds,
                            "outcome": epoch_outcome,
                            "successor_hold_reason": successor_reason_value,
                            "expectations": requested_expectations,
                        }
                    ),
                    now,
                ),
            )
            if claimed_epoch.rowcount != 1:
                replayed = replayed_epoch_agents(conn)
                if replayed is not None:
                    return replayed
                raise ValidationError(
                    "fleet release epoch id could not be claimed"
                )

            for agent_id, reason in normalized:
                row_before = conn.execute(
                    "SELECT * FROM agents WHERE id = ? AND deleted_at IS NULL",
                    (agent_id,),
                ).fetchone()
                if row_before is None:
                    raise NotFoundError("agent not found: %s" % agent_id)
                active_task = conn.execute(
                    "SELECT id FROM tasks WHERE owner_agent_id = ? "
                    "AND state IN (?, ?) LIMIT 1",
                    (
                        agent_id,
                        TaskState.CLAIMED.value,
                        TaskState.RUNNING.value,
                    ),
                ).fetchone()
                if active_task is not None or row_before["current_task_id"] is not None:
                    raise ValidationError(
                        "fleet release epoch found active work on %s" % agent_id
                    )
                expected = ensure_json_object(expected_by_agent.get(agent_id))
                if expected:
                    resources = ensure_json_object(
                        json_loads(row_before["resources"], {})
                    )
                    authenticated = ensure_json_object(
                        resources.get("worker_credential_authenticated")
                    )
                    baseline_seen = str(expected.get("baseline_seen") or "").strip()
                    last_seen = str(row_before["last_seen_at"] or "").strip()
                    if (
                        row_before["status"] != AgentStatus.IDLE.value
                        or row_before["health_status"] != HealthStatus.HEALTHY.value
                        or not baseline_seen
                        or not last_seen
                        or parse_time(last_seen) <= parse_time(baseline_seen)
                        or resources.get("deployment_generation")
                        != expected.get("generation")
                    ):
                        raise ValidationError(
                            "fleet release epoch lost readiness for %s" % agent_id
                        )
                    if bool(expected.get("require_authenticated")) and not (
                        authenticated.get("agent_id") == agent_id
                        and authenticated.get("principal_id")
                        == expected.get("principal_id")
                    ):
                        raise ValidationError(
                            "fleet release epoch lost credential proof for %s"
                            % agent_id
                        )
                    if bool(expected.get("require_report_executor")) and not (
                        self._report_executor_release_ready(agent_id, resources)
                    ):
                        raise ValidationError(
                            "fleet release epoch lost report executor proof for %s"
                            % agent_id
                        )
                if successor_reason_value is None:
                    committed = conn.execute(
                        """
                        UPDATE agents
                        SET dispatch_hold = 0, dispatch_hold_reason = NULL,
                            dispatch_hold_at = NULL, updated_at = ?
                        WHERE id = ? AND deleted_at IS NULL
                            AND dispatch_hold = 1 AND dispatch_hold_reason = ?
                        """,
                        (now, agent_id, reason),
                    )
                else:
                    committed = conn.execute(
                        """
                        UPDATE agents
                        SET dispatch_hold = 1, dispatch_hold_reason = ?,
                            dispatch_hold_at = ?, updated_at = ?
                        WHERE id = ? AND deleted_at IS NULL
                            AND dispatch_hold = 1 AND dispatch_hold_reason = ?
                        """,
                        (
                            successor_reason_value,
                            now,
                            now,
                            agent_id,
                            reason,
                        ),
                    )
                row = conn.execute(
                    "SELECT * FROM agents WHERE id = ? AND deleted_at IS NULL",
                    (agent_id,),
                ).fetchone()
                if committed.rowcount != 1:
                    raise ValidationError(
                        "fleet release epoch lost dispatch-hold ownership for %s"
                        % agent_id
                    )
                if successor_reason_value is not None:
                    self._withdraw_service_claims_for_dispatch_hold(
                        conn, agent_id, now
                    )
                self._record_agent_lifecycle_event(
                    conn,
                    agent_id,
                    receipt_event_type,
                    actor,
                    {
                        "agent_id": agent_id,
                        "epoch_id": epoch_id,
                        "hold_reason": reason,
                        "outcome": epoch_outcome,
                        "successor_hold_reason": successor_reason_value,
                    },
                    now,
                )
                agents.append(self._agent_from_row(row))
        return agents

    def clear_agent_dispatch_hold(self, agent_id: str) -> "Agent":
        """Remove the dispatch hold from an agent, making it eligible for dispatch again."""
        self.get_agent(agent_id)  # raises NotFoundError if absent
        now = utcnow()
        with self.store.transaction() as conn:
            conn.execute(
                "UPDATE agents SET dispatch_hold = 0, dispatch_hold_reason = NULL, dispatch_hold_at = NULL, updated_at = ? WHERE id = ?",
                (now, agent_id),
            )
        return self.get_agent(agent_id)

    def unconsumed_control_stream_age_seconds(self, agent_id: str) -> Optional[float]:
        agent = self.get_agent(agent_id)
        published_at = agent.last_control_stream_published_at
        if not published_at:
            return None
        published = parse_time(published_at)
        consumed_at = agent.last_control_stream_consumed_at
        if consumed_at and parse_time(consumed_at) >= published:
            return None
        age = (parse_time(utcnow()) - published).total_seconds()
        return max(0.0, age)

    def delete_agent(self, agent_id: str, *, actor: str = "human") -> None:
        """Decommission an agent: tombstone, do NOT erase its history.

        task_c394685a (AgentBus audit 2/7): the agents row previously
        hard-deleted, cascading away the agent's entire AgentBus stream
        history on both sides — for appear→work→exit ephemeral agents that
        is precisely backwards, because their proxied results must outlive
        them. The row now stays with ``deleted_at`` set (so bus streams,
        agent_events, and delivery history keep their real identities) while
        operational overlays (moods, naps, config flags, deploy config) are
        purged and liveness operations refuse the tombstoned agent.
        Idempotent: deleting a tombstoned agent is a no-op.
        """
        with self.store.transaction() as conn:
            # Serialize decommissioning with credential issue/activation and
            # every liveness path that takes the agent-row fence.  Reading the
            # agent and its leases before this transaction left a PostgreSQL
            # window in which issuance could commit a fresh principal after we
            # had scanned credentials but before the tombstone was written.
            # Keep the global order agent row -> credential rows: the worker
            # credential lifecycle uses the same order, avoiding a
            # delete-versus-activate deadlock.
            agent_lock = conn.execute(
                "UPDATE agents SET updated_at = updated_at WHERE id = ?",
                (agent_id,),
            )
            if agent_lock.rowcount != 1:
                raise NotFoundError("agent not found: %s" % agent_id)
            agent_row = conn.execute(
                "SELECT * FROM agents WHERE id = ?", (agent_id,)
            ).fetchone()
            agent = self._agent_from_row(agent_row)
            if not agent.deleted_at:
                active_lease = conn.execute(
                    """
                    SELECT 1 FROM leases l
                    JOIN tasks t ON t.lease_id = l.id
                    WHERE l.agent_id = ?
                      AND l.status = ?
                      AND t.owner_agent_id = ?
                    LIMIT 1
                    """,
                    (agent_id, LeaseStatus.ACTIVE.value, agent_id),
                ).fetchone()
                if active_lease is not None:
                    raise ValidationError(
                        "agent cannot be deleted while holding an active lease"
                    )
            now = utcnow()
            # Decommissioning is a permanent credential boundary.  Merely
            # hiding credentials behind agents.deleted_at lets an intentional
            # later resurrection make every old active bearer valid again.
            # Revoke pending/active principals in the same transaction as the
            # tombstone and preserve secret-free audit facts. This also repairs
            # credentials left behind by tombstones created before this rule.
            credential_rows = conn.execute(
                "SELECT id, agent_id, credential_version, token_fingerprint "
                "FROM worker_credentials WHERE agent_id = ? "
                "AND state IN ('pending_install', 'active')",
                (agent_id,),
            ).fetchall()
            conn.execute(
                "UPDATE worker_credentials SET state = 'revoked', "
                "revoked_at = ?, updated_at = ? WHERE agent_id = ? "
                "AND state IN ('pending_install', 'active')",
                (now, now, agent_id),
            )
            for credential in credential_rows:
                conn.execute(
                    "INSERT INTO worker_credential_events ("
                    "id, principal_id, agent_id, event_type, actor, detail, created_at"
                    ") VALUES (?, ?, ?, ?, ?, ?, ?)",
                    (
                        new_id("workercred-event"),
                        credential["id"],
                        credential["agent_id"],
                        "worker_credential.revoked",
                        actor,
                        json_dumps(
                            {
                                "schema": "mac.worker_credential_event.v1",
                                "credential_version": int(
                                    credential["credential_version"] or 0
                                ),
                                "token_fingerprint": str(
                                    credential["token_fingerprint"] or ""
                                ),
                                "state": "revoked",
                                "reason": "agent_decommissioned",
                            }
                        ),
                        now,
                    ),
                )
            if agent.deleted_at:
                return
            self._record_agent_lifecycle_event(
                conn,
                agent_id,
                "agent.deleted",
                actor,
                {
                    "agent_id": agent.id,
                    "agent_name": agent.name,
                    "machine_id": agent.machine_id,
                    "status": agent.status,
                    "health_status": agent.health_status,
                    "hermes_instance_id": agent.persona_instance_id,
                },
                now,
            )
            conn.execute("DELETE FROM mood_overlays WHERE agent_id = ?", (agent_id,))
            conn.execute("DELETE FROM nap_schedules WHERE agent_id = ?", (agent_id,))
            conn.execute("DELETE FROM nap_runs WHERE agent_id = ?", (agent_id,))
            conn.execute("DELETE FROM agent_config_flags WHERE agent_id = ?", (agent_id,))
            conn.execute("DELETE FROM agent_deploy_configs WHERE agent_id = ?", (agent_id,))
            conn.execute(
                """
                UPDATE agents
                SET deleted_at = ?, status = ?, current_task_id = NULL,
                    dispatch_hold = 1, dispatch_hold_reason = ?,
                    dispatch_hold_at = ?, updated_at = ?
                WHERE id = ?
                """,
                (
                    now,
                    AgentStatus.OFFLINE.value,
                    "decommissioned by %s" % actor,
                    now,
                    now,
                    agent.id,
                ),
            )

    def _require_live_agent(self, agent_id: str) -> Agent:
        """Existence check that also refuses tombstoned agents.

        Reads (history, effective config, stream hydration) stay permissive
        via get_agent; anything that implies the agent is ALIVE — heartbeats,
        task claims, gateway leases, publishing new bus streams — goes
        through here instead.
        """
        agent = self.get_agent(agent_id)
        if agent.deleted_at:
            raise ValidationError(
                "agent %s was decommissioned at %s" % (agent_id, agent.deleted_at)
            )
        return agent

    def heartbeat_agent(
        self,
        agent_id: str,
        status: Optional[str] = None,
        health_status: Optional[str] = None,
        resources: Optional[Dict[str, Any]] = None,
        running_digest: Optional[str] = None,
        running_digest_signature: Optional[str] = None,
        actor: Optional[str] = None,
    ) -> Agent:
        agent_before = self._require_live_agent(agent_id)
        now = utcnow()
        updates = ["last_seen_at = ?", "updated_at = ?"]
        params: List[Any] = [now, now]
        status_value: Optional[str] = None
        health_value: Optional[str] = None
        resource_value = agent_before.resources
        next_running_digest = agent_before.running_digest
        changed_fields: List[str] = []
        resource_param_index: Optional[int] = None
        if status is not None:
            status_value = _state_value(status)
            try:
                AgentStatus(status_value)
            except ValueError:
                raise ValidationError("unsupported agent status: %s" % status_value)
            updates.append("status = ?")
            params.append(status_value)
            if status_value != agent_before.status:
                changed_fields.append("status")
        if health_status is not None:
            health_value = _state_value(health_status)
            try:
                HealthStatus(health_value)
            except ValueError:
                raise ValidationError("unsupported agent health_status: %s" % health_value)
        if resources is not None:
            resource_value = self._agent_resources_with_preserved_control_plane_fields(agent_id, resources)
            updates.append("resources = ?")
            resource_param_index = len(params)
            params.append(json_dumps(resource_value))
            if resource_value != agent_before.resources:
                changed_fields.append("resources")
        projected_health_value = self._project_agent_health_for_resources(
            agent_before.health_status,
            health_value,
            resource_value,
        )
        if projected_health_value is not None:
            updates.append("health_status = ?")
            params.append(projected_health_value)
            if projected_health_value != agent_before.health_status:
                changed_fields.append("health_status")
            health_value = projected_health_value
        if running_digest is not None:
            digest = running_digest.strip()
            if digest:
                # Anchor fleet rollout state to a known runtime build. If you
                # roll out a new agent build, register the runtime first; the
                # heartbeat that declares the new digest then becomes the truth
                # source for "how many agents are on which build."
                exists = self.store.query_one(
                    "SELECT 1 FROM runtime_environments WHERE digest = ? LIMIT 1",
                    (digest,),
                )
                if exists is None:
                    raise ValidationError(
                        "running_digest %s is not registered as a runtime_environments.digest"
                        % digest
                    )
                # mac-oud5: require the agent to sign its digest claim
                # with its attestation key when it differs from the
                # previously-declared digest. This doesn't prove the
                # process IS that digest — that would need OS / runtime
                # attestation — but it does cryptographically bind the
                # claim to the agent's identity so a peer cannot inject
                # a false digest on another agent's behalf, and the
                # signature is durable enough to audit later.
                if (
                    digest != agent_before.running_digest
                    and running_digest_signature is not None
                ):
                    key = self._agent_attestation_key(agent_id)
                    if key is None:
                        raise ValidationError(
                            "agent %s has no attestation key — cannot verify "
                            "running_digest signature" % agent_id
                        )
                    claim = {"agent_id": agent_id, "running_digest": digest}
                    if not verify_verification_manifest_signature(
                        key, claim, running_digest_signature
                    ):
                        raise ValidationError(
                            "running_digest signature does not verify under "
                            "agent's attestation key"
                        )
                updates.append("running_digest = ?")
                params.append(digest)
                next_running_digest = digest
                if digest != agent_before.running_digest:
                    changed_fields.append("running_digest")
                    if running_digest_signature is None:
                        self.observability.record_log(
                            "agent.running_digest_unsigned",
                            level="warning",
                            layer="control_plane",
                            source="control_plane",
                            subject_type="agent",
                            subject_id=agent_id,
                            detail={
                                "running_digest": digest,
                                "note": "mac-oud5: digest accepted without signature; "
                                "future enforcement will require running_digest_signature",
                            },
                        )
            else:
                updates.append("running_digest = NULL")
                next_running_digest = None
                if agent_before.running_digest is not None:
                    changed_fields.append("running_digest")
        if status_value == AgentStatus.IDLE.value and self._agent_has_active_lease(agent_id):
            raise ValidationError("agent cannot report idle while holding an active lease")
        if status_value == AgentStatus.DRAINING.value and self._agent_has_active_lease(agent_id):
            updates.append("current_task_id = NULL")
        if status_value == AgentStatus.OFFLINE.value:
            self._expire_agent_active_leases(agent_id, now, "heartbeat_offline")
            try:
                self.service_roles.expire_agent_claims(agent_id, reason="heartbeat_offline")
            except Exception:  # noqa: BLE001 - best-effort service-claim cleanup
                pass
        if status_value in {AgentStatus.IDLE.value, AgentStatus.OFFLINE.value}:
            updates.append("current_task_id = NULL")
        params.append(agent_id)
        # Only log a lifecycle/observability event when something MEANINGFUL
        # changed (status / health / running_digest) — not on resource jitter,
        # which differs on essentially every heartbeat. Writing a durable
        # agent_lifecycle_events row (+ mirrored observability_event) on every
        # beat was the dominant source of hub-db bloat: ~527K lifecycle + ~228K
        # obs rows in ~4 days on rocky, almost all just CPU/mem jitter.
        meaningful_changes = [f for f in changed_fields if f != "resources"]
        with self.store.transaction() as conn:
            if resources is not None and resource_param_index is not None:
                # Acquire the agent row before reading its controller-owned
                # approval. This closes the stale-read resurrection race with
                # an overlapping admin revoke/update.
                conn.execute(
                    "UPDATE agents SET updated_at = updated_at WHERE id = ?",
                    (agent_id,),
                )
                resource_value = (
                    self._agent_resources_with_preserved_control_plane_fields(
                        agent_id, resources, conn=conn
                    )
                )
                params[resource_param_index] = json_dumps(resource_value)
            conn.execute("UPDATE agents SET %s WHERE id = ?" % ", ".join(updates), tuple(params))
            if resources is not None:
                self._mirror_agent_reported_hardware_to_machine(
                    conn, agent_before.machine_id, resource_value, now
                )
            if meaningful_changes:
                self._record_agent_lifecycle_event(
                    conn,
                    agent_id,
                    "agent.heartbeat_updated",
                    actor or agent_id,
                    {
                        "agent_id": agent_id,
                        "agent_name": agent_before.name,
                        "changed_fields": sorted(set(meaningful_changes)),
                        "previous_status": agent_before.status,
                        "status": status_value or agent_before.status,
                        "previous_health_status": agent_before.health_status,
                        "health_status": health_value or agent_before.health_status,
                        "previous_running_digest": agent_before.running_digest,
                        "running_digest": next_running_digest,
                    },
                    now,
                )
        agent = self.get_agent(agent_id)
        if {"status", "health_status"} & set(meaningful_changes):
            self.dispatch.invalidate_pull_round_cache()
        self._ensure_agent_nap_schedule(agent.id, actor=actor or agent_id)
        self._release_auto_quarantine_on_heartbeat(agent_before)
        self._maybe_advance_reviews_on_heartbeat(agent_before)
        self._maybe_drain_notifications_on_heartbeat(agent_before)
        return agent

    def _ensure_agent_nap_schedule(self, agent_id: str, *, actor: str) -> None:
        agent = self.get_agent(agent_id)
        if agent.status == AgentStatus.OFFLINE.value:
            return
        if self.get_nap_schedule(agent.id) is None:
            self.configure_nap(agent.id, actor=actor or agent.id)



    def _maybe_drain_notifications_on_heartbeat(self, agent: Agent) -> None:
        """Drain ``pending`` operator notifications on hub-agent heartbeat.

        Mirrors :meth:`_maybe_advance_reviews_on_heartbeat`: only the
        designated hub agent triggers the drain so a fleet of N agents
        doesn't make N concurrent delivery attempts. Without this, the
        ``deliver_pending`` method would sit idle — no other code path
        runs it periodically.
        """
        if not _truthy_env("MAC_NOTIFIER_DRAIN_ON_HEARTBEAT", "1"):
            return
        hub_agent = resolve_hub_agent(
            "MAC_NOTIFIER_DRAIN_HUB_AGENT",
            "MAC_REVIEW_TICK_HUB_AGENT",
        )
        if not hub_agent:
            return
        if agent.name != hub_agent and agent.id != hub_agent:
            return
        try:
            limit = int(os.environ.get("MAC_NOTIFIER_DRAIN_LIMIT", "100"))
        except ValueError:
            limit = 100
        if limit <= 0:
            return
        try:
            result = self.deliver_pending_notifications(limit=limit)
            delivered = (
                int(result.get("delivered", 0)) if isinstance(result, dict) else 0
            )
            if delivered:
                self.record_log(
                    "notifier.heartbeat_drain",
                    layer="control_plane",
                    source=agent.id,
                    level="info",
                    detail={"delivered": delivered, "limit": limit},
                )
        except Exception as exc:  # noqa: BLE001 - heartbeat liveness must survive delivery failures.
            try:
                self.record_log(
                    "notifier.heartbeat_drain_failed",
                    layer="control_plane",
                    source=agent.id,
                    level="warning",
                    detail={"error": str(exc)},
                )
            except Exception:
                pass

    def _release_auto_quarantine_on_heartbeat(self, agent: Agent) -> None:
        """Lift the zombie quarantine once the agent proves it is alive.

        AUTO_QUARANTINE_REASON means "consecutive lease expiries with no
        executor telemetry" -- i.e. the hub believes this worker is a zombie.
        A heartbeat is direct counter-evidence. Nothing else in the codebase
        clears this hold: clear_agent_dispatch_hold has only operator callers,
        so a single fleet-wide event (a deploy expiring every in-flight lease)
        could bench every agent permanently. Observed live twice on 2026-07-31.

        Only this machine-set reason is released. An operator hold, and the
        source-convergence hold that owns its own lifecycle, are left alone.
        """

        if not agent.dispatch_hold:
            return
        if str(agent.dispatch_hold_reason or "").strip() != AUTO_QUARANTINE_REASON:
            return
        try:
            self.clear_agent_dispatch_hold(agent.id)
        except Exception:  # noqa: BLE001 - heartbeat liveness must survive this
            return
        try:
            self.record_log(
                "agent.auto_quarantine_released",
                layer="control_plane",
                source=agent.id,
                level="info",
                detail={
                    "agent_id": agent.id,
                    "reason": "heartbeat proves the agent is not a zombie",
                    "released_reason": AUTO_QUARANTINE_REASON,
                    "held_since": agent.dispatch_hold_at,
                },
            )
        except Exception:  # noqa: BLE001 - diagnostic only
            pass

    def _maybe_advance_reviews_on_heartbeat(self, agent: Agent) -> None:
        # DEFAULT OFF. This ran the review sweep -- a repository clone plus a
        # sandboxed contract gate -- on a WORKER'S HEARTBEAT REQUEST THREAD.
        # The cost was paid by the worker, not the hub: heartbeats of 250-315
        # seconds and lease renewals of 33 seconds were observed live, which is
        # a worker unable to finish a request while it waits on someone else's
        # test run.
        #
        # The sweep now has a dedicated worker (api._start_publication_worker).
        # Set MAC_REVIEW_TICK_ON_HEARTBEAT=1 to restore the old behaviour.
        if not _truthy_env("MAC_REVIEW_TICK_ON_HEARTBEAT", "0"):
            return
        hub_agent = resolve_hub_agent("MAC_REVIEW_TICK_HUB_AGENT")
        if not hub_agent:
            return
        if agent.name != hub_agent and agent.id != hub_agent:
            return
        try:
            limit = int(os.environ.get("MAC_REVIEW_TICK_LIMIT", "25"))
        except ValueError:
            limit = 25
        try:
            result = self._advance_default_review_sweep_page(
                limit=max(1, limit),
                actor=agent.id,
                tenant_id=None,
            )
            stuck = [
                item
                for item in result.get("results", [])
                if item.get("status")
                in {
                    "waiting_for_verifiable_evidence",
                    "waiting_for_reviewer",
                    "waiting_for_reviewer_verdict",
                    "waiting_for_publication_evidence",
                    "waiting_for_publication_target",
                    "ambiguous_pending_reviews",
                }
            ]
            if result.get("processed") or stuck:
                self.record_log(
                    "workflow.default_review.heartbeat_tick",
                    layer="control_plane",
                    source=agent.id,
                    level="warning" if stuck else "info",
                    detail={"processed": result.get("processed", 0), "stuck": stuck},
                )
        except Exception as exc:  # noqa: BLE001 - heartbeat liveness must survive review sweeps.
            try:
                self.record_log(
                    "workflow.default_review.heartbeat_tick_failed",
                    layer="control_plane",
                    source=agent.id,
                    level="warning",
                    detail={"error": str(exc)},
                )
            except Exception:
                pass

    def fleet_build_distribution(self) -> JsonDict:
        """Aggregate agents by their declared running_digest.

        Useful for "what percent of the fleet is on v0.8 vs v0.9" without joining
        rollouts. Agents with no declared digest are bucketed as 'unknown'.
        """
        rows = self.store.query_all(
            """
            SELECT COALESCE(running_digest, '') AS digest, COUNT(*) AS count
            FROM agents
            WHERE status != ?
            GROUP BY running_digest
            ORDER BY count DESC
            """,
            (AgentStatus.OFFLINE.value,),
        )
        buckets = [
            {"digest": row["digest"] or None, "count": int(row["count"])}
            for row in rows
        ]
        total = sum(bucket["count"] for bucket in buckets) or 1
        for bucket in buckets:
            bucket["percent"] = round(bucket["count"] * 100.0 / total, 2)
        return {"total_live_agents": total if total > 0 else 0, "buckets": buckets}

    # Mood overlays (agent-self-reported emotional state)
    #
    # The contract: agents pick their own mood based on local signals (recent
    # outcomes, retry counts, review rejections — already in the events
    # stream). mac records and audits transitions; it does NOT derive mood on
    # the agent's behalf. Operators can read, but the authoritative caller is
    # the agent itself.

    # Moods: thin facade over ``self.agent_state``.

    def set_mood(self, *args: Any, **kwargs: Any) -> MoodOverlay:
        return self.agent_state.set_mood(*args, **kwargs)

    def get_current_mood(self, agent_id: str) -> Optional[MoodOverlay]:
        return self.agent_state.get_current_mood(agent_id)

    def clear_mood(self, *args: Any, **kwargs: Any) -> Optional[MoodOverlay]:
        return self.agent_state.clear_mood(*args, **kwargs)

    def get_mood_overlay(self, overlay_id: str) -> MoodOverlay:
        return self.agent_state.get_mood_overlay(overlay_id)

    def list_mood_history(self, *args: Any, **kwargs: Any) -> List[MoodOverlay]:
        return self.agent_state.list_mood_history(*args, **kwargs)

    # Config flags: thin facade over ``self.agent_state``.

    def set_config_flag(self, *args: Any, **kwargs: Any) -> Dict[str, Any]:
        return self.agent_state.set_config_flag(*args, **kwargs)

    def get_config_flag(self, *args: Any, **kwargs: Any) -> Dict[str, Any]:
        return self.agent_state.get_config_flag(*args, **kwargs)

    def list_config_flags(self, *args: Any, **kwargs: Any) -> List[Dict[str, Any]]:
        return self.agent_state.list_config_flags(*args, **kwargs)

    def clear_config_flag(self, *args: Any, **kwargs: Any) -> bool:
        return self.agent_state.clear_config_flag(*args, **kwargs)

    # Deploy config + the consolidated per-agent effective view.

    def report_agent_deploy_config(
        self, *args: Any, **kwargs: Any
    ) -> Dict[str, Any]:
        return self.agent_state.report_deploy_config(*args, **kwargs)

    def get_agent_deploy_config(
        self, *args: Any, **kwargs: Any
    ) -> Optional[Dict[str, Any]]:
        return self.agent_state.get_deploy_config(*args, **kwargs)

    def effective_agent_config(self, *args: Any, **kwargs: Any) -> Dict[str, Any]:
        return self.agent_state.effective_agent_config(*args, **kwargs)

    # Nap schedule + lifecycle
    #
    # Each agent has a single nap_schedule row (offset_minutes, window_minutes).
    # The offset defaults to a stable hash of the agent's name to spread the
    # fleet across each hourly cycle (MD5 % 60). Nap
    # *execution* is off-process — the agent (or a sidecar) decides what to
    # summarize and where to store it. mac records begin/complete events and
    # links to the produced summary evidence + vector refs.

    # Nap schedule + lifecycle: thin facade over ``self.agent_state``.

    def configure_nap(self, *args: Any, **kwargs: Any) -> NapSchedule:
        return self.agent_state.configure_nap(*args, **kwargs)

    def get_nap_schedule(self, agent_id: str) -> Optional[NapSchedule]:
        return self.agent_state.get_nap_schedule(agent_id)

    def list_nap_schedules(self) -> List[NapSchedule]:
        return self.agent_state.list_nap_schedules()

    def next_nap_window(self, *args: Any, **kwargs: Any) -> Optional[Dict[str, str]]:
        return self.agent_state.next_nap_window(*args, **kwargs)

    def begin_nap(self, *args: Any, **kwargs: Any) -> NapRun:
        return self.agent_state.begin_nap(*args, **kwargs)

    def memory_health(
        self,
        *,
        qdrant_url: Optional[str] = None,
        nap_interval_hours: float = 1.0,
        vector_ingestion_max_age_hours: float = (
            _DEFAULT_INGESTION_MAX_AGE_HOURS
        ),
        qdrant_transport: Optional[Any] = None,
        qdrant_scan_limit: Optional[int] = None,
    ) -> JsonDict:
        """mem-10: memory-tier health snapshot.

        Returns a dict the operator (and a future scheduled alerter)
        can read to spot the failure modes the audits found:

          * Inert vector tier — memory_records growing while
            vector_refs stays at 0. The 2026-05-28 audit's smoking gun.
          * Stalled consolidator — last_nap_run_at older than
            ``2 * nap_interval_hours`` means the nap cycle stopped
            running.
          * Stalled vector ingestion — a Qdrant collection whose newest
            ``embedded_at`` is older than
            ``vector_ingestion_max_age_hours``. ``points_count`` alone
            cannot see this: points persist, so a collection frozen
            since 2026-07-25 still reports 667 healthy-looking points.
          * Unwritten memory tier — a declared tier with zero points
            while a sibling tier is populated. Nothing promotes into it.
          * Mixed embedding spaces — one collection holding vectors from
            two embedding models, which are not comparable, so recall
            silently returns wrong neighbours.
          * Disk bloat — mac.db growing faster than the vector tier.

        ``qdrant_url`` defaults to the configured Qdrant URL
        (MAC_QDRANT_URL, QDRANT_URL, QDRANT_ADDRESS, or
        QDRANT_FLEET_URL). When unreachable,
        the qdrant_collections block reports its error instead of
        raising; the operator still gets the database-side numbers.

        ``qdrant_transport`` and ``qdrant_scan_limit`` exist for tests
        and for operators tuning the bounded payload scan; production
        callers leave both at their defaults.
        """
        from datetime import datetime, timezone
        from pathlib import Path

        now = utcnow()
        now_dt = datetime.now(tz=timezone.utc)

        # SQLite-side counts.
        def _count(sql: str) -> int:
            row = self.store.query_one(sql)
            return int(row["n"]) if row is not None else 0

        mr_count = _count("SELECT COUNT(*) AS n FROM memory_records")
        vr_count = _count("SELECT COUNT(*) AS n FROM vector_refs")
        oe_count = _count("SELECT COUNT(*) AS n FROM observability_events")

        nap_row = self.store.query_one(
            "SELECT MAX(completed_at) AS last FROM nap_runs WHERE status = 'completed'"
        )
        last_nap_at = nap_row["last"] if nap_row is not None and nap_row["last"] else None

        # mac.db file size (when we can find the file).
        db_path = getattr(self.store, "path", None) or getattr(self.store, "_path", None)
        db_size: Optional[int] = None
        if db_path:
            try:
                db_size = Path(str(db_path)).stat().st_size
            except OSError:
                db_size = None

        # Qdrant per-collection state — best-effort. Beyond points_count this
        # reads each point's embedded_at + embedding_model payload, because
        # ingestion freshness and model mixing are invisible in the count.
        url = _configured_qdrant_url(qdrant_url)
        qdrant_block: JsonDict = {
            "url": url,
            "collections": {},
            "error": None,
            "ingestion_max_age_hours": float(vector_ingestion_max_age_hours),
        }
        qdrant_alerts: List[JsonDict] = []
        if url:
            try:
                from mac.models import MAC_MEMORY_COLLECTIONS

                qdrant_block["collections"] = _probe_qdrant_collections(
                    url,
                    MAC_MEMORY_COLLECTIONS,
                    transport=qdrant_transport,
                    scan_limit=qdrant_scan_limit,
                    now=now_dt,
                )
                qdrant_alerts = _evaluate_qdrant_alerts(
                    qdrant_block["collections"],
                    ingestion_max_age_hours=float(vector_ingestion_max_age_hours),
                )
            except Exception as exc:  # noqa: BLE001
                qdrant_block["error"] = str(exc)

        # Alert rules (the audit's failure modes encoded).
        alerts: List[JsonDict] = []
        if mr_count > 100 and vr_count == 0:
            alerts.append(
                {
                    "severity": "critical",
                    "code": "inert_vector_tier",
                    "message": (
                        "memory_records=%d but vector_refs=0; the writer never "
                        "ran. This is the failure mode the original 2026-05-28 "
                        "audit surfaced." % mr_count
                    ),
                }
            )
        if last_nap_at is not None:
            try:
                last_dt = datetime.fromisoformat(last_nap_at)
                if last_dt.tzinfo is None:
                    last_dt = last_dt.replace(tzinfo=timezone.utc)
                age_hours = (now_dt - last_dt).total_seconds() / 3600.0
                if age_hours > 2.0 * nap_interval_hours:
                    alerts.append(
                        {
                            "severity": "critical",
                            "code": "stalled_consolidator",
                            "message": (
                                "last successful nap completed_at=%s "
                                "(%.1fh ago, threshold %.1fh = 2× nap_interval)"
                                % (last_nap_at, age_hours, 2.0 * nap_interval_hours)
                            ),
                        }
                    )
            except (TypeError, ValueError):
                pass
        elif mr_count > 0:
            # We have memories but no completed nap_runs at all.
            alerts.append(
                {
                    "severity": "warning",
                    "code": "no_nap_history",
                    "message": (
                        "no completed nap_runs on record despite %d "
                        "memory_records — the consolidator has never run "
                        "successfully." % mr_count
                    ),
                }
            )
        alerts.extend(qdrant_alerts)

        return {
            "schema": "mac.memory_health.v1",
            "captured_at": now,
            "mac_db_size_bytes": db_size,
            "memory_records_count": mr_count,
            "vector_refs_count": vr_count,
            "observability_events_count": oe_count,
            "last_nap_run_at": last_nap_at,
            "qdrant": qdrant_block,
            "alerts": alerts,
        }

    def recall_memory(
        self,
        query: str,
        *,
        tier: str = "medium",
        limit: int = 5,
        min_score: Optional[float] = None,
        project: Optional[str] = None,
        tenant_id: Optional[str] = None,
        agent_id: Optional[str] = None,
        qdrant_url: Optional[str] = None,
        vector_writer: Optional[Any] = None,
    ) -> List[JsonDict]:
        """mem-09: vector-tier recall.

        Embeds ``query`` and returns the top hits in the chosen tier
        as the mem-09 standard shape (memory_id, task_id, score,
        summary, ...). Server-side filters cover project/tenant; pass
        a pre-built VectorWriterService when the caller already has
        one to skip repeated initialization.
        """
        if not query or not str(query).strip():
            raise ValidationError("recall_memory requires a non-empty query")
        if vector_writer is None:
            url = _configured_qdrant_url(qdrant_url)
            if not url:
                raise ValidationError(
                    "recall_memory needs a Qdrant URL — pass qdrant_url or set "
                    "MAC_QDRANT_URL/QDRANT_URL/QDRANT_ADDRESS/QDRANT_FLEET_URL"
                )
            from mac.vector_writer_service import VectorWriterService

            vector_writer = VectorWriterService(memory=self.memory, qdrant_url=url)
        return vector_writer.recall(
            query,
            tier=tier,
            limit=limit,
            score_threshold=min_score,
            project=project,
            tenant_id=tenant_id,
            agent_id=agent_id,
        )

    def recall_dream_artifacts(
        self,
        query: str,
        *,
        tier: str = "medium",
        limit: int = 5,
        min_score: Optional[float] = None,
        project: Optional[str] = None,
        agent_id: Optional[str] = None,
        scope: Optional[str] = None,
        kind: Optional[str] = None,
        min_confidence: Optional[str] = None,
        tenant_id: Optional[str] = None,
        qdrant_url: Optional[str] = None,
        vector_writer: Optional[Any] = None,
    ) -> List[JsonDict]:
        """Recall typed ``mac.dream.v1`` artifacts using their retrieval rules.

        Dream artifacts are stored as ordinary memory_records, but this method
        keeps their read path explicit: only ``subject_type='dream'`` hits are
        eligible, and callers may narrow by scope, kind, project, agent, tenant,
        and minimum confidence.
        """
        if not query or not str(query).strip():
            raise ValidationError("recall_dream_artifacts requires a non-empty query")
        if vector_writer is None:
            url = _configured_qdrant_url(qdrant_url)
            if not url:
                raise ValidationError(
                    "recall_dream_artifacts needs a Qdrant URL — pass qdrant_url "
                    "or set MAC_QDRANT_URL/QDRANT_URL/QDRANT_ADDRESS/QDRANT_FLEET_URL"
                )
            from mac.vector_writer_service import VectorWriterService

            vector_writer = VectorWriterService(memory=self.memory, qdrant_url=url)

        must: List[JsonDict] = [{"key": "subject_type", "match": {"value": "dream"}}]
        if project:
            must.append({"key": "project", "match": {"value": project}})
        if agent_id:
            must.append({"key": "agent_id", "match": {"value": agent_id}})
        if scope:
            must.append({"key": "dream_scope", "match": {"value": scope}})
        if kind:
            must.append({"key": "dream_kind", "match": {"value": kind}})

        hits = vector_writer.recall(
            query,
            tier=tier,
            limit=max(1, int(limit)),
            score_threshold=min_score,
            filter_payload={"must": must},
            tenant_id=tenant_id,
        )
        if min_confidence:
            floor_by_name = {"low": 0.0, "medium": 0.65, "high": 0.9}
            floor = floor_by_name.get(str(min_confidence).strip().lower())
            if floor is None:
                raise ValidationError("min_confidence must be one of low / medium / high")

            def _confidence_score(hit: JsonDict) -> float:
                payload = hit.get("payload") if isinstance(hit.get("payload"), dict) else {}
                raw = payload.get("dream_confidence_score")
                try:
                    return float(raw)
                except (TypeError, ValueError):
                    name = str(payload.get("dream_confidence") or "").strip().lower()
                    return floor_by_name.get(name, 0.0)

            hits = [hit for hit in hits if _confidence_score(hit) >= floor]
        return hits[: max(1, int(limit))]

    def import_dream_logs(
        self,
        *,
        dream_logs_dir: Optional[str] = None,
        agent_id: Optional[str] = None,
        created_by: str = "dream-log-import",
        embed: bool = True,
        qdrant_url: Optional[str] = None,
        vector_writer: Optional[Any] = None,
        dry_run: bool = False,
    ) -> JsonDict:
        """Merge the gateway's orphaned ``~/.hermes/dream_logs`` reports into
        durable ``memory_records`` (record_type ``dream:imported_report``).

        No first-party reader consumes ``dream_logs`` today, so that learning
        never reached MAC's durable store; this consolidates it. Each imported
        memory is ``subject_type='dream'`` and, when ``embed`` is set and a
        Qdrant URL is configured, is embedded into the medium tier so it becomes
        retrievable via :meth:`recall_dream_artifacts`. Idempotent; dedups on
        findings. Returns the importer's stable report dict.
        """
        from pathlib import Path as _Path

        from mac import dream_log_import as _dli

        if embed and vector_writer is None and not dry_run:
            url = _configured_qdrant_url(qdrant_url)
            if url:
                from mac.vector_writer_service import VectorWriterService

                vector_writer = VectorWriterService(memory=self.memory, qdrant_url=url)
        return _dli.import_dream_logs(
            self,
            dream_logs_dir=_Path(dream_logs_dir) if dream_logs_dir else None,
            agent_id=agent_id,
            created_by=created_by,
            vector_writer=vector_writer,
            dry_run=dry_run,
        )

    def run_nap_cycle(
        self,
        agent_id: str,
        *,
        actor: Optional[str] = None,
        vector_writer: Optional[Any] = None,
        embed_into_medium: bool = True,
        emit_dream_artifacts: bool = True,
        promote_into_long: bool = True,
    ) -> JsonDict:
        """mem-08 autonomy: drive an agent through one full nap.

        Sequence:
          1. begin_nap (agent → DRAINING, nap_run created)
          2. consolidate (summarize since last nap, embed into medium)
          3. promote settled medium memories into the long tier
          4. complete_nap (agent → IDLE, nap_run completed)

        Neither consolidation nor completion is allowed to escape once
        begin_nap has moved the agent to DRAINING: a step-2 failure is
        captured in ``consolidation_error`` and a step-3 failure in
        ``complete_error``, and the agent's resolved state is always
        refetched and reported. A leaking exception here would strand
        the agent in DRAINING, which is much worse than a missing
        summary, so this method never re-raises after the nap begins.

        If begin_nap itself refuses (e.g. the agent holds an active
        lease — it's mid-task, not nappable right now), the cycle is
        reported as ``skipped`` rather than raising. This keeps the
        autonomous nap-tick from failing its whole batch over one busy
        agent; the next tick retries once the agent is free.
        """
        try:
            run = self.begin_nap(agent_id, actor=actor)
        except ValidationError as exc:
            return {
                "nap_run": None,
                "skipped": True,
                "skip_reason": str(exc),
                "consolidation": {},
                "consolidation_error": None,
                "repair_tasks": {},
                "repair_task_error": None,
                "complete_error": None,
            }
        consolidation_report: JsonDict = {}
        consolidation_error: Optional[str] = None
        repair_task_report: JsonDict = {}
        repair_task_error: Optional[str] = None
        dream_report: JsonDict = {}
        dream_error: Optional[str] = None
        promotion_report: JsonDict = {}
        promotion_error: Optional[str] = None
        complete_error: Optional[str] = None
        completed = run
        try:
            try:
                consolidation_report = self.consolidate_nap(
                    agent_id,
                    nap_run_id=run.id,
                    embed_into_medium=embed_into_medium,
                    # The legacy dreamer appended a dream:failure_pattern row
                    # per group per nap. mac.dreaming replaces it and writes to
                    # a reviewable candidate store instead, so it stays off.
                    emit_dream_artifacts=False,
                    vector_writer=vector_writer,
                    created_by=actor or "nap-cycle:%s" % agent_id,
                )
            except Exception as exc:  # noqa: BLE001
                consolidation_error = str(exc)
            if consolidation_error is None and emit_dream_artifacts:
                try:
                    dream_report = self.run_dream_cycle(
                        agent_id=agent_id,
                        actor=actor or "nap-cycle:%s" % agent_id,
                    )
                except Exception as exc:  # noqa: BLE001
                    dream_error = str(exc)
            # Long-tier promotion rides the nap because the nap is the only
            # thing that already runs on a schedule and already holds a
            # vector writer. Giving it its own timer would repeat the mistake
            # that killed ingestion on 2026-07-25: a second scheduled thing
            # nobody remembers to migrate.
            if vector_writer is not None and promote_into_long:
                try:
                    promotion_report = self.promote_memory_tier(
                        vector_writer=vector_writer,
                        created_by=actor or "nap-cycle:%s" % agent_id,
                    )
                except Exception as exc:  # noqa: BLE001
                    promotion_error = str(exc)
        finally:
            # Always attempt to complete the nap so the agent returns to
            # IDLE, even when consolidation threw. A completion failure
            # (anything other than the benign off-path TransitionError)
            # is recorded rather than re-raised so the agent isn't left
            # stranded in DRAINING by a propagating exception.
            try:
                completed = self.complete_nap(
                    run.id,
                    summary_evidence_id=None,
                    detail={
                        "consolidation": consolidation_report,
                        "consolidation_error": consolidation_error,
                        "dream": dream_report,
                        "dream_error": dream_error,
                        "promotion": promotion_report,
                        "promotion_error": promotion_error,
                    },
                    actor=actor,
                )
            except TransitionError:
                # An off-path actor already completed/failed the run
                # (e.g., an admin cancelled mid-cycle). Refetch and
                # report; not an error from this cycle's perspective.
                completed = self._safe_get_nap_run(run.id, run)
            except Exception as exc:  # noqa: BLE001
                complete_error = str(exc)
                completed = self._safe_get_nap_run(run.id, run)
        return {
            "nap_run": completed.to_dict(),
            "skipped": False,
            "consolidation": consolidation_report,
            "consolidation_error": consolidation_error,
            "dream": dream_report,
            "dream_error": dream_error,
            "promotion": promotion_report,
            "promotion_error": promotion_error,
            # Retained so existing callers keep parsing; the low-confidence
            # repair-task filer it reported on is gone. Of the 1,259 tasks it
            # filed in production, 4 completed.
            "repair_tasks": repair_task_report,
            "repair_task_error": repair_task_error,
            "complete_error": complete_error,
        }

    def run_dream_cycle(
        self,
        *,
        agent_id: Optional[str] = None,
        project: Optional[str] = None,
        since: str = "",
        limit: int = 2000,
        actor: str = "dreaming",
        policy: Optional[Any] = None,
        auto_promote: Optional[bool] = None,
        vector_writer: Optional[Any] = None,
    ) -> JsonDict:
        """Run one dream and persist the resulting candidate store.

        The run lands in ``dream_runs``/``dream_candidate_entries`` first, so a
        bad dream can be discarded rather than cleaned out of live memory
        afterwards.

        ``auto_promote`` closes the learning loop: a run that passed *every*
        gate is adopted immediately, writing ``dream_memory:*`` records and
        retiring the rows they supersede. A quarantined run is never promoted.
        Leaving it ``None`` reads ``MAC_DREAM_AUTO_PROMOTE`` (default on), so
        the behaviour can be switched off on a live fleet by setting that to
        ``0`` and restarting, without a redeploy.
        """

        from mac import dreaming

        # Boundary validation: callers reach this over the CLI and the API, so
        # accept a DreamPolicy or a plain mapping and reject anything else
        # rather than failing later on an attribute access.
        if policy is None:
            dream_policy = dreaming.DreamPolicy()
        elif isinstance(policy, dreaming.DreamPolicy):
            dream_policy = policy
        elif isinstance(policy, Mapping):
            try:
                dream_policy = dreaming.DreamPolicy(**dict(policy))
            except TypeError as exc:
                raise ValidationError("invalid dream policy: %s" % exc) from exc
        else:
            raise ValidationError(
                "policy must be a DreamPolicy or mapping, got %s"
                % type(policy).__name__
            )
        records = dreaming.load_records(
            self.store, project=project, agent_id=agent_id, since=since, limit=limit
        )
        # Prior promoted memories go in as state to revise, not as evidence.
        existing = dreaming.load_existing_memories(self.store, project=project)
        # Transcripts are the primary material a dream mines. Passing an empty
        # list here showed the extractor "(no transcripts supplied)", and 49
        # consecutive production runs returned nothing as a result.
        sessions = dreaming.load_sessions(self.store, agent_id=agent_id, since=since)
        model, caller = dreaming.resolve_model_caller()
        result = dreaming.dream(
            records,
            sessions,
            existing=existing,
            policy=dream_policy,
            model=model,
            model_caller=caller,
        )
        dreaming.save_run(
            self.store,
            result,
            dream_policy,
            agent_id=agent_id,
            project=project,
            created_by=actor,
            input_record_count=len(records),
            input_session_count=len(sessions),
        )
        report = result.to_dict()
        report["promotion"] = None
        # Bound the run history. The nap cycle calls this per agent per nap, so
        # an unpruned audit trail would become the next 154k table.
        try:
            report["prune"] = dreaming.prune_runs(self.store)
        except Exception as exc:  # noqa: BLE001 - pruning is maintenance, not the run
            report["prune"] = {"error": str(exc)[:300]}
        if auto_promote is None:
            from mac.env_config import env_bool

            auto_promote = env_bool("MAC_DREAM_AUTO_PROMOTE", default=True)
        if auto_promote and result.state is dreaming.StoreState.READY_FOR_REVIEW:
            # Only a run that cleared every gate reaches this branch; a
            # quarantined one stays put for inspection.
            try:
                report["promotion"] = dreaming.promote_run(
                    self.store,
                    self.memory,
                    result.run_id,
                    actor=actor,
                    vector_writer=vector_writer,
                )
            except Exception as exc:  # noqa: BLE001 - a failed adopt is not a failed dream
                report["promotion"] = {"error": str(exc)[:300]}
        return report

    def promote_dream_run(
        self,
        run_id: str,
        *,
        actor: str = "dreaming",
        vector_writer: Optional[Any] = None,
        retire_superseded: bool = True,
    ) -> JsonDict:
        """Adopt a reviewed dream run into live memory."""

        from mac import dreaming

        return dreaming.promote_run(
            self.store,
            self.memory,
            run_id,
            actor=actor,
            retire_superseded=retire_superseded,
            vector_writer=vector_writer,
        )

    def get_dream_run(self, run_id: str) -> Optional[JsonDict]:
        from mac import dreaming

        return dreaming.get_run(self.store, run_id)

    def list_dream_runs(
        self, *, state: Optional[str] = None, limit: int = 20
    ) -> List[JsonDict]:
        from mac import dreaming

        return dreaming.list_runs(self.store, state=state, limit=limit)

    def discard_dream_run(self, run_id: str, *, reason: str = "") -> JsonDict:
        from mac import dreaming

        return dreaming.discard_run(self.store, run_id, reason=reason)

    def _safe_get_nap_run(self, run_id: str, fallback: NapRun) -> NapRun:
        """Refetch a nap_run for reporting in an error path, falling
        back to a known run object if even the read fails — so
        run_nap_cycle never re-raises after the nap has begun."""
        try:
            return self.get_nap_run(run_id)
        except Exception:  # noqa: BLE001
            return fallback

    def list_due_nap_agents(self, *, as_of: Optional[str] = None) -> List[JsonDict]:
        """Return enabled nap_schedules whose current window has opened
        and hasn't been completed yet.

        An agent's "current window" is the current cadence bucket start plus
        ``offset_minutes`` (or the previous bucket if this bucket has not
        opened yet).
        We consider it open when `as_of` >= window_start, and unclaimed
        when last_completed_at is either NULL or before window_start.

        Selection is deliberately catch-up, not strict: an agent stays
        due from window_start until it actually completes a nap, even
        once `as_of` has passed window_end. ``window_minutes`` therefore
        does NOT gate the autonomous path — it only sets how long the
        informational ``in_window`` flag stays true. This keeps the
        hourly nap robust against a tick that lands just after a
        narrow window closes (a strict in-window check would silently
        skip the agent for the whole cycle). Callers that want strict
        windowing should filter on ``in_window`` themselves.
        """
        from datetime import datetime, timedelta, timezone

        as_of_dt = (
            datetime.fromisoformat(as_of)
            if as_of
            else datetime.now(timezone.utc)
        )
        if as_of_dt.tzinfo is None:
            as_of_dt = as_of_dt.replace(tzinfo=timezone.utc)
        rows = self.store.query_all(
            """
            SELECT agent_id, offset_minutes, window_minutes, last_completed_at
            FROM nap_schedules WHERE enabled = 1
            """
        )
        due: List[JsonDict] = []
        for row in rows:
            offset = int(row["offset_minutes"] or 0) % NAP_WINDOW_MINUTES
            window = int(row["window_minutes"] or 15)
            day_start = as_of_dt.replace(hour=0, minute=0, second=0, microsecond=0)
            elapsed_minutes = int((as_of_dt - day_start).total_seconds() // 60)
            cycle_minutes = (
                elapsed_minutes // NAP_WINDOW_MINUTES
            ) * NAP_WINDOW_MINUTES
            window_start = day_start + timedelta(minutes=cycle_minutes + offset)
            if window_start > as_of_dt:
                window_start = window_start - timedelta(minutes=NAP_WINDOW_MINUTES)
            window_end = window_start + timedelta(minutes=window)
            already_done = False
            if row["last_completed_at"]:
                try:
                    last_dt = datetime.fromisoformat(row["last_completed_at"])
                    if last_dt.tzinfo is None:
                        last_dt = last_dt.replace(tzinfo=timezone.utc)
                    if last_dt >= window_start:
                        already_done = True
                except (TypeError, ValueError):
                    pass
            if already_done:
                continue
            due.append(
                {
                    "agent_id": row["agent_id"],
                    "window_start": window_start.isoformat(timespec="microseconds"),
                    "window_end": window_end.isoformat(timespec="microseconds"),
                    "last_completed_at": row["last_completed_at"],
                    "in_window": window_start <= as_of_dt <= window_end,
                }
            )
        return due

    def consolidate_nap(
        self,
        agent_id: str,
        *,
        since: Optional[str] = None,
        nap_run_id: Optional[str] = None,
        embed_into_medium: bool = True,
        emit_dream_artifacts: bool = True,
        vector_writer: Optional[Any] = None,
        created_by: Optional[str] = None,
    ) -> JsonDict:
        """mem-08: build per-(task/project) summaries from the agent's
        recent memory_records and embed them into the medium tier.

        ``vector_writer`` is an optional pre-built VectorWriterService.
        When None, no embedding happens (consolidator runs in
        summary-only mode — useful when Qdrant is unreachable)."""
        from mac.nap_consolidator import NapConsolidatorService

        consolidator = NapConsolidatorService(
            store=self.store,
            memory=self.memory,
            vector_writer=vector_writer,
        )
        return consolidator.consolidate_agent(
            agent_id,
            since=since,
            nap_run_id=nap_run_id,
            embed_into_medium=embed_into_medium,
            emit_dream_artifacts=emit_dream_artifacts,
            created_by=created_by,
        )

    def _vector_writer_for(
        self, vector_writer: Optional[Any], qdrant_url: Optional[str], caller: str
    ) -> Any:
        """Reuse a caller's writer, or build one from the Qdrant cascade."""

        if vector_writer is not None:
            return vector_writer
        url = _configured_qdrant_url(qdrant_url)
        if not url:
            raise ValidationError(
                "%s needs a Qdrant URL — pass qdrant_url or set "
                "MAC_QDRANT_URL/QDRANT_URL/QDRANT_ADDRESS/QDRANT_FLEET_URL" % caller
            )
        from mac.vector_writer_service import VectorWriterService

        return VectorWriterService(memory=self.memory, qdrant_url=url)

    def reconcile_memory_embedding_spaces(
        self,
        *,
        tier: str = "medium",
        limit: Optional[int] = None,
        scan_limit: Optional[int] = None,
        dry_run: bool = False,
        report_only: bool = False,
        qdrant_url: Optional[str] = None,
        vector_writer: Optional[Any] = None,
        created_by: str = "memory-reconcile",
    ) -> JsonDict:
        """Collapse a tier onto one embedding model.

        A model switch left ``mac_memory_medium`` holding 601 points from one
        embedder and 66 from another. Qdrant compares them anyway — same
        dimension, incommensurable spaces — so similarity search returned
        wrong neighbours and raised nothing. Re-embedding the minority through
        the normal write path restores a single comparable space.
        """

        writer = self._vector_writer_for(
            vector_writer, qdrant_url, "reconcile_memory_embedding_spaces"
        )
        if report_only:
            return writer.embedding_space_report(tier=tier, scan_limit=scan_limit)
        return writer.reconcile_embedding_spaces(
            tier=tier,
            limit=limit,
            scan_limit=scan_limit,
            dry_run=dry_run,
            created_by=created_by,
        )

    def promote_memory_tier(
        self,
        *,
        vector_writer: Optional[Any] = None,
        qdrant_url: Optional[str] = None,
        min_age_days: Optional[float] = None,
        limit: Optional[int] = None,
        drop_medium: bool = False,
        dry_run: bool = False,
        created_by: str = "memory-promotion",
    ) -> JsonDict:
        """Promote settled medium-tier memories into ``mac_memory_long``.

        The long tier was declared in mem-06 and had never received a point:
        no code path anywhere passed ``tier="long"`` to the vector writer, so
        the collection advertised a capability the fleet did not have. This is
        the writer. See :mod:`mac.memory_promotion` for what "settled" means.

        Returns a report even when nothing qualified, so a caller can tell
        "ran and found nothing old enough" from "did not run".
        """

        from mac.memory_promotion import (
            MemoryPromotionService,
            promotion_settings,
        )

        settings = promotion_settings()
        if not settings["enabled"]:
            return {
                "schema": "mac.memory_promotion.v1",
                "skipped": True,
                "skip_reason": "MAC_MEMORY_PROMOTION_ENABLED is off",
                "candidates": 0,
                "promoted": 0,
            }
        service = MemoryPromotionService(
            memory=self.memory,
            vector_writer=self._vector_writer_for(
                vector_writer, qdrant_url, "promote_memory_tier"
            ),
        )
        report = service.promote(
            min_age_days=(
                settings["min_age_days"] if min_age_days is None else float(min_age_days)
            ),
            limit=settings["max_per_pass"] if limit is None else limit,
            drop_medium=drop_medium,
            dry_run=dry_run,
            created_by=created_by,
        )
        report["skipped"] = False
        if settings["configuration_errors"]:
            report["configuration_errors"] = settings["configuration_errors"]
        return report

    def complete_nap(self, *args: Any, **kwargs: Any) -> NapRun:
        return self.agent_state.complete_nap(*args, **kwargs)

    def fail_nap(self, *args: Any, **kwargs: Any) -> NapRun:
        return self.agent_state.fail_nap(*args, **kwargs)

    def get_nap_run(self, run_id: str) -> NapRun:
        return self.agent_state.get_nap_run(run_id)

    def list_nap_runs(self, *args: Any, **kwargs: Any) -> List[NapRun]:
        return self.agent_state.list_nap_runs(*args, **kwargs)

