    def _record_claim_next_log_best_effort(
        self,
        name: str,
        *,
        agent_id: str,
        task_id: str,
        detail: JsonDict,
    ) -> None:
        """Keep post-claim telemetry from stranding an already leased task."""
        try:
            self.record_log(
                name,
                layer="control_plane",
                source=agent_id,
                subject_type="task",
                subject_id=task_id,
                detail=detail,
            )
        except Exception:
            pass

    def _send_claim_next_nudge_best_effort(
        self,
        agent_id: str,
        task_id: str,
        lease_id: str,
    ) -> None:
        """Dispatcher nudges are advisory; the claim response is authoritative."""
        try:
            self.send_message(
                "dispatcher",
                agent_id,
                MessageType.NUDGE.value,
                {"task_id": task_id, "lease_id": lease_id, "reason": "worker_claimed"},
                task_id=task_id,
            )
        except Exception:
            pass

    def _active_assignment_for_agent(self, agent: Agent) -> Optional[JsonDict]:
        """Return the authoritative assignment a loop worker must resume.

        Push dispatch claims the task before the worker's next polling turn.
        Looking only for OPEN work at claim-next time therefore loses the one
        assignment the worker already owns.  Resolve it from the active lease
        and task rows, preferring ``current_task_id`` when capacity permits an
        agent to hold more than one lease.
        """
        if agent.status not in {AgentStatus.IDLE.value, AgentStatus.BUSY.value}:
            return None
        row = self.store.query_one(
            """
            SELECT l.id AS lease_id, t.id AS task_id
            FROM leases l
            JOIN tasks t ON t.lease_id = l.id
            WHERE l.agent_id = ?
              AND l.status = ?
              AND t.owner_agent_id = ?
              AND t.state IN (?, ?)
            ORDER BY CASE WHEN t.id = ? THEN 0 ELSE 1 END,
                     l.created_at, l.id
            LIMIT 1
            """,
            (
                agent.id,
                LeaseStatus.ACTIVE.value,
                agent.id,
                TaskState.CLAIMED.value,
                TaskState.RUNNING.value,
                agent.current_task_id or "",
            ),
        )
        if row is None:
            return None
        task = self.get_task(str(row["task_id"]))
        lease = self.get_lease(str(row["lease_id"]))
        return {
            "task": self._assignment_task_payload(task, lease),
            "agent": self.get_agent(agent.id).to_dict(),
            "lease": lease.to_dict(),
            "resumed": True,
        }

    def tick(
        self,
        lease_seconds: int = 900,
        limit: int = 100,
        stale_after_seconds: Optional[int] = None,
    ) -> JsonDict:
        assignment_limit = max(0, min(int(limit), 1000))
        limit_value = max(1, assignment_limit)
        stale_agents = []
        if stale_after_seconds is not None:
            stale_agents = [
                agent.to_dict()
                for agent in self.mark_stale_agents_offline(stale_after_seconds)
            ]
        try:
            expired_ephemerals = [
                agent.to_dict()
                for agent in self.expire_ephemeral_agents(limit=limit_value)
            ]
        except Exception as exc:  # noqa: BLE001 - expiry must never stop dispatch.
            expired_ephemerals = []
            self.record_log(
                "agent.ephemeral.expiry_tick_failed",
                layer="control_plane",
                source="dispatcher.tick",
                level="error",
                detail={"error": str(exc)[:500]},
            )
        expired_page = self._expire_leases_sweep_page(limit=limit_value)
        expired = [task.to_dict() for task in expired_page["tasks"]]
        try:
            workflow_runs = [
                run.to_dict()
                for run in self.workflow_runtime.tick(
                    actor="dispatcher.tick",
                    limit=limit_value,
                )
            ]
        except Exception as exc:  # noqa: BLE001 - one workflow must not stop fleet dispatch.
            workflow_runs = []
            self.record_log(
                "workflow.recovery.failed",
                layer="control_plane",
                source="dispatcher.tick",
                level="error",
                detail={"error": str(exc)},
            )
        try:
            self.reconcile_service_roles()  # media-01: reap stale claims + signal zero-holder ops
        except Exception:  # noqa: BLE001 - reconcile must never break the tick
            pass
        unblocked_page = self._unblock_ready_sweep_page(limit=limit_value)
        auto_retry_page = self._auto_retry_blocked_attempts_sweep_page(
            limit=limit_value
        )
        # Retention runs HERE -- before the review sweep -- and not further down,
        # because the sweep below can block this thread for minutes while it
        # clones a repository and runs a contract gate. Retention used to sit
        # after it and was therefore starved: observed live on 2026-08-17, the
        # hub emitted ZERO retention events in the 48 minutes after a restart
        # while 235,615 observability_events and 5,576 action_events sat past
        # the 7-day cutoff.
        #
        # That failure is invisible by construction. `prune()` deliberately
        # stays silent when there is nothing to do (so the audit row never
        # becomes the retained data), so "retention is alive with no work" and
        # "retention is never reached" look identical from outside -- which is
        # how the store previously grew to 16GB / 10.4M rows while retention was
        # believed to be wired. See the `retention.tick_ran` heartbeat below.
        #
        # Retention is cheap and bounded (max_batches x batch_size rows), so
        # running it first costs the sweep nothing.
        try:
            retention_pruned = self.retention_prune_tick()
        except Exception as exc:  # noqa: BLE001 - retention must never stop dispatch.
            retention_pruned = {"errors": [{"error": str(exc)[:500]}]}
            self.record_log(
                "retention.prune_tick_failed",
                layer="control_plane",
                source="dispatcher.tick",
                level="error",
                detail={"error": str(exc)[:500]},
            )
        # The tick is the RIGHT place to run a publication's contract gate, and
        # for a long time it was the only place that refused to.
        #
        # With this False, the tick advanced reviews but would not run the
        # verify, so the only path that actually published was
        # _maybe_advance_reviews_on_heartbeat -- an agent HTTP request. That
        # made a heartbeat take 250-315s (measured; the agent's own client gives
        # up at 30s and retries, starting ANOTHER overlapping publication), and
        # three approved canaries sat unpublished for hours because the one
        # worker whose heartbeat drives it could not finish a request.
        #
        # This loop is a background thread (api.py `_loop`), not a request
        # handler. Blocking here delays the next tick; blocking on a heartbeat
        # costs a worker. MAC_TICK_BLOCKING_HUB_VERIFY=0 restores the old
        # behaviour for an operator who would rather the tick never stall.
        #
        # This is the narrow version of task_fad95a2b. The full fix is a bounded
        # publication worker so neither the tick nor a request waits on a
        # sandboxed test run.
        # The review sweep is NOT run here any more. It clones a repository and
        # runs a contract gate inline, so it used to make this thread's period
        # equal to a git clone plus a test run rather than
        # MAC_HUB_TICK_INTERVAL_SECONDS. Measured on the live hub: a manual
        # POST /dispatch/tick did not return within 120 seconds.
        #
        # Everything ordered after it inherited that period. Retention was the
        # stage that got measured -- it emitted ZERO events in 48 minutes while
        # sitting behind this call (#392), and even after being moved ahead of
        # it ran only once per tick (#393), which is why it ended up on its own
        # timer. Retention was not special; every later stage had the same
        # problem, silently.
        #
        # It now runs on a dedicated worker (api._start_publication_worker) on
        # its own interval. `_advance_default_review_sweep_page` already
        # serialises through `reconciliation.claim("default-review-sweep")`, so
        # a single worker is strictly safer than the previous arrangement,
        # where the tick thread AND any worker's heartbeat thread could both
        # enter the sweep and contend for that claim.
        #
        # Set MAC_TICK_RUNS_REVIEW_SWEEP=1 to restore the inline behaviour for
        # an operator who would rather the tick own it.
        if _truthy_env("MAC_TICK_RUNS_REVIEW_SWEEP", "0"):
            review_workflows = self._advance_default_review_sweep_page(
                limit=limit_value,
                actor="default-review-workflow",
                tenant_id=None,
                allow_blocking_hub_verify=_truthy_env(
                    "MAC_TICK_BLOCKING_HUB_VERIFY", "1"
                ),
            )
        else:
            review_workflows = {"skipped": "runs_on_publication_worker"}
        # Stranding episodes were only ever created inside task_flow.report(),
        # whose callers are the CLI, the HTTP route and two facades -- no
        # scheduler. docs/task-throughput-observability.md describes an episode
        # that "opens once per task/attempt/stage and is updated until progress
        # resolves it", but nothing opened one unless a human ran
        # `mac task throughput`. On 2026-07-31 the detector had 312 unresolved
        # episodes and had not run for 30 hours while the fleet was stalled.
        # Drive it from the hub's own clock so the detector observes the fleet
        # rather than the operator.
        try:
            self.task_flow.report(
                project=None,
                since_hours=_task_flow_tick_since_hours(),
                refresh_limit=limit_value,
            )
        except Exception as exc:  # noqa: BLE001 - diagnostics must never stop the tick.
            self.record_log(
                "task_flow.tick_failed",
                layer="control_plane",
                level="warning",
                detail={"error": str(exc)[:500]},
            )
        # Desired-source holds must land before dispatch.  Otherwise a stale
        # idle node can acquire new work in the same tick that notices drift.
        try:
            source_convergence = self.source_convergence.tick(limit=limit_value)
        except Exception as exc:  # noqa: BLE001 - controller failure must not stop lease maintenance.
            source_convergence = {
                "schema": "mac.source_convergence.v1",
                "errors": [{"error": str(exc)[:500]}],
            }
            self.record_log(
                "source_convergence.tick_failed",
                layer="control_plane",
                source="dispatcher.tick",
                level="error",
                detail={"error": str(exc)[:500]},
            )
        try:
            crash_repairs = self.crashes.tick(limit=limit_value)
        except Exception as exc:  # noqa: BLE001 - crash repair must not stop dispatch.
            crash_repairs = {
                "schema": "mac.agent_crash_repair_tick.v1",
                "errors": [{"error": str(exc)[:500]}],
            }
            self.record_log(
                "agent.crash.repair_tick_failed",
                layer="control_plane",
                source="dispatcher.tick",
                level="error",
                detail={"error": str(exc)[:500]},
            )
        assignments = (
            self._dispatch_batch_impl(
                lease_seconds=lease_seconds,
                limit=assignment_limit,
                run_maintenance=False,
            )
            if assignment_limit
            else []
        )
        dead_letters_page = self.list_dead_letters_page(limit=limit_value)
        return {
            "stale_agents": stale_agents,
            "expired_ephemeral_agents": expired_ephemerals,
            "expired": expired,
            "workflow_runs": workflow_runs,
            "review_workflows": review_workflows,
            "source_convergence": source_convergence,
            "crash_repairs": crash_repairs,
            "retention_pruned": retention_pruned,
            "auto_reopened": [
                task.to_dict() for task in auto_retry_page["tasks"]
            ],
            "auto_retry_exhausted": [
                task.to_dict() for task in auto_retry_page.get("exhausted", [])
            ],
            "assignments": assignments,
            "dead_letters": [
                task.to_dict() for task in dead_letters_page["tasks"]
            ],
            "maintenance": {
                "expired_leases_has_more": expired_page["has_more"],
                "blocked_tasks_has_more": unblocked_page["has_more"],
                "blocked_attempt_retries_has_more": auto_retry_page["has_more"],
                "blocked_attempt_retries_next_cursor": auto_retry_page["next_cursor"],
                "dead_letters_has_more": dead_letters_page["has_more"],
                "dead_letters_next_cursor": dead_letters_page["next_cursor"],
            },
        }

