    # Human directives: the hub-verified human->agent channel. Authority is
    # attested provenance — the API layer refuses agent-bound tokens on this
    # topic, so receipt of one IS proof of operator origin. This is how a
    # human reaches an agent with no chat identity (Slack-less GKE runners,
    # ephemeral session agents): the mirror image of the delivery outbox.

    OPERATOR_PERSONA_AGENT_ID = "agent_operator"

    def _ensure_operator_persona(self) -> Agent:
        try:
            agent = self.get_agent(self.OPERATOR_PERSONA_AGENT_ID)
            if not agent.deleted_at:
                return agent
        except NotFoundError:
            pass
        try:
            machine = self.get_machine("machine_operator_persona")
        except NotFoundError:
            machine = self.register_machine(
                "operator-persona",
                machine_id="machine_operator_persona",
                labels={"virtual": True},
            )
        return self.register_agent(
            machine.id,
            "operator",
            agent_id=self.OPERATOR_PERSONA_AGENT_ID,
            resources={"virtual": True, "operator_persona": True},
        )

    def _task_scoped_directive_ownership(
        self, task_id: str, target_agent_id: str
    ) -> "TaskOwnershipVerdict":
        """Evaluate whether *target* owns a current lease for *task_id*.

        Pure decision (mac.executor_directive.task_ownership_verdict) fed from
        the tasks row so the hub and the worker apply one contract. Fails
        closed with a structured status for a missing task, a task with no
        active executor lease, an agent/task mismatch, or an expired lease.
        """
        from mac.executor_directive import task_ownership_verdict

        try:
            task = self.get_task(task_id)
            found = True
            state = task.state
            owner = task.owner_agent_id
            lease_id = task.lease_id
            leased_until = task.leased_until
        except NotFoundError:
            found = False
            state = None
            owner = None
            lease_id = None
            leased_until = None
        return task_ownership_verdict(
            task_id=task_id,
            target_agent_id=target_agent_id,
            task_found=found,
            task_state=state,
            owner_agent_id=owner,
            lease_id=lease_id,
            leased_until=leased_until,
            now=datetime.now(timezone.utc),
        )

    def publish_human_directive(
        self,
        target_agent_id: str,
        message: str,
        *,
        issued_by: str = "human",
        correlation_id: Optional[str] = None,
        task_id: Optional[str] = None,
    ) -> JsonDict:
        from mac.agentbus_service import (
            HUMAN_DIRECTIVE_CONTENT_TYPE,
            HUMAN_DIRECTIVE_SCHEMA,
            HUMAN_DIRECTIVE_TOPIC,
        )
        from mac.executor_directive import (
            DELIVERY_TARGET_EXECUTOR,
            DELIVERY_TARGET_HEADER,
            DELIVERY_TARGET_PERSONA,
            EXECUTOR_SCOPED_HEADER,
        )

        body = str(message or "").strip()
        if not body:
            raise ValidationError("human directive message is required")
        target = self._require_live_agent(target_agent_id)

        # Task-scoped path (task_60be): when a structured task id is supplied
        # the hub validates that the target agent owns a CURRENT lease for that
        # task before minting an executor-scoped directive. This fails closed
        # (ValidationError) rather than publishing a directive the executor can
        # never own — the exact silent-mis-delivery the incident describes.
        ownership = None
        resolved_task_id = None
        if task_id:
            ownership = self._task_scoped_directive_ownership(task_id, target.id)
            if not ownership.deliverable:
                raise ValidationError(
                    "task-scoped directive not deliverable (%s): %s"
                    % (ownership.status, ownership.reason or "")
                )
            resolved_task_id = ownership.task_id

        persona = self._ensure_operator_persona()
        corr = (correlation_id or "").strip() or new_id("corr")
        headers = {"correlation_id": corr, "issued_by": issued_by}
        payload = {
            "schema": HUMAN_DIRECTIVE_SCHEMA,
            "message": body[:16000],
            "issued_by": issued_by,
            "correlation_id": corr,
            "to_agent_id": target.id,
        }
        if resolved_task_id:
            headers[EXECUTOR_SCOPED_HEADER] = "true"
            headers[DELIVERY_TARGET_HEADER] = DELIVERY_TARGET_EXECUTOR
            payload[EXECUTOR_SCOPED_HEADER] = True
            payload["task_id"] = resolved_task_id
            payload["delivery_target"] = DELIVERY_TARGET_EXECUTOR
        else:
            headers[DELIVERY_TARGET_HEADER] = DELIVERY_TARGET_PERSONA
            payload["delivery_target"] = DELIVERY_TARGET_PERSONA
        published = self.agentbus.publish(
            sender_agent_id=persona.id,
            recipient_agent_id=target.id,
            topic=HUMAN_DIRECTIVE_TOPIC,
            content_type=HUMAN_DIRECTIVE_CONTENT_TYPE,
            headers=headers,
            task_id=resolved_task_id,
            payload=payload,
        )
        self.record_log(
            "agentbus.human_directive.published",
            layer="agentbus",
            source=issued_by,
            subject_type="agentbus_stream",
            subject_id=published["stream"]["id"],
            detail={
                "target_agent_id": target.id,
                "issued_by": issued_by,
                "task_id": resolved_task_id,
                "executor_scoped": bool(resolved_task_id),
            },
        )
        result = {
            "schema": "mac.human.directive_publish.v1",
            "stream": published["stream"],
            "correlation_id": corr,
            "target_agent_id": target.id,
            "executor_scoped": bool(resolved_task_id),
            "task_id": resolved_task_id,
        }
        if ownership is not None:
            result["ownership"] = ownership.to_dict()
        return result

    def verify_human_directive(self, stream_id: str) -> JsonDict:
        """Confirm a cited stream is a genuine operator-minted human directive.

        Closes the relay-by-citation gap Natasha hit (2026-07-13): AGENTS.md
        tells agents to relay authority by citing a directive stream id and
        letting the receiver verify at the hub — but there was no way to
        verify. A directive is genuine iff its topic is human.directive.v1
        AND its sender is the reserved operator persona; the API layer refuses
        agent tokens minting that topic, so those two facts together are proof
        of operator origin. Any agent may call this (directives are
        fleet-readable), which is exactly what relay-by-citation needs.
        """
        from mac.agentbus_service import HUMAN_DIRECTIVE_TOPIC

        try:
            stream = self.get_agentbus_stream(stream_id)
        except NotFoundError:
            return {
                "schema": "mac.human.directive_verification.v1",
                "stream_id": stream_id,
                "verified": False,
                "reason": "no such stream",
            }
        genuine = (
            stream.topic == HUMAN_DIRECTIVE_TOPIC
            and stream.sender_agent_id == self.OPERATOR_PERSONA_AGENT_ID
        )
        if not genuine:
            return {
                "schema": "mac.human.directive_verification.v1",
                "stream_id": stream_id,
                "verified": False,
                "reason": "stream is not an operator-minted human directive",
            }
        from mac.executor_directive import (
            DELIVERY_TARGET_HEADER,
            EXECUTOR_SCOPED_HEADER,
        )

        payload = None
        chunks = self.read_agentbus_chunks(
            self.OPERATOR_PERSONA_AGENT_ID, stream_id, limit=1
        )
        if chunks and isinstance(chunks[0].payload, dict):
            payload = chunks[0].payload
        headers = stream.headers or {}
        executor_scoped = str(headers.get(EXECUTOR_SCOPED_HEADER) or "").lower() == "true"
        result = {
            "schema": "mac.human.directive_verification.v1",
            "stream_id": stream_id,
            "verified": True,
            "issued_by": str(headers.get("issued_by") or "human"),
            "target_agent_id": stream.recipient_agent_id,
            "message": str((payload or {}).get("message") or ""),
            "created_at": stream.created_at,
            "task_id": stream.task_id,
            "executor_scoped": executor_scoped,
            "delivery_target": str(
                headers.get(DELIVERY_TARGET_HEADER)
                or ("executor" if executor_scoped else "persona")
            ),
        }
        # For an executor-scoped directive, re-assert ownership at verify time
        # so a lease that expired between publish and consume fails closed on
        # the worker side too.
        if executor_scoped and stream.task_id and stream.recipient_agent_id:
            ownership = self._task_scoped_directive_ownership(
                stream.task_id, stream.recipient_agent_id
            )
            result["ownership"] = ownership.to_dict()
            result["deliverable_to_executor"] = ownership.deliverable
        return result

    def set_agentbus_consumer_cursor(self, *args: Any, **kwargs: Any) -> JsonDict:
        return self.agentbus.set_consumer_cursor(*args, **kwargs)

    def get_agentbus_consumer_cursor(
        self, *args: Any, **kwargs: Any
    ) -> Optional[JsonDict]:
        return self.agentbus.get_consumer_cursor(*args, **kwargs)

    def publish_agentbus_repo_update(
        self,
        sender_agent_id: str,
        recipient_agent_ids: Optional[List[str]] = None,
        *,
        all_agents: bool = False,
        repo_path: Optional[str] = None,
        remote: str = "origin",
        branch: str = "main",
        restart: bool = True,
        restart_services: Optional[List[str]] = None,
        request_id: Optional[str] = None,
        target_sha: Optional[str] = None,
        desired_generation: Optional[int] = None,
        release_id: Optional[str] = None,
    ) -> JsonDict:
        recipients = list(recipient_agent_ids or [])
        if all_agents:
            recipients.extend(agent.id for agent in self.list_agents())
        recipients = list(dict.fromkeys(item for item in recipients if item))
        if not recipients:
            raise ValidationError("repo-update requires recipient_agent_ids or all_agents=true")
        payload = repo_update_payload(
            repo_path=repo_path,
            remote=remote,
            branch=branch,
            restart=restart,
            restart_services=list(restart_services or []),
            request_id=request_id,
            target_sha=target_sha,
            desired_generation=desired_generation,
            release_id=release_id,
        )
        published = [
            self.publish_agentbus_content(
                sender_agent_id=sender_agent_id,
                recipient_agent_id=recipient_id,
                content_type=REPO_UPDATE_CONTENT_TYPE,
                topic=REPO_UPDATE_TOPIC,
                payload=payload,
            )
            for recipient_id in recipients
        ]
        return {
            "schema": "mac.agentbus.repo_update_publish.v1",
            "count": len(published),
            "streams": [item["stream"] for item in published],
        }

    def publish_agent_reflection(
        self,
        agent_id: str,
        *,
        recipient_agent_id: Optional[str] = None,
        request_id: Optional[str] = None,
        reflect_timeout: float = 30.0,
    ) -> JsonDict:
        agent = self.get_agent(agent_id)
        recipient_id = recipient_agent_id or agent.id
        self.get_agent(recipient_id)
        effective_request_id = request_id or ""
        payload = agent_reflection_payload(
            agent=agent.to_dict(),
            request_id=effective_request_id,
        )
        published = self.publish_agentbus_content(
            sender_agent_id=agent.id,
            recipient_agent_id=recipient_id,
            content_type=AGENT_REFLECTION_CONTENT_TYPE,
            topic=AGENT_REFLECTION_TOPIC,
            payload=payload,
        )
        # Send a runtime reflect request to the target agent over the AgentBus.
        # The agent worker processes this request through its own runtime and
        # publishes a REFLECT_RESULT_TOPIC response back to the requester.
        deep_query = (
            "Reflection request: in under 250 words describe (1) who you are "
            "per your soul/memory, (2) custom scripts, cron jobs, or local "
            "automation on YOUR host (~/.hermes and beyond) an operator should "
            "preserve, (3) anything in your memory worth migrating before the "
            "hermes runtime is retired. Be specific and factual; name files."
        )
        deep = self.publish_agentbus_content(
            sender_agent_id=recipient_id,
            recipient_agent_id=agent.id,
            content_type=REFLECT_REQUEST_CONTENT_TYPE,
            topic=REFLECT_REQUEST_TOPIC,
            payload={
                "schema": REFLECT_REQUEST_SCHEMA,
                "request_id": effective_request_id,
                "sender_agent_id": recipient_id,
                "query": deep_query,
            },
        )
        # Wait (with a bounded timeout) for the matching reflect result from
        # the target agent.  The result arrives as a REFLECT_RESULT_TOPIC
        # stream published FROM agent.id TO recipient_id.  When reflect_timeout
        # is 0 (or negative) we skip the wait entirely so tests and callers
        # that do not need the live narrative can avoid the blocking poll.
        narrative: Optional[str] = None
        if reflect_timeout > 0:
            deadline = time.monotonic() + reflect_timeout
            poll_interval = 0.1
            while time.monotonic() < deadline:
                try:
                    streams = self.list_agentbus_streams(agent_id=recipient_id)
                    for stream in streams:
                        if stream.topic != REFLECT_RESULT_TOPIC:
                            continue
                        if stream.sender_agent_id != agent.id:
                            continue
                        chunks = self.read_agentbus_chunks(recipient_id, stream.id)
                        for chunk in chunks:
                            chunk_payload = chunk.payload or {}
                            if not isinstance(chunk_payload, dict):
                                continue
                            # Match by request_id when one was supplied.
                            if effective_request_id:
                                if chunk_payload.get("request_id") != effective_request_id:
                                    continue
                            response = chunk_payload.get("response")
                            if isinstance(response, str) and response:
                                narrative = response
                                break
                        if narrative is not None:
                            break
                except Exception:  # noqa: BLE001 - polling must not crash the caller
                    pass
                if narrative is not None:
                    break
                time.sleep(poll_interval)
        payload["reflection"] = narrative
        return {
            "schema": "mac.agentbus.agent_reflection_publish.v1",
            "deep_request_stream": deep["stream"],
            "agent_id": agent.id,
            "recipient_agent_id": recipient_id,
            "count": 1,
            "streams": [published["stream"]],
            "payload": payload,
        }

    def publish_agentbus_artifact(
        self,
        sender_agent_id: str,
        operation: str = "upsert",
        recipient_agent_ids: Optional[List[str]] = None,
        all_agents: bool = False,
        artifact_id: Optional[str] = None,
        digest: Optional[str] = None,
        kind: str = "public-artifact",
        uri: Optional[str] = None,
        public_url: Optional[str] = None,
        path: Optional[str] = None,
        publish_dir: Optional[str] = None,
        sbom_uri: Optional[str] = None,
        signers: Optional[List[str]] = None,
        metadata: Optional[Dict[str, Any]] = None,
        task_id: Optional[str] = None,
        request_id: Optional[str] = None,
    ) -> JsonDict:
        self.get_agent(sender_agent_id)
        op = (operation or "upsert").strip().lower()
        if op == "create":
            op = "upsert"
        if op == "read":
            op = "get"
        if op not in {"upsert", "update", "get", "list", "delete"}:
            raise ValidationError("unsupported artifact publish operation: %s" % operation)

        configured_publish_dir = (
            publish_dir
            or os.environ.get("MAC_PUBLISH_DIR")
            or os.environ.get("MAC_WEBDAV_ROOT")
            or ""
        ).strip()
        configured_public_url = (
            public_url
            or os.environ.get("MAC_PUBLISH_PUBLIC_URL")
            or os.environ.get("MAC_PUBLISH_WEBDAV_URL")
            or os.environ.get("MAC_WEBDAV_PUBLIC_URL")
            or ""
        ).strip()
        if not public_url and configured_public_url and path:
            configured_public_url = "%s/%s" % (configured_public_url.rstrip("/"), path.strip("/"))
        else:
            configured_public_url = configured_public_url.rstrip("/")

        artifact: Optional[JsonDict] = None
        artifacts: Optional[List[JsonDict]] = None
        deleted: Optional[JsonDict] = None

        if op in {"upsert", "update"}:
            if not digest:
                raise ValidationError("artifact publish upsert requires digest")
            artifact_uri = (uri or configured_public_url or "").strip()
            if not artifact_uri:
                raise ValidationError("artifact publish upsert requires uri or public_url")
            merged_metadata = dict(metadata or {})
            if path:
                merged_metadata.setdefault("publish_path", path.strip("/"))
            if configured_publish_dir:
                merged_metadata.setdefault("publish_dir", configured_publish_dir)
            if configured_public_url:
                merged_metadata.setdefault("public_url", configured_public_url)
            artifact = self.register_artifact(
                kind,
                digest,
                artifact_uri,
                sender_agent_id,
                sbom_uri=sbom_uri,
                signers=signers or [],
                metadata=merged_metadata,
            ).to_dict()
        elif op == "get":
            key = artifact_id or digest
            if not key:
                raise ValidationError("artifact publish get requires artifact_id or digest")
            artifact = self.get_artifact(key).to_dict()
        elif op == "list":
            artifacts = [item.to_dict() for item in self.list_artifacts(kind or None)]
        elif op == "delete":
            key = artifact_id or digest
            if not key:
                raise ValidationError("artifact publish delete requires artifact_id or digest")
            deleted = self.delete_artifact(key, actor=sender_agent_id)
            artifact_value = deleted.get("artifact") if isinstance(deleted, dict) else None
            artifact = artifact_value if isinstance(artifact_value, dict) else None

        recipients = list(recipient_agent_ids or [])
        if all_agents:
            recipients.extend(agent.id for agent in self.list_agents())
        recipients = list(dict.fromkeys(item for item in recipients if item))
        streams: List[JsonDict] = []
        if recipients and op in {"upsert", "update", "delete"}:
            payload = artifact_publish_payload(
                operation=op,
                artifact=artifact,
                publish_dir=configured_publish_dir,
                public_url=configured_public_url,
                path=path,
                request_id=request_id,
            )
            streams = [
                self.publish_agentbus_content(
                    sender_agent_id=sender_agent_id,
                    recipient_agent_id=recipient_id,
                    content_type=ARTIFACT_PUBLISH_CONTENT_TYPE,
                    topic=ARTIFACT_PUBLISH_TOPIC,
                    payload=payload,
                    task_id=task_id,
                )["stream"]
                for recipient_id in recipients
            ]

        response: JsonDict = {
            "schema": "mac.agentbus.artifact_publish_crud.v1",
            "operation": op,
            "count": len(streams),
            "streams": streams,
        }
        if artifact is not None:
            response["artifact"] = artifact
        if artifacts is not None:
            response["artifacts"] = artifacts
        if deleted is not None:
            response["deleted"] = bool(deleted.get("deleted"))
        if configured_publish_dir:
            response["publish_dir"] = configured_publish_dir
        if configured_public_url:
            response["public_url"] = configured_public_url
        return response

    # Reviews + publication: thin facade over ``self.reviews``.

    def request_review(self, *args: Any, **kwargs: Any) -> Review:
        review = self.reviews.request_review(*args, **kwargs)
        actor = kwargs.get("actor")
        if actor is None and len(args) >= 3:
            actor = args[2]
        if actor is None:
            actor = "dispatcher"
        return review

    def claim_review(
        self,
        review_id: str,
        reviewer_agent_id: str,
        *,
        executor_evidence_id: Optional[str] = None,
        actor: str = "reviewer",
        sync_beads: bool = True,
    ) -> JsonDict:
        review = self.get_review(review_id)
        if review.reviewer_agent_id != reviewer_agent_id:
            raise AuthorizationError("reviewer does not own review")
        task = self.get_task(review.task_id)
        existing_claim = ensure_json_object(
            ensure_json_object(task.metadata).get("review_claims")
        ).get(review.id)
        if review.status != ReviewStatus.PENDING.value:
            return {
                "schema": "mac.review_claim.v1",
                "status": "not_claimable",
                "reason": "review_%s" % review.status,
                "review": review.to_dict(),
                "task": task.to_dict(),
                "claim": existing_claim if isinstance(existing_claim, dict) else None,
            }
        current_target = self.reviews.current_review_target_evidence_id(task.id)
        if current_target and executor_evidence_id != current_target:
            raise ValidationError(
                "review claim must fence the current executor evidence revision"
            )
        if isinstance(existing_claim, dict) and existing_claim.get(
            "reviewer_agent_id"
        ) not in {
            None,
            "",
            reviewer_agent_id,
        }:
            raise ValidationError(
                "review is already claimed by %s"
                % existing_claim.get("reviewer_agent_id")
            )
        evidence = None
        if executor_evidence_id:
            evidence = self.get_evidence(executor_evidence_id)
            if evidence.task_id != task.id:
                raise ValidationError("review claim evidence must belong to reviewed task")
        claim = self._review_claim_detail(task, review, evidence, actor=actor)
        now = utcnow()
        claim["claimed_at"] = now
        # mem-05: idempotent re-claim. The verified 30,806-row storm was one
        # review re-claiming identical evidence over and over. A repeat claim
        # (same review + executor_evidence_id + head_sha) is now a no-op: it
        # writes no new task.review_claimed row. Availability still has to
        # linearize in the transaction below: stale claim metadata must not let a
        # drained/held reviewer re-enter after a deployment fence wins.
        prior: JsonDict = {}
        prior_is_identical = False
        with self.store.transaction() as conn:
            task_lock = conn.execute(
                "UPDATE tasks SET updated_at = updated_at "
                "WHERE id = ? AND state = ?",
                (task.id, TaskState.REVIEWING.value),
            )
            review_lock = conn.execute(
                "UPDATE reviews SET status = status WHERE id = ? "
                "AND task_id = ? AND reviewer_agent_id = ? AND status = ?",
                (
                    review.id,
                    task.id,
                    reviewer_agent_id,
                    ReviewStatus.PENDING.value,
                ),
            )
            current_task_row = conn.execute(
                "SELECT metadata FROM tasks WHERE id = ?", (task.id,)
            ).fetchone()
            current_metadata = ensure_json_object(
                json_loads(current_task_row["metadata"], {})
                if current_task_row is not None
                else {}
            )
            current_claims = ensure_json_object(
                current_metadata.get("review_claims")
            )
            prior = ensure_json_object(current_claims.get(review.id))
            prior_is_identical = bool(
                prior
                and str(prior.get("executor_evidence_id") or "")
                == str(claim.get("executor_evidence_id") or "")
                and str(prior.get("repository_head_sha") or "")
                == str(claim.get("repository_head_sha") or "")
            )
            current_claims[review.id] = claim
            current_metadata["review_claims"] = current_claims
            current_metadata["latest_review_claim"] = claim
            if prior_is_identical:
                agent_claim = conn.execute(
                    """
                    UPDATE agents
                    SET status = ?, current_task_id = ?, updated_at = ?, last_seen_at = ?
                    WHERE id = ? AND deleted_at IS NULL
                        AND health_status = ? AND dispatch_hold = 0
                        AND (
                            (status = ? AND current_task_id = ?)
                            OR (status = ? AND current_task_id IS NULL)
                        )
                    """,
                    (
                        AgentStatus.BUSY.value,
                        task.id,
                        now,
                        now,
                        reviewer_agent_id,
                        HealthStatus.HEALTHY.value,
                        AgentStatus.BUSY.value,
                        task.id,
                        AgentStatus.IDLE.value,
                    ),
                )
            else:
                agent_claim = conn.execute(
                    """
                    UPDATE agents
                    SET status = ?, current_task_id = ?, updated_at = ?, last_seen_at = ?
                    WHERE id = ? AND deleted_at IS NULL
                        AND status = ? AND health_status = ?
                        AND current_task_id IS NULL AND dispatch_hold = 0
                    """,
                    (
                        AgentStatus.BUSY.value,
                        task.id,
                        now,
                        now,
                        reviewer_agent_id,
                        AgentStatus.IDLE.value,
                        HealthStatus.HEALTHY.value,
                    ),
                )
            current_agent_row = conn.execute(
                "SELECT resources FROM agents WHERE id = ?",
                (reviewer_agent_id,),
            ).fetchone()
            current_agent_resources = ensure_json_object(
                json_loads(current_agent_row["resources"], {})
                if current_agent_row is not None
                else {}
            )
            report_reviewer_ineligible = (
                metadata_declares_read_only_report_repository(current_metadata)
                and not agent_has_read_only_report_repository_executor(
                    current_agent_resources
                )
            )
            locked_target = str(
                ensure_json_object(current_metadata.get("review_target")).get(
                    "executor_evidence_id"
                )
                or ""
            ).strip()
            if (
                task_lock.rowcount != 1
                or review_lock.rowcount != 1
                or agent_claim.rowcount != 1
                or report_reviewer_ineligible
                or (locked_target and executor_evidence_id != locked_target)
            ):
                raise AuthorizationError(
                    "review assignment, reviewer availability, or executor evidence revision changed"
                )
            if not prior_is_identical:
                conn.execute(
                    "UPDATE tasks SET metadata = ?, updated_at = ? WHERE id = ?",
                    (json_dumps(current_metadata), now, task.id),
                )
                self._record_history(
                    task.id,
                    "task.review_claimed",
                    reviewer_agent_id,
                    None,
                    None,
                    claim,
                    conn=conn,
                )
        refreshed = self.get_task(task.id)
        result = {
            "schema": "mac.review_claim.v1",
            "status": "claimed",
            "review": review.to_dict(),
            "task": refreshed.to_dict(),
            "claim": prior if prior_is_identical else claim,
        }
        if prior_is_identical:
            result["idempotent"] = True
        return result


    def _review_claim_detail(
        self,
        task: Task,
        review: Review,
        evidence: Optional[Evidence],
        *,
        actor: str,
    ) -> JsonDict:
        verification = ensure_json_object(
            evidence.metadata.get("verification") if evidence is not None else {}
        )
        repo = ensure_json_object(verification.get("repo"))
        tests = (
            verification.get("tests")
            if isinstance(verification.get("tests"), list)
            else []
        )
        checks = (
            verification.get("checks")
            if isinstance(verification.get("checks"), list)
            else []
        )
        runtime = ensure_json_object(ensure_json_object(task.metadata).get("runtime"))
        return {
            "schema": "mac.review_claim.detail.v1",
            "actor": actor,
            "task_id": task.id,
            "task_title": task.title,
            "project": task.project,
            "review_id": review.id,
            "reviewer_agent_id": review.reviewer_agent_id,
            "executor_evidence_id": evidence.id if evidence is not None else None,
            "work_summary": evidence.summary if evidence is not None else "",
            "evidence_type": verification.get("evidence_type"),
            "repository_worktree": (
                repo.get("path")
                or runtime.get("repository_worktree")
                or repo.get("worktree")
                or ""
            ),
            "repository_branch": repo.get("branch")
            or runtime.get("repository_branch")
            or "",
            "repository_head_sha": repo.get("head_sha") or "",
            "repository_remote_ref": repo.get("remote_ref") or "",
            "repository_files_changed": (
                repo.get("files_changed")
                if isinstance(repo.get("files_changed"), list)
                else []
            ),
            "checks": checks,
            "tests": tests,
        }

    def submit_review(self, *args: Any, **kwargs: Any) -> Review:
        review = self.reviews.submit_review(*args, **kwargs)
        reviewer_agent_id = kwargs.get("reviewer_agent_id")
        if reviewer_agent_id is None and len(args) >= 3:
            reviewer_agent_id = args[2]
        if reviewer_agent_id is None:
            reviewer_agent_id = review.reviewer_agent_id
        current = self.get_agent(str(reviewer_agent_id))
        if current.current_task_id == review.task_id:
            self._set_agent_idle(str(reviewer_agent_id))
        # Glanceable per-task narrative: record what the reviewer concluded.
        # Only real verdicts (not pending/retracted churn); best-effort.
        try:
            verdict = str(review.status or "").strip()
            if verdict.lower() in {"approved", "rejected", "changes_requested", "changes"}:
                reason = str(getattr(review, "reason", "") or "").strip()
                self.append_task_activity(
                    review.task_id,
                    "review",
                    str(reviewer_agent_id),
                    "%s — %s" % (verdict, reason) if reason else verdict,
                )
        except Exception:  # noqa: BLE001 - narrative is best-effort
            pass
        return review

    def get_review(self, review_id: str) -> Review:
        return self.reviews.get_review(review_id)

    def list_reviews(
        self,
        task_id: str,
        limit: Optional[int] = None,
    ) -> List[Review]:
        return self.reviews.list_reviews(
            self._resolve_task_id(task_id),
            limit=limit,
        )

    def publish_task(self, *args: Any, **kwargs: Any) -> Publication:
        task_id = kwargs.get("task_id") if "task_id" in kwargs else (args[0] if args else None)
        target = kwargs.get("target") if "target" in kwargs else (args[1] if len(args) >= 2 else None)
        evidence_id = kwargs.get("evidence_id")
        if evidence_id is None and len(args) >= 4:
            evidence_id = args[3]
        if task_id is not None:
            self._validate_publication_evidence(str(task_id), evidence_id)
        git_publication = None
        if task_id is not None and target is not None and evidence_id is not None:
            git_publication = self._publish_git_target_if_needed(
                str(task_id),
                str(target),
                str(evidence_id),
            )
            if git_publication is not None:
                self._record_canonical_integration_proof(
                    str(task_id),
                    str(evidence_id),
                    str(kwargs.get("created_by") if "created_by" in kwargs else args[2]),
                    git_publication,
                )
        publication = self.reviews.publish_task(*args, **kwargs)
        if git_publication is not None:
            self.record_log(
                "task.git_published",
                layer="control_plane",
                source=publication.created_by,
                subject_type="task",
                subject_id=publication.task_id,
                detail={**git_publication, "publication_id": publication.id},
            )
            self._schedule_cicd_check_after_publication(publication, git_publication)
        # publish_task transitions the underlying task to COMPLETED inside
        # its own transaction (bypassing transition_task), so we run the
        # workflow runtime hook here so workflow runs advance on publish.
        row = self.store.query_one(
            "SELECT workflow_run_id FROM tasks WHERE id = ?", (publication.task_id,)
        )
        if row is not None and row["workflow_run_id"]:
            try:
                self.workflow_runtime.on_task_completed(
                    publication.task_id, TaskState.COMPLETED.value
                )
            except Exception:  # noqa: BLE001
                import logging

                logging.getLogger(__name__).exception(
                    "workflow runtime failed to advance after publish_task"
                )
        return publication

    def _schedule_cicd_check_after_publication(
        self,
        publication: Publication,
        git_publication: JsonDict,
    ) -> None:
        """Append the durable exact-SHA handoff for post-publication CI.

        Publication remains complete once the reviewed change is remotely
        integrated. CI is a linked lifecycle continuation: the background
        monitor chooses the repository-specific delay, re-polls pending runs,
        and coalesces terminal failures into low-priority maintenance.
        """

        final_sha = str(git_publication.get("final_sha") or "").strip()
        if not _GIT_SHA_RE.match(final_sha):
            return
        monitor = getattr(self, "_cicd_monitor", None)
        if monitor is None:
            return
        task = self.get_task(publication.task_id)
        metadata = ensure_json_object(task.metadata)
        origin = ensure_json_object(metadata.get("origin"))
        repository_url = str(
            origin.get("repository_url")
            or git_publication.get("repository_url")
            or ""
        ).strip()
        try:
            monitor.schedule_publication_followup(
                task_id=publication.task_id,
                publication_id=publication.id,
                project=str(task.project or ""),
                canonical_sha=final_sha,
                repository_url=repository_url,
                published_at=publication.created_at,
                actor=publication.created_by,
            )
        except Exception:  # noqa: BLE001 - publication is already durable.
            try:
                self.record_log(
                    "cicd.followup.schedule_failed",
                    layer="control_plane",
                    source=publication.created_by,
                    level="error",
                    subject_type="task",
                    subject_id=publication.task_id,
                    detail={
                        "publication_id": publication.id,
                        "canonical_sha": final_sha,
                    },
                )
            except Exception:
                pass

    def _record_canonical_integration_proof(
        self,
        task_id: str,
        evidence_id: str,
        created_by: str,
        publication: JsonDict,
    ) -> None:
        """Persist the post-merge canonical tip before marking a task complete.

        A successful Git publication is the canonical integration event.
        Its source evidence describes the reviewed task ref, whereas its final
        branch SHA can be a merge commit.  Store both facts in a separate,
        immutable ledger record; completion then consumes that durable proof
        instead of treating the pre-merge task branch as canonical.
        """
        task = self.get_task(task_id)
        contract = self._repository_contract_for_task(task)
        if not contract:
            return
        final_sha = str(publication.get("final_sha") or "").strip()
        reviewed_sha = str(publication.get("head_sha") or "").strip()
        if not (_GIT_SHA_RE.match(final_sha) and _GIT_SHA_RE.match(reviewed_sha)):
            raise ValidationError("git publication did not return canonical integration SHAs")
        try:
            canonical_branch = resolve_task_repository_branch(
                task.to_dict(),
                legacy_branch=contract.get("canonical_branch"),
                default_branch="main",
            )
        except ValueError as exc:
            raise ValidationError(
                "canonical integration proof branch is invalid: %s" % exc
            ) from exc
        source = self.get_evidence(evidence_id)
        source_metadata = ensure_json_object(source.metadata)
        source_manifest = ensure_json_object(source_metadata.get("verification")) or source_metadata
        source_repo = ensure_json_object(source_manifest.get("repo"))
        manifest = {
            "schema": "mac.worker_evidence.v1",
            "status": "complete",
            "evidence_type": "repo_change",
            "repo": {
                **source_repo,
                "head_sha": reviewed_sha,
                "pushed": True,
            },
            "canonical_integration": {
                "schema": "mac.canonical_integration.v1",
                "status": "pass",
                "canonical_ref": "refs/heads/%s" % canonical_branch,
                "canonical_tip_sha": final_sha,
                "reviewed_head_sha": reviewed_sha,
                # A squash merge lands the reviewed *content* under a new SHA,
                # so the reviewed commit is intentionally not an ancestor of
                # the canonical tip. Report what the publication observed
                # rather than asserting an ancestry squashing destroys.
                "contains_reviewed_head": bool(
                    publication.get("contains_reviewed_head", True)
                ),
                "remote_verified": True,
                "publication_mode": str(publication.get("publication_mode") or ""),
                **(
                    {
                        "squash_merged": True,
                        "merge_serialization": str(
                            publication.get("merge_serialization") or ""
                        ),
                        "pull_request_opened_by": str(
                            publication.get("pull_request_opened_by") or ""
                        ),
                        "pull_request_url": str(
                            publication.get("pull_request_url") or ""
                        ),
                        "pull_request_number": int(
                            publication.get("pull_request_number") or 0
                        ),
                    }
                    if str(publication.get("publication_mode") or "")
                    == "pull_request_squash"
                    else {}
                ),
            },
        }
        self.add_evidence(
            task_id,
            "test",
            "ledger://canonical-integration/%s/%s" % (task_id, final_sha),
            "Canonical branch integration verified at %s" % final_sha,
            created_by,
            metadata={"verification": manifest},
            _trusted_internal=True,
        )

    def _publication_targets_runtime_source(self, task_id: str) -> bool:
        """Whether legacy publication would mutate this process's source checkout."""

        task = self.get_task(task_id)
        metadata = ensure_json_object(task.metadata)
        origin = ensure_json_object(metadata.get("origin"))
        repository_path = str(origin.get("repository_path") or "").strip()
        if not repository_path:
            return False
        try:
            candidate = Path(repository_path).expanduser().resolve()
            runtime_source = Path(__file__).resolve().parents[2]
        except OSError:
            return False
        return candidate == runtime_source

    @_serialize_runtime_source_publication
    def _publish_git_target_if_needed(
        self,
        task_id: str,
        target: str,
        evidence_id: str,
    ) -> Optional[JsonDict]:
        if target not in {"git://main", "git://origin/main"}:
            return None
        task = self.get_task(task_id)
        if metadata_declares_report_deliverable(task.metadata):
            raise ValidationError(
                "report deliverables cannot use Git publication targets"
            )
        metadata = ensure_json_object(task.metadata)
        origin = ensure_json_object(metadata.get("origin"))
        try:
            canonical_branch = resolve_task_repository_branch(
                task.to_dict(),
                legacy_branch=(
                    origin.get("default_branch") or origin.get("canonical_branch")
                ),
                default_branch="main",
            )
        except ValueError as exc:
            raise ValidationError(
                "git publication canonical branch is invalid: %s" % exc
            ) from exc
        repo_path_raw = str(origin.get("repository_path") or "").strip()
        repository_url = str(origin.get("repository_url") or "").strip()
        # mac-k8s: remote-clone tasks (jordanh-gke and any K8s fleet) have no
        # local repository_path on the hub. Rather than refuse to publish, merge
        # via a transient authed clone of the remote so K8s-mode work can reach
        # main. The clone is cleaned up before returning (best-effort on errors).
        # Read the executor evidence first: its repo block records the remote the
        # worker actually pushed the task branch to, which lets us publish a
        # local-repo task (origin has only an agent-side repository_path that does
        # not exist on the hub) by cloning that remote.
        evidence = self.get_evidence(evidence_id)
        manifest = ensure_json_object(evidence.metadata.get("verification"))
        repo = ensure_json_object(manifest.get("repo"))
        head_sha = str(repo.get("head_sha") or "").strip()
        if not _GIT_SHA_RE.match(head_sha):
            raise ValidationError("git publication requires evidence repo.head_sha")
        # The agent opens its own pull request when it pushes the branch; the
        # hub reads that fact from the evidence rather than opening one.
        agent_pull_request = ensure_json_object(repo.get("pull_request"))
        remote_ref = str(repo.get("remote_ref") or "").strip()
        source_branch = _remote_branch_from_ref(remote_ref)
        if not source_branch:
            raise ValidationError("git publication requires branch-like repo.remote_ref")

        # Resolve the canonical remote without using its hub checkout as the
        # publication worktree.  A long-lived checkout is operator/runtime
        # state: its local ``main`` may be dirty, ahead, behind, or midway
        # through another operation.  Publication must instead start from the
        # exact remote canonical-branch tip in a fresh disposable clone on
        # every attempt.
        local_path: Optional[Path] = None
        if repo_path_raw:
            candidate = Path(repo_path_raw).expanduser()
            if candidate.exists():
                local_path = candidate
        clone_url = repository_url or str(
            repo.get("remote_url") or repo.get("push_remote") or ""
        ).strip()
        contract = ensure_json_object(origin.get("repository_contract"))
        canonical_remote_url = str(contract.get("canonical_remote_url") or "").strip()
        if local_path is not None:
            top = self._git_output(local_path, ["rev-parse", "--show-toplevel"])
            if top["returncode"] != 0 or not top.get("stdout"):
                raise ValidationError(
                    "git publication repository path is not a git worktree: %s"
                    % local_path
                )
            local_root = Path(str(top["stdout"])).expanduser()
            origin_url_probe = self._git_output(
                local_root, ["remote", "get-url", "origin"]
            )
            if origin_url_probe["returncode"] != 0:
                raise ValidationError(
                    "git publication could not read worktree origin: %s"
                    % (
                        origin_url_probe.get("stderr")
                        or origin_url_probe.get("stdout")
                        or local_root
                    )
                )
            worktree_origin = str(origin_url_probe.get("stdout") or "").strip()
            if not clone_url:
                clone_url = worktree_origin
            # mac-y7ha: when the task's registered project pins a canonical
            # remote URL, refuse to publish through a checkout whose origin is
            # a different repository.  The checkout is only an identity/auth
            # hint; it is never mutated by publication.
            if canonical_remote_url:
                expected = _canonicalize_git_url(canonical_remote_url)
                actual = _canonicalize_git_url(worktree_origin)
                if expected is None or actual is None or expected != actual:
                    raise ValidationError(
                        "git publication worktree origin %r does not match the project's "
                        "registered remote %r"
                        % (worktree_origin, canonical_remote_url)
                    )
        elif canonical_remote_url and clone_url:
            expected = _canonicalize_git_url(canonical_remote_url)
            actual = _canonicalize_git_url(clone_url)
            if expected is None or actual is None or expected != actual:
                raise ValidationError(
                    "git publication remote %r does not match the project's "
                    "registered remote %r"
                    % (clone_url, canonical_remote_url)
                )

        if not clone_url:
            raise ValidationError(
                "git publication requires a hub-reachable repo: origin.repository_url, "
                "a hub-local origin.repository_path with an origin remote, or "
                "evidence repo.remote_url"
            )

        from . import gitops as _gitops

        # Authentication normalization remains centralized in gitops.  Each
        # attempt clones the remote again so neither a failed merge nor a lost
        # optimistic-concurrency race can poison the following attempt.
        # Clean URL + credential in the child ENVIRONMENT. The URL form put the
        # whole token in argv, where `ps` exposed it to every user on the hub --
        # the exposure askpass_remote_auth exists to prevent, and which its own
        # docstring records as still live on "the hub publish and hub verify
        # paths". Verify was fixed (#341); this is publish.
        auth_url, auth_env = _gitops.askpass_remote_auth(clone_url)
        last_base_move: Optional[_PublicationBaseMovedError] = None
        for attempt in range(2):
            try:
                return self._publish_git_target_attempt(
                    task=task,
                    target=target,
                    remote_ref=remote_ref,
                    source_branch=source_branch,
                    head_sha=head_sha,
                    clone_url=clone_url,
                    auth_url=auth_url,
                    auth_env=auth_env,
                    canonical_branch=canonical_branch,
                    attempt=attempt + 1,
                    agent_pull_request=agent_pull_request,
                )
            except _PublicationBaseMovedError as exc:
                last_base_move = exc
                if attempt == 0:
                    continue
        assert last_base_move is not None
        exhausted = ValidationError(
            "%s; a second exact-base attempt also lost the publication race; "
            "retry is deferred to avoid a hot loop" % last_base_move
        )
        exhausted.publication_retry_after_seconds = 300
        exhausted.publication_failure_kind = "canonical_base_moved"
        raise exhausted

    # ------------------------------------------------------------------
    # Publication strategy: land through a pull request, not a push to main.
    # ------------------------------------------------------------------

    _PUBLICATION_STRATEGIES = ("pull_request", "direct_push")

    def _resolve_publication_strategy(self, clone_url: str) -> JsonDict:
        """Decide how this publication lands, and say why.

        ``pull_request`` is the default: the reviewed branch is pushed, a PR is
        opened against the canonical branch, and the *forge* performs a squash
        merge.  The hub never pushes the canonical branch.

        ``direct_push`` (``MAC_PUBLICATION_STRATEGY=direct_push``) is the
        documented opt-out and the automatic fallback for a canonical remote
        with no API-reachable forge — a ``file://`` or bare-path remote, or an
        http(s) remote for which no credential is configured.  Falling back is
        deliberate rather than fatal: mac manages repositories that have no
        forge at all, and refusing to publish those would strand them.  The
        fallback reason is recorded in the publication commands so a repo that
        *should* be using a PR but silently is not is visible in the evidence.
        """

        from mac.env_config import env_str

        from . import gitops as _gitops

        configured = (
            str(env_str("MAC_PUBLICATION_STRATEGY", "pull_request") or "").strip().lower()
            or "pull_request"
        )
        if configured not in self._PUBLICATION_STRATEGIES:
            raise ValidationError(
                "MAC_PUBLICATION_STRATEGY must be one of %s (got %r)"
                % (", ".join(self._PUBLICATION_STRATEGIES), configured)
            )
        if configured == "direct_push":
            return {
                "strategy": "direct_push",
                "forge": "",
                "reason": "MAC_PUBLICATION_STRATEGY=direct_push (explicit opt-out)",
                "api_url": "",
            }
        api_url = _gitops.https_remote_for_token_auth(clone_url)
        forge = _gitops.resolve_forge(clone_url)
        if not forge:
            return {
                "strategy": "direct_push",
                "forge": "",
                "reason": (
                    "canonical remote has no API-reachable forge (no http(s) "
                    "forge URL, or no GH_TOKEN/GITEA_TOKEN for its host); "
                    "falling back to direct push"
                ),
                "api_url": "",
            }
        return {
            "strategy": "pull_request",
            "forge": forge,
            "reason": "",
            "api_url": api_url,
        }

    # ------------------------------------------------------------------
    # mac's own merge queue (see mac.native_merge_queue).
    # ------------------------------------------------------------------

    def _native_merge_queue(self) -> Any:
        """The durable native queue, bound to this hub's store.

        Constructed lazily and cached: the queue holds no state of its own --
        everything lives in ``merge_queue_entries`` / ``merge_queue_windows`` --
        so a restart rebuilds this object and continues from the ledger.
        """

        from mac.native_merge_queue import NativeMergeQueue

        queue = getattr(self, "_native_merge_queue_instance", None)
        if queue is None:
            queue = NativeMergeQueue(self.store, observe=self.record_metric)
            self._native_merge_queue_instance = queue
        return queue

    def _merge_queue_snapshot(self, queue: Any, entry_id: str) -> Optional[JsonDict]:
        """Depth, window, and eviction history for the queue this entry is in.

        Recorded into the publication evidence beside `merge_serialization` so
        the guarantee is not a claim: an operator reading `mac task show` can
        see how deep the queue was, how wide the speculation window was, and
        what was evicted and why. This repository has shipped four gates today
        that reported healthy while enforcing nothing; a queue nobody can watch
        is the next one.
        """

        try:
            entry = queue.entry(entry_id)
            if entry is None:
                return None
            return queue.snapshot(entry.repository, entry.branch)
        except Exception:  # noqa: BLE001 - observability never blocks a land
            return None

    def _merge_queue_owner(self) -> str:
        """Who holds a queue slot.  Stable per hub process, unique per hub."""

        owner = getattr(self, "_merge_queue_owner_id", "")
        if not owner:
            owner = "hub-%s-%d" % (socket.gethostname(), os.getpid())
            self._merge_queue_owner_id = owner
        return owner

    def _resolve_merge_serialization(
        self, clone_url: str, canonical_branch: str
    ) -> JsonDict:
        """Decide WHICH mechanism serializes this landing, from stored state.

        The capability is a project attribute refreshed by the existing GitHub
        ingest poller (see :mod:`mac.merge_capability`), not a per-merge probe.
        A missing or expired answer is resolved right here and written back, so
        a repository registered five minutes ago does not have to wait for a
        poll before it can publish.

        If it still cannot be determined, the answer is mac's own queue.
        "Unknown" is never permission to do an unserialized squash.
        """

        from mac.merge_capability import (
            MergeCapability,
            capability_ttl_seconds,
            repository_remote_and_branch,
            resolve_merge_capability,
            stored_capability,
        )
        from mac.native_merge_queue import MODE_FORGE_QUEUE, MODE_NATIVE_QUEUE

        wanted = _canonicalize_git_url(clone_url)
        record = None
        capability: Optional[MergeCapability] = None
        try:
            for repo in self.list_project_repositories(enabled=True):
                coordinates = repository_remote_and_branch(repo)
                if not coordinates["remote"]:
                    continue
                if _canonicalize_git_url(coordinates["remote"]) == wanted:
                    record = repo
                    break
        except Exception:  # noqa: BLE001 - an unreadable registry is not fatal
            record = None
        if record is not None:
            capability = stored_capability(getattr(record, "metadata", None))
        source = "stored"
        if capability is None or capability.is_stale(
            branch=canonical_branch, ttl_seconds=capability_ttl_seconds()
        ):
            source = "resolved_now"
            capability = resolve_merge_capability(
                clone_url, canonical_branch, resolver="publication"
            )
            if record is not None:
                try:
                    self.record_repository_merge_capability(
                        record.id, capability.to_dict()
                    )
                except Exception:  # noqa: BLE001 - caching is best effort
                    pass
        mode = MODE_FORGE_QUEUE if capability.use_forge_queue else MODE_NATIVE_QUEUE
        return {
            "mode": mode,
            "source": source,
            "repository_id": getattr(record, "id", "") if record is not None else "",
            "capability": capability.to_dict(),
        }

    def _build_speculative_base(
        self,
        root: Path,
        git_step: Any,
        base_sha: str,
        predecessors: Sequence[JsonDict],
    ) -> str:
        """Project the queue entries ahead of us on top of the canonical tip.

        This is the speculative half of the queue: entry N is tested against
        ``tip + entries 1..N-1`` rather than the bare tip, so N does not have to
        wait for N-1 to land before it can be tested.  Each predecessor is
        merged with ``git merge-tree`` (no working tree is touched) and the
        result committed with ``commit-tree`` to give the next step a parent.

        Returns "" when the projection cannot be built -- an unfetchable
        predecessor branch, or a conflict between two queued changes.  The
        caller defers; it never falls back to testing against the bare tip,
        because that result would be attributed to a queue position it was not
        tested at.
        """

        current = str(base_sha or "").strip()
        for predecessor in predecessors:
            sha = str(predecessor.get("head_sha") or "").strip()
            branch = str(predecessor.get("source_branch") or "").strip()
            if not sha:
                return ""
            have = git_step(
                "speculative_have", ["cat-file", "-e", "%s^{commit}" % sha], check=False
            )
            if _git_step_returncode(have) != 0:
                if not branch:
                    return ""
                fetched = git_step(
                    "speculative_fetch",
                    [
                        "fetch",
                        "origin",
                        "+refs/heads/%s:refs/remotes/origin/%s" % (branch, branch),
                    ],
                    timeout=180,
                    check=False,
                )
                if _git_step_returncode(fetched) != 0:
                    return ""
                have = git_step(
                    "speculative_have_after_fetch",
                    ["cat-file", "-e", "%s^{commit}" % sha],
                    check=False,
                )
                if _git_step_returncode(have) != 0:
                    return ""
            merged = git_step(
                "speculative_merge_tree",
                ["merge-tree", "--write-tree", "--name-only", current, sha],
                check=False,
            )
            if _git_step_returncode(merged) != 0:
                # Two queued changes conflict with each other. Speculation on
                # top of this predecessor is worthless; defer rather than
                # pretend the bare tip is our base.
                return ""
            lines = [
                line
                for line in str(merged.get("stdout") or "").splitlines()
                if line.strip()
            ]
            if not lines:
                return ""
            committed = git_step(
                "speculative_commit_tree",
                [
                    "-c",
                    "user.name=MAC Merge Queue",
                    "-c",
                    "user.email=merge-queue@mac.invalid",
                    "commit-tree",
                    lines[0],
                    "-p",
                    current,
                    "-p",
                    sha,
                    "-m",
                    "MAC merge queue speculative base",
                ],
                check=False,
            )
            if _git_step_returncode(committed) != 0:
                return ""
            current = str(committed.get("stdout") or "").strip()
            if not current:
                return ""
        return current

    def _publish_via_pull_request(
        self,
        *,
        task: Task,
        target: str,
        remote_ref: str,
        source_branch: str,
        head_sha: str,
        base_sha: str,
        canonical_branch: str,
        api_url: str,
        commands: List[JsonDict],
        attempt: int,
        git_step: Any,
        root: Path,
        agent_pull_request: Optional[JsonDict] = None,
        required_checks: Tuple[str, ...] = (),
        serialization: Optional[JsonDict] = None,
        queue: Any = None,
        queue_entry_id: str = "",
    ) -> JsonDict:
        """Land the agent's pull request; the hub records, it does not author.

        The AGENT opens the pull request when it pushes its branch
        (``gitops.agent_pull_request``), and the hub reads it from the worker
        evidence.  The hub opens one itself only when the evidence carries
        none -- an older worker, or a forge the agent could not reach -- and
        that fallback is recorded in the publication commands rather than
        being indistinguishable from the normal path.

        The hub does not merge either: it asks the forge's MERGE QUEUE to
        land the PR when the canonical branch has one, and the queue performs
        the merge after testing the projected post-merge tree.  Without a
        queue the request degrades to a plain squash merge, which does *not*
        carry that guarantee -- so the canonical tip is re-validated against
        the tested base immediately beforehand, and the weaker serialization
        is named in the evidence.

        The hub never pushes the canonical branch.  A squash merge means the
        reviewed commit is deliberately *not* an ancestor of the canonical tip
        afterwards, so the canonical-integration proof records
        ``contains_reviewed_head`` honestly instead of asserting an ancestry
        that squashing destroys.
        """

        from . import gitops as _gitops

        branch = str(source_branch or "").strip()
        remote_head_ref = "refs/heads/%s" % branch
        observed = git_step(
            "observe_pull_request_branch",
            ["ls-remote", "origin", remote_head_ref],
            check=False,
        )
        observed_sha = str(observed.get("stdout") or "").split(None, 1)
        observed_sha = observed_sha[0] if observed_sha else ""
        if observed_sha != head_sha:
            # NEVER a bare push: an explicit source:destination refspec, and a
            # lease pinned to exactly what we just observed, so a branch that
            # moved under us fails instead of being overwritten.
            push_args = ["push"]
            if observed_sha:
                push_args.append(
                    "--force-with-lease=%s:%s" % (remote_head_ref, observed_sha)
                )
            push_args += ["origin", "%s:%s" % (head_sha, remote_head_ref)]
            git_step("push_pull_request_branch", push_args, timeout=180)
            confirm = git_step(
                "verify_pull_request_branch", ["ls-remote", "origin", remote_head_ref]
            )
            confirmed = str(confirm.get("stdout") or "").split(None, 1)
            if (confirmed[0] if confirmed else "") != head_sha:
                raise ValidationError(
                    "git publication could not place reviewed commit %s on branch %s"
                    % (head_sha[:12], branch)
                )

        title = "%s (%s)" % (str(task.title or "").strip() or "mac change", task.id)
        body = (
            "Landed by the MAC control plane after review approval.\n\n"
            "- task: `%s`\n- reviewed head: `%s`\n- base at publication: `%s`\n"
            % (task.id, head_sha, base_sha)
        )
        # The agent's own pull request, opened when it pushed the branch.
        # Opening a PR is not the hub's job -- storing the fact that one was
        # opened is.
        agent_pr = ensure_json_object(agent_pull_request)
        agent_pr_number = int(agent_pr.get("number") or 0)
        agent_pr_base = str(agent_pr.get("base") or "").strip()
        reuse_agent_pr = bool(
            agent_pr.get("opened")
            and agent_pr_number > 0
            and (not agent_pr_base or agent_pr_base == canonical_branch)
        )
        if reuse_agent_pr:
            pr = _gitops.PullRequestResult(
                host=str(agent_pr.get("forge") or ""),
                number=agent_pr_number,
                url=str(agent_pr.get("url") or ""),
                state=str(agent_pr.get("state") or "open"),
            )
            opened_by = "agent"
        else:
            try:
                pr = _gitops.open_pull_request(
                    api_url,
                    branch,
                    base=canonical_branch,
                    title=title,
                    body=body,
                )
            except Exception as exc:  # noqa: BLE001 - surfaced as a publication failure
                detail = _gitops._scrub_secret(str(exc))
                failure = ValidationError(
                    "git publication could not open a pull request for branch %s: %s"
                    % (branch, detail[:400])
                )
                failure.publication_retry_after_seconds = 600
                failure.publication_failure_kind = "pull_request_open_failed"
                raise failure from None
            opened_by = "hub_fallback"
        commands.append(
            {
                "name": "open_pull_request",
                "attempt": attempt,
                "number": pr.number,
                "url": pr.url,
                "state": pr.state,
                "head": branch,
                "base": canonical_branch,
                "opened_by": opened_by,
                "agent_reason": ""
                if reuse_agent_pr
                else str(agent_pr.get("reason") or "worker evidence carried no pull request"),
            }
        )

        # VERIFY, DO NOT ASSUME. The party requesting the merge confirms the
        # required contexts actually passed for this head SHA, instead of
        # trusting the forge to refuse. The fleet authenticates as the
        # repository owner, and this repository's ruleset carries a
        # RepositoryRole bypass with mode `always` (deliberate operator
        # break-glass) -- so the requester inherits it and CAN merge straight
        # past required checks. It did: the first publication under this flow
        # merged two seconds after the PR was opened, with every required
        # context reported SKIPPED. Nothing gated it, because this path also
        # skips its own contract re-projection precisely BECAUSE the forge
        # reports required checks.
        #
        # "No required contexts" and "required contexts that have not reported
        # yet" are NOT the same thing, and are recorded separately: the first
        # is an unprotected repository, where the local contract gate above
        # ran instead; the second is a gate that has not run, which defers.
        if required_checks:
            verdicts = _gitops.required_check_verdicts(
                api_url, head_sha, tuple(required_checks)
            )
            if verdicts.get("failed"):
                case = "failed"
            elif not verdicts.get("known"):
                case = "unverifiable"
            elif verdicts.get("pending"):
                case = "pending"
            else:
                case = "verified"
        else:
            verdicts = {
                "known": True,
                "contexts": [],
                "passed": [],
                "pending": [],
                "failed": [],
            }
            case = "none_configured"
        commands.append(
            {
                "name": "required_check_verification",
                "attempt": attempt,
                "case": case,
                "head_sha": head_sha,
                "contexts": list(verdicts.get("contexts") or []),
                "passed": list(verdicts.get("passed") or []),
                "pending": list(verdicts.get("pending") or []),
                "failed": list(verdicts.get("failed") or []),
            }
        )
        if case == "failed":
            failure = ValidationError(
                "git publication will not merge %s: required checks failed for "
                "reviewed head %s: %s"
                % (
                    pr.url or ("#%d" % pr.number),
                    head_sha[:12],
                    ", ".join(str(item) for item in verdicts.get("failed") or []),
                )
            )
            failure.publication_retry_after_seconds = 600
            failure.publication_failure_kind = "pull_request_checks_failed"
            raise failure
        if case in {"pending", "unverifiable"}:
            pending = ValidationError(
                "git publication is waiting on the pull request's own required "
                "checks before %s can merge into %s: %s"
                % (
                    pr.url or ("#%d" % pr.number),
                    canonical_branch,
                    "could not read check results for %s" % head_sha[:12]
                    if case == "unverifiable"
                    else "not yet reported for %s: %s"
                    % (
                        head_sha[:12],
                        ", ".join(str(item) for item in verdicts.get("pending") or []),
                    ),
                )
            )
            pending.publication_retry_after_seconds = 600
            pending.publication_failure_kind = "pull_request_checks_pending"
            raise pending

        # HOW THE MERGE IS SERIALIZED -- the guarantee, written down.
        #
        # merge_queue.py validates against the PROJECTED post-merge state (the
        # "Not Rocket Science Rule"): test the tree that will actually land,
        # serialize the merges, and post-merge testing is redundant because
        # what was tested IS what landed. A plain forge squash-merge does not
        # preserve that -- if the canonical branch advances between the status
        # checks finishing and the merge executing, the landed tree was never
        # tested. Required status checks alone do not close that; a MERGE
        # QUEUE does, and unlike `strict` required checks it serializes the
        # merges without serializing the (here ~2 hour) test runs.
        #
        # So: use the queue when the canonical branch has one. When it does
        # not -- no queue configured yet, gitea, or an unreadable ruleset --
        # degrade EXPLICITLY: re-validate that the canonical tip is still the
        # base this candidate was projected and gated against, and name the
        # weaker serialization in the evidence. Silently squash-merging while
        # the code still assumes the queue's guarantee is the same hole in a
        # harder-to-see place.
        from mac.native_merge_queue import (
            MODE_DIRECT_SQUASH,
            MODE_FORGE_QUEUE,
            MODE_NATIVE_QUEUE,
        )

        mode = str(ensure_json_object(serialization).get("mode") or "")
        if not mode:
            # No capability was resolved for us (a direct caller, or a test
            # exercising this method alone). Ask, and fail toward the mechanism
            # that serializes: an unknown answer is never a licence to squash.
            probed = _gitops.merge_queue_enabled(api_url, canonical_branch)
            mode = MODE_FORGE_QUEUE if probed else MODE_DIRECT_SQUASH
        queue_enabled = mode == MODE_FORGE_QUEUE
        native = bool(queue is not None and queue_entry_id and mode == MODE_NATIVE_QUEUE)

        pre_merged: Optional[Any] = None
        if native:
            # NEVER DOUBLE-LAND. Between attempts the PR may have been merged by
            # a human, by the forge, or by a previous attempt of ours that died
            # after the merge and before recording it. #400 established the
            # pattern -- read PR state before acting -- and this path needs it
            # more, because mac is the one doing the merging.
            # Tell the entry which PR it is landing. claim_slot ran before the
            # PR existed, so the column is still at its 0 default -- and every
            # step below assumes a PR to look at. An entry that never learns
            # its number can neither land nor be evicted; one on the live hub
            # reached 70 attempts that way while its work had already merged.
            queue.record_pull_request(queue_entry_id, int(pr.number))
            observed_pr = _gitops.pull_request_state(api_url, pr.number)
            commands.append(
                {
                    "name": "merge_queue_observe_pull_request",
                    "attempt": attempt,
                    "number": pr.number,
                    "known": bool(observed_pr.get("known")),
                    "merged": bool(observed_pr.get("merged")),
                    "state": str(observed_pr.get("state") or ""),
                    "sha": str(observed_pr.get("sha") or ""),
                }
            )
            if not observed_pr.get("known"):
                unreadable = ValidationError(
                    "mac merge queue could not read the state of %s before "
                    "merging; deferring rather than merging blind"
                    % (pr.url or ("#%d" % pr.number))
                )
                unreadable.publication_retry_after_seconds = 600
                unreadable.publication_failure_kind = "merge_queue_unreadable_state"
                raise unreadable
            if observed_pr.get("merged"):
                pre_merged = _gitops.PullRequestMergeResult(
                    merged=True,
                    number=pr.number,
                    sha=str(observed_pr.get("sha") or ""),
                    serialization=MODE_NATIVE_QUEUE,
                    reason="already merged on the forge; observed, not re-merged",
                )
            else:
                git_step(
                    "merge_queue_refresh_tip",
                    [
                        "fetch",
                        "origin",
                        "+refs/heads/%s:refs/remotes/origin/%s"
                        % (canonical_branch, canonical_branch),
                    ],
                    check=False,
                )
                tip_tree = str(
                    git_step(
                        "merge_queue_tip_tree",
                        [
                            "rev-parse",
                            "refs/remotes/origin/%s^{tree}" % canonical_branch,
                        ],
                        check=False,
                    ).get("stdout")
                    or ""
                ).strip()
                allowed, why, _entry = queue.may_land(
                    queue_entry_id, canonical_tip_tree=tip_tree
                )
                commands.append(
                    {
                        "name": "merge_queue_land_gate",
                        "attempt": attempt,
                        "entry_id": queue_entry_id,
                        "allowed": bool(allowed),
                        "reason": why,
                        "canonical_tip_tree": tip_tree,
                    }
                )
                if not allowed:
                    if "front of the queue" in why:
                        waiting = ValidationError(
                            "mac merge queue is landing an earlier change first: "
                            "%s" % why
                        )
                        waiting.publication_retry_after_seconds = 300
                        waiting.publication_failure_kind = "merge_queue_waiting"
                        raise waiting
                    observed_canonical = git_step(
                        "revalidate_canonical_tip",
                        [
                            "ls-remote",
                            "origin",
                            "refs/heads/%s" % canonical_branch,
                        ],
                        check=False,
                    )
                    observed_tip = str(
                        observed_canonical.get("stdout") or ""
                    ).split(None, 1)
                    observed_tip = observed_tip[0] if observed_tip else ""
                    # The tested projection is stale. Re-project; do NOT merge.
                    raise _PublicationBaseMovedError(base_sha, observed_tip or why)
        elif not queue_enabled:
            observed_canonical = git_step(
                "revalidate_canonical_tip",
                ["ls-remote", "origin", "refs/heads/%s" % canonical_branch],
            )
            observed_tip = str(observed_canonical.get("stdout") or "").split(None, 1)
            observed_tip = observed_tip[0] if observed_tip else ""
            if observed_tip and observed_tip != base_sha:
                # OCC validation phase: the tested projection is stale, so a
                # merge now would land a tree nobody tested. Re-project.
                raise _PublicationBaseMovedError(base_sha, observed_tip)
        commands.append(
            {
                "name": "merge_serialization",
                "attempt": attempt,
                "merge_queue": bool(queue_enabled or native),
                "mode": mode,
                "queue_entry_id": queue_entry_id if native else "",
                "queue": self._merge_queue_snapshot(queue, queue_entry_id)
                if native
                else None,
                "guarantee": (
                    "the forge merge queue tests the projected post-merge tree "
                    "and merges in order: what was tested is what lands"
                    if queue_enabled
                    else "mac's own merge queue ordered this change, tested it "
                    "against the tree it will land on, and refused the merge "
                    "unless the canonical tip's tree is still that exact tree: "
                    "what was tested is what lands"
                    if native
                    else "no merge queue on this branch; a plain squash merge "
                    "is not serialized against concurrent merges, so the "
                    "canonical tip was re-validated against the tested base "
                    "immediately before requesting it"
                ),
            }
        )
        try:
            merge = pre_merged or _gitops.request_pull_request_merge(
                api_url,
                pr.number,
                sha=head_sha,
                branch=canonical_branch,
                method="squash",
                commit_title="%s (#%d)" % (title, pr.number),
                commit_message=body,
                queue_enabled=queue_enabled,
            )
        except Exception as exc:  # noqa: BLE001
            detail = _gitops._scrub_secret(str(exc))
            failure = ValidationError(
                "git publication could not merge pull request %s: %s"
                % (pr.url or ("#%d" % pr.number), detail[:400])
            )
            failure.publication_retry_after_seconds = 600
            failure.publication_failure_kind = "pull_request_merge_failed"
            raise failure from None
        commands.append(
            {
                "name": "merge_pull_request",
                "attempt": attempt,
                "number": pr.number,
                "merged": merge.merged,
                "blocked": merge.blocked,
                "queued": merge.queued,
                "serialization": merge.serialization,
                "sha": merge.sha,
                "reason": merge.reason,
            }
        )
        if merge.queued and not merge.merged:
            # Accepted into the merge queue. The queue tests the projected
            # post-merge tree and lands it in order, so publication is not
            # complete yet: defer through the SAME retry backoff pending
            # checks use, and observe the merge on a later attempt.
            queued = ValidationError(
                "git publication placed %s in the %s merge queue; it lands once "
                "the queue's checks pass"
                % (pr.url or ("#%d" % pr.number), canonical_branch)
            )
            queued.publication_retry_after_seconds = 600
            queued.publication_failure_kind = "pull_request_queued"
            raise queued
        if not merge.merged:
            # The PR exists and is correct; the forge's own gates simply have
            # not finished. Publication is NOT complete, so the task stays in
            # REVIEWING and the existing publication-retry backoff re-attempts
            # later. Retrying is cheap because the PR is reused, not reopened.
            pending = ValidationError(
                "git publication is waiting on the pull request's own required "
                "checks before %s can merge into %s: %s"
                % (pr.url or ("#%d" % pr.number), canonical_branch, merge.reason[:300])
            )
            pending.publication_retry_after_seconds = 600
            pending.publication_failure_kind = "pull_request_checks_pending"
            raise pending

        if native:
            landed = queue.record_landed(
                queue_entry_id, landed_sha=str(merge.sha or "")
            )
            commands.append(
                {
                    "name": "merge_queue_landed",
                    "attempt": attempt,
                    "entry_id": queue_entry_id,
                    "observed_only": bool(pre_merged),
                    **landed,
                }
            )

        final_sha = str(merge.sha or "").strip()
        git_step(
            "refresh_canonical_after_merge",
            [
                "fetch",
                "origin",
                "+refs/heads/%s:refs/remotes/origin/%s"
                % (canonical_branch, canonical_branch),
            ],
        )
        verify_remote = git_step(
            "verify_remote_canonical",
            ["ls-remote", "origin", "refs/heads/%s" % canonical_branch],
        )
        remote_sha = str(verify_remote.get("stdout") or "").split(None, 1)
        remote_sha = remote_sha[0] if remote_sha else ""
        if not _GIT_SHA_RE.match(final_sha):
            final_sha = remote_sha
        if not _GIT_SHA_RE.match(final_sha):
            raise ValidationError(
                "git publication merged pull request #%d but could not resolve the "
                "resulting canonical SHA" % pr.number
            )
        contains_reviewed_head = (
            git_step(
                "verify_source_ancestor",
                ["merge-base", "--is-ancestor", head_sha, remote_sha or final_sha],
                check=False,
            ).get("returncode")
            == 0
        )
        merged_tree = str(
            git_step(
                "merged_canonical_tree",
                ["rev-parse", "%s^{tree}" % (remote_sha or final_sha)],
                check=False,
            ).get("stdout")
            or ""
        ).strip()
        self._announce_merge(
            task=task,
            canonical_branch=canonical_branch,
            source_branch=source_branch,
            pr_number=int(getattr(pr, "number", 0) or 0),
            pr_url=str(getattr(pr, "url", "") or ""),
            head_sha=head_sha,
            base_sha=base_sha,
            final_sha=final_sha,
            tree_sha=merged_tree,
            target=target,
        )
        return {
            "status": "published",
            "target": target,
            "repository_path": str(root),
            "canonical_branch": canonical_branch,
            "source_branch": source_branch,
            "remote_ref": remote_ref,
            "head_sha": head_sha,
            "base_sha": base_sha,
            "final_sha": final_sha,
            "publication_mode": "pull_request_squash",
            "merge_serialization": (
                MODE_NATIVE_QUEUE
                if native
                else (merge.serialization or mode or MODE_DIRECT_SQUASH)
            ),
            "pull_request_opened_by": opened_by,
            "pull_request_number": pr.number,
            "pull_request_url": pr.url,
            "contains_reviewed_head": bool(contains_reviewed_head),
            "attempt": attempt,
            "commands": commands,
        }

    def _publish_git_target_attempt(
        self,
        *,
        task: Task,
        target: str,
        remote_ref: str,
        source_branch: str,
        head_sha: str,
        clone_url: str,
        auth_url: str,
        auth_env: Mapping[str, str],
        canonical_branch: str,
        attempt: int,
        agent_pull_request: Optional[JsonDict] = None,
    ) -> JsonDict:
        """Build, test, and publish one exact-base candidate in a fresh clone."""

        from . import gitops as _gitops

        commands: List[JsonDict] = []
        with tempfile.TemporaryDirectory(prefix="mac-publish-") as tmp:
            root = Path(tmp)
            clone = self._git_output(
                root,
                [
                    "clone",
                    "--no-tags",
                    "--branch",
                    canonical_branch,
                    "--",
                    auth_url,
                    ".",
                ],
                timeout=240,
                env=auth_env,
            )
            commands.append(
                {
                    "name": "clone_exact_canonical",
                    "args": [
                        "clone",
                        "--no-tags",
                        "--branch",
                        canonical_branch,
                        "--",
                        clone_url,
                        ".",
                    ],
                    "attempt": attempt,
                    **clone,
                }
            )
            if clone["returncode"] != 0:
                raise ValidationError(
                    "git publication could not clone remote for merge: %s"
                    % (clone.get("stderr") or clone.get("stdout") or clone_url)
                )

            def git_step(
                name: str,
                args: List[str],
                timeout: int = 120,
                *,
                check: bool = True,
            ) -> JsonDict:
                result = self._git_output(root, args, timeout=timeout, env=auth_env)
                commands.append({"name": name, "args": args, **result})
                if check and result["returncode"] != 0:
                    raise ValidationError(
                        "git publication %s failed: %s"
                        % (name, result.get("stderr") or result.get("stdout") or args)
                    )
                return result

            git_step("configure_author_name", ["config", "user.name", "MAC Publisher"])
            git_step(
                "configure_author_email",
                ["config", "user.email", "publisher@mac.invalid"],
            )
            git_step(
                "fetch_source",
                [
                    "fetch",
                    "origin",
                    "+refs/heads/%s:refs/remotes/origin/%s"
                    % (source_branch, source_branch),
                ],
            )
            # Typed, because a missing object is PERMANENT: retrying cannot
            # make the SHA appear, and the sweep must stop re-picking this task.
            verify = git_step(
                "verify_commit",
                ["cat-file", "-e", "%s^{commit}" % head_sha],
                check=False,
            )
            if _git_step_returncode(verify) != 0:
                raise _PublicationAnchorMissingError(
                    "git publication verify_commit failed: the reviewed commit "
                    "%s does not exist in %s. It cannot be published: retrying "
                    "will not make it appear. Re-review against a commit that "
                    "is present. (%s)"
                    % (
                        head_sha,
                        clone_url,
                        str(verify.get("stderr") or "").strip()[:200],
                    )
                )
            base_result = git_step("exact_canonical_base", ["rev-parse", "HEAD"])
            base_sha = str(base_result.get("stdout") or "").strip()

            from mac.merge_queue import (
                validate_projected_merge,
                validate_projected_merge_contract,
            )
            from mac.native_merge_queue import MODE_NATIVE_QUEUE

            # WHICH MECHANISM SERIALIZES THIS LANDING.
            #
            # Read from the project's stored repository attribute rather than
            # probed here (mac.merge_capability): the answer changes maybe twice
            # a year and this is the worst possible moment to depend on a forge
            # API call. GitHub merge queues are organization-only, so for every
            # User-owned repository the operator has, `mac_native_queue` is not
            # a fallback -- it is the only path.
            strategy = self._resolve_publication_strategy(clone_url)
            serialization = self._resolve_merge_serialization(
                clone_url, canonical_branch
            )
            commands.append(
                {
                    "name": "merge_serialization_capability",
                    "attempt": attempt,
                    "mode": serialization["mode"],
                    "source": serialization["source"],
                    **serialization["capability"],
                }
            )
            use_native_queue = (
                serialization["mode"] == MODE_NATIVE_QUEUE
                and strategy["strategy"] == "pull_request"
            )

            queue = None
            queue_entry_id = ""
            queue_owner = ""
            projected_base_sha = base_sha
            if use_native_queue:
                queue = self._native_merge_queue()
                queue_owner = self._merge_queue_owner()
                queue_repository = _canonicalize_git_url(clone_url) or clone_url
                decision = queue.claim_slot(
                    repository=queue_repository,
                    branch=canonical_branch,
                    task_id=str(task.id),
                    head_sha=head_sha,
                    owner=queue_owner,
                    detail={"source_branch": source_branch},
                )
                commands.append(
                    {
                        "name": "merge_queue_slot",
                        "attempt": attempt,
                        **decision.to_dict(),
                    }
                )
                if not decision.admitted:
                    # The window is full, or another worker holds this slot.
                    # Deferring is the correct answer: the entry keeps its place
                    # in line and the existing publication backoff re-attempts.
                    deferred = ValidationError(
                        "mac merge queue deferred publication of %s: %s"
                        % (task.id, decision.reason)
                    )
                    deferred.publication_retry_after_seconds = max(
                        60, int(decision.defer_seconds or 300)
                    )
                    deferred.publication_failure_kind = "merge_queue_deferred"
                    raise deferred
                queue_entry_id = decision.entry.id if decision.entry else ""
                if decision.predecessors:
                    predecessor_entries = [
                        {
                            "head_sha": entry.head_sha,
                            "source_branch": str(
                                (entry.detail or {}).get("source_branch") or ""
                            ),
                        }
                        for entry in queue.live_entries(
                            queue_repository, canonical_branch
                        )
                        if entry.head_sha in set(decision.predecessors)
                    ]
                    projected_base_sha = self._build_speculative_base(
                        root, git_step, base_sha, predecessor_entries
                    )
                    commands.append(
                        {
                            "name": "merge_queue_speculative_base",
                            "attempt": attempt,
                            "tip": base_sha,
                            "speculative_base": projected_base_sha,
                            "predecessors": list(decision.predecessors),
                            "built": bool(projected_base_sha),
                        }
                    )
                    if not projected_base_sha:
                        # A predecessor we cannot fetch, or two queued changes
                        # that conflict. Never test against the bare tip
                        # instead: that result would be attributed to a queue
                        # position it was not tested at.
                        queue.release(queue_entry_id, owner=queue_owner)
                        stalled = ValidationError(
                            "mac merge queue could not project %s on top of the "
                            "%d change(s) ahead of it; deferring rather than "
                            "testing against a base this entry will not land on"
                            % (task.id, len(decision.predecessors))
                        )
                        stalled.publication_retry_after_seconds = 300
                        stalled.publication_failure_kind = (
                            "merge_queue_speculation_unavailable"
                        )
                        raise stalled

            gate = validate_projected_merge(str(root), projected_base_sha, head_sha)
            commands.append({"name": "merge_gate", **gate.to_dict()})
            if not gate.clean:
                if queue is not None and queue_entry_id:
                    # A conflict is this entry's fault, not the queue's: evict
                    # it, halve the window, and discard every speculative
                    # result that was built on top of it.
                    eviction = queue.evict(
                        queue_entry_id,
                        reason="projected merge conflicts with the queue base",
                    )
                    commands.append(
                        {
                            "name": "merge_queue_eviction",
                            "attempt": attempt,
                            "entry_id": queue_entry_id,
                            **eviction,
                        }
                    )
                merge_gate_error = ValidationError(
                    "git publication merge gate: task branch does not integrate onto "
                    "the current main tip (%s); conflicts: %s — route to integration "
                    "(rebase + resolve + re-verify), do not merge"
                    % (
                        gate.base_sha[:12] or "?",
                        ", ".join(gate.conflicted_files[:10])
                        or gate.error
                        or "unknown",
                    )
                )
                merge_gate_error.conflict_integration_context = {
                    "schema": "mac.merge_gate_conflict_context.v1",
                    "task_id": str(task.id),
                    "reviewed_head_sha": str(head_sha).strip(),
                    "current_main_sha": str(gate.base_sha or "").strip(),
                    "conflicted_paths": [
                        str(path).strip()
                        for path in gate.conflicted_files
                        if str(path).strip() and str(path).strip() != "<unknown>"
                    ],
                    "repo_root": str(root),
                }
                raise merge_gate_error

            # Scope the projected gate the way the REVIEW verifier scopes its
            # own, for the same reason and from the same helper.
            #
            # This ran the whole contract suite -- ~45 minutes -- under
            # MAC_HUB_VERIFY_TIMEOUT, which defaults to 1200s. It could not
            # finish, so no approved task could ever publish: it failed, retried
            # ~1200s later, failed again, and the task sat in REVIEWING,
            # approved and unpublished. Measured on task_de42aa6c: approved
            # 19:36:51, publication failed 20:02:44 and again 20:23:43.
            #
            # The projected tree differs from the tree review already gated only
            # by however far main moved, so the changed-file selection is the
            # honest question to ask of it. An unresolvable diff falls back to
            # the full command, exactly as the review helper does.
            required_checks: tuple[str, ...] = ()
            if strategy["strategy"] == "pull_request":
                probed = _gitops.required_status_check_contexts(
                    str(strategy["api_url"]), canonical_branch
                )
                required_checks = tuple(probed or ())
            commands.append(
                {
                    "name": "publication_strategy",
                    "strategy": strategy["strategy"],
                    "forge": strategy["forge"],
                    "reason": strategy["reason"],
                    "required_status_checks": list(required_checks),
                }
            )
            # WHO gates the merge. On the pull-request path the forge's own
            # required status checks run against the merge result GitHub will
            # actually produce, which is a strictly better question than the
            # hub's local re-projection of it -- and the local one costs 15-45
            # minutes under MAC_HUB_VERIFY_TIMEOUT, which is exactly why
            # approved tasks used to sit unpublished (see the note below). So
            # when the forge is demonstrably gating the branch, mac's reviewer
            # verdict decides whether a PR is opened and merged at all, and the
            # forge's checks decide whether that merge is permitted. When the
            # forge reports no required checks, the hub keeps its own gate --
            # a repo nobody protected must not silently lose the contract run.
            forge_gates_merge = bool(required_checks)

            projected_changed: list[str] = []
            try:
                projected_diff = self._git_output(
                    root,
                    ["diff", "--name-only", "%s...%s" % (projected_base_sha, head_sha)],
                    timeout=60,
                )
                if int(projected_diff.get("returncode") or 1) == 0:
                    projected_changed = [
                        line.strip()
                        for line in str(projected_diff.get("stdout") or "").splitlines()
                        if line.strip()
                    ]
            except Exception:  # noqa: BLE001 - an unreadable diff means "run everything"
                projected_changed = []
            full_test_command = self._hub_review_test_command(
                task, {"files_changed": projected_changed}
            )
            # Say which question was asked. The scoped and full commands take
            # ~15 and ~45 minutes, and only one of them fits the timeout -- so
            # a silent fallback to full looks exactly like a gate that hung,
            # and the timeout message says nothing about which ran.
            commands.append(
                {
                    "name": "publication_gate_scope",
                    "changed_files": len(projected_changed),
                    "scoped": bool(projected_changed)
                    and "run-sanity-tests.sh" in full_test_command,
                    "command": full_test_command[:200],
                }
            )
            if forge_gates_merge:
                commands.append(
                    {
                        "name": "publication_contract_gate",
                        "skipped": True,
                        "reason": "delegated to the pull request's required checks",
                        "required_status_checks": list(required_checks),
                    }
                )
            else:
                publication_test_runner = getattr(
                    self, "_publication_merge_test_runner", None
                )
                if publication_test_runner is None:
                    publication_test_runner = self._hub_verify_run_contract_test
                contract_gate = validate_projected_merge_contract(
                    str(root),
                    projected_base_sha,
                    head_sha,
                    full_test_command,
                    test_runner=publication_test_runner,
                    merge_gate=gate,
                )
                commands.append(
                    {"name": "publication_contract_gate", **contract_gate.to_dict()}
                )
                if not contract_gate.passed:
                    diagnosis = contract_gate.error or contract_gate.output_tail
                    if queue is not None and queue_entry_id:
                        eviction = queue.evict(
                            queue_entry_id,
                            reason="projected contract gate failed: %s"
                            % (diagnosis or "unknown failure")[:200],
                        )
                        commands.append(
                            {
                                "name": "merge_queue_eviction",
                                "attempt": attempt,
                                "entry_id": queue_entry_id,
                                **eviction,
                            }
                        )
                    raise ValidationError(
                        "git publication contract gate failed on the projected "
                        "current-main merge: %s" % (diagnosis or "unknown failure")
                    )

            if queue is not None and queue_entry_id:
                # THE TREES ARE THE RECEIPT. What lands is checked against
                # `tested_base_tree` at merge time, so recording it here is what
                # makes "never land an untested tree" enforceable rather than
                # asserted.
                base_tree = str(
                    git_step(
                        "merge_queue_tested_base_tree",
                        ["rev-parse", "%s^{tree}" % projected_base_sha],
                        check=False,
                    ).get("stdout")
                    or ""
                ).strip()
                recorded = queue.record_tested(
                    queue_entry_id,
                    owner=queue_owner,
                    base_sha=projected_base_sha,
                    base_tree=base_tree,
                    merge_tree=gate.merged_tree_sha,
                )
                commands.append(
                    {
                        "name": "merge_queue_tested",
                        "attempt": attempt,
                        "entry_id": queue_entry_id,
                        "recorded": bool(recorded),
                        "tested_base_sha": projected_base_sha,
                        "tested_base_tree": base_tree,
                        "tested_merge_tree": gate.merged_tree_sha,
                    }
                )
                if not recorded or not base_tree:
                    # We no longer hold the slot (a restart reclaimed it) or the
                    # tree is unreadable. Either way this result cannot be
                    # trusted to authorize a merge.
                    lost = ValidationError(
                        "mac merge queue could not record the tested trees for "
                        "%s; the slot is no longer held. Deferring." % task.id
                    )
                    lost.publication_retry_after_seconds = 300
                    lost.publication_failure_kind = "merge_queue_slot_lost"
                    raise lost

            if strategy["strategy"] == "pull_request":
                return self._publish_via_pull_request(
                    task=task,
                    target=target,
                    remote_ref=remote_ref,
                    source_branch=source_branch,
                    head_sha=head_sha,
                    base_sha=projected_base_sha,
                    canonical_branch=canonical_branch,
                    api_url=str(strategy["api_url"]),
                    commands=commands,
                    attempt=attempt,
                    git_step=git_step,
                    root=root,
                    agent_pull_request=agent_pull_request,
                    required_checks=required_checks,
                    serialization=serialization,
                    queue=queue,
                    queue_entry_id=queue_entry_id,
                )

            publication_mode = "fast_forward"
            ff_merge = git_step(
                "merge_source_ff", ["merge", "--ff-only", head_sha], check=False
            )
            if ff_merge["returncode"] != 0:
                already_merged = git_step(
                    "source_already_merged",
                    ["merge-base", "--is-ancestor", head_sha, "HEAD"],
                    check=False,
                )
                if already_merged["returncode"] == 0:
                    publication_mode = "already_integrated"
                else:
                    publication_mode = "merge_commit"
                    merge = git_step(
                        "merge_source",
                        ["merge", "--no-ff", "--no-edit", head_sha],
                        timeout=180,
                        check=False,
                    )
                    if merge["returncode"] != 0:
                        git_step("merge_abort", ["merge", "--abort"], check=False)
                        raise ValidationError(
                            "git publication merge_source failed: %s"
                            % (merge.get("stderr") or merge.get("stdout") or head_sha)
                        )
            publication_tree = git_step(
                "verify_projected_tree", ["rev-parse", "HEAD^{tree}"]
            )
            actual_tree_sha = str(publication_tree.get("stdout") or "").strip()
            if actual_tree_sha != gate.merged_tree_sha:
                raise ValidationError(
                    "git publication merged tree differs from the fully tested "
                    "projection: expected %s, observed %s"
                    % (gate.merged_tree_sha, actual_tree_sha or "<unresolved>")
                )
            final_head = git_step("final_head", ["rev-parse", "HEAD"])
            final_sha = str(final_head.get("stdout") or "").strip()
            push_args = [
                "push",
                "--force-with-lease=refs/heads/%s:%s"
                % (canonical_branch, base_sha),
                "origin",
                "HEAD:refs/heads/%s" % canonical_branch,
            ]
            push = git_step("push_main_occ", push_args, timeout=180, check=False)
            if push["returncode"] != 0:
                git_step(
                    "refresh_canonical_after_push_race",
                    [
                        "fetch",
                        "origin",
                        "+refs/heads/%s:refs/remotes/origin/%s"
                        % (canonical_branch, canonical_branch),
                    ],
                )
                observed_result = git_step(
                    "observed_canonical_after_push_race",
                    ["rev-parse", "refs/remotes/origin/%s" % canonical_branch],
                )
                observed_sha = str(observed_result.get("stdout") or "").strip()
                if observed_sha != base_sha:
                    raise _PublicationBaseMovedError(base_sha, observed_sha)
                raise ValidationError(
                    "git publication push_main_occ failed without canonical "
                    "movement: %s"
                    % (push.get("stderr") or push.get("stdout") or push_args)
                )
            verify_remote = git_step(
                "verify_remote_canonical",
                ["ls-remote", "origin", "refs/heads/%s" % canonical_branch],
            )
            remote_sha = str(verify_remote.get("stdout") or "").split(None, 1)[0]
            if remote_sha != final_sha:
                raise ValidationError(
                    "git publication remote canonical branch verification failed: "
                    "expected %s, "
                    "observed %s" % (final_sha, remote_sha or "<unresolved>")
                )
            contains_source = git_step(
                "verify_source_ancestor",
                ["merge-base", "--is-ancestor", head_sha, final_sha],
                check=False,
            )
            if contains_source["returncode"] != 0:
                raise ValidationError(
                    "git publication final canonical branch %s does not contain "
                    "reviewed commit %s"
                    % (final_sha, head_sha)
                )
            return {
                "status": "published",
                "target": target,
                "repository_path": str(root),
                "canonical_branch": canonical_branch,
                "source_branch": source_branch,
                "remote_ref": remote_ref,
                "head_sha": head_sha,
                "base_sha": base_sha,
                "final_sha": final_sha,
                "publication_mode": publication_mode,
                "attempt": attempt,
                "commands": commands,
            }

    def _build_conflict_integration_payload(
        self,
        *,
        approved_task_id: str,
        accepted_evidence_id: str,
        reviewed_head_sha: str,
        current_main_sha: str,
        attempt_base_sha: str,
        conflicted_paths: Sequence[str],
        repo_path: Path,
        depends_on: Optional[Sequence[str]] = None,
    ) -> JsonDict:
        """Thin ControlPlane wrapper over ``build_conflict_integration_payload``.

        Binds ``self._git_output`` (scoped to ``repo_path``) as the pure
        builder's ``git_runner`` so path-restricted landed-commit provenance is
        computed against the real canonical checkout.

        Returns the ``JsonDict`` payload; it does not persist anything or touch
        the REVIEWING flow.
        """

        def git_runner(args: List[str], timeout: int = 60) -> JsonDict:
            # Landed-commit provenance is best-effort: if the resolved repo path
            # is unavailable (e.g. a transient clone already cleaned up, or a
            # path that no longer exists), return a failure dict so the pure
            # builder records empty provenance rather than raising — a conflict
            # payload must always be producible.
            try:
                return self._git_output(repo_path, list(args), timeout=timeout)
            except OSError:
                return {"returncode": 1, "stdout": "", "stderr": "repo path unavailable"}

        return build_conflict_integration_payload(
            approved_task_id=approved_task_id,
            accepted_evidence_id=accepted_evidence_id,
            reviewed_head_sha=reviewed_head_sha,
            current_main_sha=current_main_sha,
            attempt_base_sha=attempt_base_sha,
            conflicted_paths=conflicted_paths,
            depends_on=depends_on,
            git_runner=git_runner,
        )

    @staticmethod
    def _conflict_integration_idempotency_fingerprint(
        *,
        approved_task_id: str,
        accepted_evidence_id: str,
        attempt_base_sha: str,
        current_main_sha: str,
        reviewed_head_sha: str,
        conflicted_paths: Sequence[str],
    ) -> str:
        """Stable fingerprint over the conflict identity.

        Duplicate conflict events for the SAME approved task, accepted
        evidence, attempt base, canonical tip, reviewed head, and conflict set
        must resolve to the SAME integration task rather than spawning
        duplicates.  The conflict set is order-normalised so path enumeration
        order never changes the fingerprint.
        """
        normalized_paths = sorted(
            {str(path).strip() for path in (conflicted_paths or []) if str(path).strip()}
        )
        material = json_dumps(
            {
                "schema": "mac.conflict_integration_fingerprint.v1",
                "approved_task_id": str(approved_task_id).strip(),
                "accepted_evidence_id": str(accepted_evidence_id).strip(),
                "attempt_base_sha": str(attempt_base_sha).strip(),
                "current_main_sha": str(current_main_sha).strip(),
                "reviewed_head_sha": str(reviewed_head_sha).strip(),
                "conflicted_paths": normalized_paths,
            }
        )
        return "sha256:%s" % hashlib.sha256(material.encode("utf-8")).hexdigest()

    def _find_linked_conflict_integration_task(
        self, approved_task_id: str, fingerprint: str
    ) -> Optional[str]:
        """Re-read any integration task already created for this exact conflict.

        Looks for a task whose metadata records the same
        ``conflict_integration.fingerprint`` and links back to the approved
        task.  This is the durable idempotency backstop that complements the
        ``create_task`` idempotency key, so a duplicate conflict event that
        loses the key race still resolves to the SAME single integration task.
        """
        try:
            rows = self.store.query_all(
                "SELECT id, state, dependencies, metadata, created_at "
                "FROM tasks WHERE metadata LIKE ? ORDER BY created_at DESC",
                ("%" + fingerprint + "%",),
            )
        except Exception:  # noqa: BLE001 - idempotency lookup is best-effort.
            return None
        for row in rows:
            try:
                metadata = ensure_json_object(json.loads(row["metadata"] or "{}"))
            except Exception:  # noqa: BLE001
                continue
            integration = ensure_json_object(metadata.get("conflict_integration"))
            if (
                str(integration.get("fingerprint") or "") == fingerprint
                and str(integration.get("approved_task_id") or "")
                == str(approved_task_id).strip()
            ):
                task_id = str(row["id"])
                if str(row["state"] or "") in TERMINAL_TASK_STATES:
                    continue
                self._reconcile_conflict_integration_family(
                    approved_task_id=str(approved_task_id).strip(),
                    keep_task_id=task_id,
                )
                return task_id
        return None

    def _reconcile_conflict_integration_family(
        self, *, approved_task_id: str, keep_task_id: str
    ) -> None:
        """Repair the live legacy-conflict family around one current task.

        Older deployments made the repair depend on the still-REVIEWING task
        it must unblock.  Repeated base movement then produced a new repair for
        each canonical tip, leaving every older baseline parked forever.  The
        exact-fingerprint lookup is the natural reconciliation point: retain
        the current conflict identity, clear its impossible parent dependency,
        and retire every older non-terminal repair for the same approved task.
        """

        try:
            keep = self.get_task(keep_task_id)
            if approved_task_id in keep.dependencies:
                # Hub-internal reconciliation (see above): clearing an
                # impossible parent dependency is not an operator edit and must
                # not stop and restart the task.
                self._update_task_fields(
                    keep_task_id,
                    dependencies=[
                        dependency
                        for dependency in keep.dependencies
                        if dependency != approved_task_id
                    ],
                    actor="default-review-workflow",
                )
            rows = self.store.query_all(
                "SELECT id, state, metadata FROM tasks WHERE metadata LIKE ?",
                ("%" + approved_task_id + "%",),
            )
        except Exception:  # noqa: BLE001 - publication diagnosis must survive.
            logging.getLogger("mac.conflict_integration").warning(
                "conflict integration family reconciliation failed for %s",
                approved_task_id,
                exc_info=True,
            )
            return

        for row in rows:
            candidate_id = str(row["id"])
            if (
                candidate_id == keep_task_id
                or str(row["state"] or "") in TERMINAL_TASK_STATES
            ):
                continue
            try:
                metadata = ensure_json_object(json.loads(row["metadata"] or "{}"))
            except Exception:  # noqa: BLE001
                continue
            integration = ensure_json_object(metadata.get("conflict_integration"))
            if (
                str(integration.get("role") or "") != "integration_repair"
                or str(integration.get("approved_task_id") or "")
                != approved_task_id
            ):
                continue
            try:
                self.close_task(
                    candidate_id,
                    TaskState.CANCELLED.value,
                    "default-review-workflow",
                    {
                        "reason": (
                            "superseded by the current integration conflict "
                            "baseline"
                        ),
                        "disposition": "superseded",
                        "replacement_task_id": keep_task_id,
                        "cleanup_grace_seconds": 0,
                    },
                )
            except Exception:  # noqa: BLE001 - keep the current repair usable.
                logging.getLogger("mac.conflict_integration").warning(
                    "failed to supersede stale integration repair %s",
                    candidate_id,
                    exc_info=True,
                )

    def _handoff_conflict_to_integration(
        self,
        *,
        task: Task,
        review: "Review",
        evidence: "Evidence",
        target: str,
        conflict_context: Mapping[str, Any],
        actor: str,
    ) -> Optional[str]:
        """Turn a legacy single-task publication conflict into ONE idempotent,
        context-rich integration repair task.

        Returns the integration task id (existing or newly created), or
        ``None`` when the handoff does not apply / could not be produced (the
        caller still records the diagnosis telemetry).
        """
        approved_task_id = str(task.id)
        metadata = ensure_json_object(task.metadata)
        # COORDINATION GUARD: plan-DAG coordination modes own their own
        # integration path; never divert them.
        coordination = ensure_json_object(metadata.get("coordination"))
        coordination_mode = str(coordination.get("mode") or "").strip()
        if coordination_mode in {
            "cooperative_integration",
            "plan_dag",
        }:
            return None

        reviewed_head_sha = str(conflict_context.get("reviewed_head_sha") or "").strip()
        current_main_sha = str(conflict_context.get("current_main_sha") or "").strip()
        conflicted_paths = [
            str(path).strip()
            for path in (conflict_context.get("conflicted_paths") or [])
            if str(path).strip()
        ]
        repo_root = str(conflict_context.get("repo_root") or "").strip()
        runtime = ensure_json_object(metadata.get("runtime"))
        attempt_base_sha = str(runtime.get("repository_base_sha") or "").strip()
        if not attempt_base_sha:
            # Without a valid attempt base the pure builder cannot validate; fall
            # back to the current main tip so the payload still records where the
            # attempt diverged (worst case: empty landed-since provenance).
            attempt_base_sha = current_main_sha
        if not (reviewed_head_sha and current_main_sha and conflicted_paths):
            # Not a structured merge-gate conflict (some other publish failure);
            # let the caller record the plain diagnosis without a handoff.
            return None

        fingerprint = self._conflict_integration_idempotency_fingerprint(
            approved_task_id=approved_task_id,
            accepted_evidence_id=str(evidence.id),
            attempt_base_sha=attempt_base_sha,
            current_main_sha=current_main_sha,
            reviewed_head_sha=reviewed_head_sha,
            conflicted_paths=conflicted_paths,
        )

        # Idempotency backstop: if an integration task already exists for this
        # exact conflict identity, reuse it rather than spawning a duplicate.
        existing = self._find_linked_conflict_integration_task(
            approved_task_id, fingerprint
        )
        if existing is not None:
            return existing

        try:
            payload = self._build_conflict_integration_payload(
                approved_task_id=approved_task_id,
                accepted_evidence_id=str(evidence.id),
                reviewed_head_sha=reviewed_head_sha,
                current_main_sha=current_main_sha,
                attempt_base_sha=attempt_base_sha,
                conflicted_paths=conflicted_paths,
                repo_path=Path(repo_root) if repo_root else Path("."),
                depends_on=[],
            )
        except (ValidationError, MACError):
            # Payload could not be assembled (e.g. an unexpected non-git sha);
            # do not spawn a malformed integration task — the caller still
            # surfaces the diagnosis.
            return None

        # DISTINCT AGENT: the integration executor must not be the approved
        # task's executor.  Model the integration task as a cooperative family
        # member of the approved task so the durable lease-based separation
        # (``_coordination_excluded_agent_ids``) excludes the executor, and add
        # an explicit exclusion of the executor agent as a belt-and-suspenders.
        excluded_agent_ids = sorted(
            {
                str(evidence.created_by).strip()
                for _ in (0,)
                if str(evidence.created_by or "").strip()
            }
            | {
                str(task.owner_agent_id).strip()
                for _ in (0,)
                if str(task.owner_agent_id or "").strip()
            }
        )

        integration_metadata: JsonDict = {
            "schema": "mac.task.v1",
            "conflict_integration": {
                "schema": "mac.conflict_integration_link.v1",
                "role": "integration_repair",
                "approved_task_id": approved_task_id,
                "accepted_evidence_id": str(evidence.id),
                "review_id": review.id,
                "publication_target": target,
                "fingerprint": fingerprint,
                "payload": payload,
            },
            "context_payload": payload,
            "publication_target": target,
            "relationships": {
                "parent_task_id": approved_task_id,
                "relationship": "integration_repair",
                "blocks": [approved_task_id],
            },
            "coordination": {
                "mode": "legacy_conflict_integration",
                "integration_task_id": approved_task_id,
                "require_distinct_agent": True,
            },
            "excluded_agent_ids": excluded_agent_ids,
            "retry_excluded_agent_ids": excluded_agent_ids,
        }
        # Carry the approved task's project and repository/execution contract so
        # the integration executor runs against the same repository.
        for carry_key in ("origin", "execution_contract", "acc_metadata", "runtime"):
            value = metadata.get(carry_key)
            if value is not None:
                integration_metadata[carry_key] = value

        landed_task_ids = [
            str(tid).strip()
            for tid in ensure_json_object(payload.get("landed_since_base")).get(
                "task_ids", []
            )
            if str(tid).strip()
        ]
        try:
            contention_metadata = {
                "schema": "mac.merge_conflict_contention.v1",
                "publication_target": target,
                "current_main_sha": current_main_sha,
                "reviewed_head_sha": reviewed_head_sha,
                "conflicted_path_count": len(conflicted_paths),
            }
            common_contention = {
                "task_id": approved_task_id,
                "project": task.project,
                "attempt": max(1, int(task.attempt_count or 0)),
                "stage": "publication",
                "reason": "base_moved_merge_conflict",
                "peer_task_ids": landed_task_ids,
                "wait_started_at": review.completed_at or review.created_at,
                "outcome": "blocked",
                "metadata": contention_metadata,
            }
            self.task_flow.record_contention(
                resource_class="repository_ref",
                resource_key="%s:%s:%s"
                % (str(task.project or ""), target, current_main_sha),
                **common_contention,
            )
            self.task_flow.record_contention(
                resource_class="repository_path_set",
                resource_key="%s:%s"
                % (
                    str(task.project or ""),
                    "\x00".join(sorted(conflicted_paths)),
                ),
                **common_contention,
            )
        except Exception:  # noqa: BLE001 - telemetry cannot block repair.
            logging.getLogger("mac.task_flow").warning(
                "failed to record merge contention for %s",
                approved_task_id,
                exc_info=True,
            )

        description = (
            "Legacy single-task publication conflict repair.\n\n"
            "The approved task %s (evidence %s, reviewed head %s) could not "
            "fast-forward onto the current canonical main tip %s: the reviewed "
            "branch conflicts on: %s.\n\n"
            "As a DISTINCT agent (you must not be the approved task's executor): "
            "rebase/resolve the reviewed change onto current main, rerun the FULL "
            "projected-main contract (validate_projected_merge_contract via "
            "scripts/run-contract-tests.sh on the projected merge), push a "
            "replacement ref, and trigger publication retry for the approved "
            "task. Current main is the canonical baseline; preserve it and record "
            "any supersession decision explicitly (see "
            "metadata.context_payload.supersession). Landed tasks touching the "
            "conflicted paths since the attempt base: %s."
            % (
                approved_task_id,
                str(evidence.id),
                reviewed_head_sha[:12],
                current_main_sha[:12],
                ", ".join(conflicted_paths[:20]) or "(unknown)",
                ", ".join(landed_task_ids) or "(none recorded)",
            )
        )

        try:
            integration_task = self.create_task(
                "Integrate conflicting approved task %s onto current main"
                % approved_task_id,
                description=description,
                project=task.project,
                priority=int(task.priority),
                required_capabilities=list(task.required_capabilities),
                # The approved task stays REVIEWING until this task resolves
                # its publication conflict.  A hard dependency on it creates
                # an unbreakable lifecycle deadlock.
                dependencies=[],
                metadata=integration_metadata,
                actor=actor,
                idempotency_key=fingerprint,
                _idempotency_scope="conflict-integration:%s" % approved_task_id,
            )
        except (ValidationError, MACError):
            # A concurrent duplicate conflict event may have won the create
            # race; re-read the linked integration task so both events resolve
            # to the SAME single task.
            return self._find_linked_conflict_integration_task(
                approved_task_id, fingerprint
            )
        self._reconcile_conflict_integration_family(
            approved_task_id=approved_task_id,
            keep_task_id=integration_task.id,
        )
        return integration_task.id

    def _validate_publication_evidence(self, task_id: str, evidence_id: Optional[str]) -> None:
        if evidence_id is None:
            raise ValidationError("publication requires evidence")
        task = self.get_task(task_id)
        evidence = self.get_evidence(str(evidence_id))
        if evidence.task_id != task_id:
            raise ValidationError("publication evidence must belong to task")
        if self.reviews.task_requires_publication_evidence(task):
            if evidence.kind != "publication":
                raise ValidationError("publication policy requires publication evidence")
            if not evidence.checksum:
                raise ValidationError("publication evidence requires a checksum")
            review_problems = self._publication_review_executor_problems(task_id)
            if review_problems:
                raise ValidationError(
                    "publication review evidence is not verifiable: %s"
                    % ", ".join(review_problems)
                )
            return
        assessment = self._assess_default_review_evidence(task, evidence)
        if not assessment.get("valid"):
            raise ValidationError(
                "publication evidence is not verifiable: %s"
                % ", ".join(str(item) for item in assessment.get("problems", []))
            )
        review_problems = self._publication_review_problems(task_id, evidence.id)
        if review_problems:
            raise ValidationError(
                "publication review evidence is not verifiable: %s"
                % ", ".join(review_problems)
            )

    def _publication_review_executor_problems(self, task_id: str) -> List[str]:
        task = self.get_task(task_id)
        approved = [
            review
            for review in self.list_reviews(task_id)
            if review.status == ReviewStatus.APPROVED.value
        ]
        if not approved:
            return ["publication requires an approved review"]
        problems: List[str] = []
        for review in approved:
            if not review.evidence_id:
                problems.append("review %s lacks review evidence" % review.id)
                continue
            try:
                verdict = self.get_evidence(review.evidence_id)
            except NotFoundError:
                problems.append("review %s references missing evidence" % review.id)
                continue
            manifest = verdict.metadata.get("verification")
            if not isinstance(manifest, dict):
                problems.append("review %s evidence lacks verification manifest" % review.id)
                continue
            executor_evidence_id = str(manifest.get("reviewed_evidence_id") or "").strip()
            if not executor_evidence_id:
                problems.append("review %s verdict lacks reviewed_evidence_id" % review.id)
                continue
            try:
                executor_evidence = self.get_evidence(executor_evidence_id)
            except NotFoundError:
                problems.append("review %s references missing executor evidence" % review.id)
                continue
            assessment = self._assess_default_review_evidence(task, executor_evidence)
            if not assessment.get("valid"):
                problems.append(
                    "review %s executor evidence is not verifiable: %s"
                    % (
                        review.id,
                        ", ".join(str(item) for item in assessment.get("problems", [])),
                    )
                )
                continue
            verdict_evidence, verdict_problems = self._find_review_verdict_evidence(
                task_id,
                review.reviewer_agent_id,
                executor_evidence_id=executor_evidence.id,
                verdict_evidence_id=review.evidence_id,
                not_before=review.created_at,
            )
            if verdict_evidence is not None and verdict_evidence.id == review.evidence_id:
                if self._verdict_value(verdict_evidence) == "approved":
                    return []
                problems.append("review %s verdict is not approved" % review.id)
                continue
            problems.append(
                "review %s lacks verifiable signed review_verdict evidence" % review.id
            )
            problems.extend(verdict_problems[:5])
        return problems

    def _publication_review_problems(self, task_id: str, executor_evidence_id: str) -> List[str]:
        approved = [
            review
            for review in self.list_reviews(task_id)
            if review.status == ReviewStatus.APPROVED.value
        ]
        if not approved:
            return ["publication requires an approved review"]
        problems: List[str] = []
        for review in approved:
            verdict_evidence, verdict_problems = self._find_review_verdict_evidence(
                task_id,
                review.reviewer_agent_id,
                executor_evidence_id=executor_evidence_id,
                verdict_evidence_id=review.evidence_id,
                not_before=review.created_at,
            )
            if verdict_evidence is not None and verdict_evidence.id == review.evidence_id:
                if self._verdict_value(verdict_evidence) == "approved":
                    return []
                problems.append("review %s verdict is not approved" % review.id)
                continue
            problems.append(
                "review %s lacks verifiable signed review_verdict evidence" % review.id
            )
            problems.extend(verdict_problems[:5])
        return problems

    def get_publication(self, publication_id: str) -> Publication:
        return self.reviews.get_publication(publication_id)

    def list_publications(self, *args: Any, **kwargs: Any) -> List[Publication]:
        return self.reviews.list_publications(*args, **kwargs)

    def _advance_default_review_sweep_page(
        self,
        *,
        limit: int,
        actor: str,
        tenant_id: Optional[str],
        allow_blocking_hub_verify: bool = True,
    ) -> JsonDict:
        """Advance one database-coordinated cursor page for autonomous callers."""
        claim = self.reconciliation.claim("default-review-sweep")
        if claim is None:
            return {
                "processed": 0,
                "results": [],
                "next_cursor": None,
                "has_more": False,
                "skipped": "lease_held",
            }
        try:
            result = self.advance_default_review_workflows(
                limit=limit,
                actor=actor,
                tenant_id=tenant_id,
                cursor=claim.cursor,
                allow_blocking_hub_verify=allow_blocking_hub_verify,
            )
        except Exception:
            self.reconciliation.abandon(claim)
            raise
        self.reconciliation.complete(
            claim,
            cursor=result.get("next_cursor"),
        )
        return result

    def advance_default_review_workflows(
        self,
        limit: int = 100,
        actor: str = "default-review-workflow",
        tenant_id: Optional[str] = None,
        cursor: Optional[str] = None,
        allow_blocking_hub_verify: bool = True,
    ) -> JsonDict:
        """Sweep one bounded, state-filtered page of reviewable tasks.

        ``cursor`` is the opaque ``next_cursor`` from a prior response.
        Autonomous callers persist it in ``reconciliation_state`` so tasks
        waiting on a verdict cannot starve later reviewable rows indefinitely.
        """
        limit_value = max(1, min(int(limit), 1000))
        clauses = ["state IN ('needs_review', 'reviewing')"]
        params: List[Any] = []
        if tenant_id is not None:
            clauses.append(
                "COALESCE("
                "NULLIF(json_extract(metadata, '$.origin.tenant_id'), ''), "
                "NULLIF(json_extract(metadata, '$.tenant_id'), '')"
                ") = ?"
            )
            params.append(tenant_id)
        if cursor is not None:
            priority, created_at, task_id = self._decode_review_sweep_cursor(cursor)
            clauses.append(
                "(priority < ? OR "
                "(priority = ? AND created_at > ?) OR "
                "(priority = ? AND created_at = ? AND id > ?))"
            )
            params.extend(
                [priority, priority, created_at, priority, created_at, task_id]
            )
        params.append(limit_value + 1)
        rows = self.store.query_all(
            "SELECT * FROM tasks INDEXED BY idx_tasks_review_queue WHERE %s "
            "ORDER BY priority DESC, created_at, id LIMIT ?"
            % " AND ".join(clauses),
            tuple(params),
        )
        has_more = len(rows) > limit_value
        tasks = [self._task_from_row(row) for row in rows[:limit_value]]
        results = []
        for task in tasks:
            # Per-task isolation: a single unadvanceable review (stale state, a
            # concurrent completion, bad evidence) must not abort the whole
            # sweep — and, because this sweep runs inside the hub self-tick,
            # must not abort the tick and starve dispatch. The self-driver never
            # crashes the hub; it records the failure and moves on.
            try:
                if allow_blocking_hub_verify:
                    result = self.advance_default_review_workflow(
                        task.id,
                        actor=actor,
                    )
                else:
                    result = self.advance_default_review_workflow(
                        task.id,
                        actor=actor,
                        allow_blocking_hub_verify=False,
                    )
                results.append(result)
            except Exception as exc:  # noqa: BLE001 - one row must not stop the sweep
                try:
                    self._record_default_review_observation(
                        task.id,
                        "workflow.default_review.error",
                        "error",
                        {"error": str(exc), "error_class": exc.__class__.__name__},
                        actor,
                    )
                except Exception:  # noqa: BLE001 - best-effort telemetry only
                    pass
                results.append(
                    {
                        "task_id": task.id,
                        "status": "error",
                        "error": str(exc),
                        "error_class": exc.__class__.__name__,
                    }
                )
        next_cursor = (
            self._encode_review_sweep_cursor(tasks[-1])
            if has_more and tasks
            else None
        )
        return {
            "processed": len(results),
            "results": results,
            "next_cursor": next_cursor,
            "has_more": has_more,
        }

    def _encode_review_sweep_cursor(self, task: Task) -> str:
        payload = json_dumps(
            {
                "priority": int(task.priority),
                "created_at": task.created_at,
                "task_id": task.id,
            }
        ).encode("utf-8")
        encoded = base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")
        return "v1:%s" % encoded

    def _decode_review_sweep_cursor(self, cursor: str) -> Tuple[int, str, str]:
        raw = str(cursor or "").strip()
        if not raw.startswith("v1:"):
            raise ValidationError("invalid review sweep cursor")
        encoded = raw[3:]
        try:
            padding = "=" * (-len(encoded) % 4)
            payload = json_loads(
                base64.urlsafe_b64decode((encoded + padding).encode("ascii")).decode(
                    "utf-8"
                ),
                {},
            )
            priority = int(payload["priority"])
            created_at = str(payload["created_at"])
            task_id = str(payload["task_id"])
        except (binascii.Error, KeyError, TypeError, ValueError, UnicodeError):
            raise ValidationError("invalid review sweep cursor") from None
        if not created_at or not task_id:
            raise ValidationError("invalid review sweep cursor")
        return priority, created_at, task_id

    def _terminal_review_noop(self, task_id: str) -> Optional[JsonDict]:
        """Return a terminal-aware successful no-op result when ``task_id`` has
        already been completed and/or published, otherwise ``None``.

        The default-review workflow runs from both the periodic sweep actor
        (``default-review-workflow``) and the event-driven consumer
        (``event-driven-review``). When those race, one consumer can complete +
        publish a task while the other is mid-flight. Re-reading the terminal
        state through this helper — at entry, immediately before publishing, and
        in the publish-failure handler — lets the losing consumer return an
        idempotent no-op (never a spurious ``publish_failed`` diagnosis) while
        preserving the canonical publication receipt of the first publish.
        """
        task = self.get_task(task_id)
        published = [
            publication
            for publication in self.list_publications(task_id)
            if publication.status == PublicationStatus.PUBLISHED.value
        ]
        if published:
            # Return the id of the EXISTING published publication; never create
            # or mutate a second receipt.
            return {
                "task_id": task_id,
                "status": "already_published",
                "publication_id": published[-1].id,
            }
        if task.state == TaskState.COMPLETED.value:
            return {"task_id": task_id, "status": "already_completed"}
        return None

    def advance_default_review_workflow(
        self,
        task_id: str,
        actor: str = "default-review-workflow",
        *,
        allow_blocking_hub_verify: bool = True,
    ) -> JsonDict:
        # Terminal-aware entry gate: if a concurrent consumer already
        # completed/published this task, no-op with the existing receipt.
        terminal = self._terminal_review_noop(task_id)
        if terminal is not None:
            return terminal
        task = self.get_task(task_id)
        if task.state not in {TaskState.NEEDS_REVIEW.value, TaskState.REVIEWING.value}:
            return {"task_id": task_id, "status": "not_reviewable", "state": task.state}
        publication_retry = ensure_json_object(
            ensure_json_object(task.metadata).get("publication_retry")
        )
        retry_not_before = str(publication_retry.get("not_before") or "").strip()
        if retry_not_before:
            try:
                if parse_time(utcnow()) < parse_time(retry_not_before):
                    return {
                        "task_id": task_id,
                        "status": "publication_backoff",
                        "not_before": retry_not_before,
                        "failure_kind": publication_retry.get("failure_kind"),
                    }
            except (TypeError, ValueError):
                # Malformed controller metadata must not strand the task.
                pass
        if self._default_review_disabled(task):
            self._record_default_review_observation(
                task_id,
                "workflow.default_review.skipped",
                "info",
                {"reason": "disabled_by_task_policy"},
                actor,
            )
            return {"task_id": task_id, "status": "disabled_by_task_policy"}

        evidence, evidence_assessment = self._bound_review_evidence(task)
        if evidence is None:
            self._record_default_review_observation(
                task_id,
                "workflow.default_review.waiting",
                "warning",
                evidence_assessment,
                actor,
            )
            return {
                "task_id": task_id,
                "status": "waiting_for_verifiable_evidence",
                **evidence_assessment,
            }

        # If the task has more than one pending review, refuse to act —
        # the ambiguous state has no clear winner and the autonomous
        # swarm shouldn't silently pick one (mac-d9c).
        pending_reviews = [
            r for r in self.list_reviews(task_id)
            if r.status == ReviewStatus.PENDING.value
        ]
        pending_reviews = self._dedupe_same_reviewer_pending_reviews(
            pending_reviews,
            actor,
        )
        if len(pending_reviews) > 1:
            self._record_default_review_observation(
                task_id,
                "workflow.default_review.ambiguous",
                "warning",
                {
                    "reason": "multiple_pending_reviews",
                    "pending_review_ids": [r.id for r in pending_reviews],
                },
                actor,
            )
            return {
                "task_id": task_id,
                "status": "ambiguous_pending_reviews",
                "pending_review_ids": [r.id for r in pending_reviews],
            }

        review = self._default_review_for_task(task_id)
        if review is not None and review.status == ReviewStatus.PENDING.value:
            reviewer_issue = self._default_reviewer_unavailable_reason_for_id(
                task,
                review.reviewer_agent_id,
                executor_agent_id=evidence.created_by,
                allow_conditional_independence_fallback=True,
            )
            if reviewer_issue is not None:
                self._retract_default_review(
                    review,
                    actor,
                    "reviewer_unavailable:%s" % reviewer_issue,
                )
                self._record_default_review_observation(
                    task_id,
                    "workflow.default_review.retracted",
                    "warning",
                    {
                        "review_id": review.id,
                        "reviewer_agent_id": review.reviewer_agent_id,
                        "reason": reviewer_issue,
                    },
                    actor,
                )
                review = None
        if review is None:
            # mem-12: bound review retraction. Before creating a fresh
            # review for the same executor evidence, count how many
            # reviews for this task have already retracted *since the
            # latest evidence was recorded*. If we've hit the cap, block
            # the task for repair — looping forever is what bit task_d7c51a0b
            # with 503 retracted reviews in the original incident.
            try:
                retraction_cap = int(os.environ.get("MAC_REVIEW_RETRACTION_CAP", "3"))
            except ValueError:
                retraction_cap = 3
            # mem-12 window fix: scope the retraction count to "retractions
            # since the work under review was submitted" — i.e. the executor
            # evidence we are actually reviewing (already resolved above as
            # ``evidence``). The original query took the latest evidence of
            # ANY kind, so the reviewer's own ``review``-kind attempt evidence
            # advanced the window every cycle and the cap never tripped — the
            # bug behind the 2026-06 review runaway. Genuine rework still
            # resets the window because new executor evidence becomes the
            # reviewed ``evidence`` on the next advance.
            threshold_at = evidence.created_at or ""
            retracted_count_row = self.store.query_one(
                """
                SELECT COUNT(*) AS n FROM reviews
                WHERE task_id = ? AND status = ?
                  AND created_at >= ?
                """,
                (task_id, ReviewStatus.RETRACTED.value, threshold_at),
            )
            retracted_count = (
                int(retracted_count_row["n"]) if retracted_count_row else 0
            )
            if retracted_count >= retraction_cap:
                self._record_default_review_observation(
                    task_id,
                    "workflow.default_review.exhausted",
                    "error",
                    {
                        "reason": "review_retraction_cap_hit",
                        "cap": retraction_cap,
                        "retracted_count": retracted_count,
                        "executor_evidence_id": evidence.id,
                    },
                    actor,
                )
                self._record_history(
                    task_id,
                    "task.review_exhausted",
                    actor,
                    None,
                    None,
                    {
                        "cap": retraction_cap,
                        "retracted_count": retracted_count,
                        "executor_evidence_id": evidence.id,
                    },
                )
                try:
                    self._transition_task_internal(
                        task_id,
                        TaskState.BLOCKED.value,
                        actor,
                        {
                            "reason": "review_retraction_cap_hit",
                            "manual_repair_required": True,
                            "cap": retraction_cap,
                            "retracted_count": retracted_count,
                            "executor_evidence_id": evidence.id,
                        },
                    )
                except TransitionError:
                    # Already terminal or otherwise moved: nothing more to do.
                    pass
                return {
                    "task_id": task_id,
                    "status": "review_retraction_exhausted",
                    "cap": retraction_cap,
                    "retracted_count": retracted_count,
                }
            protocol_failed_reviewer_ids = {
                str(row["reviewer_agent_id"])
                for row in self.store.query_all(
                    """
                    SELECT reviewer_agent_id FROM reviews
                    WHERE task_id = ? AND status = ?
                      AND created_at >= ?
                      AND reason LIKE 'reviewer_protocol_failure:%'
                    """,
                    (task_id, ReviewStatus.RETRACTED.value, threshold_at),
                )
            }
            reviewer = self._select_default_reviewer(
                task,
                executor_agent_id=evidence.created_by,
                excluded_agent_ids=protocol_failed_reviewer_ids,
            )
            if reviewer is None:
                review_policy = self._default_review_policy(task)
                target_reviewer_id = str(
                    review_policy.get("target_agent_id")
                    or review_policy.get("reviewer_agent_id")
                    or ""
                ).strip()
                if target_reviewer_id in protocol_failed_reviewer_ids:
                    detail = {
                        "reason": "target_reviewer_protocol_failed",
                        "manual_repair_required": True,
                        "reviewer_agent_id": target_reviewer_id,
                        "executor_evidence_id": evidence.id,
                    }
                    self._record_default_review_observation(
                        task_id,
                        "workflow.default_review.target_reviewer_protocol_failed",
                        "error",
                        detail,
                        actor,
                    )
                    try:
                        self._transition_task_internal(
                            task_id,
                            TaskState.BLOCKED.value,
                            actor,
                            detail,
                        )
                    except TransitionError:
                        pass
                    return {
                        "task_id": task_id,
                        "status": "target_reviewer_protocol_failed",
                        **detail,
                    }
                self._ensure_hub_review_verifier_agent(task, actor=actor)
                reviewer = self._select_default_reviewer(
                    task,
                    executor_agent_id=evidence.created_by,
                    excluded_agent_ids=protocol_failed_reviewer_ids,
                )
            if reviewer is None:
                reviewer = self._select_default_reviewer(
                    task,
                    executor_agent_id=evidence.created_by,
                    excluded_agent_ids=protocol_failed_reviewer_ids,
                    allow_independence_fallback=True,
                )
            if reviewer is None:
                self._record_default_review_observation(
                    task_id,
                    "workflow.default_review.waiting",
                    "warning",
                    {"reason": "no_eligible_reviewer"},
                    actor,
                )
                # Signal that the swarm needs a reviewer-capable agent it
                # doesn't have. The default-review workflow will pick the
                # request up on a future tick once the provisioner has
                # registered a matching agent.
                self.provisioning.request_agent(
                    reason="review.no_eligible_reviewer",
                    capabilities=["review"],
                    task_id=task_id,
                    tenant_id=self._task_tenant_id(task),
                    detail={
                        "evidence_type": evidence_assessment.get("evidence_type"),
                    },
                )
                return {"task_id": task_id, "status": "waiting_for_reviewer"}
            fallback_reason = self._reviewer_independence_fallback_reason(
                task,
                reviewer,
                executor_agent_id=evidence.created_by,
                excluded_agent_ids=protocol_failed_reviewer_ids,
            )
            review = self.request_review(task_id, reviewer.id, actor=actor)
            assignment_detail = {
                "review_id": review.id,
                "reviewer_agent_id": reviewer.id,
                "reviewer_independence": (
                    "fallback" if fallback_reason else "independent"
                ),
            }
            if fallback_reason:
                assignment_detail["reviewer_independence_reason"] = fallback_reason
            self._record_default_review_observation(
                task_id,
                "workflow.default_review.assigned",
                "info",
                assignment_detail,
                actor,
            )

        if review.status == ReviewStatus.PENDING.value:
            # mac-jqb: the workflow no longer self-approves. It requires
            # the reviewer agent to have produced a *review verdict*
            # evidence row — a separate, signed manifest authored by
            # the reviewer (not the executor) declaring approve/reject.
            # Until that exists, the review stays pending. This makes
            # the second-eyes role actually do work; today the workflow
            # waits for the verdict, and a follow-up review-executor
            # worker will produce it automatically.
            verdict_evidence, verdict_problems = self._find_review_verdict_evidence(
                task_id,
                review.reviewer_agent_id,
                executor_evidence_id=evidence.id,
                not_before=review.created_at,
            )
            # Option C — hub-side verification. Instead of dispatching a nudge
            # and waiting for a reviewer agent to independently clone + run the
            # contract test (fragile: every reviewer node needs a working dev
            # environment, in-sandbox and host, and the sandbox->host handoff
            # to be perfect), the hub runs the contract test ONCE in a
            # controlled OpenShell sandbox on the pushed branch and records the
            # signed verdict on the selected reviewer's behalf. Second-eyes
            # holds (the verdict is signed by a non-author agent); the fragile
            # N-node verification collapses to one controlled environment.
            if verdict_evidence is None and _hub_review_verify_enabled():
                if allow_blocking_hub_verify:
                    self._run_hub_review_verification(task, review, evidence, actor)
                else:
                    # The periodic tick owns lease expiry, dependency
                    # unblocking, and dispatch. Never make that clock wait for
                    # Git/OpenShell/tests; the dedicated event consumer retains
                    # the same fail-closed verifier and per-review in-flight
                    # guard.
                    self._nudge_review_workflow(task.id)
                verdict_evidence, verdict_problems = self._find_review_verdict_evidence(
                    task_id,
                    review.reviewer_agent_id,
                    executor_evidence_id=evidence.id,
                    not_before=review.created_at,
                )
                # Blocking guard (Option C): hub verify is the authoritative
                # review gate.  If no verdict was produced in this tick (e.g.
                # the sandbox is still running, the reviewer key is not yet
                # available, or a concurrent in-flight guard fired), we MUST
                # NOT fall through to the agent-nudge path — that would allow
                # an unverified task to advance toward merge.  Return a
                # waiting status so the sweep retries on the next tick.
                #
                # Exception: experiment tasks need a human-model reviewer for
                # measurement validity; they skip hub verify and keep the
                # agent-nudge path (see hub_verify_skipped observation recorded
                # inside _run_hub_review_verification).
                if verdict_evidence is None:
                    task_meta = ensure_json_object(task.metadata)
                    experiment_assignment = ensure_json_object(
                        task_meta.get("review_experiment")
                    )
                    is_experiment = (
                        experiment_assignment.get("schema") == "mac.review_experiment.v1"
                    )
                    # Hold the merge gate only for evidence hub-verify can
                    # actually gate: a pushed repo change with a contract test to
                    # run. Evidence that is NOT a pushed repo change (e.g. an
                    # operator_result log from a non-code task) has nothing to
                    # hub-verify, so waiting for a verdict that can never be
                    # produced stalls the review forever — until the lease
                    # expires and the task fails. Fall through to the agent-nudge
                    # path so a real reviewer performs the semantic second-eyes
                    # review instead (its signed verdict is still required; the
                    # merge gate is not weakened for actual code changes).
                    hub_verifiable = (
                        self._hub_verify_repo_info(task, evidence) is not None
                    )
                    if not is_experiment and hub_verifiable:
                        self._record_default_review_observation(
                            task_id,
                            "workflow.default_review.waiting_for_hub_verify",
                            "warning",
                            {
                                "review_id": review.id,
                                "reviewer_agent_id": review.reviewer_agent_id,
                                "executor_evidence_id": evidence.id,
                                "reason": "hub_verify_in_progress_or_pending",
                            },
                            actor,
                        )
                        return {
                            "task_id": task_id,
                            "status": "waiting_for_hub_verify",
                            "review_id": review.id,
                            "reviewer_agent_id": review.reviewer_agent_id,
                            "executor_evidence_id": evidence.id,
                        }
            if verdict_evidence is None:
                failed_attempt, failure_reason = self._review_attempt_protocol_failure(
                    task_id,
                    review,
                    executor_evidence_id=evidence.id,
                )
                if failed_attempt is not None:
                    retraction_reason = "reviewer_protocol_failure:%s" % failure_reason
                    self._retract_default_review(review, actor, retraction_reason)
                    self._record_default_review_observation(
                        task_id,
                        "workflow.default_review.reviewer_protocol_failed",
                        "warning",
                        {
                            "review_id": review.id,
                            "reviewer_agent_id": review.reviewer_agent_id,
                            "executor_evidence_id": evidence.id,
                            "review_attempt_evidence_id": failed_attempt.id,
                            "reason": failure_reason,
                            "problems": verdict_problems,
                        },
                        actor,
                    )
                    return {
                        "task_id": task_id,
                        "status": "reviewer_protocol_failed",
                        "review_id": review.id,
                        "reviewer_agent_id": review.reviewer_agent_id,
                        "review_attempt_evidence_id": failed_attempt.id,
                        "reason": failure_reason,
                    }
                # Bound the verdict-wait loop. mem-12 only caps RETRACTION;
                # a reviewer that keeps producing review-attempt evidence but
                # never a valid signed verdict would otherwise spin here
                # forever, re-nudging every tick (task_5de06b: 59 review-kind
                # evidence rows, 0 verdict — the live half of the 2026-06
                # runaway). Past a cap, block the task instead of re-nudging.
                try:
                    verdict_wait_cap = int(
                        os.environ.get("MAC_REVIEW_VERDICT_WAIT_CAP", "6")
                    )
                except ValueError:
                    verdict_wait_cap = 6
                wait_count_row = self.store.query_one(
                    """
                    SELECT COUNT(*) AS n FROM evidence
                    WHERE task_id = ? AND kind = 'review'
                      AND created_at >= ?
                    """,
                    (task_id, review.created_at),
                )
                wait_count = int(wait_count_row["n"]) if wait_count_row else 0
                if verdict_wait_cap > 0 and wait_count >= verdict_wait_cap:
                    self._record_default_review_observation(
                        task_id,
                        "workflow.default_review.exhausted",
                        "error",
                        {
                            "reason": "review_verdict_wait_cap_hit",
                            "cap": verdict_wait_cap,
                            "wait_count": wait_count,
                            "review_id": review.id,
                            "reviewer_agent_id": review.reviewer_agent_id,
                        },
                        actor,
                    )
                    self._record_history(
                        task_id,
                        "task.review_exhausted",
                        actor,
                        None,
                        None,
                        {
                            "reason": "review_verdict_wait_cap_hit",
                            "cap": verdict_wait_cap,
                            "wait_count": wait_count,
                            "review_id": review.id,
                        },
                    )
                    try:
                        self._transition_task_internal(
                            task_id,
                            TaskState.BLOCKED.value,
                            actor,
                            {
                                "reason": "review_verdict_wait_cap_hit",
                                "manual_repair_required": True,
                                "cap": verdict_wait_cap,
                                "wait_count": wait_count,
                                "review_id": review.id,
                            },
                        )
                    except TransitionError:
                        pass
                    return {
                        "task_id": task_id,
                        "status": "review_verdict_wait_exhausted",
                        "cap": verdict_wait_cap,
                        "wait_count": wait_count,
                        "review_id": review.id,
                    }
                self._record_default_review_observation(
                    task_id,
                    "workflow.default_review.waiting_for_verdict",
                    "warning",
                    {
                        "review_id": review.id,
                        "reviewer_agent_id": review.reviewer_agent_id,
                        "evidence_id": evidence.id,
                        "problems": verdict_problems,
                    },
                    actor,
                )
                nudge = self._ensure_review_verdict_nudge(task_id, review, evidence)
                return {
                    "task_id": task_id,
                    "status": "waiting_for_reviewer_verdict",
                    "review_id": review.id,
                    "reviewer_agent_id": review.reviewer_agent_id,
                    "executor_evidence_id": evidence.id,
                    "problems": verdict_problems,
                    "nudge_id": nudge.id if nudge is not None else None,
                    "nudge_status": "queued" if nudge is not None else "already_queued",
                }
            verdict_value = self._verdict_value(verdict_evidence)
            if review.status != ReviewStatus.PENDING.value:
                # A prior tick, the event-driven advance, or the reviewer already
                # recorded this verdict, but the task never left the review state
                # (e.g. the tick crashed before publishing). Re-submitting a
                # completed review raises "review is already completed" which,
                # unguarded, aborts the entire hub tick every cycle and wedges
                # the task in review forever. Skip re-submission and fall through
                # to the status gate + publication below so approved work lands.
                pass
            elif verdict_value == "rejected":
                review = self.submit_review(
                    review.id,
                    ReviewStatus.REJECTED.value,
                    review.reviewer_agent_id,
                    reason="reviewer rejected via signed verdict evidence",
                    evidence_id=verdict_evidence.id,
                )
                self._record_default_review_observation(
                    task_id,
                    "workflow.default_review.rejected",
                    "warning",
                    {
                        "review_id": review.id,
                        "reviewer_agent_id": review.reviewer_agent_id,
                        "verdict_evidence_id": verdict_evidence.id,
                    },
                    actor,
                )
                # Distill the rejection into a durable, project-scoped lesson so
                # the next execution run on this project recalls it (the review
                # branch never wrote a deployment_learning record, so rejected
                # work taught the fleet nothing — a real learn-from-bad gap).
                self._record_project_failure_lesson(
                    task_id,
                    evidence_type="review_verdict",
                    error_signature="review_rejected",
                    signals={"review_rejected": True, "problems": list(verdict_problems or [])[:5]},
                    evidence_id=verdict_evidence.id,
                )
            else:
                review = self.submit_review(
                    review.id,
                    ReviewStatus.APPROVED.value,
                    review.reviewer_agent_id,
                    reason="reviewer approved via signed verdict evidence",
                    evidence_id=verdict_evidence.id,
                )
                self._record_default_review_observation(
                    task_id,
                    "workflow.default_review.approved",
                    "info",
                    {
                        "review_id": review.id,
                        "reviewer_agent_id": review.reviewer_agent_id,
                        "verdict_evidence_id": verdict_evidence.id,
                        "executor_evidence_id": evidence.id,
                        "evidence_type": evidence_assessment.get("evidence_type"),
                    },
                    actor,
                )
            # The publication evidence below stays as the executor's
            # signed work — that's the artifact being published. The
            # reviewer's verdict was just consumed onto the review row
            # via submit_review(evidence_id=verdict_evidence.id) above.

        if review.status != ReviewStatus.APPROVED.value:
            return {
                "task_id": task_id,
                "status": "review_not_approved",
                "review_id": review.id,
                "review_status": review.status,
            }

        task = self.get_task(task_id)
        if task.state != TaskState.REVIEWING.value:
            return {
                "task_id": task_id,
                "status": "approved_not_publishable",
                "state": task.state,
                "review_id": review.id,
            }
        if self.reviews.task_requires_publication_evidence(task):
            self._record_default_review_observation(
                task_id,
                "workflow.default_review.waiting",
                "warning",
                {
                    "reason": "publication_evidence_required",
                    "review_id": review.id,
                    "evidence_id": evidence.id,
                },
                actor,
            )
            return {
                "task_id": task_id,
                "status": "waiting_for_publication_evidence",
                "review_id": review.id,
            }

        target = self._default_publication_target(task)
        if target is None:
            if metadata_declares_report_deliverable(task.metadata):
                # The reviewed operator_result itself is the durable report
                # deliverable. Publish that hub-owned evidence identity rather
                # than inventing or inheriting a Git merge target.
                target = "evidence://%s" % evidence.id
            else:
                # No operator-configured publication destination; refuse to
                # invent one. The review is approved, but the task stays in
                # REVIEWING until an operator sets metadata.publication_target
                # (mac-w29).
                #
                # Stamp the reason onto the task as well as into the event
                # stream. The event is the record that it happened; the marker
                # is what makes the CURRENT state self-describing, so the
                # "reviewing-publication-parked" diagnostic and `mac task stats`
                # can tell a parked task from work in flight without anyone
                # thinking to go looking (task_ce6c8ea3).
                self._record_publication_block(
                    task_id,
                    reason="no_publication_target",
                    review_id=review.id,
                    evidence_id=evidence.id,
                    actor=str(actor or "control-plane"),
                )
                self._record_default_review_observation(
                    task_id,
                    "workflow.default_review.no_publication_target",
                    "warning",
                    {"review_id": review.id, "evidence_id": evidence.id},
                    actor,
                )
                return {
                    "task_id": task_id,
                    "status": "waiting_for_publication_target",
                    "review_id": review.id,
                }
        # Re-read terminal state immediately before publishing. Between the
        # approval gate above and this point a racing consumer (sweep vs.
        # event-driven-review) may have already completed + published this
        # task. Publishing again would either create a duplicate receipt or
        # raise TransitionError('task state changed during publish; retry');
        # instead return the existing receipt as an idempotent no-op.
        terminal = self._terminal_review_noop(task_id)
        if terminal is not None:
            return terminal
        try:
            publication = self.publish_task(
                task_id,
                target,
                review.reviewer_agent_id,
                evidence_id=evidence.id,
            )
        except PublicationDeferredError as exc:
            barrier = dict(exc.barrier)
            self._record_publication_deferred_once(
                task_id,
                barrier=barrier,
                target=target,
                review_id=review.id,
                evidence_id=evidence.id,
                actor=actor,
            )
            return {
                "task_id": task_id,
                "status": "publication_deferred",
                "review_id": review.id,
                "target": target,
                "reason": str(exc),
                "barrier": barrier,
            }
        except (ValidationError, MACError) as exc:
            # A concurrent consumer may have completed + published this task
            # after the pre-publish re-read (or its publish_task landed the
            # WHERE state=REVIEWING UPDATE first, so ours raised
            # TransitionError('task state changed during publish; retry') /
            # ValidationError). Re-read terminal state BEFORE recording any
            # failure telemetry: if the task is now completed/published, the
            # exception was caused by that concurrent completion, so treat it
            # as a successful no-op and never emit a spurious publish_failed
            # diagnosis. Only genuine, still-in-REVIEWING failures (e.g. a real
            # merge conflict) fall through to the diagnosis below.
            terminal = self._terminal_review_noop(task_id)
            if terminal is not None:
                return terminal
            # Auto-publish failed AFTER a genuine approval — most often the
            # reviewed branch no longer merges cleanly into main (a stale branch
            # base / merge conflict). Previously this exception propagated and was
            # swallowed, leaving the task silently parked in REVIEWING with no
            # explanation (approved but never published). Surface it instead: an
            # observation for telemetry AND a glanceable Problem/Remediation
            # diagnosis on the task (via `mac task show`/`summary`), so the
            # operator knows exactly why it didn't merge and how to recover.
            # (mac task_51a777c2)
            detail = str(exc)
            retry_after_seconds = int(
                getattr(exc, "publication_retry_after_seconds", 0) or 0
            )
            if retry_after_seconds > 0:
                # Publication may spend minutes cloning and testing. Re-read
                # metadata before adding controller backoff so a concurrent
                # task update made during that work is not overwritten by the
                # stale pre-publication snapshot.
                retry_metadata = ensure_json_object(self.get_task(task_id).metadata)
                retry_metadata["publication_retry"] = {
                    "schema": "mac.publication_retry.v1",
                    "failure_kind": str(
                        getattr(exc, "publication_failure_kind", "transient")
                    ),
                    "failed_at": utcnow(),
                    "not_before": (
                        parse_time(utcnow())
                        + timedelta(seconds=max(60, retry_after_seconds))
                    ).isoformat(timespec="microseconds"),
                    "retry_after_seconds": max(60, retry_after_seconds),
                    "error": detail[:500],
                }
                self.update_task(
                    task_id,
                    metadata=retry_metadata,
                    actor=actor,
                    _preserve_control_plane_publication_metadata=True,
                )
            # Legacy single-task publication conflict handoff: when the failure
            # is the merge-gate reporting that the approved branch no longer
            # integrates onto the CURRENT canonical main tip, do not just park
            # the task in REVIEWING with a diagnosis. Create exactly ONE
            # idempotent, context-rich integration repair task that a DISTINCT
            # agent picks up to rebase/resolve, rerun the FULL projected-main
            # contract, push a replacement ref, and trigger publication retry.
            # Work-package / plan-DAG tasks are guarded out inside the helper and
            # keep their managed integration path unchanged. The diagnosis /
            # observation telemetry below is preserved regardless so operators
            # still see why publication paused.
            conflict_context = getattr(exc, "conflict_integration_context", None)
            integration_task_id: Optional[str] = None
            if isinstance(conflict_context, Mapping):
                try:
                    integration_task_id = self._handoff_conflict_to_integration(
                        task=task,
                        review=review,
                        evidence=evidence,
                        target=target,
                        conflict_context=conflict_context,
                        actor=actor,
                    )
                except Exception:  # noqa: BLE001 - handoff is best-effort; the
                    # diagnosis telemetry below still surfaces the failure.
                    logging.getLogger("mac.conflict_integration").warning(
                        "conflict-to-integration handoff failed for %s",
                        task_id,
                        exc_info=True,
                    )
                    integration_task_id = None
            self._record_default_review_observation(
                task_id,
                "workflow.default_review.publish_failed",
                "warning",
                {
                    "review_id": review.id,
                    "evidence_id": evidence.id,
                    "target": target,
                    "error": detail[:500],
                    "integration_task_id": integration_task_id,
                },
                actor,
            )
            if integration_task_id is not None:
                # Distinct, glanceable telemetry that a repair task was linked so
                # operators can follow the handoff, without losing the diagnosis.
                self._record_default_review_observation(
                    task_id,
                    "workflow.default_review.conflict_integration_created",
                    "info",
                    {
                        "review_id": review.id,
                        "evidence_id": evidence.id,
                        "target": target,
                        "integration_task_id": integration_task_id,
                    },
                    actor,
                )
            try:
                if integration_task_id is not None:
                    self.append_task_activity(
                        task_id,
                        "diagnosis",
                        actor,
                        "Problem: Auto-publish to %s failed after approval — the "
                        "reviewed branch no longer integrates onto the current "
                        "canonical main tip (a merge conflict against the moving "
                        "trunk). The task is approved but stays in REVIEWING, "
                        "unpublished.\n"
                        "Remediation: Linked integration repair task %s was "
                        "created for a DISTINCT agent to rebase/resolve onto "
                        "current main, rerun the full projected-main contract, "
                        "push a replacement ref, and trigger publication retry. "
                        "Current main remains the canonical baseline. Error: %s"
                        % (target, integration_task_id, detail[:300]),
                    )
                else:
                    self.append_task_activity(
                        task_id,
                        "diagnosis",
                        actor,
                        "Problem: Auto-publish to %s failed after approval — the "
                        "reviewed branch could not be merged into main (usually a "
                        "merge conflict from a stale branch base). The task is "
                        "approved but stays in REVIEWING, unpublished.\n"
                        "Remediation: Re-drive the task from current main so its "
                        "branch merges cleanly and let review->publish re-run, or an "
                        "operator resolves the conflict and re-publishes. Error: %s"
                        % (target, detail[:300]),
                    )
            except Exception:
                pass
            return {
                "task_id": task_id,
                "status": "publish_failed",
                "review_id": review.id,
                "target": target,
                "error": detail,
                "integration_task_id": integration_task_id,
            }
        self._record_default_review_observation(
            task_id,
            "workflow.default_review.published",
            "info",
            {
                "review_id": review.id,
                "publication_id": publication.id,
                "target": publication.target,
            },
            actor,
        )
        # Ground truth into memory: publication is the strongest outcome signal
        # the pipeline produces, and until now it never became a lesson (the
        # executor's deployment_learning writeback happens BEFORE review).
        self._record_review_outcome_lesson(
            task_id, outcome="approved_published", detail="published to %s" % publication.target
        )
        return {
            "task_id": task_id,
            "status": "published",
            "review_id": review.id,
            "publication_id": publication.id,
        }

    def _record_review_outcome_lesson(
        self, task_id: str, *, outcome: str, detail: str
    ) -> None:
        """Distill a review-stage outcome into a ``deployment_learning`` memory
        record (best-effort; never breaks the workflow).

        Emitted with schema ``mac.deployment_learning.v1`` so the executor's
        existing ``recall_deployment_lessons`` surfaces it to the NEXT task on
        the project with zero reader changes — the fleet learns from verdicts,
        not just from its own exit codes."""
        try:
            task = self.get_task(task_id)
            project = str(task.project or "") or "unknown"
            content = {
                "schema": "mac.deployment_learning.v1",
                "task_id": task_id,
                "task_title": task.title,
                "project": project,
                "repository": "",
                "evidence_type": "review_verdict",
                "outcome": outcome,
                "signals": {"stage": "hub_review"},
                "error_signature": ("" if outcome == "approved_published" else str(detail)[:200]),
                "detail": str(detail)[:300],
                "at": utcnow(),
            }
            self.add_memory(
                task_id,
                "project",
                project,
                "deployment_learning:%s" % project,
                json.dumps(content, sort_keys=True, separators=(",", ":")),
                None,
                "hub-review-workflow",
            )
        except Exception:  # noqa: BLE001 - lessons are advisory, workflow is not.
            logging.getLogger("mac.review_lessons").warning(
                "could not record review outcome lesson for %s", task_id, exc_info=True
            )

