    # Project bridge


    def import_project_item(
        self,
        source: str,
        external_id: str,
        title: str,
        payload: Dict[str, Any],
        required_capabilities: Optional[Iterable[str]] = None,
        *,
        description: Optional[str] = None,
        project: Optional[str] = None,
        priority: int = 0,
        dependencies: Optional[Iterable[str]] = None,
        metadata: Optional[Dict[str, Any]] = None,
        actor: str = "bridge",
    ) -> ProjectItem:
        existing = self.store.query_one(
            "SELECT * FROM project_items WHERE source = ? AND external_id = ?",
            (source, external_id),
        )
        if existing is not None:
            return self._project_item_from_row(existing)
        task_metadata = {"source": source, "external_id": external_id}
        task_metadata.update(ensure_json_object(metadata))
        task = self.create_task(
            title,
            description=description if description is not None else json_dumps(payload),
            project=project or source,
            priority=priority,
            required_capabilities=required_capabilities,
            dependencies=dependencies,
            metadata=task_metadata,
            actor=actor,
        )
        now = utcnow()
        item_id = new_id("item")
        self.store.execute(
            """
            INSERT INTO project_items (id, source, external_id, title, payload, task_id, status, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (item_id, source, external_id, title, json_dumps(payload), task.id, "imported", now, now),
        )
        self.add_memory(
            task.id,
            "project_item",
            item_id,
            "imported",
            "Imported %s:%s as durable task %s" % (source, external_id, task.id),
            None,
            actor,
        )
        return self.get_project_item(item_id)

    def register_project_repository(
        self,
        name: str,
        path: str,
        source: Optional[str] = None,
        project: Optional[str] = None,
        required_capabilities: Optional[Iterable[str]] = None,
        enabled: bool = True,
        poll_interval_seconds: int = 60,
        metadata: Optional[Dict[str, Any]] = None,
        actor: str = "project-repo",
    ) -> ProjectRepository:
        registered = self.project_repositories.register(
            name,
            path,
            source=source,
            project=project,
            required_capabilities=required_capabilities,
            enabled=enabled,
            poll_interval_seconds=poll_interval_seconds,
            metadata=metadata,
            actor=actor,
        )
        # A new registration can bring a contract requiring tools the image
        # does not ship. Checked here because this is one of only two events
        # that change the union of contracts, and because a worker does not
        # know which project will land on it -- so a gap on one repo is a gap
        # for the whole fleet.
        self.check_sandbox_bom_drift(actor=actor, project=project)
        return registered

